StructuralRule.Predicate:
ConfigPair : name matches "PUT_REGEX_HERE"
    and value is [ConfigConcrete: value is [String: ]]
    and not value is [ConfigConcrete : value is [Null:]]
    /* Temporary fix to exclude null values, SCA defect 647001 */
    and not value matches "(?i)^(null|~)$"
    and not value is [ConfigConcrete : value == ""]
    /* Valid booleans in YAML 1.1 standard, similar to null values SCA doesn't translate them properly. Ideally both null and booleans should not be interpreted as strings. */
    and not value is [ConfigConcrete : value matches "(?i)true|false|on|off|yes|no|y|n"]
    /* Ruby erb variable substitution, used frequently in RubyOnRails */
    and not value matches "^<%=.+"
    /* Java Spring framework variables */
    and not value matches "^\$\{.+"
    /* Ansible variables and inline functions */
    and not value matches "^\{\{.+"
    /* Azure pipelines expressions */
    and not value matches "^\$(\{\{|\[|\().+"
    /* Azure Resource Manager ARM expressions */
    and not value matches "\[.+\]"
    /* Environment variables, used in for example docker-compose.yml */
    and not value matches "(?i)\$[a-z0-9_]+"
    /* Versions in pnpm lock files, keeping it to 1-2 numbers to avoid removing TPs */
    and not value matches "\d{1,2}\.\d{1,2}.\d{1,2}"
    /* Concourse-ci variables */
    and not value matches "^\(\(.+"

