ConfigurationRule.Script:
// Rule for Spring-Boot 1.0-1.4
// If not SpringBoot 1.0-1.4, or Spring-Security is in the classpath, disable the rule
if (
    (!hasDependency("org.springframework.boot", "spring-boot-starter-parent", "1.0")
    && !hasDependency("org.springframework.boot", "spring-boot-starter-parent", "1.1")
    && !hasDependency("org.springframework.boot", "spring-boot-starter-parent", "1.2")
    && !hasDependency("org.springframework.boot", "spring-boot-starter-parent", "1.3")
    && !hasDependency("org.springframework.boot", "spring-boot-starter-parent", "1.4"))
    || hasDependency("org.springframework.boot", "spring-boot-starter-security")
) {
    rule.XPathMatch["@expression"] = String("FTFY_NON_EXISTANT");
}

// Rule for Spring-Boot 2.x
// If not Spring-Boot 2.x or Spring-Security is in the classpath, disable the rule
// Post script will check that management.endpoints.web.exposure.include is set (E26502E4-5867-42F7-94CA-D759A2DE51C4)
// otherwise, this issue will be removed
if (!hasDependency("org.springframework.boot", "spring-boot-starter-parent", "2.")
    || hasDependency("org.springframework.boot", "spring-boot-starter-security")) {
    rule.XPathMatch["@expression"] = String("FTFY_NON_EXISTANT");
}

// Rule for Spring-Boot 1.5.x
// If not Spring-Boot 1.5.x, disable the rule
// Post script will check if either:
//  - management.security.enabled=false (CC836D6B-F972-4C02-B786-6CCCD287E682)
//  - or endpoints.\.\*.sensitive=false (D55AB4AB-8FFF-4714-AF57-8C58529B9AB1)
// otherwise, this issue will be removed
if (!hasDependency("org.springframework.boot", "spring-boot-starter-parent", "1.5")) {
    rule.XPathMatch["@expression"] = String("FTFY_NON_EXISTANT");
}

               // This rule handles the following case: /validators/validator

               // get the list of names of all scanned xml files
               var xmlFiles = getXMLConfigFileNames();

               // build a list of results
               var results = new Array();

               // check whether the validator has been decalred
               function isValidatorDeclared(vname) {
                 for each (var i in program.validators) {
                   if (i.name == vname) {
                     return true;
                   }
                 }
                 return false;
               }

               default xml namespace = new Namespace("");
               var fieldns = new Namespace("");

               // add in validated action field names
               for each (var act in program.struts_actions) {
                 for each (var fileName in xmlFiles) {
                   var shortFileName = "";
                   if (-1 != fileName.lastIndexOf("/")) {
                     shortFileName = fileName.substring(fileName.lastIndexOf("/")+1);
                   }
                   else {
                     shortFileName = fileName.substring(fileName.lastIndexOf("\\")+1);
                   }
                   if (shortFileName.startsWith(act.className) && shortFileName.match("validation.xml")) {
//alert("FILES MATCHED: " + fileName);
                     try {
                       var validationFile = new XML(readFile(fileName));
//alert ("foo: " + validationFile..fieldns::validator.fieldns::param.(@name == "fieldName"));
                       for each (var j in validationFile..fieldns::validator) {
                         var result = new Object();
                         result.filename = shortFileName;
                         result.valtype = String(j["@type"]);
//alert("VALTYPE: " + result.valtype);
                         if (false == isValidatorDeclared(result.valtype)) {
//alert("VAL: " + result.valtype);
                           results[results.length] = result;
                         }
                       }
                     }
                     catch (err) {
                       // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
                       // log(fileName + ": " + err);
                     }
                   }
                 }
               }

               default xml namespace = new Namespace("xmlns://www.fortifysoftware.com/schema/rules");

               // modify attributes of the rule
               var configFileName = "";
               var xpathString = "";

               for each (var i in results) {
                 if (null == configFileName.match(i.filename)) {
                   if (configFileName != "") {
                     configFileName += "|";
                   }
                   configFileName += i.filename;
                 }
                 if (xpathString != "") {
                   xpathString += " or ";
                 }
                 xpathString += "@type = '" + i.valtype + "'";
               }

               if (null != configFileName || 0 != configFileName.length) {
                 rule.ConfigFile.Pattern = configFileName;
               }
               var tmp = String(rule.XPathMatch["@expression"]);
               if ("" == xpathString) {
                 // deleting a rule seems to be causing all sorts of problems, so changing back to assigning an XPath that won't match
                 //delete rule;
                 rule.XPathMatch["@expression"] = "/adhjk";
                 rule.ConfigFile.Pattern = "";
               }
               else {
                 rule.XPathMatch["@expression"] = String(rule.XPathMatch["@expression"]).replace(/PUT_VALIDATOR_TYPES_HERE/, xpathString);
               }

//alert("***************");
//alert(rule);
//alert("******************");

