               // This rule handles the following case: /validators/validator[@type = 'nonexistentfield']/param[@fieldName = 'foo']

               // get the list of names of all scanned xml files
               var xmlFiles = getXMLConfigFileNames();

               // build a list of results
               var results = new Array();

               // build array of duplicates
               var duplicates = new Array();

               // checks whether there is the same type of validator already associated with the field
               function containsValidator(array, valType) {
                 for each (var i in array) {
                   if (i == valType) {
                     return true;
                   }
                 }
                 return false;
               }

               // checks whether we already looked at this field in this action
               function lookedAtField(array, fieldName) {
                 for each (var i in array) {
                   if (i.field == fieldName) {
                     return i;
                   }
                 }
                 return null;
               }

               // checks whether we already looked at this action class
               function doResultsContainDuplicate(thisdupl) {
                 for each (var i in duplicates) {
                   if (i.filename.match(thisdupl.filename) && thisdupl.filename.match(i.filename) &&
                       i.fieldname.match(thisdupl.fieldname) && thisdupl.fieldname.match(i.fieldname) &&
                       i.valtype.match(thisdupl.valtype) && thisdupl.valtype.match(i.valtype)) {
                     return true;
                   }
                 }
                 return false;
               }

               default xml namespace = new Namespace("");
               var fieldns = new Namespace("");
               // add in validated action field names
               for each (var act in program.struts_actions) {
                 for each (var fileName in xmlFiles) {
                   var shortFileName = "";
                   if (-1 != fileName.lastIndexOf("/")) {
                     shortFileName = fileName.substring(fileName.lastIndexOf("/")+1);
                   }
                   else {
                     shortFileName = fileName.substring(fileName.lastIndexOf("\\")+1);
                   }
                   if (shortFileName.startsWith(act.className) && shortFileName.match("validation.xml")) {
                     var result = new Object();
                     result.fields = new Array();
                     result.filename = shortFileName;
                     result.clss = act.clss;
//alert("FILES MATCHED: " + fileName);
                     try {
                       var validationFile = new XML(readFile(fileName));
//alert("STUFF: " + validationFile..fieldns::field);
                       for each (var j in validationFile..fieldns::validator) {
//alert("ADDING: " + String(j["@name"]));
                         var fieldObject = new Object();
                         fieldObject.field = String(j.fieldns::param.(@name == "fieldName"));
                         fieldObject.validators = new Array();
                         var tempFieldObject = lookedAtField(result.fields, fieldObject.field);
                         if (null != tempFieldObject) {
                           if (false == containsValidator(tempFieldObject.validators, String(j["@type"]))) {
                             tempFieldObject.validators[tempFieldObject.validators.length] = String(j["@type"]);
                           }
                           else {
                             var dupl = new Object();
                             dupl.filename = shortFileName;
                             dupl.fieldname = fieldObject.field;
                             dupl.valtype = String(j["@type"]);
                             if (false == doResultsContainDuplicate(dupl)) {
                               duplicates[duplicates.length] = dupl;
                             }
                           }
                         }
                         else {
                           fieldObject.validators[fieldObject.validators.length] = String(j["@type"]);
                           result.fields[result.fields.length] = fieldObject;
                         }
                       }
//alert("ADDING: " + result);
                       for each (var j in validationFile..fieldns::field) {
                         var fieldObject = new Object();
                         fieldObject.field = String(j["@name"]);
                         fieldObject.validators = new Array();
                         var tempFieldObject = lookedAtField(result.fields, fieldObject.field);
                         if (null != tempFieldObject) {
                           for each (var i in j.fieldns::["field-validator"]) {
                             if (false == containsValidator(tempFieldObject.validators, String(i["@type"]))) {
                               tempFieldObject.validators[tempFieldObject.validators.length] = String(i["@type"]);
                             }
                             else {
                               var dupl = new Object();
                               dupl.filename = shortFileName;
                               dupl.fieldname = tempFieldObject.field;
                               dupl.valtype = String(i["@type"]);
                               if (false == doResultsContainDuplicate(dupl)) {
                                 duplicates[duplicates.length] = dupl;
                               }
                             }
                           }
                         }
                       }
                       //if (null == doResultsContain(shortFileName)) {
                         results[results.length] = result;
                       //}
                     }
                     catch (err) {
                       // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
                       // log(fileName + ": " + err);
                     }
                   }
                }
              }

              default xml namespace = new Namespace("xmlns://www.fortifysoftware.com/schema/rules");

               var spareCheckElement = rule.Check[0].toXMLString();
               var count = 0;
               for each (var i in duplicates) {
                 var xpathString = "string(param) = '" + i.fieldname + "'";
                 var xpathString2 = "@type = '" + i.valtype + "'";

                 if (0 != count) {
                   rule.appendChild(new XML(spareCheckElement));
                 }
                 rule.Check[count].ConfigFile.Pattern = i.filename;
                 rule.Check[count].XPathMatch["@expression"] = String(rule.Check[count].XPathMatch["@expression"]).replace(/PUT_ACTION_FIELD_NAMES_HERE/, xpathString);
                 rule.Check[count].XPathMatch["@expression"] = String(rule.Check[count].XPathMatch["@expression"]).replace(/PUT_VALIDATOR_TYPES_HERE/, xpathString2);
                 count++;
               }

               if ("" == rule.Check[0].ConfigFile.Pattern) {
                 // deleting the rule seems to be causing all sorts of problems, so chabging back to assigning an XPath that won't match
                 //delete rule;
                 rule.Check[0].XPathMatch["@expression"] = "/adghjk";
               }

//alert("duplicates.length: " + duplicates.length);
//alert("cpathString: " + xpathString);
//alert("xpathString2: " + xpathString2);
//alert("***************");
//alert(rule);
//alert("******************");

