               // This rule handles the following case: /validators/validator[(string(param) = 'anothernonexistentfield') and param/@name = 'fieldName']/param

               function searchForFieldInActionClass(className, fieldName) {
                 if (typeof nameTable.getClassByName != 'undefined') {
                   var dotIndex = className.lastIndexOf(".");
                   if(-1 != dotIndex) {
                     var actionClass = nameTable.getClassByName(className.substring(0, dotIndex), className.substr(dotIndex+1), "java");
                     if (null != actionClass && actionClass.getName() != "[UnknownType]") {
                       var actionFields = actionClass.getFields();
                       if (null != actionFields) {
                         for (var f = 0; f < actionFields.length; f++) {
                           if (actionFields[f].getName() == fieldName) {
                             return true;
                           }
                         }
                       }
                     }
                   }
                 }
                 return false;
               }

