               var results = new Array();

               // checks whether we already looked at this action class
               function doResultsContain(name) {
                 for each (var i in results) {
                   if (null != i.filename.match(name) && name.match(i.filename)) {
                     return i;
                   }
                 }
                 return null;
               }

               // checks whether we already looked at this field
               function containsField(array, fname) {
                 for each (var i in array) {
                   if (i == fname) {
