// get the list of names of all scanned xml files
var xmlFiles = getXMLConfigFileNames();

// build list of unused validation forms
var unusedValidationFormNames = new Array();
var unusedValidationFormCount = 0;
function addUnusedValidationFormName(name) {
  for each (var foo in unusedValidationFormNames) {
    if (foo == name || null == name || 0 == name.length) {
      return;
    }
  }
  unusedValidationFormNames[unusedValidationFormCount++] = name;
}

for each (var fileName in xmlFiles) {
  if (-1 != fileName.lastIndexOf("/")) {
    fileName = fileName.substring(fileName.lastIndexOf("/")+1);
  }
  else {
    fileName = fileName.substring(fileName.lastIndexOf("\\")+1);
  }
  if (null == fileName.match("validation.xml") || fileName == "validation.xml") {
    continue;
  }
  var unused = true;
  for each (var act in program.struts_actions) {
    if (null == act.className || 0 == act.className.length) {
      continue;
    }
    var temp = act.className;
    if (null != temp.match("\\\*")) {
      temp = act.className.replace(/\*/g, "\.\*");
    }
    if (null != fileName.match(act.className)) {
      unused = false;
      break;
    }
  }
  if (true == unused) {
    addUnusedValidationFormName(fileName);
  }
}

// create ConfigFile/Pattern
var configFileName = "";
for each (var i in unusedValidationFormNames) {
  if (configFileName != "") {
    configFileName += "|";
  }
  configFileName += i;
}

if (null != configFileName || 0 != configFileName.length) {
  rule.ConfigFile.Pattern = configFileName;
}

 var field = "";
 var found = false;
 var thisResult = null;
 var results = new Array();
 for each (var a in program.struts1_actions) {
   if (0 != a.name.length) {
     var bean = program.form_beans[a.name];
     if (null != bean) {
       for each (var v in program.validation_forms) {
         if (null != v) {
           // for ValidatorForm and DynaValidatorForm, look up by name, for ValidatorActionForm and DynaValidatorActionForm, look up by path
           // for non Validator forms, report based on the path
           if (((true == bean.vaf || true == bean.dvaf) && a.path == v.name) ||
              (((true == bean.vf && false == bean.vaf) || (true == bean.dvf && false == bean.dvaf)) && a.name == v.name)) {
             if (null == bean.fields || 0 == bean.fields.length) {
               for each (var prop in bean.properties) {
                 found = false;
                 dbg("property name: " + prop);
                 if (null != prop) {
                   for (var f in v.fields) {
                     if (prop == f) {
                       found = true;
                     }
                   }
                   if (false == found) {
                     if (null == results[bean.name]) {
                       thisResult = new Array();
                     }
                     else {
                       thisResult = results[bean.name];
                     }
                     thisResult[thisResult.length] = prop;
                     results[bean.name] = thisResult;
                     dbg("extra property: " + prop);
                   }
                 }
               }
             }
           }
         }
       }
     }
   }
 }

var spareCheckElement = rule.Check[0].toXMLString();
var count = 0;
var index = 0;
for (var form_name in results) {
  xpath = "";
  for each (var prop_name in results[form_name]) {
    if ("" != xpath) {
      xpath += " or ";
    }
    xpath += "@name = '" + prop_name + "'";
  }
  if ("" != xpath) {
    if (0 != count) {
      rule.appendChild(new XML(spareCheckElement));
      index++;
    }
    rule.Check[index].XPathMatch["@expression"] = String(rule.Check[index].XPathMatch["@expression"]).replace(/FORM_BEAN_NAME/, form_name);
    rule.Check[index].XPathMatch["@expression"] = String(rule.Check[index].XPathMatch["@expression"]).replace(/PROPERTY_NAMES/g, xpath);
  }
  count++;
}

if (-1 != rule.Check[0].XPathMatch["@expression"].indexOf("FORM_BEAN_NAME") || -1 != rule.Check[0].XPathMatch["@expression"].indexOf("PROPERTY_NAMES")) {
  // cannot delete the rule because then the rule with the lower format version will start triggering
  //delete rule;
  rule.Check[0].XPathMatch["@expression"] = "/adhfjkl";
  rule.Check[0].ConfigFile.Pattern = "";
}

