ScriptDefinitions.ScriptDefinition:
var JavaUtils = {}
var java = {}
// for adding a new check, see script 'master_java_post_checks'
java.checks = function () {
    var checks = new Array()
    return {
        add: function (func) {
            if (typeof func !== "undefined") {
                checks.push(new func());
            }
        },
        retrieve: function () {
            return checks
        }
    }
}()

JavaUtils.isLambda = function(className) {
    // with SCA 24.x, Java lambda classes have a name like "lambda [<FQCN>]"
    return className.startsWith('lambda ')
        // or in older versions would match a class name like Foo$1
        || RegExp('\$/d+$').exec(className) !== null
}

//
// This function make sure that the string passed as an argument is a valid Java package name
//
JavaUtils.isValidPackageName = function(inputString) {
    if (null != inputString.match(/[^A-Za-z0-9_\.]+/)) {
        return false;
    }
    else {
        return true;
    }
}

//
// This function make sure that the string passed as an argument is a valid Java identifier
//
JavaUtils.isValidIdentifier = function(inputString) {
    if (null != inputString.match(/[^A-Za-z0-9_]+/)) {
        return false;
    }
    else {
        return true;
    }
}

//
// This function ckecks if a given type is safe to be promoted to Global, specifically for Java
//
JavaUtils.isSafeForGlobal = function(cls) {
    var regex = /^(android|sun|(jakarta|(kotlin|java)(x)?))\./
    var lang = "java";
    var matches = namespaceMatchesRegularExpression(cls, regex, lang);
    // if match found, or if the class is not found, then it's not safe to try and make global
    if (matches || matches == null) return false;
    return true;
}

//
// attempts to figure out if the application is an Android application
//
JavaUtils.isAndroidApp = function() {
    dbg("in JavaUtils.isAndroidApp");
    var xmlConfigFiles = getXMLConfigFileNames()
    for (var i = 0; i < xmlConfigFiles.length; i++) {
        var filename = xmlConfigFiles[i]
        dbg("iterating over getXMLConfigFileNames()");
        if (null != filename) {
            dbg("null != filename");
            var shortName = String(filename).replace(/\\/g, "/");
            shortName = shortName.substring(shortName.lastIndexOf("/") + 1);
            dbg("shortName: " + shortName);
            if ("androidmanifest.xml" == shortName.toLowerCase()) {
                dbg("it's an Android app");
                return true;
            }
        }
    }
    return false;
}

JavaUtils.usesCertificatePinning = function() {
    for (var filename in program.xml) {
        var cfg = program.xml[filename];
        if (null == cfg.name() || "network-security-config" !== String(cfg.name())) continue;

        var children = cfg.children()
        for (var i = 0; i < children.length; i++) {
            var domain = children[i]
            if (domain.name() != "domain-config") continue;
            var domainChildren = domain.children()
            for (var j = 0; j < domainChildren.length; j++) {
                var trust = domainChildren[j]
                if (trust.name() != "trust-anchors") continue;
                var trustChildren = trust.children()
                for (var k = 0; k < trustChildren.length; k++) {
                    var cert = trustChildren[k]
                    if (cert.name() == "certificates") return true;
                }
            }

        }
    }
    return false;
}

//
// Wrapper function calls nameTable.getFieldsByLabel() for the provided language(s)
// @param label: The label 
// @param languages: [Optional] The languages to include in the lookup. Accepts single
//   string value or array of values. Defaults to Platform.JVM.
// @return: Array of jsField objects containing label or empty array if no matches found
//
function getFieldsByLabel(label, languages) {
    languages = [].concat(languages || Platform.JVM);
    var fields = [];
    for each (var language in languages) {
        for each (var field in (nameTable.getFieldsByLabel(label, language) || [])) {
            fields.push(field);
        }
    }
    return fields;
}

//
// Wrapper function calls nameTable.getMethodsByLabel() for the provided language(s)
// @param label: The label 
// @param languages: [Optional] The languages to include in the lookup. Accepts single
//   string value or array of values. Defaults to Platform.JVM.
// @return: Array of jsMethod objects containing label or empty array if no matches found
//
function getMethodsByLabel(label, languages) {
    languages = [].concat(languages || Platform.JVM);
    var methods = [];
    for each (var language in languages) {
        for each (var method in (nameTable.getMethodsByLabel(label, language) || [])) {
            methods.push(method);
        }
    }
    return methods;
}

//
// Wrapper function calls nameTable.getClassesByLabel() for the provided language(s)
// @param label: The label 
// @param languages: [Optional] The languages to include in the lookup. Accepts single
//   string value or array of values. Defaults to Platform.JVM.
// @return: Array of jsType objects containing label or empty array if no matches found
//
function getClassesByLabel(label, languages) {
    languages = [].concat(languages || Platform.JVM);
    var classes = [];
    for each (var language in languages) {
        for each (var cls in (nameTable.getClassesByLabel(label, language) || [])) {
            classes.push(cls);
        }
    }
    return classes;
}

//
// Wrapper function calls nameTable.getAllClasses() for the provided language(s)
// @param languages: [Optional] The languages to include in the lookup. Accepts single
//   string value or array of values. Defaults to Platform.JVM.
// @return: Array of jsType objects for given language(s) or empty array if none found
//
function getAllClasses(languages) {
    languages = [].concat(languages || Platform.JVM);
    var classes = [];
    for each (var language in languages) {
        for each (var cls in (nameTable.getAllClasses(language) || [])) {
            classes.push(cls);
        }
    }
    return classes;
}

//
// Wrapper function calls nameTable.getClassByName() for the provided language(s)
// @packageName: The package name
// @className: The simple class name
// @param languages: [Optional] The languages to include in the lookup. Accepts single
//   string value or array of values. Defaults to Platform.JVM.
// @return: First jsType object matching package/className within languages.
//   Returns UnkownTypeMeta object if no match found
//
function getClassByName(packageName, className, languages) {
    languages = [].concat(languages || Platform.JVM);
    var cls = null;
    for each (var language in languages) {
        // nameTable.getClassByName() returns UnkownTypeMeta object if no class found by name
        cls = nameTable.getClassByName(packageName, className, language);
        if (cls && cls.getName() != "[UnknownType]") {
            break; // match found
        }
    }
    return cls;
}

//
// Wrapper function calls nameTable.getClassByFullName() for the provided language(s)
// @className: The fully qualified class name
// @param languages: [Optional] The languages to include in the lookup. Accepts single
//   string value or array of values. Defaults to Platform.JVM.
// @return: First jsType object matching className within languages.
//   Returns UnkownTypeMeta object if no match found
//
function getClassByFullName(className, languages) {
    languages = [].concat(languages || Platform.JVM);
    var cls = null;
    for each (var language in languages) {
        // nameTable.getClassByFullName() returns UnkownTypeMeta object if no class found by name
        cls = nameTable.getClassByFullName(className, language); 
        if (cls && cls.getName() != "[UnknownType]") {
            break; // match found
        }
    }
    return cls;
}

function angular_ngCookie_checks(){
    /**
    * this script attempts to determine if cookies are set either per-cookie or globally via $cookiesProvider, in which case we shouldn't show the associated issues.
    * In actuality, $cookiesProvider is configured on a module/app, but we can't determine the module for which the sink is occurring,
    * so we assume if it's disabled in one app, it's disabled across all.
    * Similarly if they are set to globally insecure, we should also remove the ones on individual calls to $cookies.put(Object)? because it will just be unnecessary duplicates.
    * This may lead to FPs the sink is in a separate module than one configured to disabling SCE,
    * but this is better than showing a large number of false positives.
    */

    _areCookiesConfigSetGlobally = false; //defaults to false
    _insecureCookiesPerCookie = new Array(); //these will be deleted if cookies config is set globally and checks the default
    _cookieSetSecurelySinks = new Array(); //Those set securely globally, these are all removed


    _pushToInsecureCookies = function(sink){
        _insecureCookiesPerCookie[_insecureCookiesPerCookie.length] = sink;
    }

    _pushToCookieSetSecurely = function(sink){
        _cookieSetSecurelySinks[_cookieSetSecurelySinks.length] = sink;
    }

    _cookiesConfigSetGlobally = function() {
        _areCookiesConfigSetGlobally = true;
    }

    _cookiesSetSafeGlobally = function(sink){
        _cookiesConfigSetGlobally();
        _pushToCookieSetSecurely(sink);
    }


    this.loopFuncs = {
        // rule checks if $sceProvider.enabled(false);
        "C1270A1F-768A-4A23-815C-2AD19A1C8F0F0": _cookiesSetSafeGlobally,
        "7FE291D9-33C1-470D-8C09-CF8F4F45B1E8": _cookiesSetSafeGlobally,
        "94173267-632A-4410-A7E4-C1864C70EBA20": _cookiesConfigSetGlobally,
        "DA09DAE4-89E3-4879-BAF2-C392006B6FA1": _cookiesConfigSetGlobally,
        "3D39EC59-A3E9-491D-9BCE-CB59BDA080FA": _pushToInsecureCookies

    }

    this.postFuncs = new Array();
    this.postFuncs.push(function(){
        for each (var vuln in _cookieSetSecurelySinks){
            vuln.remove();
        }
        if (_areCookiesConfigSetGlobally){
            //if the cookies are set globally, if they are set to true, we need to remove the issues as they would be false positives. If they are set to false, then we should just flag in the one place in the configuration, as the others would just be duplicates.
            for each (var vuln in _insecureCookiesPerCookie){
                vuln.remove();
            }
        }else{
            //log("Cookies not set globally, don't modify anything'");
        }
    });
}

function angular_sce_checks(){
    /**
    * this script attempts to determine if $sceProvider.enabled(false), then the sinks should stay as such.
    * if $sceProvider.enabled(true), then sinking on ngBindHtml requires going through a passthrough
    * such as $sce.trustAsHtml() which adds additional taint.
    * In actuality, $sceProvider is configured on a module/app, but we can't determine the module for which the sink is occurring,
    * so we assume if it's disabled in one app, it's disabled across all.
    * This may lead to FPs the sink is in a separate module than one configured to disabling SCE,
    * but this is better than showing a large number of false positives, since SCE is enabled by default.
    */

    _isSceProviderEnabled = true; //defaults to true
    _angular_trusted_html = "ANGULAR_TRUSTED_HTML";
    _angular_trusted_resource_url = "ANGULAR_TRUSTED_RESOURCE_URL";
    _ngBindHtmlSinks = new Array();
    _ngIncludeSinks = new Array();


    _pushToNgBindHtml = function(sink){
        _ngBindHtmlSinks[_ngBindHtmlSinks.length] = sink;
    }

    _pushToNgInclude = function(sink){
        _ngIncludeSinks[_ngIncludeSinks.length] = sink;
    }

    this.loopFuncs = {
        // rule checks if $sceProvider.enabled(false);
        "782CDCCF-B212-4019-80AC-769ED2A33016": function(){
            //log('sceProvider is disabled');
            _isSceProviderEnabled = false;
        },
        // push the issue to an array if XSS sink on ngBindHtml
        "15676205-A8D4-4B88-910A-8758F95D3AAF0": _pushToNgBindHtml,
        "DD6F312A-BE22-40DF-9F7C-250924E5C3980": _pushToNgBindHtml,
        "83F7B78C-B04B-440F-A602-073F790BC9A60": _pushToNgBindHtml,
        "2BE7AE2C-97CF-43AE-8E04-BD73E4CE7DF60": _pushToNgInclude,
        "8905B8EA-F42E-4564-98F2-448846FA3EA80": _pushToNgInclude,
        "33F679FD-C733-4AE0-8F3C-E00E6D557D040": _pushToNgInclude


    }

    this.postFuncs = new Array();
    this.postFuncs.push(function(){
        if (_isSceProviderEnabled){
            //log("sceProvider Enabled");
            for each (var vuln in _ngBindHtmlSinks){
                removeWithTaint(vuln, _angular_trusted_html);
            }
            for each (var vuln in _ngIncludeSinks){
                removeWithTaint(vuln, _angular_trusted_resource_url);
            }
        }else{
            //log("sceProvider Disabled");
        }
    });
}

function removeWithTaint(vuln, taintFlagToMatch){
    var taintPaths = vuln.getTaintPaths();
    if (taintPaths === null || taintPaths === undefined){
        //log("Attempted to get taint paths from non-dataflow issue");
        return;
    }
    for each (var taintPath in taintPaths){
        var taintFlags = taintPath.getTaintFlags();
        var trusted = false;
        // loop through the taintflags on the current path to see if "taintFlagToMatch" is set
        for each (var taintFlag in taintFlags){
            if (taintFlag == taintFlagToMatch){
                trusted = true;
                break;
            }
        }
        if (!trusted){
            //log("Removing taint path to sink, as $sce is enabled and path not trusted");
            taintPath.removePath();
        }
    }
}

 /**
* Checks to see if developer specifies a XSRF header name, or cookie to check for an XSRF token.
* Although by default it will check for XSRF-TOKEN, and specify X-XSRF-TOKEN, and we're not guaranteed that they're actually doing this server-side.
* However, if they're specifying this, I think this is a good indication that they're likely doing it server-side.
*/
function angular_xsrf_checks(){
    _httpProvider_defaults_configured = false;
    _XSRF_issues_found = new Array();
    _internal_check_issues = new Array();

    _addToIssues = function(sink){
        _XSRF_issues_found[_XSRF_issues_found.length] = sink;
    }

    this.loopFuncs = {
        "110D710B-44D9-43BB-88C4-D5FC47784718": function(sink){
            _httpProvider_defaults_configured = true;
            _internal_check_issues.push(sink);
        },
        categories: [{"Cross-Site Request Forgery": _addToIssues}]

    }
    this.postFuncs = [function(){
        if (_httpProvider_defaults_configured){
            /*
            at the moment this will remove all CSRF issues in the project. Technically it would only be the ones associated with this controller/service depending on how it's configured. But we don't have this information. So the option is to either remove all CSRF issues from the project, or all the issues we find in that particular file.
            */
            for each (var vuln in _internal_check_issues){
                vuln.remove();
            }
            for each (var vuln in _XSRF_issues_found){
                vuln.remove();
            }
        }
    }]


}

function expressjs_csrf_checks(){
    /**
     * This script is to check whether CSRF protection is established globally. For example using app.use(csrfprotection). If CSRF protection is globally set, issues associated with it will be removed.
     * Typically, app.use(csrfprotection) is configured at the module or app level. However, pinpointing the exact module where the sink occurs may be impractical.
     * As a practical solution, if CSRF protection is enabled in one app, we assume it is enabled throughout.
     * Note: there might be routes setup before enabling global CSRF protection. These routes may or may not be CSRF protected (depending on the supported middleware). In practise, these are rare and issues will be removed.
     */

    _areCSRFConfigApplyGlobally = false //defaults to false
    _missingCSRFProtection = new Array(); //these will be deleted if cookies config is set globally and checks the default


    _pushToMissingCSRFProtection = function(sink){
        _missingCSRFProtection[_missingCSRFProtection.length] = sink;
    }


    _CSRFConfigSetGlobally = function() {
        _areCSRFConfigSetGlobally = true;
    }

    _CSRFConfigApplyGlobally = function() {
        _areCSRFConfigApplyGlobally = true;
    }

    this.loopFuncs = {
        "B92EE4BF-00A1-40E8-A684-B792B0B98B15": _pushToMissingCSRFProtection,
        "4E305B68-BDAB-4CD2-A021-548CC1239072": _CSRFConfigApplyGlobally

    }

    this.postFuncs = new Array();
    this.postFuncs.push(function(){
        if (_areCSRFConfigApplyGlobally){
            //if the CSRF protection is set globally, we need to remove the issues as they would be false positives.
            for each (var vuln in _missingCSRFProtection){
                vuln.remove();
            }
        }else{
            //log("CSRF not set globally, don't modify anything'");
        }
    });
}

