// ARRAY PROTOTYPES 
// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/includes
if (!Array.prototype.includes) {
    Object.defineProperty(Array.prototype, 'includes',
        {
            value: function (valueToFind, fromIndex) {
                if (this == null) {
                    dbg('\"this\" is null or not defined');
                }
                var o = Object(this);
                var len = o.length >>> 0; // bitwise operation that converts non-numbers to 0 
                if (len === 0) {
                    return false;
                }
                var n = fromIndex | 0;
                while (n < len) {
                    if (this[n] == valueToFind) {
                        return true;
                    }
                    n++;
                }
                return false;
            }
        });
}

/**
 * Creates a new array with the union of this array and another, duplicates removed
 */
if (!Array.prototype.concatUnique) {
    Object.defineProperty(Array.prototype, 'concatUnique',
        {
            value: function (b) {
                if (b === null || b === undefined) {
                    dbg('concatUnique must have at least 1 argument')
                }
                var c = this.slice(0); // clone existing array
                for (i = 0; i < b.length; i++) {
                    if (!this.includes(b[i])) {
                        c[c.length] = b[i];
                    }
                }
                return c;
            }
        });
}

// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/forEach
if (!Array.prototype.forEach) {
    Object.defineProperties(Array.prototype, 'forEach', {
        value: function (cb) {
            if (cb === null || cb === undefined) {
                dbg('no callback passed to forEach')
            }
            if (typeof cb !== 'function') {
                throw new Error('forEach passed an argument that is not a function')
            }
            for (var i = 0; i < this.length; i++) {
                cb(this[i])
            }
        }
    })
}

// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/filter
if (!Array.prototype.filter) {
    Object.defineProperty(Array.prototype, 'filter',
        {
            value: function (callback, thisArg) {
                var arr = [];
                if (thisArg === undefined || thisArg === null) {
                    thisArg = this;
                }
                for (var i = 0; i < this.length; i++) {
                    if (callback.call(thisArg, this[i], i, this)) {
                        arr.push(this[i])
                    }
                }
                return arr;
            }
        });
}

// STRING PROTOTYPES

// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/startsWith
if (!String.prototype.startsWith) {
    Object.defineProperty(String.prototype, 'startsWith',
        {
            value: function (searchString, position) {
                var positionToSearch = position === undefined ? 0 : position
                return this.indexOf(searchString) == positionToSearch;
            }
        });
}

// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/endsWith
if (!String.prototype.endsWith) {
    Object.defineProperty(String.prototype, 'endsWith',
        {
            value: function (searchString, length) {
                var lengthToCheck = length === undefined ? this.length : length
                return this.lastIndexOf(searchString) == (lengthToCheck - searchString.length);
            }
        });
}

// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/includes
if (!String.prototype.includes) {
    Object.defineProperty(String.prototype, 'includes',
        {
            value: function (searchString, position) {
                var fromIndex = position === undefined ? 0 : position
                return this.indexOf(searchString, fromIndex) != -1;
            }
        });
}

// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/trimStart
if (!String.prototype.trimStart) {
    Object.defineProperty(String.prototype, 'trimStart',
        {
            value: function () {
                var regexMatch = this.match(/\S.*/)
                if (regexMatch === null || regexMatch === undefined) {
                    return regexMatch
                }
                return regexMatch[0]
            }
        });
}

// deprecated name for trimStart
if (!String.prototype.trimLeft) {
    Object.defineProperty(String.prototype, 'trimLeft',
        {
            value: function () {
                return this.trimStart()
            }
        });
}

// https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/String/trimEnd
if (!String.prototype.trimEnd) {
    Object.defineProperty(String.prototype, 'trimEnd',
        {
            value: function () {
                var fullyTrimmed = this.trim()
                var leadingWhitespace = this.match(/^\s+/)
                if (leadingWhitespace == null) {
                    return fullyTrimmed
                } else {
                    return leadingWhitespace[0] + fullyTrimmed
                }
            }
        });
}

// deprecated name for trimEnd
if (!String.prototype.trimRight) {
    Object.defineProperty(String.prototype, 'trimRight',
        {
            value: function () {
                return this.trimEnd()
            }
        });
}


// Checks if array contains a given element
function contains(a, obj) {
    var i = a.length;
    while (i--) {
        if (a[i] === obj) {
            return true;
        }
    }
    return false;
}

// Returns a filtered version of the array with removed duplicates
function uniq(a) {
    if (a === undefined || a === null) return [];
    return a.sort().filter(function (item, pos, ary) {
        return !pos || item != ary[pos - 1];
    })
}

//
// Check if argument is a primitive string or object String
//
function isString(arg) {
    if (typeof arg === "string") return true
    else if (arg instanceof String) return true
    else return false;
}

//
// Language agnostic function checks if a NAMESPACE contains a given regular expression
// @param cls = the class. Either a Type object or a string, which will retrieve the class
// @param regex = the regular expression to check. Note that this should be an actual regular expression object, not a string
// @param lang = the language string. Optional/ignored if the cls argument is a Type object
//
function namespaceMatchesRegularExpression(cls, regex, lang) {
    return classMatchesRegularExpression(cls, regex, lang, function (klass) {
        var namespaceName = String(klass.getPackageName());
        return namespaceName + '.'
    });
}

//
// Language agnostic function checks if a CLASS contains a given regular expression
// @param cls: the class. Either a Type object or a string. If a string, the class is retrieved to verify the type.
// @param regex: the regular expression to check. Note that this should be an actual regular expression object, not a string
// @param lang: the language string. Optional/ignored if the cls argument is a Type object
// @param classManipulator: optional lambda. Is passed the class object for manipulation into a string object. If not passed, simply calls String() on the class
//
// @return: true if contains the regular expression, false if it does not, null if the class is not found
//
function classMatchesRegularExpression(cls, regex, lang, classManipulator) {
    try {
        var nsName = "";
        if (isString(cls)) {
            var klass = nameTable.getClassByFullName(cls, lang);
            if (klass === null || klass === undefined || klass == '[UnknownType]') {
                return null;
            }
            return classMatchesRegularExpression(klass, regex, lang, classManipulator);
        } else {
            if (classManipulator === undefined) {
                nsName = String(cls);
            } else {
                nsName = classManipulator(cls);
            }
        }
        if (nsName.match(regex)) return true;
        else return false;
    } catch (err) {
        warn_internal('error caught when attempting to validate a class against a regular expression: ' + err);
        // not safe to try and return true or false, so pretend that it's a class not found in the nameTable
        return null;
    }
}

//
// This function queries MetaTable for a return type of a function fName defined in class cName or its superclasses.
//
function queryMetaTableForFunctionReturnType(cName, fName) {
    if (null != cName && null != fName && (typeof nameTable.getClassByName != 'undefined')) {
        var dotIndex = cName.lastIndexOf(".");
        if (-1 != dotIndex) {
            var actualClass = nameTable.getClassByName(cName.substring(0, dotIndex), cName.substr(dotIndex + 1), "java");
            var result = queryMetaTableForFunctionReturnTypeHelper(actualClass, fName);
            if ("" == result) {
                if (null != actualClass && actualClass.getName() != "[UnknownType]") {
                    var superClasses = actualClass.getSuperClasses();
                    if (null != superClasses) {
                        for (var i = 0; i < superClasses.length; i++) {
                            result = queryMetaTableForFunctionReturnTypeHelper(superClasses[i], fName);
                            if ("" != result) {
                                return result;
                            }
                        }
                    }
                }
            }
            else {
                return result;
            }
        }
    }
    return "";
}

function queryMetaTableForFunctionReturnTypeHelper(actualClass, fName) {
    if (null != actualClass && actualClass.getName() != "[UnknownType]") {
        var methods = actualClass.getMethods();
        if (null != methods) {
            for (var i = 0; i < methods.length; i++) {
                if (methods[i].getName() == fName) {
                    return methods[i].getReturnType().getPackageName() + "." + methods[i].getReturnType().getName();
                }
            }
        }
    }
    return "";
}

