function getAndroidMinSdkVersion() {
    var xmlFiles = getXMLConfigFileNames();
    var ns = new Namespace();
    for each (var filename in xmlFiles) {
        var lowername = String(filename).toLowerCase();
        var suffix = "androidmanifest.xml";
        if (lowername.indexOf(suffix, lowername.length - suffix.length) < 0) continue;
        var contents = '';
        try {
            contents = readFile(filename);
        } catch (err) {
            log("Error reading file "+filename);
            continue
        }
        try {
            if (contents.charAt(0) != '<') {
                contents = contents.substring(1);
            }
            var xml = new XML(contents);
            if (null !== xml && null !== xml.name() && null !== xml.name().localName && xml.name().localName.toLowerCase() == "manifest") {
                if (xml.children() !== null) {
                    for each (var j in xml.children()) {
                        if (null !== j && null !== j.name() && null !== j.name().localName && j.name().localName.toLowerCase() == "uses-sdk") {
                            if (j.attributes() !== null) {
                                for each (var attr in j.attributes()) {
                                    if (attr !== null && attr.localName() !== null) {
                                        if ("minsdkversion" == attr.localName().toLowerCase()) return parseInt(String(attr));
                                    }
                                }
                            }
                        }
                    }
                }
            }
        } catch (err) {
            // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
            // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
        }
    }
}

