function doCSR(persistedObject, ruleID, title, textNodes) {
          dbg("in doCSR before: " + persistedObject + " : " + title);
          var visited = {};
          var validatedFields = loadPersistedObject(persistedObject);
          var vulns = getVulnerabilities();
          dbg("in doCSR after: " + vulns.length);
          if (null != validatedFields) {
            dbg("doCSR: validatedFields is not null!");
            for each (v in vulns) {
              dbg("doCSR: in for each");
              if(null != v) {
                dbg("doCSR: v is not null");
                var sourceRule = v.getSourceRule();
                var sinkRule = v.getRule();
                if (null != sourceRule && null != sinkRule) {
                  dbg("doCSR sourceRule: " + sourceRule.getIdentifier());
                  dbg("doCSR sinkRule: " + sinkRule.getIdentifier());
                  // look only at vulnerabilities generated by a Struts source rule
                  if (ruleID == sourceRule.getIdentifier()) {
                    dbg("Source rule matched!");
                    var sourceMethod = v.getSourceFunction();
                    if (null != sourceMethod) {
                      var sourceClass = sourceMethod.getEnclosingClass();
                      if (null != sourceClass) {
                        var sourceClassName = "";
                        if (null == sourceClass.getPackageName() || 0 == sourceClass.getPackageName().length) {
                          sourceClassName = sourceClass.getName();
                        }
                        else {
                          sourceClassName = sourceClass.getPackageName() + "." +sourceClass.getName();
                        }
                        dbg("sourceClass: " + sourceClassName);
                        if (null != validatedFields[sourceClassName]) {
                          dbg("Struts class matched!");
                          for each (element in validatedFields[sourceClassName]) {
                            dbg("source: '" + element.source);
                            dbg("sourceMethod.getName(): '" + sourceMethod.getName() + "':" + sourceMethod.getName().constructor.name);
                            if (element.source == sourceMethod.getName()) {
                              dbg("Found a match");
