/**
 * 
 * @param {string} groupId the group ID of the dependency
 * @param {string} artifactId the artifact ID of the dependency
 * @param {string?} versionPrefix the version. If not included, just checks if the dependency has any version
 * @returns {Boolean} if the dependency exists (with a version specified)
 */
function hasDependency(groupId, artifactId, versionPrefix) {

    var versions = retrieveDependencyVersions(groupId, artifactId);
    if (versions.length > 0 && versionPrefix === undefined)
        return true;

    for (var i = 0; i < versions.length; i++) {
        var v = versions[i];
        if (v.indexOf(versionPrefix) === 0) return true;
    }
    return false;
}

function dependencyHasAtLeastVersion(groupId, artifactId, versionToCheck){
    var versions = retrieveDependencyVersions(groupId, artifactId);
    if (versions.length == 0) // dependency not found
        return false;

    for (var i = 0; i < versions.length; i++) {
        var v = versions[i];
        if (compareVersions(v, versionToCheck) < 0){ // version isn't at least versionToCheck
            return false;
        }
    }
    return true;
}

function propertyHasAtLeastVersion(propertyName, versionToCheck){
    var versions = retrievePropertyValues(propertyName);

    if (versions.length == 0) {
        return false;
    }

    for each (var v in versions) {
        if (compareVersions(v, versionToCheck) < 0){ // version isn't at least versionToCheck
            return false;
        }
    }
    return true;
}

/**
 * Compares 2 version number strings
 * In this case, optional part of a version is equivalent to equal
 * meaning that a comparison of "2.1" will appear equivalent to "2.1.3"
 * If either parameter is undefined, it returns false
 * Note: this only checks major, minor and patch versions
 * @param {String} version1 the first version to compare
 * @param {String} version2 the second version to compare
 * @returns {number} 0 if versions equal, -1 if version1 < version2, +1 if version1 > version2
 */
function compareVersions(version1, version2){
    if (version1 === null || version1 === undefined || version2 === null || version2 === undefined)
        return false;
    // note that we need to account for version comparisons with and without patch versions
    // the easiest way to do this would be just check an indexOf of both parameters,
    // but then this would assume that "3.1" and "3.14" are equivalent, which is not correct, so we still need to split them up
    var v1Split = version1.split('.')
    var v2Split = version2.split('.')

    var v1Major = parseInt(v1Split[0]);
    // non-typical case
    if (isNaN(v1Major)){
        return 0;
    }
    var v1Minor = parseInt(v1Split[1]);
    var v1Patch = parseInt(v1Split[2]);

    var v2Major = parseInt(v2Split[0]);
    // non-typical case
    if (isNaN(v2Major)){
        return 0;
    }
    var v2Minor = parseInt(v2Split[1]);
    var v2Patch = parseInt(v2Split[2]);

    if (v1Major < v2Major){
        return -1;
    }else if(v1Major > v2Major){
        return 1;
    }else{ // same major version
        if (isNaN(v1Minor) || isNaN(v2Minor)){ // if minor is missing from one or both, assume equal
            return 0;
        }
        if (v1Minor < v2Minor){
            return -1;
        }else if(v1Minor > v2Minor){
            return 1;
        }else { // same minor versions
            if (isNaN(v1Patch) || isNaN(v2Patch)) { // if patch is missing from one or both, assume equal
                return 0;
            }
            if (v1Patch < v2Patch){
                return -1;
            }else if(v1Patch > v2Patch){
                return 1;
            }else if(v1Patch == v2Patch){
                return 0;
            }else{ // should not be possible to get here, so throw error
                throw Error('Unknown values: ' + version1 + ' and ' + version2)
            }
        }
    }
}



/**
 * Retrieves the versions associated with a dependency. Usually should only be a single dependency, 
 * but returns an array just in case.
 * @param {string} groupId - the group ID of the dependency
 * @param {string} artifactId - the artifact ID of the dependency
 * @returns {Array<string>} the list of dependency versions found
 */
function retrieveDependencyVersions(groupId, artifactId) {
    var dependentVersions = new Array();

    for (var d in dependencies) {
        var group = d.split(":")[0];
        var artifact = d.split(":")[1];
        var version = d.split(":")[2];
        if (group == groupId && artifact == artifactId){
            dependentVersions.push(version);
        }
    }
    return dependentVersions;
}

/**
 * Retrieves the values associated with a property.
 * @param {string} propName - the group ID of the dependency
 * @returns {Array<string>} the list of property values found
 */
function retrievePropertyValues(propName) {
    var propValues = new Array();

    for (var p in properties) {
        var thisPropName = p.split(":")[1];
        if (thisPropName == propName) {
            propValues.push(properties[p]);
        }
    }
    return propValues;
}

