function isValidDotnetIdentifier(inputString) {
  if (null != inputString.match(/[^A-Za-z0-9_]+/)) {
    return false;
  }
  else {
    return true;
  }
}

//
// This function make sure that the string passed as an argument is a valid Dotnet namespace name
//
function isValidDotnetNamespace(inputString) {
  if (null != inputString.match(/[^A-Za-z0-9_\.]+/)) {
    return false;
  }
  else {
    return true;
  }
}

function isASPDOTNETApp() {
  dbg("in isASPDOTNETApp");
  for (filename in program.xml) {
    dbg("iterating over program.xml");
    if (null != filename) {
      dbg("null != filename");
      var shortName = String(filename).replace(/\\/g, "/");
      shortName = shortName.substring(shortName.lastIndexOf("/")+1);
      dbg("shortName: " + shortName);
      if ("web.config" == shortName.toLowerCase()) {
        dbg("it's an ASP.NET app");
        program.webconfig = filename;
        return true;
      }
    }
  }

  dbg("did not find web.config");
  for (filename in program.cxml) {
    dbg("iterating over program.cxml");
    if (null != filename) {
      dbg("filename != null");
      if (null != filename.match(/.*\.aspx$/)) {
        dbg("it's an ASP.NET app");
        return true;
      }
    }
  }
  return false;
}

