function getSignature(vuln) {
    var sourcefunction = "";
    if (vuln.getSourceFunction() != null) {
        sourcefunction = String(vuln.getSourceFunction().getName());
    }
    var sinkfunction = "";
    if (vuln.getPrimaryCall() != null) {
        sinkfunction = String(vuln.getPrimaryCall().getName());
    }
    var sourcefile = "";
    var sourceline = "";
    if (vuln.getTaintSource() != null) {
        sourcefile = String(vuln.getTaintSource().getFile());
        sourceline = String(vuln.getTaintSource().getLine());
    }
    var category = "";
    var subcategory = "";
    if (vuln.getRule() != null) {
        category = String(vuln.getRule().getCategory());
        subcategory = String(vuln.getRule().getSubcategory());
    }
    return sourcefunction + ":" + sinkfunction + ":" + String(vuln.getPrimaryFile()) + ":" + String(vuln.getPrimaryLine()) + ":" + sourcefile + ":" + sourceline + ":" + category + ":" + subcategory;
}
