            if (vuln !== null) {
                if (contains(remove_candidates, vuln.getInstanceIdentifier())) {
                    vuln.remove();
                }
            }
        }
    }
}
function result_filter_on_sinks(dominants_ruleids, subordinates_ruleids) {
    // This function filters dataflow findings so that if an issue with a subordinate sink ruleid is found
    // with source and sink nodes on the same files/lines than an different issue with a dominant ruleid
    // the subordinate one is removed
    var dominants = [];
    var subordinates = [];
    var vulns = getVulnerabilities();
    for each (var vuln in vulns) {
        if (vuln !== null) {
            var sinkid = String(vuln.getRule().getIdentifier());
            // Process dominants
            if (contains_prefixed(dominants_ruleids, sinkid)) {
                dominants[getSignature(vuln)] = vuln.getInstanceIdentifier();
            }
            // Process subordinates
            if (contains_prefixed(subordinates_ruleids, sinkid)) {
                subordinates[getSignature(vuln)] = vuln.getInstanceIdentifier();
            }
        }
    }
    var remove_candidates  = [];
    for (var subordinate_signature in subordinates) {
        if (dominants[subordinate_signature] !== null) {
            remove_candidates[remove_candidates.length] = subordinates[subordinate_signature];
        }
    }
    if (remove_candidates.length > 0) {
        for each (var vuln in vulns) {
            if (vuln !== null) {
                if (contains(remove_candidates, vuln.getInstanceIdentifier())) {
                    vuln.remove();
                }
            }
        }
    }
}

function canonicalizeType(typeName, language) {
  if (language == "JAVA") {
    if (typeName == "java.lang.String") {
      return "String";
    } else if (
      typeName == "java.lang.Byte" ||
      typeName == "java.lang.Integer" ||
      typeName == "java.lang.Long" ||
      typeName == "java.lang.Short"
    ) {
      return "Integer";
    } else if (
      typeName == "java.lang.Double" ||
      typeName == "java.lang.Number" ||
      typeName == "java.lang.Float"
    ) {
      return "FloatingPoint";
    } else if (typeName == "java.lang.Boolean") {
      return "Boolean";
    } else if (typeName == "java.util.Date") {
      return "DateTime";
    }
  }
  return String(typeName);
}

function dbg(msg, indentLevel) {
  if (indentLevel === undefined || indentLevel === null) {
    indentLevel = 0;
  }

  msg = indentString(msg, indentLevel);
  // warn(msg)
}

function printResults(results) {
  alert("There are " + results.length + " results:");

  for (var i = 0; i < results.length; i++) {
    alert("Result " + i + ": " + results[i].URL.sourceLocation);

    alert(indentString("URL: ", 1));
    alert(indentString("url pattern: " + results[i].URL.location, 2));
    alert(indentString("isTemplated: " + results[i].URL.isTemplated, 2));

    alert(indentString("taintflags: ", 1));
    if (results[i].taintflags != null && results[i].taintflags !== undefined) {
      for (var j = 0; j < results[i].taintflags.length; j++) {
        alert(indentString(results[i].taintflags[j], 2));
      }
    }

    if (
      results[i].Parameter === undefined ||
      results[i].Parameter.type === undefined
    ) {
      alert(indentString("Param type unknown", 1));
    } else {
      alert(indentString("Parameter: ", 1));
      alert(printTypeArray(results[i].Parameter.type, 2));
    }
    alert(" ");
  }
}

function getAnnotationValue(annotation) {
  if (annotation !== null && annotation !== undefined) {
    if (
      annotation.get("value") !== null &&
      annotation.get("value") !== undefined
    ) {
      if (annotation.get("value").isString()) {
        return annotation.get("value").getStrValue();
      }

      if (annotation.get("value").isArray()) {
        // actual annotation takes an array
        if (annotation.get("value").element(0).isString()) {
          return annotation.get("value").element(0).getStrValue();
        }
      }
    } else return getAnnotationPath(annotation);
  }
}

function getAnnotationPath(annotation) {
  if (annotation !== null && annotation !== undefined) {
    if (
      annotation.get("path") !== null &&
      annotation.get("path") !== undefined
    ) {
      if (annotation.get("path").isString()) {
        return annotation.get("path").getStrValue();
      }

      if (annotation.get("path").isArray()) {
        // actual annotation takes an array
        if (annotation.get("path").element(0).isString()) {
          return annotation.get("path").element(0).getStrValue();
        }
      }
    }
  }

  // Otherwise return empty string
  return "";
}

function getFunctionMapping(annotationsList, sourceFunction) {
  if (sourceFunction !== null && sourceFunction !== undefined) {
    for (var i = 0; i < annotationsList.length; i++) {
      funcAnnotation = sourceFunction.getAnnotation(annotationsList[i][0]);
      if (funcAnnotation !== null && funcAnnotation !== undefined)
        return funcAnnotation;
    }
    return null;
  }
}

function getParamAnnotation(annotationsList, entryPosition, sourceFunction) {
  if (sourceFunction !== null && sourceFunction !== undefined) {
    for (var i = 0; i < annotationsList.length; i++) {
      paramAnnotation = sourceFunction.getParameterAnnotation(
        entryPosition,
        annotationsList[i]
      );
      if (paramAnnotation !== null) return paramAnnotation;
    }
    return null;
  }
}

function getHttpMethods(functionMapping, sourceFunction, hardCodedAnnoList) {
  var httpMethodMatches = new Array();
  var functionAnnotation = functionMapping.get("method");
  if (functionAnnotation !== null && functionAnnotation.isArray()) {
    for (var i = 0; i < functionAnnotation.length(); i++) {
      var thisElement = functionAnnotation.element(i);
      if (thisElement.isEnum()) {
        httpMethodMatches[httpMethodMatches.length] = String(
          thisElement.getEnumValue()
        );
      }
    }
  } else {
    for (var i = 0; i < hardCodedAnnoList.length; i++) {
      functionAnnotation = sourceFunction.getAnnotation(
        hardCodedAnnoList[i][0]
      );
      if (functionAnnotation !== null)
        httpMethodMatches.push(hardCodedAnnoList[i][1]);
    }
  }
  return httpMethodMatches;
}

function indentString(msg, indentLevel) {
  indentationString = "";
  for (var i = 0; i < indentLevel; i++) {
    indentationString += "\t";
  }
  return indentationString + msg;
}

function printTypeArray(typesArray, indentLevel) {
  if (indentLevel === undefined || indentLevel === null) {
    indentLevel = 0;
  }

  dbg("Parameter of type '" + typesArray[0] + "' has the following fields");
  for (var i = 1; i < typesArray.length; i++) {
    // If type has subTypes
    if (Array.isArray(typesArray[i])) {
      alert(indentString(typesArray[i][0], indentLevel));
      printTypeArray(typesArray[i], indentLevel + 1);
    } else {
      alert(indentString(typesArray[i], indentLevel));
    }
  }
}

function getCategory(rule) {
  var category = rule.getCategory();
  var subcategory = rule.getSubcategory();
  if (subcategory != null) {
    category = category + ": " + subcategory;
  }
  return category;
}

function convertTypeArrayToStringArray(typeArray) {
  if (typeArray === undefined || typeArray === null) return;

  if (!Array.isArray(typeArray)) {
    typeArray.DataType = canonicalizeType(typeArray.DataType, "JAVA");
    return;
  }

  for (var i = 0; i < typeArray.length; i++) {
    if (typeArray[i] !== undefined && typeArray[i] != null) {
      if (Array.isArray(typeArray[i])) {
        convertTypeArrayToStringArray(typeArray[i]);
      } else {
        if (typeArray[i].DataType !== undefined) {
          typeArray[i].DataType = canonicalizeType(
            typeArray[i].DataType,
            "JAVA"
          );
        }
        if (typeArray[i].fields !== undefined) {
          for (var j = 0; j < typeArray[i].fields.length; j++) {
            convertTypeArrayToStringArray(typeArray[i].fields[j]);
          }
        }
      }
    }
  }
  return typeArray;
}

function isSpringApp() {
  var allClasses = nameTable.getAllClasses("java");
  if (allClasses == null || allClasses == undefined) return false;
  for (var i = 0; i < allClasses.length; i++) {
    var clss = allClasses[i];
    if (clss !== null && clss.getPackageName() !== null) {
      if (
        clss.getPackageName().includes("org.springframework.core") ||
        clss.getPackageName().includes("org.springframework.boot")
      )
        return true;
    }
  }
  return false;
}

function normalizeCategory(categoryName) {
  if (categoryName.startsWith("Cross-Site Scripting")) {
    return "XSS";
  } else if (categoryName.startsWith("SQL Injection")) {
    return "SQLI";
  } else {
    return categoryName;
  }
}

/**
 *
 * @param {String} typeName
 * @returns Boolean - Returns 'true' if the objects fields should be resolved
 */
function shouldResolveFields(typeName) {
    if (isPrimitiveType(typeName)) {
        return false;
    }
    // Do not resolve fields for classes in the java.lang namespace
    else if (String(typeName).startsWith("java.lang")) {
        return false;
    }
    else {
        return true;
    }
}

// Returns true if the type being examined should not be further resolved
/**
 *
 * @param {String} typeName The name of the type being processed
 * @returns Boolean - Returne 'true' if typeName is one of the base types understood by WebInspect
 */
function isPrimitiveType(typeName) {
  var baseTypes = [
    "Unused",
    "Unknown",
    "Integer",
    "FloatingPoint",
    "String",
    "Boolean",
    "DateTime",
    "Guid",
    "JSON",
    "XML",
  ];

  for (var i = 0; i < baseTypes.length; i++) {
    if (typeName == baseTypes[i]) {
      return true;
    }
  }
  return false;
}


function isAttackableType(dataType) {
  var attackableTypes = [
    "String",
    "JSON",
    "XML",
  ];

  for (var i = 0; i < attackableTypes.length; i++) {
    if (dataType == attackableTypes[i]) {
      return true;
    }
  }
  return false;
}

/**
 *
 * @param {*} paramObject The type being resolved
 * @param {*} findings An object containing information about the current vulnerability
 * @param {*} flattenedParamList The running list of resolved request parameters and their fields
 * @returns An array containing information on parameters and all fields of the paramObject
 *
 *  This functions purpose is to take a java type and return a flat list containing objects representing
 *  all of the root object's parameters, fields, and subfields.
 *
 */
function flattenParameters(paramObject, findings, flattenedParamList) {
  var returnResults = false;
  if (paramObject == null || paramObject == undefined) return;

  if (flattenedParamList == undefined) {
    flattenedParamList = new Array();
    returnResults = true
  }

  // Put all fields of paramObject in flattenedParamList
  flattenedParamList.push({
      // Set the name of this entry to either the parameter name, if present, or the field name
      name: paramObject.parameterID ? String(paramObject.parameterID) : paramObject.name,
      dataType: paramObject.DataType,
  });
  if (!isPrimitiveType(paramObject.DataType) && paramObject.fields !== undefined) {
    for (var i = 0; i < paramObject.fields.length; i++) {
      // Recursivly resolve and flatten all fields
      flattenParameters(paramObject.fields[i], findings, flattenedParamList);
    }
  }

  // Don't bother creating the paramObjects array unless this is the origional call
  if (returnResults) {
    var paramObjects = new Array();

    // Ignore findings where we can't determine the name of the param
    if (paramObject.NameMatches !== null) {
      for (var i = 0; i < flattenedParamList.length; i++) {
          // Only produce results for base types
          if (isPrimitiveType(flattenedParamList[i].dataType)) {
            var paramObject = {
                // Should the type being examined be excluded from WebInspect's attacks
                Exclude: isAttackableType(flattenedParamList[i].dataType) ? "false" : "true",
                DataTypes: new Array(flattenedParamList[i].dataType),
                NameMatches: new Array(flattenedParamList[i].name),
                Findings: findings,
            };

            paramObjects.push(paramObject);
        }
      }
    }

    return paramObjects;
  }
}

function GetFieldsOfTypeAndSupers(thisType) {
  var fieldsList = new Array();

  dbg("current type: " + thisType.name);
  var fields = thisType.fields;
  if (fields !== null) {
    for (var i = 0; i < fields.length; i++) {
      // Only collect unique field names (overridden fields)
      dbg(
        "processing Field: " + fields[i].name + " with type: " + fields[i].type
      );
      if (fields[i].name.includes("~")) continue;
      fieldsList[fieldsList.length] = getFieldTypesRecursivly(fields[i]);
      getSuperFieldTypesRecursivly(fieldsList[fieldsList.length - 1]);
    }
  }
  getSuperFieldTypesRecursivly(thisType, fieldsList);
  return fieldsList;
}

function getSuperFieldTypesRecursivly(fieldObj, fieldsList) {
    dbg("Called GetSuperFieldTypesRecursivly");
    getSuperFieldTypes(fieldObj, fieldsList, 0);
}

function getSuperFieldTypes(fieldObj, fieldsList, depth) {
  var superFieldTypesDepthLimit = 5;
  var thisFieldType;

  dbg("getSuperFieldTypes: Depth = " + depth);
  // Limit depth
  if (depth == undefined){
    throw new Error("Depth can't be undefined")
  } else if (depth < superFieldTypesDepthLimit) {
    depth += 1;
  } else {
    return;
  }


  // Getting supers of base type
  if (fieldsList !== undefined) {
    thisFieldType = fieldObj;
  } else if (fieldObj !== undefined) {
    thisFieldType = fieldObj.DataType;
  } else {
    return;
  }

  var supers;

  try {
    supers = thisFieldType.getSuperClasses();
  } catch (TypeError) {
    return;
  }

  // Only add field types that are not present on 'thisType'
  if (supers == null || supers == undefined) {
    return;
  }

  for (var i = 0; i < supers.length; i++) {
    var thisSuperFields = supers[i].fields;
    if (thisSuperFields.length > 0) {
      for (var j = 0; j < thisSuperFields.length; j++) {
        dbg('getSuperFieldTypesRecursivly: ' + thisSuperFields[j].name)
        var thisSuperFieldObj = getFieldTypesRecursivly(thisSuperFields[j]);
        getSuperFieldTypes(thisSuperFieldObj, fieldsList, depth);

        // Check if the current object already has fields
        if (fieldObj.fields == undefined && fieldsList == undefined) {
          fieldObj.fields = new Array();
        }

        // Handle base types vs. fields
        if (fieldsList == undefined) {
          fieldObj.fields[fieldObj.fields.length] = thisSuperFieldObj;
        } else {
          fieldsList[fieldsList.length] = thisSuperFieldObj;
        }
      }
    }
  }
}

function getFieldTypesRecursivly(thisField) {
    dbg("Called GetFieldTypesRecursivly");
    return getFieldTypes(thisField, 0);
}

function getFieldTypes(thisField, depth) {
  var fieldResolutionDepthLimit = 5
  if (depth == undefined) {
    throw new Error("Depth can't be undefined")
  } else if (depth < fieldResolutionDepthLimit) {
    depth += 1;
  }else {
    return;
  }

  // Try and get jsType (if thisField is not already a jsType)
  var thisFieldType;
  try {
    thisFieldType = thisField.getType();
  } catch (error) {
    // Already a type
    return thisFieldType;
  }

  if (thisFieldType.fields == null || thisFieldType.fields == undefined) return;

  // Check if this type has subTypes
  dbg('Checking base type of ' + thisFieldType.name)

  var fieldTypeObj = {
    name: String(thisField.name),
    DataType: thisFieldType,
  }

  if (thisFieldType.fields.length > 0 && shouldResolveFields(thisFieldType.name)) {
    var typeArray = new Array();
    dbg('looping over field types. Array length: ' + thisFieldType.fields.length);
    // recursively get list
    for (var i = 0; i < thisFieldType.fields.length; i++) {
      dbg('getFieldTypes' + i + ' -  name: ' + thisFieldType.fields[i].name)
      dbg('getFieldTypes' + i + ' -  file: ' + thisFieldType.fields[i].getFileName())
      dbg('getFieldTypes' + i + ' -  type: ' + thisFieldType.fields[i].getType().name)

      var fieldTypeResult = getFieldTypes(thisFieldType.fields[i], depth);

      if (fieldTypeResult != undefined) {
        typeArray[typeArray.length] = fieldTypeResult;
      }
    }
    fieldTypeObj.fields = typeArray;
  }
  return fieldTypeObj
}

var wiGlobalParams = new Array();

function getOrAddParameterID(parameter) {
  if (parameter.parameterID !== undefined && parameter.parameterID !== null) {
    if (index == -1) {
      index = wiGlobalParams.length;
      wiGlobalParams[index] = parameter;
    }
    return index;
  } else {
    var index = parameter.parameterID;
    if (wiGlobalParams[index] !== null && wiGlobalParams[index] !== undefined) {
      // TODO: check equality before returning. Throw error if not the same object!
      return index;
    } else {
      wiGlobalParams[index] = parameter;
      return index;
    }
  }
}

// Only yamlToProperties function is meant to be exposed publicly.
// The private fields and functions have been prefixed with _

// Global vars
var _indentAmount=1;

function _splitCollection(str) {
    // Splits a dictionary or list in their composing elements.
    // This is basically a str.split(",") but taking quoted strings into account
    // so if a comma (,) is found within a string, it is ignored

    if (str === undefined || str === null) return [];

    str = str.trim();
    var items = [];
    var lastItemIdx = 0;
    var state = ["general"];
    for (var i=0; i < str.length; i++) {
        var c = str.charAt(i);
        if (state.slice(-1)[0] === "general") {
            if (c == "\"") state.push("doubleQuoted"); 
            else if (c == "'") state.push("singleQuoted"); 
            else if (c == ",") {
                items.push(str.substring(lastItemIdx, i).trim()); 
                lastItemIdx = i+1;
            }
        } else if (state.slice(-1)[0] === "singleQuoted") {
            if (c == "\\") state.push("escaped"); 
            else if (c == "'") state.pop(); 
        } else if (state.slice(-1)[0] === "doubleQuoted") {
            if (c == "\\") state.push("escaped"); 
            else if (c == "\"") state.pop(); 
        } else if (state.slice(-1)[0] === "escaped") state.pop();
    }
    items.push(str.substring(lastItemIdx).trim()); 
    return items;
} 

function _removeComments(str) {
    // Remove comments from YAML line
    // A comment is identified by a # char, but we need to ignore those within quoted strings

    if (str === undefined || str === null) return "";

    str = str.trim();
    var state = ["general"];
    for (var i=0; i < str.length; i++) {
        var c = str.charAt(i);
        if (["general", "list", "dictionary"].indexOf(state.slice(-1)[0]) > -1) {
            if (c == "\"") state.push("doubleQuoted"); 
            else if (c == "'") state.push("singleQuoted"); 
            else if (c == "[") state.push("list"); 
            else if (c == "{") state.push("dictionary"); 
            else if (c == "}" || c == "]") state.pop(); 
            else if (c == "#") return str.substring(0, i); 
        } else if (state.slice(-1)[0] === "singleQuoted") {
            if (i+1 < str.length) {
                var nextChar = str.charAt(i+1);
                if (nextChar == "'") state.push("escaped");
                else state.pop();
            } else if (c == "'") state.pop(); 
        } else if (state.slice(-1)[0] === "doubleQuoted") {
            if (c == "\\") state.push("escaped"); 
            else if (c == "\"") state.pop(); 
        } else if (state.slice(-1)[0] === "escaped") state.pop();
    }
    return str;
}

function _extractValue(str, lines, lineno, level) {
    // Extracts the value for a mapping.
    // It handles raw, single and double quoted values
    // It handles single and multi-line values

    if (str === undefined || str === null) return [];
    if (lines === undefined || lines === null) return [];

    var buffer = [];
    var state = ["general"];

    var iterations = 0;
    var MAXITERATIONS = 500;
    while (true) {
        // make sure we break after a number of iterations to prevent DoSing in the case of a bug
        // or unsupported configuration
        iterations++;
        if (iterations > MAXITERATIONS) break;

        // process current line
        for (var i=0; i < str.length; i++) {
            var c = str.charAt(i);
            if (state.slice(-1)[0] === "general") {
                if (c == "\"") state.push("doubleQuoted"); 
                else if (c == "'") state.push("singleQuoted"); 
                else buffer.push(c);
            } else if (state.slice(-1)[0] == "singleQuoted") {
                // for "'", check if its escaped or not
                // check if next char is another "'"
                if (c == "'" && i+1 < str.length) {
                    var nextChar = str.charAt(i+1);
                    if (nextChar == "'") {
                        buffer.push("'");
                        i++;
                    }
                // otherwise, we are closing a sigle quoted string
                } else if (c == "'") {
                    state.pop(); 
                } else {
                    buffer.push(c);
                }
            } else if (state.slice(-1)[0] ===  "doubleQuoted") {
                if (c == "\\") state.push("escaped"); 
                else if (c == "\"") state.pop(); 
                else buffer.push(c);
            } else if (state.slice(-1)[0] == "escaped") {
                buffer.push(c);
                state.pop();
            } 
        }

        var nextLine = lines[lineno];

        // no more lines, so nothing else to process
        if (nextLine === undefined || nextLine === null) break;

        // processing a quoted string literal, continue in next line
        if (state.slice(-1)[0] == "doubleQuoted" || state.slice(-1)[0] == "singleQuoted") {
            str = nextLine;
            lineno++;
            continue;
        } 

        // if next line is indented one level, either a block scalar or a plain flow scalar
        var indent = nextLine.search(/\S/);
        var nextLineLevel = indent/_indentAmount;
        if (nextLineLevel == level + 1) {
            str = nextLine;
            lineno++;
            continue;
        }

        // done processing value
        break;
    }
    return buffer.join('');
}

// public function
function yamlToPropertyMap(filePath) {
    // transforms a YAML document into a properties one
    var result = [];
    var content = '';
    try {
        var content = readFile(filePath);
    } catch (err) {
        log("Error reading file "+filePath);
        return result;
    }
    var lines = content.split('\n');
    var stack = {};
    var lineno = 1;
    var foundIndentAmount=false;
    for each (var line in lines) {
        var indent = line.search(/\S/);
        if (indent > 0 && !foundIndentAmount) {
            foundIndentAmount = indent;
            _indentAmount=indent;
        }
        var level = indent/_indentAmount;
        text = line.trim(); 
        // skip empty lines
        if (text == "") {lineno++; continue;}
        // remove line comments
        if (text.lastIndexOf("#",0) === 0) {lineno++; continue;}
        // remove yaml start mark
        if (text === "---") {lineno++; continue};
        // remove yaml end mark
        if (text === "...") {lineno++; continue};
        // namespace
        if (text.endsWith(":")) {
            stack[level]=text.slice(0,-1);
        } else {
            // process list items 
            if (text.indexOf("- ") === 0) {
                // resolve namespace
                var propNamespace = "";
                for (var i=0; i < level; i++) {
                    if (i==0) propNamespace = stack[i];
                    else propNamespace=propNamespace + "." + stack[i];
                }
                var propValue = _extractValue(text.substring(2, text.length).trim(), lines, lineno, level);
                propValue = _removeComments(propValue).trim();
                result.push(lineno + "::" + propNamespace + "=" + propValue);
            // process mappings
            } else if (text.indexOf(": ") > 0) {
                var propIdx = text.indexOf(": ");
                var propName = text.substring(0,propIdx);
                // resolve namespace
                var propNamespace = "";
                for (var i=0; i < level; i++) {
                    if (i==0) propNamespace = stack[i];
                    else propNamespace=propNamespace + "." + stack[i];
                }
                if (propNamespace !== undefined && propNamespace !== null && propNamespace.length > 0)
                    var prop = propNamespace + "." + propName
                else
                    var prop = propName
                var propValue = text.substring(propIdx+1, text.length).trim();
                propValue = _removeComments(propValue).trim();

                // process abbreviated dictionaries
                if (propValue.indexOf("{") === 0 && propValue.lastIndexOf("}") === propValue.length-1) {
                    propValue = propValue.substr(1,propValue.length-2);
                    var elements = _splitCollection(propValue);
                    for each (var element in elements) {
                        var idx = element.indexOf(":");
                        var name = element.substr(0, idx).trim();
                        var value = element.substr(idx+1).trim();
                        newProp = prop + "." + name;
                        propValue = _extractValue(value, lines, lineno, level);
                        result.push(lineno + "::" + newProp+ "=" + propValue);
                    }
                // process abbreviated lists 
                } else if (propValue.indexOf("[") === 0 && propValue.lastIndexOf("]") === propValue.length-1) {
                    propValue = propValue.substr(1,propValue.length-2);
                    var elements = _splitCollection(propValue);
                    for each (var element in elements) {
                        propValue = _extractValue(element, lines, lineno, level); 
                        result.push(lineno + "::" + prop + "=" + propValue);
