 /**
* when using Express JS, if used helmet.noSniff(), then delete issues
*/
function expressjs_mime_sniffing_check(){
    _noSniff = false;
    _mime_sniffing_issues_found = new Array();
    _internal_check_issues = new Array();

    _addToIssues = function(sink){
        _mime_sniffing_issues_found[_mime_sniffing_issues_found.length] = sink;
    }

    this.loopFuncs = {
        "BB834B09-C007-4220-A065-8DB9E617FD16": function(sink){
            _noSniff = true;
            _internal_check_issues.push(sink);
        },
        categories: [{"HTML5: MIME Sniffing": _addToIssues}]

    }
    this.postFuncs = [function(){
        if (_noSniff){
            /*
            at the moment this will remove all CSRF issues in the project. Technically it would only be the ones associated with this controller/service depending on how it's configured. But we don't have this information. So the option is to either remove all CSRF issues from the project, or all the issues we find in that particular file.
            */
            for each (var vuln in _internal_check_issues){
                vuln.remove();
            }
            for each (var vuln in _mime_sniffing_issues_found){
                vuln.remove();
            }
        }
    }]


}

/* a list of rule IDs with associated callbacks. May optionally take an array of callbacks */
ruleid_checks = {};
category_checks = {};

/* a lib func that will add callbacks to a global object such that when something is compared to the rule ID, the callback is called */
function addRuleCheck(condition, callback) {
    addCheck(condition, callback, ruleid_checks);
}
/* will add callbacks to a global object such that when something is compared to the category, the callback is called */
function addCategoryCheck(condition, callback) {
    //adding category check
    addCheck(condition, callback, category_checks);
}

/* generic function for adding a callback to an object */
function addCheck(condition, callback, obj) {
    var callbacks = obj[condition];
    var callbacksArray = null;
    if (callbacks === null || callbacks === undefined) {
        callbacksArray = new Array();
    } else {
        callbacksArray = callbacks;
    }
    /* don't bother checking if the conditional func, already set. May want to change in the future */
    callbacksArray.push(callback);
    obj[condition] = callbacksArray;
}

/* a lib function that takes a rule ID and compares it to the checks. If matches, calls the callbacks in order */
function checkRule(vuln) {
    category = String(vuln.getRule().getCategory());
    subcategory = String(vuln.getRule().getSubcategory());
    //normalize category name
    issue_category = vulnCategoryNormalizer(category, subcategory);
    issue_rule_id = String(vuln.getRule().getIdentifier());

    //get Rule ID checks
    rule_id_callbacks = ruleid_checks[issue_rule_id];
    //check category. If this wants to be changed to remove all subcategories under a category, this would need to be looped
    category_callbacks = category_checks[issue_category];

    var callbacks = new Array();
    if (rule_id_callbacks !== null && rule_id_callbacks !== undefined && category_callbacks !== null && category_callbacks !== undefined) {
        callbacks = rule_id_callbacks.concat(category_callbacks);
    } else if (rule_id_callbacks !== null && rule_id_callbacks !== undefined) {
        //if so category_callbacks is undefined/null
        callbacks = rule_id_callbacks;
    } else if (category_callbacks !== null && category_callbacks !== undefined) {
        //if so rule_id_callbacks is undefined/null
        callbacks = category_callbacks;
    }


    for each(var callback in callbacks) {
        if (typeof callback !== 'function') {
            //log('the callback: ' + callback + ' is not a function!');
        } else {
            callback(vuln);
        }
    }
}

/* returns the category with optional subcategory, delimited by a colon */
function vulnCategoryNormalizer(category, subcategory) {
    return (subcategory != "null" && subcategory !== undefined) ? String(category + ": " + subcategory) : String(category);
}


