/**
 *
 * @param {string} filePath Path of function.json
 * @returns {string} string of form {enclosingFolder}::{scriptName}::{entryPoint}
 *  Could return an empty string.
 */
function extractAzureFunctionTarget(filePath) {
  var bindings = [];
  var fileContents = '';
  try {
    fileContents = readFile(filePath);
  } catch (err) {
    log("Error reading file: "+filePath);
    return bindings
  }
  var scriptFile = "";
  var functionName = "main";
  var thisMatch = "";

  var fileSep = "/";

  // Get system file separator
  if (filePath.indexOf(fileSep) == -1) {
    fileSep = "\\";
  }

  var functionPath = filePath.substring(0, filePath.lastIndexOf(fileSep));
  var functionFolder = functionPath.substring(
    functionPath.lastIndexOf(fileSep) + 1,
    functionPath.length()
  );

  var lines = fileContents.split("\n");
  var inBindings = false;
  var inBinding = false;
  var thisBinding = {};
  var thisMatch = "";
  var thisTriggerType = "";

  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    if (line.match(/"entryPoint"/)) {
      thisMatch = line.match(/"[a-zA-Z_]+"/g)[1];
      if (thisMatch !== null) {
        functionName = thisMatch.substring(1, thisMatch.length - 1);
      }
    }
    if (line.match(/"scriptFile"/)) {
      thisMatch = line.match(/"[\w._0-9]+"/g)[1];
      if (thisMatch != undefined) {
        scriptFile = thisMatch.substring(1, thisMatch.length - 1);
      }
    }
    if (line.match(/"bindings"/)) {
      inBindings = true;
    }
    if (inBindings) {
      if (inBinding && line.match(/}/)) {
        inBinding = false;
        thisBinding.functionFolder = functionFolder;
        thisBinding.scriptFile = scriptFile;
        thisBinding.functionName = functionName;
        bindings.push(thisBinding);
      }
      if (line.match(/{/)) {
        inBinding = true;
        thisBinding = {
          triggerType: "",
          type: "",
          paramName: "",
          direction: "",
          functionFolder: "",
          scriptFile: "",
          functionName: "",
          authLevel:"",
        };
      }
      if (inBinding && line.match(/"type"/)) {
        thisMatch = String(line.match(line.match(/[\w._0-9]+/g)[1]));
        thisBinding.type = thisMatch;
        if (thisMatch.match(/.*Trigger/)) {
          thisTriggerType = thisMatch;
        }
      }
      if (inBinding && line.match(/"direction"/)) {
        thisBinding.direction = line.match(/\"(in|out)\"/)[1];
      }
      if (inBinding && line.match(/"name"/)) {
        thisBinding.paramName = line.match(/[\w._0-9]+/g)[1];
      }
      if (inBinding && line.match(/"authLevel"/)) {
        thisBinding.authLevel = line.match(/[\w._0-9]+/g)[1];
      }
    }
  }
  // If no "entryPoint" value is found "main" is the default value
  //log(bindings);
  for (var i = 0; i < bindings.length; i++) {
    bindings[i].triggerType = thisTriggerType;
     log(
      'Add Binding: TriggerType = ' +
        bindings[i].triggerType +
        ': ScriptFile = ' +
        bindings[i].scriptFile +
        ': FunctionName = ' +
        bindings[i].functionName +
        ': ParamName = ' +
        bindings[i].paramName +
        ': Direction = ' +
        bindings[i].direction +
        ': AuthLevel = ' +
        bindings[i].authLevel
    ); 
  }
  return bindings;
}

/**
 *
 * @returns list of strings containing relevant information about python Azure Functions
 */
function identifyAzureFunctions() {
  var filePaths = getAllProgramFileNames();
  var azureBindings = [];

  for (var i = 0; i < filePaths.length; i++) {
    var filePath = filePaths[i];
    if (filePath.match(/function\.json/gi)) {
      // log('Found: ' + filePath);
      var bindings = extractAzureFunctionTarget(filePath);
      azureBindings = azureBindings.concat(bindings);
    }
  }
  return azureBindings;
}

