  }  

function buildAzureFuncRulePredicate(theseAzureBindings, type, direction) {
  var newStructuralMatch = "";
  var clauseAdded = false;

  if (theseAzureBindings != null && theseAzureBindings.length > 0) {
    for (var i = 0; i < theseAzureBindings.length; i++) {
      var functionBinding = theseAzureBindings[i];
      var thisVarName = "";

      if (newStructuralMatch == "") {
        newStructuralMatch = "Variable v: enclosingFunction is [Function: (";
      }

      if (
        functionBinding.triggerType == type &&
        functionBinding.direction == direction
      ) {
        if (clauseAdded) {
          newStructuralMatch += "or ";
        }
        clauseAdded = true;
        newStructuralMatch +=
          '(filepath matches ".*' +
          functionBinding.functionFolder +
          "(\\\\|/)" +
          functionBinding.scriptFile +
          '" ';
        newStructuralMatch +=
          'and name == "' + functionBinding.functionName + '" ';

        thisVarName = "v" + i;

        newStructuralMatch +=
          "and parameters contains [Variable " +
          thisVarName +
          ': name == "' +
          functionBinding.paramName +
          '" and ' +
          thisVarName +
          " is v]";

        newStructuralMatch += ")\n";
      }
    }
    newStructuralMatch += ")]";
  }
  //log('Structural Rule Generated:\n' + newStructuralMatch)
  if (!clauseAdded){
    return "";
  }
  return newStructuralMatch;
}

var azureBindings = undefined;

function getAzureFunctionBindings() {
  if (azureBindings == undefined) {
    azureBindings = identifyAzureFunctions();
    //log(azureBindings);
  }
  return azureBindings;
}

