function unixPath(str) {
  return String(str).replace(/\\/g, "/");
}

/*
            * Want to get SCA install such that it may appear in a canonical path. Due to this and dealing with SCA installs in non-default locations, will just get last 2 parts of path. e.g.
            /Application/HP_Fortify/HP_Fortify_SCA_and_Apps_4.30/
            will return: 
            /HP_Fortify/HP_Fortify_SCA_and_Apps_4.30

            /Users/foo/sca/
            will return: 
            /foo/sca

            /sca 
            will return:
            /sca

            If the Core directory is at /Core (SCA install @ root directory, however absurd), or com.fortify.Core is custom and doesn't point to a directory called "Core", will return null instead of assuming this is inside the SCA install.
            */
function getSCAInstall() {
  var corePath = getProperty("com.fortify.Core");
  var scaInstallDir = null;
  if (corePath !== null && corePath !== undefined) {
    var corePathArr = unixPath(corePath).split("/");
    if (corePathArr[corePathArr.length - 1].equals("Core")) {
      /*should always be true, but just in case weird installation */
      corePathArr.pop();
      /* want to get last 2 elements for SCA install where possible */
      if (corePathArr.length > 1) {
        scaInstallDir =
          "/" +
          corePathArr[corePathArr.length - 2] +
          "/" +
          corePathArr[corePathArr.length - 1];
      } else if (corePathArr.length === 1) {
        scaInstallDir = "/" + corePathArr[corePathArr.length - 1];
      }
    } else {
      dbg("Core wasn't last part of :" + corePath);
    }
  }
  if (scaInstallDir !== null) dbg("SCA install directory is: " + scaInstallDir);
  return scaInstallDir;
}

function doSpring2CSR(persistedObject, ruleIDs, title, textNodes) {
    var vulns = getVulnerabilities();
    var visited = {};
    var commandClassMap = loadPersistedObject("program.spring2_command_class_Map");
    var validatedFields = loadPersistedObject(persistedObject);
    if (commandClassMap != null && validatedFields != null) {
        for each (v in vulns) {
            if (null != v) {
                var sourceRule = v.getSourceRule();
                var sinkRule = v.getRule();
                if (null != sourceRule && null != sinkRule) {
                    for each (var ruleID in ruleIDs) {
                        if (sourceRule.getIdentifier() == ruleID) {
                            var method = v.getTaintSource().getFunction();
                            var controller = v.getTaintSource().getFunction().getEnclosingClass();
                            //alert("Source Method: " + method.getName());
                            //alert("Controller Class: " + controller.getPackageName() + "." + controller.getName());
                            var callback = commandClassMap[controller.getPackageName() + "." + controller.getName()];
                            if (callback != null) {
                                //alert(1);
                                //alert(method.getName() + " == " +  callback.callback );
                                //alert(method.getLineNumber() + " == " +  callback.lineNumber );
                                //alert(method.getFileName() + " == " +  callback.fileName );
                                if (method.getName() == callback.callback && method.getLineNumber() == callback.lineNumber && method.getFileName() == callback.fileName) {
                                    //alert("Command Class is : " + callback.commandClass);
                                    if (validatedFields[callback.commandClass] != null && validatedFields[callback.commandClass] != "" && validatedFields[callback.commandClass] != "undefined") {
                                        if (validatedFields[callback.commandClass].length > 0) {
                                            var element = validatedFields[callback.commandClass][0];
                                            if (element != null) {
                                                if (!(v in visited)) {
                                                    //alert("Command Class " + element.commandClass + " is validated");
                                                    var metaInfoMap = sinkRule.getMetaInfo();
                                                    // alert("Metainfo " + metaInfoMap);
                                                    // alert("Lowering probability for issue originated in " + method.getName());
                                                    lowerProbabilityForCSR(v, metaInfoMap, visited);
                                                    var nodes = new Array();
                                                    for (var index in textNodes) {
                                                        var node = new Object();
                                                        node.text = textNodes[index];
                                                        node.fileName = element.fileNames[index];
                                                        node.lineNumber = element.lineNumbers[index];
                                                        nodes[index] = node;
                                                    }
                                                    addEvidenceForCSR(v, title, nodes);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                            break;
                        }
                    }
                }
            }
        }
    }
}

function doSpring3CSR(persistedObject, ruleID, title, textNodes) {
    var vulns = getVulnerabilities();
    var visited = {};
    var validatedCommandClasses = loadPersistedObject(persistedObject);
    if (validatedCommandClasses != null) {
        for each (v in vulns) {
            if (null != v) {
                var sourceRule = v.getSourceRule();
                var sinkRule = v.getRule();
                if (null != sourceRule && null != sinkRule) {
                    if (sourceRule.getIdentifier() == ruleID) {
                        var method = v.getTaintSource().getFunction();
                        //alert("Source Method: " + method.getName());
                        var args = method.getArgumentTypes();
                        // method.getArgumentTypes() can return null if the args length == 0, but will also check if it returns an empty array, just in case this changes in the future.
                        if (undefined === args || null === args || args.length == 0){
                            continue;
                        }
                        var index = v.getTaintSource().getEntryPointArgument();
                        if (index != null && index > -1) {
                            // alert("!!!!!!!! Index: " + index);
                            var commandClass = args[parseInt(index) + 1]; // First argument is 1, 0 is for the enclosing class
                            var commandClassName = commandClass.getPackageName() + "." + commandClass.getName();
                            //alert("Command Class is : " + commandClassName);


                            var valmethods = nameTable.getMethodsByLabel("validatedSpring3Function", "java");
                            if (valmethods != null) {
                                for each (var vmethod in valmethods) {


                                    if (vmethod.getEnclosingClass().getPackageName() == method.getEnclosingClass().getPackageName() && vmethod.getEnclosingClass().getName() == method.getEnclosingClass().getName() && vmethod.getName() == method.getName()) {

                                        // Check if there is any linenumber annotatation indiicating that validation takes place on a given line
                                        var skipValidation = false;
                                        var line = nameTable.getLabelValue("validatedSpring3Function", vmethod);
                                        if (line != null && line > 0) {
                                            // alert("There is a validate call in line " + line);
                                            var smethod = v.getEnclosingFunction();
                                            if (smethod.getEnclosingClass().getPackageName() == method.getEnclosingClass().getPackageName() && smethod.getEnclosingClass().getName() == method.getEnclosingClass().getName() && smethod.getName() == method.getName()) {
                                                // alert("Sink is within the source function");
                                                if (v !== null && v.getPrimaryLine() !== null && v.getPrimaryLine() < line) {
                                                    // alert("Non validated call!!! " + v.getPrimaryCall() + " at " + v.getPrimaryLine());
                                                    skipValidation = true;
                                                }
                                            }
                                        }
                                        if (!skipValidation) {
                                            //alert("Source Method " + method.getName() + " is VALIDATED, do the CSR dance!");
                                            //alert("Command Class " + commandClassName + " is validated");
                                            var element = validatedCommandClasses[commandClassName];
                                            if (null != element) {
                                                if (!(v in visited)) {
                                                    //alert("Command Class " + commandClassName + " is validated");
                                                    var metaInfoMap = sinkRule.getMetaInfo();
                                                    // alert("Metainfo " + metaInfoMap);
                                                    //alert("Lowering probability for issue originated in " + method.getName());
                                                    lowerProbabilityForCSR(v, metaInfoMap, visited);
                                                    var nodes = new Array();
                                                    for (var index in textNodes) {
                                                        var node = new Object();
                                                        node.text = textNodes[index];
                                                        node.fileName = element.fileNames[index];
                                                        node.lineNumber = element.lineNumbers[index];
                                                        nodes[index] = node;
                                                    }
                                                    addEvidenceForCSR(v, title, nodes);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

