function init() {
    if (null != sca.program) {
        //alert("config: PROGRAM ALREADY EXISTS");
        return sca.program;
    }

    var program = new Object();
    program.xml = new Array();                       // contains real xml files
    program.cxml = new Array();                      // contains fake xml files
    var xmlFiles = getXMLConfigFileNames();
    var allFiles = getAllProgramFileNames();
    default xml namespace = new Namespace("");
    for each (var filename in xmlFiles) {
        var contents = '';
        try {
            contents = readFile(filename);
        } catch (err) {
            log("Error reading file "+filename);
            continue;
        }
        try {
            if (contents.charAt(0) != '<') {
                // Running into problems with xml files that begin with the character FEFF
                // Apparently this is a standard way to say that the file is unicode, but
                // it causes the Rhino XML parser to go nuts.  I'm going to zap the
                // charater, and no doubt pay the price when some file that actually uses
                // some fancy characters comes along. bvc
                contents = contents.substring(1);
            }
            var xmlObject = new XML(contents);
            if (null != xmlObject && null != xmlObject.name()) {
            program.xml[filename] = xmlObject;
            }
        }
        catch (err) {
            // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
            // alert("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
        }
    }

    for each (var f in allFiles) {
        try {
            var contentXml = getXMLForContentFile(f);        // this gets all fake xml files
            //var contentXml = readFile(f);                  // this gets all real xml files
            //alert(contentXml);
            if(contentXml != null) {
                program.cxml[f] = new XML(contentXml);
            }
        }
        catch (err) {
            // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
            // alert("Error processing file: " + f + ". Exception thrown was: " + err + ". Please review the file for any syntax errors.");
        }
    }
    //alert("config: CREATED NEW PROGRAM");
    return program;
}

