// !!!!! IF YOU MODIFY ANY FUNCTIONS HERE DON'T FORGET TO MODIFY THEM IN THE UTIL MID SCRIPT BELOW
// This function iterates over a provided data structure,
// retrieves namespace, class, and function names from it,
// and generates function identifiers for the provided rule.
//
function generateFunctionIdentifiers(rule, dataStructure) {

  var counter = 0;
  var spareFunctionIdentifier = rule.FunctionIdentifier[0].toXMLString();

  for each (var s in dataStructure) {
    var namespaceN = "";
    var classN = "";
    var functionN = "";
    var modifierN = "";

    if (namespaceN != "") {
      namespaceN = namespaceN + "|" + s.namespaceName;
    }
    else {
      namespaceN = s.namespaceName;
    }

    if (s.namespaceName.length == 0) {
      namespaceN = ".*";
    }

    if (classN != "") {
      classN = classN + "|" + s.className;
    }
    else {
      classN = s.className;
    }

    if (functionN != "") {
      functionN = functionN + "|" + s.functionName;
    }
    else {
      functionN = s.functionName;
    }

    if (s.functionName.length == 0) {
      functionN = ".*";
    }

    if ((s.modifier != null) && (null == modifierN.match(s.modifier))) {
      modifierN = s.modifier;
    }

    if (counter > 0) {
      try {
        rule.appendChild(new XML(spareFunctionIdentifier));
      } catch(err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
      }
    }

    if (0 < classN.length && 0 < functionN.length) {
      if (0 == namespaceN.length) {
        namespaceN = ".*";
      }

      rule.FunctionIdentifier[counter].NamespaceName.Pattern = namespaceN;
      rule.FunctionIdentifier[counter].ClassName.Pattern = classN;
      rule.FunctionIdentifier[counter].FunctionName.Pattern = functionN;
      if (modifierN.length > 0) {
        rule.FunctionIdentifier[counter].Modifiers.Modifier = modifierN;
      }
    }
    counter++;
  }

  return rule;
}


// Function to split fully qualified classname into namespace (ns) and className (clsName).
function splitFullyQualifiedClsName (fullyQualifiedClsName) {
  var dotIndex = String(fullyQualifiedClsName).lastIndexOf(".");
  var returnObj = new Object();
  returnObj.ns = String(fullyQualifiedClsName).substring(0, dotIndex);
  returnObj.clsName = String(fullyQualifiedClsName).substr(dotIndex+1);
  return returnObj;
}

var attributens = new Namespace("http://schemas.android.com/apk/res/android");
program.android_xml_callbacks = new Array();
program.android_masked_fields = new Array();
for (var filename in program.xml) {
    var cfg = program.xml[filename];
    if (null == cfg.name()) continue;

    // Check on Root element's attributes
    var id = null;
    var masked = false;
    for each (var attr in cfg.attributes()) {
        var name = attr.name();
        var value = attr;
        if (name == "http://schemas.android.com/apk/res/android::id")
            id = value;
        else if (name == "http://schemas.android.com/apk/res/android::inputType" && value == "textPassword")
            masked = true;
        else if (name == "http://schemas.android.com/apk/res/android::onClick" && program.android_xml_callbacks.indexOf(value) === -1)
            program.android_xml_callbacks.push(value);
    }
    if (masked && id != null && id.indexOf("/") > -1) {
        var field_name = id.split("/").slice(-1).pop();
        if (program.android_masked_fields.indexOf(field_name) === -1)
            program.android_masked_fields.push(field_name);
    }

    // Check on descendents' attributes
    for each (var j in cfg..*) {
        if ("textPassword" === String(j.@attributens::["inputType"])) {
            var id = String(j.@attributens::["id"]);
            var field_name = String(id.split("/").slice(-1).pop());
            if ("" != field_name && program.android_masked_fields.indexOf(field_name) === -1)
                program.android_masked_fields.push(field_name);
        }
        if ("" !== String(j.@attributens::["onClick"]) && undefined !== j.@attributens::["onClick"] && null !== j.@attributens::["onClick"]) {
            var callback = String(j.@attributens::["onClick"]);
            if (program.android_xml_callbacks.indexOf(callback) === -1)
                program.android_xml_callbacks.push(callback);
        }
    }
}

