/*
gRPC Python files creates message object namespaces based on code in the .proto file. When protobuf generates python code 
from the .proto file, it creates a python file with a postpended _p2.py extension, where the filename is the namespace 
of the gRPC objects that will be created at runtime. This name is referenced in the code yet again as an argument to the
 _builder.BuildTopDescriptorsAndMessages function. Using both and ensuring they are matching is a safe bet that objects
 will be declared with the given namespace.
*/
function find_grpc_namespaces(){

    var allFiles = getAllProgramFileNames();

    var gen_NS = [];

    //look for the generated files created from the .proto file
    for each (var fName in allFiles) {
        if (fName.match(".*_pb2.py")){

            //alert("Found protobuf generated file: " + fName);      
            var genProtoContents = '';
            try {
                genProtoContents = readFile(fName);
            } catch (err) {
                log("Error reading file "+fName);
                continue;
            }

            var lines = genProtoContents.split('\n');

            var findMethod = "_builder.BuildTopDescriptorsAndMessages";

            /* There will be one line that will potentially be quite large, only process match based on the match string
            for efficiency. If the structure of the generated file changes, this assumption will need to change as well */
            for (var i = 0; i < lines.length; i++){

                //though unlikely, account for preceeding whitespace
                var cmpline = lines[i];
                cmpline = cmpline.trim();

                if(findMethod.length >= cmpline.length){
                    continue;
                }

                var prefix_matched = true;

                for (var j = 0; j < findMethod.length; j++){

                    if(findMethod[j] != cmpline[j]){
                        prefix_matched = false;
                        break;
                    }                    
                }

                if(prefix_matched){

                    //clean up the two strings for comparison of the key value
                    var margs = cmpline.substring(findMethod.length);
                    var margssp = margs.split(",");
                    var cmpstr = String(margssp[1].trim());

                    var spfname = fName.replace("\\", "/").split("/");
                    var trim_fName = String(spfname[spfname.length - 1].replace("\.py", ""));                    

                    //Variable name will have some sort of containing character like <'> 
                    if(cmpstr.includes(trim_fName)){
                        gen_NS.push(trim_fName);
                        //alert("match found, generated gRPC namespace verified in-code");
                        break;
                    }

                }
            }

        }
    }

    return gen_NS;

}

