        }

        if (0 == program.axisService.length || needToAddToArray == true) {
        newAxisService.namespaceName = thisAxisService.namespaceName;
        newAxisService.className = thisAxisService.className;
        newAxisService.functionName = methodName;
        newAxisService.modifier = "public";

        program.axisService[program.axisService.length] = newAxisService;
        }

    }
    else {

        // User has specified individual methods to expose so let's model just those

        for each (var operation in serviceDescriptor..defaultNamespace::["operation"]) {
        var newAxisService = new Object();
        var methodName = "";

        // Extract each method's name
        methodName = String(operation["@name"]);

        // make sure we're dealing with valid Java method name
        if (methodName == null || false == JavaUtils.isValidIdentifier(methodName)) {
            continue;
        }

        // Determine if we need to add this new service to the existing array
        var needToAddToArray = false;
        for each (var arrayElement in program.axisService) {

            if (arrayElement.namespaceName == thisAxisService.namespaceName && arrayElement.className == thisAxisService.className) {
            arrayElement.functionName = arrayElement.functionName + "|" + methodName;
            needToAddToArray = false;
            break;
            }
            else {
            needToAddToArray = true;
            }
        }

        if (0 == program.axisService.length || needToAddToArray == true) {
            newAxisService.namespaceName = thisAxisService.namespaceName;
            newAxisService.className = thisAxisService.className;
            newAxisService.functionName = methodName;
            newAxisService.modifier = "";
            program.axisService[program.axisService.length] = newAxisService;
        }
        }
    }
    }
}

// NOTE: Integrate this
var defaultNamespace = new Namespace("");
var axisServiceCount = 0;
if (program.blazeService == null)
    program.blazeService = new Array();

for each (var servicesXMLFile in program.xml) {
    if (null == servicesXMLFile.name() || (servicesXMLFile.name().length == 0) || (null == servicesXMLFile.name().localName.match("service") && null == servicesXMLFile.name().localName.match("services-config"))) {
    continue;
    }

    var currentServiceElement = 0;
    var targetNode = null;

    if (servicesXMLFile.name().localName.match("services-config")) {
    // Multiple services being described
    targetNode = servicesXMLFile..defaultNamespace::["services"]..defaultNamespace::["service"];

    }
    else if (servicesXMLFile.name().localName.match("service")) {
    // Only one service being described
    targetNode = servicesXMLFile;
    }

    for each (var serviceDescriptor in targetNode) {

    var thisBlazeService = new Object();
    thisBlazeService.className = "";
    thisBlazeService.namespaceName = "";
    thisBlazeService.functionName = "";
    thisBlazeService.modifier = "";

    // Verify that this is the right service object we are looking for
    if (!serviceDescriptor.hasOwnProperty("@class"))
        continue;

    var serviceName = String(serviceDescriptor.attribute("class"));

    if (!serviceName || (serviceName.toLowerCase() != "flex.messaging.services.remotingservice"))
        continue;

    // Iterate through each destination

    var destinationClassCount = serviceDescriptor..defaultNamespace::["destination"].length();
    if (destinationClassCount == 0) {
        continue;
    }

    var destinationNodes = targetNode..defaultNamespace::["destination"];
    for each (var destinationNode in destinationNodes) {
        // Discover each destination class
        var classFactory = String(destinationNode..defaultNamespace::["properties"]..defaultNamespace::["factory"]);
        if (classFactory != null && classFactory.length > 0) {
        // We currenty do not cover custom factory-classes; this is too difficult to model
        continue;
        }

        thisBlazeService.className = String(destinationNode..defaultNamespace::["properties"]..defaultNamespace::["source"]);

        if (thisBlazeService.className == null || thisBlazeService.className.length == 0) {
        continue;
        }

        var dotIndex = thisBlazeService.className.lastIndexOf(".");

        if (dotIndex == -1) {
        thisBlazeService.namespaceName = "";
        }
        else {
        thisBlazeService.namespaceName = thisBlazeService.className.substring(0, dotIndex);
        thisBlazeService.className = thisBlazeService.className.substr(dotIndex + 1);
        }

        // make sure we're dealing with valid Java package and class names
        if (false == JavaUtils.isValidPackageName(thisBlazeService.namespaceName) || false == JavaUtils.isValidIdentifier(thisBlazeService.className)) {
          continue;
        }

        // All public methods of the given class will be marked as entry points
        var newBlazeService = new Object();
        var methodName = "";

        var needToAddToArray = false;
        for each (var arrayElement in program.blazeService) {
        if (arrayElement.namespaceName == thisBlazeService.namespaceName && arrayElement.className == thisBlazeService.className) {
            arrayElement.functionName = methodName;
            arrayElement.modifier = "public";
            needToAddToArray = false;
            break;
        }
        else {
            needToAddToArray = true;
        }
        }

        if (0 == program.blazeService.length || needToAddToArray == true) {
        newBlazeService.namespaceName = thisBlazeService.namespaceName;
        newBlazeService.className = thisBlazeService.className;
        newBlazeService.functionName = methodName;
        newBlazeService.modifier = "public";
        program.blazeService[program.blazeService.length] = newBlazeService;
        }
    }
    }
}

// NOTE: Integrate this
if (null == program.spring_beans) {
  init_spring();
}

// Iterate through each known spring bean and add the flex-remoting-enabled ones to the program.blazeService array
for each (var springBean in program.spring_beans) {
   if (springBean.flexRemote == true) {
       // alert("adding known spring bean "+springBean.className+" to blazeService array");
       // Add this bean to the program.blazeService array
       var thisBlazeService = new Object();
       thisBlazeService.className = springBean.className;
       thisBlazeService.namespaceName = springBean.namespaceName;
       thisBlazeService.modifier = "public";

       if (springBean.functionNamesInclude == null)
      thisBlazeService.functionName = "";
       else {
       // We have a string of include methods in an array
       var includeMethods = "";
       for each (var methodName in springBean.functionNamesInclude) {
           if (includeMethods.length == 0)
           includeMethods = methodName;
           else {
           includeMethods += "|";
           includeMethods += methodName;
           }
       }
       thisBlazeService.functionName = includeMethods;
       }

       // Consider Exclusions

       if (springBean.functionNamesExclude != null) {
      var excludedMethods = "";
      for each (var methodName in springBean.functionNamesExclude) {
          if (excludedMethods.length == 0)
          excludedMethods = methodName;
          else {
          excludedMethods += "|";
          excludedMethods += methodName;
          }
      }

      if (excludedMethods.length > 0) {
          if (thisBlazeService.functionName.length > 0)
         thisBlazeService.functionName += "|";

          thisBlazeService.functionName += "[^(" + excludedMethods + ")]";
      }
       }


       if (program.blazeService == null)
       program.blazeService = new Array();

       // alert("thisBlazeService (className: "+thisBlazeService.className+"; "+"namespace: "+thisBlazeService.namespaceName+"; "+"modifier: "+thisBlazeService.modifier+"; "+"methods: "+thisBlazeService.functionName+" )");
       program.blazeService[program.blazeService.length] = thisBlazeService;
   }
}

// run the script only if it is an Android app
if (null == program.android_permissions && true == JavaUtils.isAndroidApp()) {
  dbg("java: INITIALIZING ANDROID PERMISSIONS");
  init_android_permissions();
}
else {
  dbg("core_android: ANDROID PERMISSIONs HAVE ALREADY BEEN INITIALIZED OR THIS IS NOT AN ANDROID APP");
}

//
// Set up data structures for android manifest
//
function init_android_permissions() {
  var elements = new Namespace("");
  var attributens = new Namespace("http://schemas.android.com/apk/res/android");
  var pCount = 0;
  var aCount = 0;
  var sCount = 0;
  var prCount = 0;
  var mCount = 0;
  var nsACount = 0;
  var nsRCount = 0;
  var sRCount = 0;
  var dACount = 0;
  var dRCount = 0;
  var dSCount = 0;
  var sACount = 0;

  program.android_permissions = new Array();
  program.android_activities = new Array();
  program.android_services = new Array();
  program.android_protected_receivers = new Array();
  program.android_mixed_receivers = new Array();
  program.android_has_non_standard_actionA = new Array();
  program.android_has_non_standard_actionR = new Array();
  program.android_has_standard_only_actionA = new Array();
  program.android_has_standard_only_actionR = new Array();
  program.android_has_data_tagA = new Array();
  program.android_has_data_tagR = new Array();
  program.android_has_data_tagS = new Array();
  program.android_metadata = new Array();
  program.android_exported_activities = new Array();
  program.android_exported_receivers = new Array();
  program.android_exported_services = new Array();

  for (var filename in program.xml) {
    var cfg = program.xml[filename];
    if (null == cfg.name() || "manifest" != cfg.name().localName) {
      continue;
    }
    var shortName = String(filename).replace(/\\/g, "/");
    shortName = shortName.substring(shortName.lastIndexOf("/")+1);
    dbg("filename: " + filename);
    dbg("shortName: " + shortName);
    program.android_manifest = filename;

    // alert(String(cfg.@elements::["package"]));
    var packageName = cfg.@elements::["package"];
    // alert(packageName);

    // collect application metadata
    for each (var j in cfg..elements::["application"]) {
      collect_metadata("global", j);
    }

    //determine Activity component names
    for each (var j in cfg..elements::["activity"]) {
      if (false == isDeclared(String(j.@attributens::name))) {
        var activity=String(j.@attributens::name);
        var fullActivity="";
        // alert(String(j.@attributens::name));
        if (activity.charAt(0).equals('.')) {
          fullActivity=packageName+activity;
        }
        else {
          fullActivity=activity;
        }
        // alert(activity);

        program.android_activities[aCount++]=fullActivity;
        // collect activity metadata
        collect_metadata(fullActivity, j);

        // Check out if it is an exported activity
        var exported = false
        var exported_flag = String(j.@attributens::exported)
        if (exported_flag !== "" && exported_flag !== undefined && exported_flag !== null) {
          if (exported_flag.toLowerCase() == "true") exported = true;
        } else if (j.elements::["intent-filter"] !== null && j.elements::["intent-filter"] !== undefined) {
          if (j.elements::["intent-filter"].children().length() > 0) exported = true;
        }
        if (exported) program.android_exported_activities[program.android_exported_activities.length++] = fullActivity;

        //finds components that have a nonStandard action
        var nonStandardActionCount=0;
        var standardActionCount=0;
        for each (var i in j..elements::["action"]) {
          if (program.android_standard_activity_action_array.indexOf(String(i.@attributens::name))==-1)
          {
            nonStandardActionCount+=1;
          }
          else {
            standardActionCount+=1;
          }
        }
        if (nonStandardActionCount>0)
        {
          program.android_has_non_standard_actionA[nsACount++]=activity;
        }

        // finds components with only standard actions
        if (nonStandardActionCount==0 && standardActionCount > 0) {
          program.android_has_standard_only_actionA[sACount++]=activity;
        }

        //finds components that have a data tag
        var dataCount=0;
        for each (var i in j..elements::["data"]) {
          dataCount+=1;
        }
        if (dataCount>0)
        {
          program.android_has_data_tagA[dACount++]=activity;
        }
      }
    }

    for each (var j in cfg..elements::["activity-alias"]) {
      if (false == isDeclared(String(j.@attributens::name)))
      {
        var activity=String(j.@attributens::name);

        // Check out if it is an exported activity
        var fullActivity="";
        if (activity.charAt(0).equals('.')) {
          fullActivity=packageName+activity;
        }
        else {
          fullActivity=activity;
        }
        var exported = false
        var exported_flag = String(j.@attributens::exported)
        if (exported_flag !== "" && exported_flag !== undefined && exported_flag !== null) {
          if (exported_flag.toLowerCase() == "true") exported = true;
        } else if (j.elements::["intent-filter"] !== null && j.elements::["intent-filter"] !== undefined) {
          if (j.elements::["intent-filter"].children().length() > 0) exported = true;
        }
        if (exported) program.android_exported_activities[program.android_exported_activities.length++] = fullActivity;

        // collect activity alias metadata
        collect_metadata(activity, j);

        //finds components that have a nonStandard action
        var nonStandardActionCount=0;
        var standardActionCount=0;
        for each (var i in j..elements::["action"]) {
          if (program.android_standard_activity_action_array.indexOf(String(i.@attributens::name))==-1)
          {
            nonStandardActionCount+=1;
          }
          else {
            standardActionCount+=1;
          }
        }
        if (nonStandardActionCount>0)
        {
          program.android_has_non_standard_actionA[nsACount++]=activity;
        }

        // finds components with only standard actions
        if (nonStandardActionCount==0 && standardActionCount > 0) {
          program.android_has_standard_only_actionA[sACount++]=activity;
        }

        //finds components that have a data tag
        var dataCount=0;
        for each (var i in j..elements::["data"]) {
          dataCount+=1;
        }
        if (dataCount>0)
        {
          program.android_has_data_tagA[dACount++]=activity;
        }
      }
    }

    //determine Service component names
    for each (var j in cfg..elements::["service"]) {
      if (false == isDeclared(String(j.@attributens::name)))
      {
        var service=String(j.@attributens::name);
        var fullService="";
        // alert(String(j.@attributens::name));
        if (service.charAt(0).equals('.'))
        {
          fullService=packageName+service;
        } else {
          fullService=service;
        }

        // Check out if it is an exported service
        var exported = false
        var exported_flag = String(j.@attributens::exported)
        if (exported_flag !== "" && exported_flag !== undefined && exported_flag !== null) {
          if (exported_flag.toLowerCase() == "true") exported = true;
        } else if (j.elements::["intent-filter"] !== null && j.elements::["intent-filter"] !== undefined) {
          if (j.elements::["intent-filter"].children().length() > 0) exported = true;
        }
        if (exported) program.android_exported_services[program.android_exported_services.length++] = fullService;

        program.android_services[sCount++]=fullService;
        // collect service metadata
        collect_metadata(fullService, j);


        //finds components that have a data tag
        var dataCount=0;
        for each (var i in j..elements::["data"]) {
          dataCount+=1;
        }
        if (dataCount>0)
        {
          program.android_has_data_tagS[dSCount++]=service;
        }
      }
    }

    for each (var j in cfg..elements::["provider"]) {
      if (false == isDeclared(String(j.@attributens::name)))
      {
        var provider=String(j.@attributens::name);
        var fullProvider="";
        if (provider.charAt(0).equals('.'))
        {
          fullProvider=packageName+provider;
        } else {
          fullProvider=provider;
        }

        // collect provider metadata
        collect_metadata(fullProvider, j);

      }
    }

    //determine components with only protected Broadcasts, mixed protected/non-protected Broadcasts, data tags, and nonStandard actions
    for each (var j in cfg..elements::["receiver"]) {
      if (false == isDeclared(String(j.@attributens::name)))
      {
        var receiver=String(j.@attributens::name);
        var fullReceiver="";
        if (receiver.charAt(0).equals('.')) {
          fullReceiver=packageName+receiver;
        } else {
          fullReceiver=receiver;
        }

        // Check out if it is an exported receivers
        var exported = false
        var exported_flag = String(j.@attributens::exported)
        if (exported_flag !== "" && exported_flag !== undefined && exported_flag !== null) {
          if (exported_flag.toLowerCase() == "true") exported = true;
        } else if (j.elements::["intent-filter"] !== null && j.elements::["intent-filter"] !== undefined) {
          if (j.elements::["intent-filter"].children().length() > 0) exported = true;
        }
        if (exported) program.android_exported_receivers[program.android_exported_receivers.length++] = fullReceiver;

        // collect activity metadata
        collect_metadata(fullReceiver, j);

        var protectedCount = 0;
        var totalCount = 0;
        var nonStandardActionCount=0;

        for each (var i in j..elements::["action"]) {
          totalCount+=1;
          if (program.android_protected_action_array.indexOf(String(i.@attributens::name))!=-1)
          {
            protectedCount+=1;
          }
          if (program.android_standard_receiver_action_array.indexOf(String(i.@attributens::name))==-1)
          {
            nonStandardActionCount+=1;
          }
        }

        if (totalCount > protectedCount && protectedCount != 0)
        {
          program.android_mixed_receivers[mCount++]=receiver;
        }
        if (protectedCount == totalCount && protectedCount>0)
        {
          program.android_protected_receivers[prCount++]=receiver;
        }
        if (nonStandardActionCount>0)
        {
          program.android_has_non_standard_actionR[nsRCount++]=receiver;
        }

        // finds components with only standard(protected + non protected) actions
        if (nonStandardActionCount==0) {
          program.android_has_standard_only_actionR[sRCount++]=receiver;
        }

        var dataCount=0;
        for each (var i in j..elements::["data"]) {
          dataCount+=1;
        }
        if (dataCount>0)
        {
          program.android_has_data_tagR[dRCount++]=receiver;
        }

      }
    }

    for each (var j in cfg..elements::["uses-permission"]) {
      if (false == isDeclared(String(j.@attributens::name))) {
        dbg("permission: " + String(j.@attributens::name));
        program.android_permissions[pCount++] = String(j.@attributens::name);
      }
    }
    for each (var j in cfg..elements::["uses-permission-sdk-23"]) {
      if (false == isDeclared(String(j.@attributens::name))) {
        dbg("permission: " + String(j.@attributens::name));
        program.android_permissions[pCount++] = String(j.@attributens::name);
      }
    }
  }
}

// check whether we already know of this permission
function isDeclared(pname) {
  if ("" == pname) {
    return true;
  }

  for each (var i in program.android_permissions) {
    if (i == pname) {
      return true;
    }
  }
  return false;
}

// figures out whether whether AndroidManifest.xml contains a permission
// This method is uwed in scripted structural rules
function doesManifestContain(name) {
  for each (var p in program.android_permissions) {
    if (p == name) {
      return true;
    }
  }
  return false;
}

function collect_metadata(component, element) {
  // Collect meta-data
  // application, x activity, provider, x receiver, x service, x activity-alias
  var elements = new Namespace("");
  var attributens = new Namespace("http://schemas.android.com/apk/res/android");
  var mdata_vars = new Array();
  // alert("---> " + component);
  for each (var i in element.elements::["meta-data"]) {
    var mdata = new Object();
    mdata['name'] = String(i.@attributens::name);
    mdata['value'] = String(i.@attributens::value);
    mdata['resource'] = String(i.@attributens::resource);
    mdata_vars[mdata_vars.length] = mdata;
    // alert('name: ' + mdata['name']);
    // alert('value: ' + mdata['value']);
  }
  // Load component from nametable, if it fails put it in general bucket
  if (component !== "global") {
    var actualClass = null;
    var dotIndex = component.lastIndexOf(".");
    if (dotIndex > 0) {
      actualClass = getClassByName(component.substring(0, dotIndex), component.substr(dotIndex+1), Platform.ANDROID);
    } else {
      actualClass = getClassByFullName(component, Platform.ANDROID);
    }
    if (null === actualClass || actualClass.getName() == "[UnknownType]") component = "global";
  }
  if (mdata_vars.length > 0) {
    // alert(mdata_vars.length);
    program.android_metadata[component] = mdata_vars;
  }
}

