// Functions
function parsePOMDependencies(filePath) {
    // TODO: can we get line info from E4X nodes?
    var result = {};
    var content = '';
    try {
        content = readFile(filePath);
    } catch (err) {
        log("Error reading file "+filePath);
        return result;
    }
    try {
        var xml = new XML(content);
        // Fetch parent artifact as a dependency
        for each (var dep in xml..*::parent) {
            var group = String(dep.*::groupId.text());
            var artifact = String(dep.*::artifactId.text());
            var version = String(dep.*::version.text());
            if (version === "") version = "undefined"
            if (group !== "" && artifact !== "")
            result[group + ":" + artifact + ":" + version] = filePath + ":1"
        }
        // Fetch dependency info
        for each (var dep in xml..*::dependency) {
            var group = String(dep.*::groupId.text());
            var artifact = String(dep.*::artifactId.text());
            var version = String(dep.*::version.text());
            if (version === "") version = "undefined"
            if (group !== "" && artifact !== "")
            result[group + ":" + artifact + ":" + version] = filePath + ":1"
        }
        return result;
    } catch (err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
        return result;
    }
}

function parsePOMProperties(filePath) {
    var result = {};
    var content = '';
    try {
        content = readFile(filePath);
    } catch (err) {
        log("Error reading file "+filePath);
        return result;
    }
    try {
        var xml = new XML(content);
        for each (var prop in xml..*::properties.children()) {
            var name = String(prop.name().localName);
            var value = String(prop.text());
            if (name !== "" && value !== "")
            // Include filepath to track different versions across pom.xml files
            result[filePath.replace(":", "") + ":" + name] = value;
        }
        return result;
    } catch (err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
        return result;
    }
}

function resolvePOMDependencies(deps, props) {
    // Resolve maven properties into artifact versions
    var depsToRemove = [];
    var propsToRemove = [];
    var resultDeps = {};
    var resultProps = {};

    for (var dep in deps) {
        var path = deps[dep];
        var group = dep.split(":")[0];
        var artifact = dep.split(":")[1];
        var version = dep.split(":")[2];
        if (version.indexOf("${") === 0) {
            for (var prop in props) {
                propName = prop.split(":")[1]
                if (version === "${" + propName + "}") {
                    version = props[propName];
                    var key = [group, artifact, version].join(":");
                    depsToRemove.push(dep);
                    propsToRemove.push(prop)
                    deps[key] = path;
                }
            }
        }
    }
    var result = {};
    for (var dep in deps) {
        if (depsToRemove.indexOf(dep) == -1) {
            resultDeps[dep] = deps[dep];
        }
    }
    for (var prop in props) {
        if (propsToRemove.indexOf(prop) == -1) {
            resultProps[prop] = props[prop];
        }
    }
    result["dependencies"] = resultDeps;
    result["properties"] = resultProps;
    return result;
}

function parseGradleDependencies(filePath) {
    var result = {};
    var content = '';
    try {
        content = readFile(filePath);
    } catch (err) {
        log("Error reading file "+filePath);
        return result;
    }
    var lines = content.split("\n");
    // compile 'org.springframework.boot:spring-boot-starter-actuator'
    var depRegex = /^\s*\w+[\(\s]+['"]([^'"]+)['"][\)\s]*$/;
    // compile group: 'org.springframework.boot', name: 'spring-boot-devtools', version: '2.2.0.RELEASE'
    var depRegex2 = /^\s*\w+\s+group:\s+['"]([^'"]+)['"]\s*,\s*name:\s+['"]([^'"]+)['"]\s*,\s*version:\s+['"]([^'"]+)['"]\s*$/;
    var pluginRegex = /^\s*id[\(\s]+['"]([^'"]+)['"][\)\s]+version[\(\s]+['"]([^'"]+)['"].*$/;
    var lineNum = 1;
    var stateStack = [];
    for each (var line in lines) {
        // FSM
        if (line.match(/^\s*plugins\s*{\s*$/)) {
            stateStack.push("plugins")
        } else if (line.match(/^\s*dependencies\s*{\s*$/)) {
            stateStack.push("dependencies")
        } else if (line.match(/.*{\s*$/)) {
            stateStack.push("unknown")
        } else if (line.match(/^\s*}\s*$/)) {
            var s = stateStack.pop()
            // Plugins block
        } else if (stateStack.slice(-1)[0] === "plugins") {
            if (line.match(pluginRegex) !== null) {
                var artifact = line.match(pluginRegex)[1];
                var version= line.match(pluginRegex)[2];
                // plugins dont have a group and artifact, so making one empty
                result[artifact + "::" + version] = filePath + ":" + String(lineNum);
            }
            // Dependencies
        } else if (stateStack.slice(-1)[0] === "dependencies") {
            if (line.match(depRegex) !== null) {
                var dep = line.match(depRegex)[1];
                var group = dep.split(":")[0]
                var artifact = dep.split(":")[1]
                if (dep.split(":").length == 2) {
                    var version = "undefined"
                } else if (dep.split(":").length == 3) {
                    var version = dep.split(":")[2]
                } else throw "Incorrect dependency " + dep.split(":").length + " " + dep
                result[group + ":" + artifact + ":" + version] = filePath + ":" + String(lineNum);
            } else if (line.match(depRegex2) !== null) {
                var group = line.match(depRegex2)[1];
                var artifact = line.match(depRegex2)[2];
                var version = line.match(depRegex2)[3];
                result[group + ":" + artifact + ":" + version] = filePath + ":" + String(lineNum);
            }
        }
        lineNum++;
    }
    return result;
}

function parseGradleProperties(filePath) {
    var result = {};
    var content = '';
    try {
        content = readFile(filePath);
    } catch (err) {
        log("Error reading file "+filePath);
        return result;
    }
    var lines = content.split("\n");
    var state = "general"; 
    var propRegex = /^\s*([a-zA-Z0-9_-]+)\s*=\s*['"]([^'"]+)['"]\s*$/;
    // project.ext.springVersion7 = "5.0.3.RELEASE"
    var propDecl1 = /^\s*ext\.([a-zA-Z0-9_-]+)\s*=\s*['"]([^'"]+)['"]\s*$/;
    // project.ext["springVersion7"] = "5.0.3.RELEASE"
    var propDecl2 = /^\s*ext\[['"]([^'"]+)['"]\]\s*=\s*['"]([^'"]+)['"]\s*$/;
    // ext.set("springVersion5", "5.0.3.RELEASE")
    var propDecl3 = /^\s*ext\.set\(['"]([^'"]+)['"]\s*,\s*['"]([^'"]+)['"]\)\s*$/;
    for each (var line in lines) {
        line = line.replace("project.ext", "ext")
        if (line.match(/^\s*(project\.)?ext\s*{\s*$/)) {
            state = "properties";           
        } else if (state === "properties" && line.match(/^\s*}\s*$/)) {
            state = "general";
        } else if (state === "properties") {
            // ext blocks
            if (line.match(propRegex) !== null) {
                var name = line.match(propRegex)[1];
                var value = line.match(propRegex)[2];
                if (name !== "" && value !== "") result[name] = value;
            }
        } else if (line.match(propDecl1)) {
            var name = line.match(propDecl1)[1];
            var value = line.match(propDecl1)[2];
            if (name !== "" && value !== "") result[name] = value;
        } else if (line.match(propDecl2)) {
            var name = line.match(propDecl2)[1];
            var value = line.match(propDecl2)[2];
            if (name !== "" && value !== "") result[name] = value;
        } else if (line.match(propDecl3)) {
            var name = line.match(propDecl3)[1];
            var value = line.match(propDecl3)[2];
            if (name !== "" && value !== "") result[name] = value;
        }
    }
    return result;
}

function resolveGradleDependencies(deps, props) {
    // Resolve gradle extra properties in artifact versions
    var depsToRemove = [];
    var propsToRemove = [];
    var resultDeps = {};
    var resultProps = {};
    for (var dep in deps) {
        var path = deps[dep];
        var group = dep.split(":")[0];
        var artifact = dep.split(":")[1];
        var version = dep.split(":")[2];
        if (version.indexOf("$") === 0) {
            version = version.replace("$project.", "$")
            for (var prop in props) {
                if (version === "$" + prop) {
                    version = props[prop];
                    var key = [group, artifact, version].join(":");
                    depsToRemove.push(dep);
                    propsToRemove.push(prop)
                    deps[key] = path;
                }
            }
        }
    }
    var result = {};
    for (var dep in deps) {
        if (depsToRemove.indexOf(dep) == -1) {
            resultDeps[dep] = deps[dep];
        }
    }
    for (var prop in props) {
        if (propsToRemove.indexOf(prop) == -1) {
            resultProps[prop] = props[prop];
        }
    }
    result["dependencies"] = resultDeps;
    result["properties"] = resultProps;
    return result;
}

// Main program
var dependencies = {};
var project_properties = {};
var allFiles = getAllProgramFileNames();
for each (var f in allFiles) {
    try {
        var tmp_properties = {};
        var tmp_dependencies = {};

        if (f.toLowerCase().endsWith("pom.xml")) {
            tmp_properties = parsePOMProperties(f);
            tmp_dependencies = parsePOMDependencies(f);
            tmp_dependencies = resolvePOMDependencies(tmp_dependencies, tmp_properties)
        } else if (f.toLowerCase().endsWith("build.gradle")) {
            tmp_properties = parseGradleProperties(f);
            tmp_dependencies = parseGradleDependencies(f);
            tmp_dependencies = resolveGradleDependencies(tmp_dependencies, tmp_properties)
        }
        for (var dep in tmp_dependencies["dependencies"]) {
            dependencies[dep] = tmp_dependencies["dependencies"][dep];
        }
        for (var prop in tmp_dependencies["properties"]) {
            project_properties[prop] = tmp_dependencies["properties"][prop];
        }
    } catch (err) {
        warn_internal("Error parsing build scripts: " + err);
    }
}
if (null != dependencies) {
    persistObject("program.dependencies", dependencies);
}
if (null != project_properties) {
    persistObject("program.properties", project_properties);
}

// NOTE: Integrate this
var defaultNamespace = new Namespace("");
var axisServiceCount = 0;

for each (var webConfigXMLFile in program.xml) {
    if (null == webConfigXMLFile.name() || (webConfigXMLFile.name().length == 0) || (null == webConfigXMLFile.name().localName.match("configuration"))) {
        continue;
    }

    var currentServiceElement = 0;
    var targetNode = null;

    targetNode = webConfigXMLFile..defaultNamespace::["system.web"]..defaultNamespace::["httpRuntime"];

    for each (var runtimeDescriptor in targetNode) {

        var dotNetEncodingClass = new Object();
        dotNetEncodingClass.className = "";
        dotNetEncodingClass.namespaceName = "";

        // Verify that this is the right runtime element we are looking for
        if (!runtimeDescriptor.hasOwnProperty("@encoderType"))
            continue;

        var fullyQualifiedName = String(runtimeDescriptor.attribute("encoderType"));
        if (!fullyQualifiedName || fullyQualifiedName.length == 0)
            continue;

        // Parse the fully qualified name
        var nameComponents = fullyQualifiedName.split(/[, \n]+/);

        var fullyQualifiedClass = String(nameComponents[0]);
        if (fullyQualifiedClass == null || fullyQualifiedClass.length == 0)
            continue;

        var namespaceSeperatorIndex = fullyQualifiedClass.lastIndexOf(".");
        if (namespaceSeperatorIndex == -1) {
            dotNetEncodingClass.namespaceName = "";
            }
        else {
             dotNetEncodingClass.namespaceName = fullyQualifiedClass.substring(0, namespaceSeperatorIndex);
             dotNetEncodingClass.className = fullyQualifiedClass.substring(namespaceSeperatorIndex + 1);
             }

        // make sure we're dealing with a valid dotNet package and class names
        if (false == isValidDotnetNamespace(dotNetEncodingClass.namespaceName) || false == isValidDotnetIdentifier(dotNetEncodingClass.className)) {
            continue;
            }

        dotNetEncodingClass.assemblyName = nameComponents[1];
        dotNetEncodingClass.assemblyVersion = nameComponents[2];
        dotNetEncodingClass.assemblyCulture = nameComponents[3];
        dotNetEncodingClass.assemblyPublicKeyToken = nameComponents[4];
        program.dotNetCustomEncodingClass = dotNetEncodingClass;
        persistObject("program.dotNetCustomEncodingClass", program.dotNetCustomEncodingClass);
     }
}

        //
        // Set up data structures for DWR
        // This script relies on scrips named faces_config, struts1_config, and spring, so
        // it needs to appear last in the rulepack or rules file
        //

        function init_dwr() {
          var ns = new Namespace("");
          program.dwrSources = new Array();     // contains DWR entrypoints info
          var dwrSourcesCount = 0;

          for each (var cfg in program.xml) {
            if (cfg.name() != "dwr") {
              continue;
            }

            // iterate over all the creators
            for each (var j in cfg..ns::create) {
//alert("here");
              var thisDWRSource = new Object();
              thisDWRSource.creator = String(j["@creator"]);
              // handles this case: <create creator="new" javascript="ApartmentDAO" class="dwr.sample.ApartmentDAO">
              var classAttr = String(j["@class"]);
//alert("classAttr: " + classAttr);
              if (null == classAttr || 0 == classAttr.length) {
            // handles this case: <create creator="new" javascript="ApartmentDAO"><param name="class" value="dwr.sample.ApartmentDAO" />
            var paramElement = j.ns::param.(@name == "class");
//alert("paramElement: " + paramElement);
            classAttr = String(paramElement["@value"]);
              }
              if (null == classAttr || 0 == classAttr.length) {
            if (thisDWRSource.creator == "spring") {
              // for spring creator, get class name from the relevant spring beans
              var paramElement = j.ns::param.(@name == "beanName");
              classAttr = getSpringBeansInfo(String(paramElement["@value"]));
            }
            if (thisDWRSource.creator == "struts") {
              // for struts creator, get class name from the relevant form beans
              var paramElement = j.ns::param.(@name == "formBean");
              classAttr = getFormBeansInfo(String(paramElement["@value"]));
//alert("using struts: " + classAttr);
            }
            if (thisDWRSource.creator == "jsf") {
              // for jsf creator, get class name from the relevant jsf beans
              var paramElement = j.ns::param.(@name == "managedBeanName");
              classAttr = getJSFBeansInfo(String(paramElement["@value"]));
//alert("using jsf: " + classAttr);
            }
              }
              // if we are unable to determine the name of the class, stop doing anything with the current creator
              // and go on to the next one
              if (null == classAttr || 0 == classAttr.length || false == JavaUtils.isValidPackageName(classAttr)) {
            continue;
              }

              // parse the full class name into the class name and a namespace name
              var dotIndex = classAttr.lastIndexOf(".");
              thisDWRSource.namespaceName = classAttr.substring(0, dotIndex);
//alert(thisDWRSource.namespaceName);
              thisDWRSource.className = classAttr.substr(dotIndex+1);
//alert(thisDWRSource.className);

              // collect information about the methods to be included
              thisDWRSource.functionNamesInclude = new Array();
              var functionNamesIncludeCount = 0;
//alert("right before the loop: " + j.ns::include);
              for each (var k in j.ns::include) {
//alert("method:" + k["@method"]);
            var functionNameInclude = String(k["@method"]);

            // make sure we're dealing with valid Java identifier
            if (JavaUtils.isValidIdentifier(functionNameInclude)) {
              thisDWRSource.functionNamesInclude[functionNamesIncludeCount++] = functionNameInclude;
            }
//alert(thisDWRSource.functionNamesInclude[functionNamesIncludeCount-1]);
              }

              // collect information about the methods to be excluded
              thisDWRSource.functionNamesExclude = new Array();
              var functionNamesExcludeCount = 0;
//alert("right before the loop: " + j.ns::exclude);
              for each (var m in j.ns::exclude) {
//alert("method:" + m["@method"]);
            var functionNameExclude = String(m["@method"]);

            // make sure we're dealing with valid Java identifier
            if (JavaUtils.isValidIdentifier(functionNameExclude)) {
              thisDWRSource.functionNamesExclude[functionNamesExcludeCount++] = functionNameExclude;
            }
//alert(thisDWRSource.functionNamesExclude[functionNamesExcludeCount-1]);
              }

              // if the list of excluded methods is specified, or if no methods are specified at all, included function name is .*
              if ((0 < functionNamesExcludeCount) ||
              (0 == functionNamesIncludeCount && 0 == functionNamesExcludeCount)) {
            thisDWRSource.functionNamesInclude[functionNamesIncludeCount++] = ".*";
              }
              program.dwrSources[dwrSourcesCount++] = thisDWRSource;
            }
          }
        }

        // finds the spring bean with the right name and returns corresponding full class name
        function getSpringBeansInfo(springBeanName) {
          for each (var b in program.spring_beans) {
            if (b.name == springBeanName) {
              return b.clss;
            }
          }
          return "";
        }

        // finds the struts form bean with the right name and returns corresponding full class name
        function getFormBeansInfo(formBeanName) {
          for each (var b in program.form_beans) {
            if (null != b) {
              if (b.name == formBeanName) {
            return b.clss;
              }
            }
          }
          return "";
        }

        // finds the jsf managed bean with the right name and returns corresponding full class name
        function getJSFBeansInfo(jsfBeanName) {
          for each (var b in program.jsf_beans) {
            if (b.name == jsfBeanName) {
              return b.clss;
            }
          }
          return "";
        }

        if (null == program.dwrSources) {
//alert("java: INITIALIING DWR");
          init_dwr();
        }
        else {
//alert("java: DWR HAS ALREADY BEEN INITIALIZED");
        }
