//
// Get JSF version string from 'faces-config.xml'.
//
function getJSFVersion() {
    // In JSF 2.0+ 'faces-config.xml' is optional so default to '2.X'
    var JsfVersion =  "2.X";

    for each (var cfg in program.xml) {
        if (null == cfg.name() || null == cfg.name().localName.match("faces-config")) {
            continue;
        }


        // Check the JSF version attribute
        for each (var att in cfg.attributes()) {
            if (att.name() == "version") {
                // alert("att val: " + att.toString());

                // If version 2.X is seen in any faces-config file return 2.X
                if (null != att.toString().match("2.")) {
                    return att.toString();
                }
                else {
                    JsfVersion = att.toString()
                }
            }
        }
    }
    return JsfVersion
}

//
// Set up data structures for JSF managed beans
//
function collectJSFBeans(defaultJSFNamespace) {
  default xml namespace = new Namespace(defaultJSFNamespace);
  var ns = new Namespace(defaultJSFNamespace);

  for each (var cfg in program.xml) {
    //alert("in outer loop: " + cfg.name());
    if (null == cfg.name() || null == cfg.name().localName.match("faces-")) {
      continue;
    }

    // alert("in outer loop after if");
    for each (var j in cfg..ns::["managed-bean"]) {
      var thisBean = new Object();
      thisBean.name = String(j["managed-bean-name"]);
      thisBean.clss = String(j["managed-bean-class"]);

      // make sure we're dealing with valid Java package name
      if (JavaUtils.isValidPackageName(thisBean.clss)) {
        program.jsf_beans[jsfBeanCount++] = thisBean;
      }
    // alert("class: " + thisBean.clss);
    }
  }
}

// Assume isJsf2 to be true unless we can detect otherwise
program.isJsf2 = true;

if (null == program.jsf_beans) {
    // alert("java: INITIALIZING JSF");

    // Attempt to determine the version of JSF being used
    if (null == getJSFVersion().match("2.")) {
        // alert("jsf2 = false");
        program.isJsf2 = false;
    }
    else {
        // alert("jsf2 = true");
        program.isJsf2 = true;
    }


    program.jsf_beans = new Array();
    var jsfBeanCount = 0;
    collectJSFBeans("");                                   // handle JSF pre 1.2
    collectJSFBeans("http://java.sun.com/xml/ns/javaee");  // handle JSF 1.2
    collectJSFBeans("http://xmlns.jcp.org/xml/ns/javaee"); // handle JSF 2.2
}
else {
    // alert("java: JSF HAS ALREADY BEEN INITIALIZED");
}

if (null != program && null != program.isJsf2) {
  // alert("PERSISTING program.isJsf2 !!!!!!!!");
  persistObject("program.isJsf2", program.isJsf2);
}

