// Updated NpA2CfA pre-script to support the new 20.2.0 scenario for these rules which has the 
// default behavior being to ignore these rules and just run the legacy Nullpointer Analyzer.  
// Only if property com.fortify.sca.EnableLegacyNullpointerAnalyzer is explicitly set to "false" 
// will the ControlflowAnalyzer rules be used

var CFrules = "19EF0414-88CD-4882-82FC-BF3A89865666,4E28CEFE-1B94-4711-BF5A-EDA5D1B3E6BF";
var oldCFrules = "FC23EFCC-2EC3-4880-A534-F5318D0BDDA1";
var npaSet  = getProperty("com.fortify.sca.EnableLegacyNullpointerAnalyzer");
var legacyNullPointerAnalyzerEnabled = (npaSet == null || npaSet != "false") // rules only care whether it's explicitly disabled
var rulesToDisable = "";

if (!legacyNullPointerAnalyzerEnabled){
    setProperty("com.fortify.sca.EnableLegacyNullpointerAnalyzer", "false"); 
    warn_internal("Nullpointer analyzer disabled; Conrolflow rules for null dereference issues will be used")
    var disableInterprocSet = getProperty("com.fortify.sca.CFRulesDisableInterproc");
    var runNullpointerRulesIntra = disableInterprocSet == null;
    if (runNullpointerRulesIntra){
        warn_internal("restricting Controlflow rules " + CFrules + " to just INTRAprocedural analysis");
        setProperty("com.fortify.sca.CFRulesDisableInterproc", CFrules);
        // this is a kludge to set the null dereference Controlflow rules to be run INTRAprocedurally 
        // even if the "local only" Controlflow rule flag is not declared in the rule.  If such CfA flag 
        // is NOT declared we can specify an empty string as the value of "com.fortify.sca.CFRulesDisableInterproc"
        // and thus such rules will not be added to the value of this property and tey will be run INTERprocedurally.  
    }
    rulesToDisable = oldCFrules;
}else{
    rulesToDisable = CFrules;
}

var disabledCFrules = getProperty("com.fortify.sca.DisableCFRules");
if (disabledCFrules == null || disabledCFrules == "") {
    disabledCFrules = rulesToDisable;
} else {
    disabledCFrules = disabledCFrules + "," + rulesToDisable;
}
setProperty("com.fortify.sca.DisableCFRules", disabledCFrules);

// Updated NpA2CfA pre-script to support the new 20.2.0 scenario for these rules which has the 
// default behavior being to ignore these rules and just run the legacy Nullpointer Analyzer.  
// Only if property com.fortify.sca.EnableLegacyNullpointerAnalyzer is explicitly set to "false" 
// will the ControlflowAnalyzer rules be used

var CFrules = "A2D33B21-FE55-4C53-86C6-2AB5BF343738,7F4CC818-7525-440B-9C68-02267A80179A";
var oldCFrules = "9DD7BC55-7A23-4416-8ED7-72A7FB3FB773";
var npaSet  = getProperty("com.fortify.sca.EnableLegacyNullpointerAnalyzer");
var legacyNullPointerAnalyzerEnabled = (npaSet == null || npaSet != "false") // rules only care whether it's explicitly disabled
var rulesToDisable = "";

if (!legacyNullPointerAnalyzerEnabled){
    setProperty("com.fortify.sca.EnableLegacyNullpointerAnalyzer", "false"); 
    warn_internal("Nullpointer analyzer disabled; Conrolflow rules for null dereference issues will be used")
    var disableInterprocSet = getProperty("com.fortify.sca.CFRulesDisableInterproc");
    var runNullpointerRulesIntra = disableInterprocSet == null;
    if (runNullpointerRulesIntra){
        warn_internal("restricting Controlflow rules " + CFrules + " to just INTRAprocedural analysis");
        setProperty("com.fortify.sca.CFRulesDisableInterproc", CFrules);
        // this is a kludge to set the null dereference Controlflow rules to be run INTRAprocedurally 
        // even if the "local only" Controlflow rule flag is not declared in the rule.  If such CfA flag 
        // is NOT declared we can specify an empty string as the value of "com.fortify.sca.CFRulesDisableInterproc"
        // and thus such rules will not be added to the value of this property and tey will be run INTERprocedurally.  
    }
    rulesToDisable = oldCFrules;
}else{
    rulesToDisable = CFrules;
}

var disabledCFrules = getProperty("com.fortify.sca.DisableCFRules");
if (disabledCFrules == null || disabledCFrules == "") {
    disabledCFrules = rulesToDisable;
} else {
    disabledCFrules = disabledCFrules + "," + rulesToDisable;
}
setProperty("com.fortify.sca.DisableCFRules", disabledCFrules);

