var oans = new Namespace("http://xmlns.oracle.com/oa");
for (var pageFile in program.xml) {
  try {
    // check the root element
    var AM = String(new XML(program.xml[pageFile])["@amDefName"]);
    if (null == AM || 0 == AM.length) {
      // check child elements
      AM = String(new XML(program.xml[pageFile])..oans::*["@amDefName"]);
      if (null == AM || 0 == AM.length) {
        continue;
      }
    }

    // alert("AM before: " + AM);
    // need to figure out whether I need to handle backward slashes too
    // AM = AM.replace(/\./g, "/");
    // alert("AM after: " + AM);

