    if (null != testAM) {
      program.OA_Pages[pageFile] = testAM;
      getInfoAboutCOs(pageFile, testAM.fullclss);
    }
    else {
      getInfoAboutVOsAndEOs(pageFile, AM);
    }
    getInfoAboutInputsAndOutputs(pageFile);
  } catch(err){
    // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
  }
}

