    process_dict("", cfg.ns::["dict"], program.plist_ssl_urls_vars, /^(https|ftps):.*/i);
    process_dict("", cfg.ns::["dict"], program.plist_non_ssl_urls_vars, /^(http|ftp|gopher):.*/i);
    process_dict("", cfg.ns::["dict"], program.plist_file_urls_vars, /^file:.*/i);
}

