//
// Set up data structures for struts1 html inputs
//

function addStruts1Inputs(datastructure, struts1property) {
  var thisInput = new Object();
  thisInput.property = struts1property;

  // make sure we're dealing with valid Java identifiers
  if (JavaUtils.isValidIdentifier(thisInput.property)) {
    datastructure[datastructure.length] = thisInput;
  }
}

if (null == program.struts1Inputs || null == program.struts1PrivateInputs) {
  program.struts1Inputs = new Array();                     // contains struts1 input tags info
  program.struts1PrivateInputs = new Array();              // contains struts1 password tags info
  var struts1ns = new Namespace("/tags/struts-html");
  for each (var struts1file in program.cxml) {
    for each (var j in struts1file..struts1ns::form) {
      for each (var k in j.struts1ns::text) {
    addStruts1Inputs(program.struts1Inputs, String(k["@property"]));
      }
      for each (var k in j.struts1ns::password) {
    addStruts1Inputs(program.struts1Inputs, String(k["@property"]));
    addStruts1Inputs(program.struts1PrivateInputs, String(k["@property"]));
      }
      for each (var k in j.struts1ns::textarea) {
    addStruts1Inputs(program.struts1Inputs, String(k["@property"]));
      }
      for each (var k in j.struts1ns::hidden) {
    addStruts1Inputs(program.struts1Inputs, String(k["@property"]));
      }
    }
  }
}
else {
}

//
// Set up data structures for struts beans
//
function init_struts1() {
    var ns = new Namespace("");
    var beanCount = 0;
    var actionCount = 0;
    program.val_files = null;
    program.form_beans = new Array();
    program.struts1_actions = new Array();
    program.validation_forms = new Array();
    program.struts1_val_files = new Array();
    dbg("in struts1_config");
    for (var cfg in program.xml) {
        dbg("interating over program.xml");
        // look at struts-config.xml
        if (null != program.xml[cfg].name() && null != program.xml[cfg].name().localName.match("struts-config")) {
            dbg("found struts-config");
            for each (var j in program.xml[cfg]..ns::["form-bean"]) {
                dbg("iterating over form beans");
                var thisBean = new Object();
                thisBean.name = String(j["@name"]);
                thisBean.clss =  String(j["@type"]);
                thisBean.properties = new Array();
                thisBean.property_details = new Array();
                thisBean.fields = new Array();
                // thisBean.fileName = cfg;
                // thisBean.lineNumber = 0;
                for each (var p in j.ns::["form-property"]) {
                    dbg("iterating over form bean properties");
                    thisBean.properties[thisBean.properties.length] = String(p["@name"]);
                    var details = new Object();
                    details.name = String(p["@name"]);
                    details.type = String(p["@type"]);
                    // details.fileName = cfg;
                    // details.lineNumber = p.getLineNumber();
                    thisBean.property_details[thisBean.property_details.length] = details;
                }

                // make sure we're dealing with valid Java class name
                if (JavaUtils.isValidPackageName(thisBean.clss)) {
                    dbg("class is valid");
                    // do not store information about duplicate form beans because it will result in incorect analysis later on
                    if (null != program.form_beans[thisBean.name]) {
                        dbg("duplicate");
                        program.form_beans[thisBean.name] = null;
                    }
                    else {
                        dbg("saving the bean: " + thisBean.name);
                        program.form_beans[thisBean.name] = thisBean;
                    }
                }
            }

            for each (var k in program.xml[cfg]..ns::["action"]) {
                var thisAction = new Object();
                thisAction.name = String(k["@name"]);
                thisAction.path = String(k["@path"]);
                thisAction.fileName = cfg;
                thisAction.lineNumber = 0;
                program.struts1_actions[actionCount++] = thisAction;
            }

            dbg("PATHNAMES: " + program.xml[cfg]..ns::["plug-in"].(@className == "org.apache.struts.validator.ValidatorPlugIn").ns::["set-property"].(@property == "pathnames")["@value"]);
            program.val_files = String(program.xml[cfg]..ns::["plug-in"].(@className == "org.apache.struts.validator.ValidatorPlugIn").ns::["set-property"].(@property == "pathnames")["@value"]).split(",");
        }
    }

    for (var cfg in program.xml) {
        for each (var f in program.val_files) {
            dbg("going through valfiles");
            // trim the filename strings
            var templ = f.replace(/^\s*/, "").replace(/\s*$/, "");
            var tempw = templ.replace(/\//g, "\\");
            dbg("templ: " + templ);
            dbg("tempw: " + tempw)
            dbg("cfg: " +cfg);
            if (0 != templ.length && -1 != cfg.indexOf(templ)) {
                program.struts1_val_files[cfg] = program.xml[cfg];
                dbg("val file: " + cfg);
            }
            else if (0 != tempw.length && -1 != cfg.indexOf(tempw)) {
                program.struts1_val_files[cfg] = program.xml[cfg];
                dbg("val file: " + cfg);
            }
        }
    }

    for (cfgName in program.struts1_val_files) {
        var cfg = program.struts1_val_files[cfgName];
        // look at validation.xml
        // TODO: need to make sure that we look at a specific validation.xml file that is specified in the validator plug-in specification
        if ( null != cfg && null != cfg.name() && null != cfg.name().localName.match("form-validation")) {
            for each (var a in cfg..ns::["form"]) {
                var thisForm = new Object();
                thisForm.name = String(a["@name"]);
                thisForm.fileName = cfgName;
                thisForm.fields = new Array();
                for each (var b in a.ns::field) {
                    var lineNumber = 0;
                    thisForm.fields[String(b["@property"])] = lineNumber;
                }

                // do not store information about duplicate validation forms because this will result in incorrect analysis later on
                if (null != program.validation_forms[thisForm.name]) {
                    program.validation_forms[thisForm.name] = null;
                }
                else {
                    program.validation_forms[thisForm.name] = thisForm;
                }
            }
        }
    }
}

