}

        //
        // This function iterates over nested properties with the help of the
        // getter function return type information retrieved from the MetaTable.
        //
        function iterateOverNestedProperties(beanClass, inputValue) {
//alert("beanClass: " + beanClass);
//alert("inpuValue: " + inputValue);
          var props = inputValue.split(".");
          var cName = beanClass;
          for (var index = 0; index < props.length-1; index++) {
            var getter =  "get" + props[index].substr(0, 1).toUpperCase() + props[index].substr(1);
//alert("cName before: " + cName);
            cName = queryMetaTableForFunctionReturnType(cName, getter);
//alert("cName after: " + cName);
          }
          return cName;
        }

