     // Because of the bug in <= 3.7 scripting API, these two functions are put into a separate <Script/> element
     // The bug consisted in doing namespaceName + className (instead of namespaceName + "." + className) when actually looking up the types in the nameTable
     // The workaround for the bug is to pass "" for namespaceName and a full  name for the class
     // 3.7 version of this script does exactly this, while 3.9 version of the script assumes that the bug is fixed

    //
    // This funtion adds a label to a particular field of a class
    function addLabelToField(namespaceName, className, fieldName, labelToUse) {
//dbg("i am in addLabelToField: " + namespaceName + " : " + className + " : " + fieldName + " : " + labelToUse);
      if(typeof nameTable.getClassByName != 'undefined') {
//dbg("6666666666666666666666666666666");
        var beanClass = nameTable.getClassByName(namespaceName, className, "java");
        if (null != beanClass && '[UnknownType]' != beanClass.getName()) {
//dbg("class not null");
          var beanClassFields = beanClass.getFields();
          if (null != beanClassFields) {
//dbg("fields not null");
        for (var i = 0; i < beanClassFields.length; i++) {
//dbg("inside for loop");
          if (null != beanClassFields[i]) {
//dbg("field not null: " + beanClassFields[i].getName());
            if (beanClassFields[i].getName() == String(fieldName)) {
//dbg("in if after");
              beanClassFields[i].setLabel(labelToUse);
//dbg("i set label " + labelToUse + " to field " + fieldName + " of class " + className);
              break;
            }
          }
        }
          }
        }
      }
    }

    //
    // This funtion adds a label to all fields of a class
    function addLabelToFields(namespaceName, className, labelToUse) {
//dbg("adding label '" + labelToUse + "' to fields in namespace '" + namespaceName + "' and class '" + className + "'");
//alert("adding label '" + labelToUse + "' to fields in namespace '" + namespaceName + "' and class '" + className + "'");
      if(typeof nameTable.getClassByName != 'undefined') {
//dbg("in first if");
        var actionClass = nameTable.getClassByName(namespaceName, className, "java");
        if (null != actionClass && '[UnknownType]' != actionClass.getName()) {
//dbg("in second if: " + actionClass.getName());
          var actionClassFields = actionClass.getFields();
          if (null != actionClassFields) {
//dbg("in third if: " + actionClassFields.length);
        for (var i = 0; i < actionClassFields.length; i++) {
//dbg("here");
          if (null != actionClassFields[i]) {
//dbg("adding label '" + labelToUse + "' to field '" + actionClassFields[i].getName() + "' in '" + namespaceName + "." + className + "'");
//alert("adding label '" + labelToUse + "' to field '" + actionClassFields[i].getName() + "' in '" + namespaceName + "." + className + "'");
            actionClassFields[i].setLabel(labelToUse);
          }
        }
          }
        }
      }
    }

            // create the program object
            var program = init();

            function init() {
              if (null != sca.program) {
                //dbg("java: PROGRAM ALREADY EXISTS");
                return sca.program;
              }

              var program = new Object();
              program.xml = new Array();                       // contains real xml files
              program.cxml = new Array();                      // contains fake xml files
              var xmlFiles = getXMLConfigFileNames();
              //dbg("XML FILES: " + xmlFiles.toString());
              //dbg("XML FILES LENGTH: " + xmlFiles.length);
              var allFiles = getAllProgramFileNames();
              default xml namespace = new Namespace("");
    //dbg("BEFORE LOOP");
              for each (var filename in xmlFiles) {
    //dbg("IN LOOP");
                var contents = '';
                try {
                    contents = readFile(filename);
                } catch (err) {
                    log("Error reading file "+filename);
                    continue;
                }
                try {
                    if (contents.charAt(0) != '<') {
                          // Running into problems with xml files that begin with the character FEFF
                          // Apparently this is a standard way to say that the file is unicode, but
                          // it causes the Rhino XML parser to go nuts.  I'm going to zap the
                          // charater, and no doubt pay the price when some file that actually uses
                          // some fancy characters comes along. bvc
                          contents = contents.substring(1);
                    }
                    program.xml[filename] = new XML(contents);
                }
                catch (err) {
                    // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
                    // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
                }
              }

              for each (var f in allFiles) {
                try {
                  var contentXml = getXMLForContentFile(f);        // this gets all fake xml files
                  //var contentXml = readFile(f);                  // this gets all real xml files
    //dbg("Init Script: cxml file element: "+contentXml);
                  if(contentXml != null) {
                    program.cxml[f] = new XML(contentXml);
                  }
                }
                catch (err) {
                    // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
                    // log("Error processing file: " + f + ". Exception thrown was: " + err + ". Please review the file for any syntax errors.");
                }
              }
    //dbg("java: CREATED NEW PROGRAM");
              return program;
            }

            //
            // Parse web.xml for url extensions
            //
            function getURLExtensionFromFilterMapping(xmlnamespace, classname) {
              var sns = new Namespace(xmlnamespace);
              var actionExtensions = new Array();
              var actionExtensionsCount = 0;
              var urlPattern;

              // compute URL extensions
              for each (var configFile in program.xml) {
                if (null != configFile && null != configFile.name() && null != configFile.name().localName && null != configFile.name().localName.match("web-app")) {
                  for each (var def in configFile..sns::filter) {
                    if (def..sns::["filter-class"] == classname) {
                      for each (var mapping in configFile..sns::["filter-mapping"]) {
                        if (mapping..sns::["filter-name"] == def..sns::["filter-name"]) {
                          urlPattern = mapping..sns::["url-pattern"];
                          for each (var pattern in urlPattern) {
                            if (null != pattern.match(/\*\.+/)) {
                              actionExtensions[actionExtensionsCount++] = pattern.substring(1);
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
              return actionExtensions;
            }

            //
            // Parse web.xml for url extensions
            //
            function getURLExtensionFromServletMapping(xmlnamespace, classname) {
              var sns = new Namespace(xmlnamespace);
              var urlExtension = "";
              var urlRoot = "";
              var info = new Array();
              var counter = 0;

              // compute URL extensions
              for (var configFileName in program.xml) {
                dbg("configFileName: " + configFileName);
                dbg("other name: " + sns + "::web-app");
                if (null != program.xml[configFileName] && null != program.xml[configFileName].name() &&
                    null != program.xml[configFileName].name().localName && null != program.xml[configFileName].name().localName.match("web-app")) {
                  urlRoot = "";
                  var path = configFileName.replace(/\\/g, "/").split("/");
                  if (path[path.length-2] == "WEB-INF") {
                    var index = configFileName.lastIndexOf(path[path.length-2]);
                    urlRoot = configFileName.substring(0, index);
                    //dbg("urlRoot: " + urlRoot);
                  }
                  for each (var def in program.xml[configFileName]..sns::servlet) {
                    if (def..sns::["servlet-class"] == classname) {
                      for each (var mapping in program.xml[configFileName]..sns::["servlet-mapping"]) {
                        if (mapping..sns::["servlet-name"] == def..sns::["servlet-name"]) {
                          urlPattern = mapping..sns::["url-pattern"];
                          var roots = new Array();
                          for each (var pattern in urlPattern) {
                            if (null != pattern.match(/\*\.+/)) {
                              roots[roots.length] = pattern.substring(1);
                              counter++;
                            }
                          }
                          if (roots.length > 0){
                            info[urlRoot] = roots;
                          }
                        }
                      }
                    }
                  }
                }
              }
              if (0 == counter) {
                return null;
              }
              return info;
            }

            //
            // This function iterates over nested JSF properties with the help of the
            // getter function return type information retrieved from the MetaTable.
            //
            function iterateOverNestedProperties(beanClass, inputValue) {
              var props = getBeansAndProperty(inputValue);

              // getBeansAndProperty() makes sure that the contents of the returned array are valid Java identifiers, so we don't have to do more checks
              var cName = beanClass;
              for (var index = 1; index < props.length-1; index++) {
                var getter =  "get" + props[index].substr(0, 1).toUpperCase() + props[index].substr(1);
                cName = queryMetaTableForFunctionReturnType(cName, getter);
              }
              return cName;
            }

            function iterateOverFields(fieldsToUse, labelToUse, visited) {
                for(var i = 0; fieldsToUse != null && i < fieldsToUse.length; i++) {
                    propLabels(fieldsToUse[i], labelToUse, visited);
                }
            }

            function propLabels(fieldToUse, labelToUse, visited) {
                    visitField(fieldToUse, labelToUse, visited);
                    var fields = fieldToUse.getType().getFields();
                    for(var j = 0; fields != null && j < fields.length; j++) {
                            if (isVisited(fields[j], visited)) {
                                     continue;
                            }
                            else if(fields[j].getType().getFields() != null && fields[j].getType().getFields().length > 0) {
                                    propLabels(fields[j], labelToUse, visited);
                            }
                            else {
                                    visitField(fields[j], labelToUse, visited);
                            }
                    }
            }

            function getFieldID(field) {
                    return (field.getEnclosingClass().getPackageName() + "." + field.getEnclosingClass().getName() + "." + field.getName());
            }

            function visitField(field, labelToUse, visited) {
                    visited[getFieldID(field)] = true;
                    field.setLabel(labelToUse);
            }

            function isVisited(field, visited) {
                    return (getFieldID(field) in visited);
            }

            // Function to split fully qualified classname into namespace (ns) and className (clsName).
            function splitFullyQualifiedClsName (fullyQualifiedClsName) {
              var dotIndex = String(fullyQualifiedClsName).lastIndexOf(".");
              var returnObj = new Object();
              returnObj.ns = String(fullyQualifiedClsName).substring(0, dotIndex);
              returnObj.clsName = String(fullyQualifiedClsName).substr(dotIndex+1);
              return returnObj;
            }

        function addLabelToClass(namespaceName, className, labelToUse) {
            if(typeof nameTable.getClassByName != 'undefined') {
            var actionClass = nameTable.getClassByName(namespaceName, className, "java");
            if (null != actionClass && '[UnknownType]' != actionClass.getName()) {
            actionClass.setLabel(labelToUse);
            }
        }
}

