            for each (var k in j..struts2ns::hidden) {
                if (String(k["@key"]).length > 0) {
                    var dotIndex = String(k["@key"]).indexOf(".");
                    if (dotIndex > 0) {
                        var property = String(k["@key"]).substring(0, dotIndex);
                        addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), property);
                    }
                    else {
                        addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), String(k["@key"]));
                    }
                } else if (String(k["@name"]).length > 0) {
                    var dotIndex = String(k["@name"]).indexOf(".");
                    if (dotIndex > 0) {
                        var property = String(k["@name"]).substring(0, dotIndex);
                        addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), property);
                    }
                    else {
                        addStruts2Inputs(program.struts2HiddenInputs, String(j["@action"]), String(k["@name"]));
                    }
                }
            }

        }
    }

    addStruts2HiddenSources(program.struts2HiddenInputs);
}
else {
    dbg("java: STRUTS INPUTS AND SOURCES HAVE ALREADY BEEN INITIALIZED");
}


//
// Set up data structures for struts beans and actions
//
function init_struts2() {
    var ns = new Namespace("");
    program.struts_actions = new Array();
    for each (var cfg in program.xml) {
        dbg("in first for");
        if (cfg.name() != "struts") {
            continue;
        }

        // depending on the version, web.xml either uses default namespace or http://java.sun.com/xml/ns/j2ee
        var actionExtensions = getURLExtensionFromFilterMapping("", "org.apache.struts2.dispatcher.FilterDispatcher");
        if (0 == actionExtensions.length) {
            actionExtensions = getURLExtensionFromFilterMapping("http://java.sun.com/xml/ns/j2ee", "org.apache.struts2.dispatcher.FilterDispatcher");
        }
        if (0 == actionExtensions.length) {
            actionExtensions = getURLExtensionFromFilterMapping("http://xmlns.jcp.org/xml/ns/j2ee", "org.apache.struts2.dispatcher.FilterDispatcher");
        }
        dbg("actionExtensions: " + actionExtensions.toString());

        for each (var p in cfg..ns::["package"]) {
            var packageNamespace = String(p["@namespace"]);
            if ("/" != packageNamespace) {
                packageNamespace = packageNamespace + "/";
            }
            dbg("packageNamespace: " + packageNamespace);
            for each (var k in p..ns::action) {
                dbg("in second for");
                var thisAction = new Object();
                thisAction.name = String(k["@name"]);
                thisAction.clss = String(k["@class"]);
                thisAction.actionURLs = new Array();
                var actionURLCount = 0;
                for each (var actionExtension in actionExtensions) {
                    thisAction.actionURLs[actionURLCount++] = packageNamespace + thisAction.name + actionExtension;
                }
                dbg("actionURLs: " + thisAction.actionURLs.toString());
                var dotIndex = thisAction.clss.lastIndexOf(".");
                thisAction.namespaceName = thisAction.clss.substring(0, dotIndex);
                thisAction.className = thisAction.clss.substr(dotIndex+1);

                thisAction.actionResults = new Array();
                // fill actionForms array in struts2 script
                thisAction.actionForms = new Array();
                for each (var r in k..ns::["result"]) {
                    var result = String(r);
                    thisAction.actionResults[result] = result;
                    dbg("result: " + result);
                }

                addLabelToFields(thisAction.namespaceName, thisAction.className, "Struts2Source");

                // make sure we're dealing with valid Java package name
                if (null == k["@class"] || (null != thisAction.clss && JavaUtils.isValidPackageName(thisAction.clss))) {
                    program.struts_actions[thisAction.name] = thisAction;
                }
            }
        }
    }
}

//
// Set up data structures for struts2 actions that could be used for storing user input
//
function addStruts2Inputs(datastructure, struts2action, struts2name) {
    var thisInput = new Object();
    thisInput.action = struts2action;
    thisInput.property = struts2name;


    // make sure we're dealing with valid Java identifier
    if (JavaUtils.isValidIdentifier(thisInput.property)) {
        datastructure[datastructure.length] = thisInput;
    }
}

function addStruts2Sources(inputstructure) {
    for each (var j in program.struts_actions) {
        dbg("here in addStruts2Sources");
        for each (var i in inputstructure) {
            dbg("in for in addStruts2Sources");
            if (i.action == j.name) {
                dbg("in if in addStruts2Sources");
                var thisSource = new Object();
                thisSource.clss = j.clss;
                thisSource.fieldName = i.property;

                var dotIndex = j.clss.lastIndexOf(".");
                thisSource.namespaceName = j.clss.substring(0, dotIndex);
                thisSource.className = j.clss.substr(dotIndex+1);

                addLabelToField(thisSource.namespaceName, thisSource.className, thisSource.fieldName, "Struts2PrivateSource");
            }
        }
    }
}

// Add Struts 2 Hidden Source Labels
function addStruts2HiddenSources(inputstructure) {
    for each (var j in program.struts_actions) {
        dbg("here in addStruts2HiddenSources");
        for each (var i in inputstructure) {
            dbg("in for in addStruts2HiddenSources");
            if (i.action == j.name) {
                dbg("in if in addStruts2HiddenSources");
                var thisSource = new Object();
                thisSource.clss = j.clss;
                thisSource.fieldName = i.property;

                var dotIndex = j.clss.lastIndexOf(".");
                thisSource.namespaceName = j.clss.substring(0, dotIndex);
                thisSource.className = j.clss.substr(dotIndex+1);

                addLabelToField(thisSource.namespaceName, thisSource.className, thisSource.fieldName, "Struts2HiddenSource");
            }
        }
    }
}

