function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj !== null && prefix !== null && prefix !== "") {
        var labels = obj.getLabels();
        if (labels !== null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                        var value = String(l.substring(prefix.length));
                        if (value != null && value.length > 0) {
                                values[values.length++] = value;
                        }
                }
            }
        }
    }
    return values;
}
// From calls to MBeanServer.createMBean("com.acme.Foo"), extract the string literal and label the class as a JMX bean
