}

 function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj !== null && prefix !== null && prefix !== "") {
        var labels = obj.getLabels();
        if (labels !== null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                    var value = String(l.substring(prefix.length));
                    if (value != null && value.length > 0) {
                        values[values.length++] = value;
                    }
                }
            }
        }
    }
    return values;
}

function isAction(cls) {
    return cls != null && 
        (
            cls.endsWith("Action") ||
            cls == "org.springframework.webflow.action.FormAction" ||
            isSubClass(cls, "org.springframework.webflow.action.FormAction")
        );
}

function isCommand(cls) {
    return cls != null && 
        (
            cls.endsWith("Controller") ||
            isSubClass(cls, "org.springframework.web.servlet.mvc.BaseCommandController")
        );
}

function isExporter(cls) {
    return cls == "org.springframework.remoting.caucho.HessianServiceExporter" ||
            cls == "org.springframework.remoting.caucho.BurlapServiceExporter" ||
            cls == "org.springframework.remoting.httpinvoker.HttpInvokerServiceExporter" ||
            cls == "org.springframework.remoting.rmi.RmiServiceExporter" ||
            isSubClass(cls, "org.springframework.remoting.rmi.RmiServiceExporter") ||
            cls == "org.codehaus.xfire.spring.remoting.XFireExporter" ||
            isSubClass(cls, "org.codehaus.xfire.spring.remoting.XFireExporter") ||
            cls == "org.springframework.remoting.httpinvoker.HttpInvokerProxyFactoryBean" ||
            isSubClass(cls, "org.springframework.remoting.support.RemoteAccessor") ||
            isSubClass(cls, "org.springframework.remoting.support.RemoteExporter");
}

function markSensitiveField(field, visited) {
    var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedWebflowFormField");
    }
    if (!type.isPrimitive() && !key.match(/^(java|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    markSensitiveField(new_field, visited);
                }
            }
        }
    }
}

function initSpringLabeling() {

    var spring_beans = loadPersistedObject("program.spring_beans");

    // Complete spring bean references with convention and scanned components
    var spring_refs = loadPersistedObject("program.spring_refs");
    if (spring_refs !== null) {
        var classes = nameTable.getClassesByLabel("SpringBean", "java");
        if (classes !== null) {
            for each (var c in classes) {
                var name = String(c.getPackageName()) + "." + String(c.getName());
                var refs = extractLabelValues(c, "SpringBeanRef::");
                if (refs !== null && refs !== undefined && refs.length > 0) {
                    for each(var alias in refs) {
                        if (alias !== null && alias !== undefined && alias !== "") spring_refs[alias] = name;
                    }
                } else {
                    var ref = String(c.getName());
                    ref = ref.substr(0, 1).toLowerCase() + ref.substr(1);
                    if (spring_refs[ref] === null || spring_refs[ref] === undefined) {
                        spring_refs[ref] = name;
                    }
                }
            }
        }
    }

    // Add Spring beans refs to spring_beans
    for (var name in spring_refs) {
        var found = false;
        for each (var bean in spring_beans) {
            if (bean.name == name) {
                found = true;
                break;
            }
        }
        if (!found) {
            var thisBean = new Object();
            thisBean.name = name;
            thisBean.clss = spring_refs[name];
            spring_beans[spring_beans.length++] = thisBean;
        }
    }
    persistObject("program.spring_beans", spring_beans);

    // Process JMS listeners in jms namespace
    var spring_jms_listeners = loadPersistedObject("program.spring_jms_listeners");
    if (spring_jms_listeners !== null) {
        for (var ref in spring_jms_listeners) {
            if (ref !== null && ref !== undefined && ref != "") {
                var refclass = spring_refs[ref];
                var exposedmethods = spring_jms_listeners[ref];
                var listenerClass = nameTable.getClassByFullName(refclass, "java");
                if (listenerClass !== null && listenerClass !== undefined && listenerClass.getName() != "[UnknownType]") {
                    var methods = listenerClass.getMethods();
                    if (methods !== null) {
                        for each (var method in methods) {
                            if (method !== null && method !== undefined && method.getName() != "[UnknownType]") {
                                for each (var exposedmethod in exposedmethods) {
                                    if (method.getName() == exposedmethod) {
                                        method.setLabel("SpringJmsListenerMethod");
                                        break;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // Process JMS Listener Adapters (JavaConfig)
    var methods = nameTable.getMethodsByLabel("SpringJmsListenerAdapter", "java");
    if (methods !== null && methods !== undefined) {
        for each (var m in methods) {
            var cname = extractLabelValues(m, "SpringJmsListenerAdapter::ClassName::");
            var mname = extractLabelValues(m, "SpringJmsListenerAdapter::MethodName::");
            if (cname !== null && cname !== undefined && cname.length > 0) {
                var listenerClass = nameTable.getClassByFullName(cname, "java");
                if (listenerClass !== null && listenerClass !== undefined && listenerClass.getName() != "[UnknownType]") {
                    var dispatcher = null;
                    if (mname !== null && mname !== undefined && mname.length > 0) dispatcher = mname[0];
                    else dispatcher = "handleMessage";
                    for each (var lmethod in listenerClass.getMethods()) {
                        if (lmethod.getName() == dispatcher) {
                            lmethod.setLabel("SpringJmsListenerMethod");
                            break;
                        }
                    }
                }
            }
        }
    }

    // Process JMS Listener Adapters (XML)
    for each (var bean in spring_beans) {
        if (bean.isJMSListenerAdapter) {
            // Get listener class
            var listenerClass = null;
            if (bean.listener !== undefined && bean.listener !== null && bean.listener.length >0) {
                listenerClass = nameTable.getClassByFullName(bean.listener, "java");
            } else if (bean.listenerRef !== undefined && bean.listenerRef !== null && bean.listenerRef.length >0) {
                for (var ref in spring_refs) {
                    if (ref == bean.listenerRef) {
                        var he = splitFullyQualifiedClsName(spring_refs[ref]);
                        listenerClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                        break;
                    }
                }
            } else {
                for each (var propHolder in bean.propertyElements) {
                    if (propHolder.name == "delegate") {
                        for (var ref in spring_refs) {
                            if (ref == propHolder.value) {
                                var he = splitFullyQualifiedClsName(spring_refs[ref]);
                                listenerClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                                break;
                            }
                        }
                    }
                }
            }

            // Get listener method
            var dispatcher = null;
            for each (var propHolder in bean.propertyElements) {
                if (propHolder.name == "defaultListenerMethod") {
                    dispatcher = propHolder.value;
                }
            }
            if (dispatcher === null || dispatcher == "") dispatcher = "handleMessage";

            // Label listener method
            if (listenerClass !== null && listenerClass !== undefined && listenerClass.getName() != "[UnknownType]") {
                for each (var lmethod in listenerClass.getMethods()) {
                    if (lmethod.getName() == dispatcher) {
                        lmethod.setLabel("SpringJmsListenerMethod");
                        break;
                    }
                }
            }
        }
    }

    for each (var bean in spring_beans) {

        // Label Singletons and Session scoped beans
        var dotIndex = String(bean.clss).lastIndexOf(".");
        var nsName = String(bean.clss).substring(0, dotIndex);
        var cName = String(bean.clss).substr(dotIndex+1);
        var beanClass = nameTable.getClassByName(nsName, cName, "java");
        if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
            if (bean.isSingleton && JavaUtils.isSafeForGlobal(beanClass)) {
                beanClass.setLabel("SpringSingletonBean");
            }
            if (bean.isSessionScoped && JavaUtils.isSafeForGlobal(beanClass)) {
                beanClass.setLabel("SpringSessionBean");
            }
            if (bean.isApplicationScoped && JavaUtils.isSafeForGlobal(beanClass)) {
                beanClass.setLabel("SpringApplicationBean");
            }
        }
        // Process Remoted beans, command classes and WebFlow Actions
        if ( bean.clss && (isAction(bean.clss) || isCommand(bean.clss) || isExporter(bean.clss)) ) {
            if (bean.propertyElements != null && Array(bean.propertyElements).length != 0) {
                for each (var propHolder in bean.propertyElements) {

                    if (propHolder.name == "formObjectClass" || propHolder.name == "commandClass") {
                        var dotIndex = String(propHolder.value).lastIndexOf(".");
                        var nsName = String(propHolder.value).substring(0, dotIndex);
                        var cName = String(propHolder.value).substr(dotIndex+1);
                        if (propHolder.name == "formObjectClass") {
                            var beanClass = nameTable.getClassByName(nsName, cName, "java");
                            if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                beanClass.setLabel("webflowFormObject");
                                var visited = {};
                                visited[beanClass.getPackageName() + "." + beanClass.getName()] = true;
                                var fields = beanClass.getFields();
                                if (fields !== null && fields !== undefined) {
                                    // Loop through the command class fields and look for other non primitive nor java classes nested in the object
                                    for each (var field in fields) {
                                        markSensitiveField(field, visited);
                                    }
                                }
                            }
                            if (nsName != null && cName != null) {
                               addLabelToFields(nsName, cName, "Webflow1FormInput");
                            }
                        } else if (propHolder.name == "commandClass") {
                            var beanClass = nameTable.getClassByName(nsName, cName, "java");
                            if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                beanClass.setLabel("spring2CommandObject");
                            }
                            if (nsName != null && cName != null) {
                                addLabelToFields(nsName, cName, "commandField");
                            }
                        }
                    } else if (propHolder.name == "service") {
                        for (var ref in spring_refs) {
                            if (ref == propHolder.ref) {
                                var he = splitFullyQualifiedClsName(spring_refs[ref]);
                                var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                                if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
                                    beanClass.setLabel("RemotedBean");
                                }
                                break;
                            }
                        }
                    } else if (propHolder.name == "serviceInterface") {
                        var he = splitFullyQualifiedClsName(propHolder.value);
                        var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                        if (beanClass !== null && beanClass !== undefined && '[UnknownType]' != beanClass.getName()) {
                            beanClass.setLabel("RemotedBean");
                        }
                    } else if (propHolder.name == "serviceBean") {
                        for (var ref in spring_refs) {
                            if (ref == propHolder.ref) {
                                var he = splitFullyQualifiedClsName(spring_refs[ref]);
                                var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                                if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
                                    beanClass.setLabel("WebServiceBean");
                                }
                                break;
                            }
                        }
                    }
                }
            }
        }

        // Check JMX beans
        if (bean.clss !== null && bean.clss !== undefined && bean.clss == "org.springframework.jmx.export.MBeanExporter") {
            if (bean.jmxEntryElements !== null && bean.jmxEntryElements !== undefined && Array(bean.jmxEntryElements).length > 0) {
                for each (var jmxEntryHolder in bean.jmxEntryElements) {
                    for (var ref in spring_refs) {
                        if (ref == jmxEntryHolder.value_ref) {
                            var he = splitFullyQualifiedClsName(spring_refs[ref]);
                            var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                            if (beanClass !== null && '[UnknownType]' != beanClass.getName()) {
                                beanClass.setLabel("JMXBean");
                            }
                            break;
                        }
                    }
                }
            }
        }
        if (bean.clss !== null && bean.clss !== undefined && bean.clss == "org.springframework.jmx.access.MBeanProxyFactoryBean") {
            for each(var prop in bean.propertyElements) {
                if (prop.name == "proxyInterface") {
                    var he = splitFullyQualifiedClsName(prop.value);
                    var beanClass = nameTable.getClassByName(he.ns, he.clsName, "java");
                    if (beanClass !== null && beanClass !== undefined && '[UnknownType]' != beanClass.getName()) {
                        beanClass.setLabel("JMXBean");
                    }
                }
            }
        }
    }

    // Spring Webflow
    //alert("WEBFLOW")
    //for each (var bean in spring_beans) {
    //    alert(bean.name + " == " + bean.clss);
    //}
    for each (var cfg in program.xml) {
        if (null == cfg.name() || null == cfg.name().localName.match("flow")) {
            continue;
        }
        var ns = new Namespace("http://www.springframework.org/schema/webflow");

        // Extract tainted(user-controlled) vars
        var taintedVars = [];
        for each (var j in cfg..ns::['input']) {
            var value = String(j["@value"]);
            if (value !== "") continue;
            var name= String(j["@name"]);
            if (name !== "") {
                name = name.replace(/[a-z]+Scope\./, '');
                if (taintedVars.indexOf(name) == -1) taintedVars.push(name);
            }
        }
        for each (var j in cfg..ns::['view-state']) {
            var model = String(j["@model"]);
            if (model !== "") {
                model = model.replace(/[a-z]+Scope\./, '');
                if (taintedVars.indexOf(model) == -1) taintedVars.push(model);
            }
        }
        for each (var j in cfg..ns::['set']) {
            var value = String(j["@value"]);
            var name = String(j["@name"]);
            if (value !== null && value.indexOf("requestParameters") > -1 && name !== "") {
                name = name.replace(/[a-z]+Scope\./, '');
                if (taintedVars.indexOf(name) == -1) taintedVars.push(name);
            }
        }
        taintedVars.push("currentUser.name")
        taintedVars.push("flowExecutionUrl")

        // Parse Expressions
        for each (var j in cfg..ns::['evaluate']) {
            var expression = String(j["@expression"]);
            group = expression.match(/(\w+)\.(\w+)\(([a-zA-Z0-9,. ]+)\)/)
            if (group === null) continue;
            if (group.length == 4) {
                var isEntrypoint = false;
                var bean_name = group[1];
                var method_name = group[2];
                var args = group[3].split(',');
                for each (var arg in args) {
                    arg = arg.trim();
                    arg = arg.replace(/[a-z]+Scope\./, '');
                    if (arg.indexOf("requestParameters")) isEntrypoint = true;
                    if (taintedVars.indexOf(arg)) isEntrypoint = true;
                }
                if (isEntrypoint) {
                    //alert("Adding entrypoint for " + bean_name + "." + method_name)
                    for each (var bean in spring_beans) {
                        if (bean !== null && bean.name == bean_name && bean.clss !== null) {
                            var klass = nameTable.getClassByFullName(bean.clss, "java");
                            if (klass !== null && klass !== undefined && klass.getName() != "[UnknownType]") {
                                var methods = klass.getMethods();
                                if (null != methods) {
                                    for each (var method in methods) {
                                        if (method.getName() == method_name) {
                                            //alert("Found method to mark as entrypoint " + method.getName());
                                            method.setLabel("SpringWebFlowEntrypoint");
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        // Consider vars as global fields and their setters as entrypoints
        // (This is not very accurate but it was working this way so lets keep it for now)
        for each (var j in cfg..ns::['var']) {
            //attribute will return 'xml' type, not a string.
            var vName = String(j["@class"]).trim();
            if (JavaUtils.isSafeForGlobal(vName)) {
                // JavaUtils.isSafeForGlobal() doesn't return true if the class is not found in the nameTable
                var klass = nameTable.getClassByFullName(vName, "java");
                klass.setLabel("WebFlowVar");
                dbg("Label WebFlowVar: " + vName);
            }

        }
    }

    program.spring_labeling_initialized = true;
}
if (null == program.spring_labeling_initialized) {
    dbg("java: INITIALIZING SPRING LABELING");
    initSpringLabeling();
} else {
    dbg("spring:  SPRING LABELING HAS ALREADY BEEN INITIALIZED OR THIS IS NOT AN ANDROID APP");
}

function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj !== null && prefix !== null && prefix !== "") {
        var labels = obj.getLabels();
        if (labels !== null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                        var value = String(l.substring(prefix.length));
                        if (value != null && value.length > 0) {
                                values[values.length++] = value;
                        }
                }
            }
        }
    }
    return values;
}

function extractAttributeName(str) {
    var prefix = "SpringELVisible";
    var first_delimiter = str.indexOf("::");
    var last_delimiter = str.lastIndexOf("::");
    if (str.indexOf(prefix) == 0 && first_delimiter > 0 && last_delimiter > 0 && last_delimiter !== first_delimiter) {
        return String(str.substring(prefix.length + 2, last_delimiter));
    }
    return null;
}

function extractAttributeType(str) {
    var prefix = "SpringELVisible";
    var first_delimiter = str.indexOf("::");
    var last_delimiter = str.lastIndexOf("::");
    if (str.indexOf(prefix) == 0 && first_delimiter > 0 && last_delimiter > 0 && last_delimiter !== first_delimiter) {
        return String(str.substring(last_delimiter + 2));
    }
    return null;
}

function generateFieldName(fieldType) {
    // ATTRIBUTE NAME AUTO GENERATION conventation:
    // Determine the conventional variable name for the supplied Object based on its concrete type. The convention used is to return the uncapitalized short name of the Class,
    // according to JavaBeans property naming rules: So, com.myapp.Product becomes product; com.myapp.MyProduct becomes myProduct; com.myapp.UKProduct becomes UKProduct.
    // For arrays, we use the pluralized version of the array component type. For Collections we attempt to 'peek ahead' in the Collection to determine the component
    // type and return the pluralized version of that component type.

    if (fieldType !== undefined && fieldType !== null) {
        var lastdot = fieldType.lastIndexOf(".");
        if (lastdot > 0) return fieldType.substring(lastdot + 1, lastdot + 2).toLowerCase() + fieldType.substring(lastdot + 2);
        else return null;
    } else return null;
}

function dlog(msg, scope) {
    var today = new Date();
    var date = today.getFullYear()+'-'+(today.getMonth()+1)+'-'+today.getDate();
    var time = today.getHours() + ":" + today.getMinutes() + ":" + today.getSeconds();
    time = String(date + ' ' + time + ' ');

    if (scope === undefined || scope == 'null'){
        dbg(time + msg);
    }else{
        dbg(time + msg + ' : ' + scope)
    }
}

