    }
}


// Retrieve view preffix and suffix from viewResolver configuration.
// Possible ViewResolvers beans to extract the JSP (do we care for other types now?) prefix/suffix info from:
// - UrlBasedViewResolver
// - InternalResourceViewResolver
dlog("[ELDEBUG] Retrieve view preffix and suffix from viewResolver configuration");
var spring_beans = loadPersistedObject("program.spring_beans");
for each (var bean in spring_beans) {
    if (bean.clss === "org.springframework.web.servlet.view.InternalResourceViewResolver" ||
        bean.clss === "org.springframework.web.servlet.view.UrlBasedViewResolver") {
        for each (var prop in bean.propertyElements) {
            if (prop.name === "prefix") page_prefixes[page_prefixes.length] = prop.value;
            if (prop.name === "suffix") page_suffixes[page_suffixes.length] = prop.value;
        }
    }
}

var map = {};                   // controller_method_name --> array of logic view names associated to the controller method
var methodname_method = {};     // controller_method_name --> jsMethod
var controller_methods = {};    // controller_method_name --> jsMethod

// Process view names collected from SimpleFormControllers.setSuccesssView (configuration)
dlog("[ELDEBUG] Process view names collected from SimpleFormControllers.setSuccesssView (configuration)");
var successMethods = ['onSubmit', 'processFormSubmission'];
for each (var bean in spring_beans) {
    if (bean !== null && bean !== undefined
        && bean.successview !== null && bean.successview !== undefined
        && bean.namespaceName !== null && bean.namespaceName !== undefined
        && bean.className !== null && bean.className !== undefined) {
        for each (var sm in successMethods) {
            var methodname = bean.namespaceName + "." + bean.className + "." + sm;
            var m = null;
            var cclass = nameTable.getClassByName(bean.namespaceName, bean.className, "java");
            if (null !== cclass && '[UnknownType]' !== cclass.getName()) {
                var methods = cclass.getMethods();
                for each (var method in methods) {
                    if (null !== method && '[UnknownType]' !== method.getName()) {
                        if (method.getName() == sm) {
                            m = method;
                            break;
                        }
                    }
                }
            }
            if (m !== null) {
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                views[views.length] = bean.successview;
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

