// Collect Apache Tiles information
dlog("[ELDEBUG] Collect Apache Tiles information 1");
var templates = {};
for each (var cfg in program.xml) {
    if (null == cfg.name() || null == cfg.name().localName.match("tiles-definitions")) {
        continue;
    }
    for each (var j in cfg.*::['definition']) {
        var name = String(j["@name"]);
        var parent_template = String(j["@extends"]);
        var view_template = String(j["@template"]);
        var template = {};
        template.name = Math.random().toString(36).substring(7);
        template.parent_template = null;
        template.views = [];
        if (name != "") template.name = name
        if (parent_template != "") template.parent_template = parent_template;
        if (view_template != "") template.views.push(view_template);
        for each (var a in j..*::['put-attribute']) {
            var value = String(a["@value"]);
            if (value != "") template.views.push(value);
        }
        for each (var d in j..*::['definition']) {
            var nested_template = String(d["@template"]);
            if (nested_template!= "") template.views.push(nested_template);
        }
        templates[template.name] = template;
    }
}
var tilesviewmap = {};
dlog("[ELDEBUG] Collect Apache Tiles information 2");
for each (var t in templates) {
    //alert(t.name);
    var views = [];
    if (t.parent_template !== null && templates[t.parent_template] !== undefined) {
        for each (var v1 in templates[t.parent_template].views) {
            //alert("    " + v1)
            views.push(v1);
        }
    }
    for each (var v2 in t.views) {
        if (templates[v2] !== null && templates[v2] !== undefined) {
            for each (var v3 in templates[v2].views) {
                //alert("    " + v3)
                views.push(v3);
            }
        } else {
            //alert("    " + v2)
            views.push(v2);
        }
    }
    tilesviewmap[t.name] = views;
}
function getTilesViews(logicName, map) {
    logicName = logicName.replace(/^\//, '');
    var result = [];
    var logicNames = Object.keys(tilesviewmap);
    for each (var name in logicNames) {
        if (name == logicName) {
            for each(var v in tilesviewmap[name]) {
                //alert(v)
                result.push(v);
            }
        } else if (name.indexOf('*') > -1) {
            name_regexp = name.replace('*', '(.*)')
            res = logicName.match(name_regexp)
            if (res !== null && res.length > 0) {
                for each (var a in tilesviewmap[name]) {
                    final_name = a.replace('{1}', res[0])
                    //alert(final_name)
                    result.push(final_name);
                }
            }
        }
    }
    return result;
}
var isApacheTiles = Object.keys(tilesviewmap).length > 0;

// Process logic view names collected from ModelAndViews, Views and return strings
dlog("[ELDEBUG] Process logic view names collected from ModelAndViews, Views and return strings");
var methods = nameTable.getMethodsByLabel("SpringMVCView", "java");
if (methods !== null && methods !== undefined) {
    for each (var m in methods) {
        var viewnames = extractLabelValues(m, "SpringMVCView::");
        for each (var viewname in viewnames) {
            if (viewname.indexOf("redirect:") != 0 && viewname.indexOf("forward:") != 0) {
                var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
                var views = map[methodname];
                if (views === null || views === undefined || views.length == 0) views = [];
                for each (var prefix in page_prefixes) {
                    for each (var suffix in page_suffixes) {
                        vn = prefix + viewname + suffix;
                        vn = String(vn).replace(/\/\//g,'/');
                        vn = String(vn).replace(/\\\\/g,'\\');
                        views[views.length] = vn;
                    }
                }
                if (isApacheTiles) {
                    for each(var atv in getTilesViews(viewname)) {
                        views[views.length] = atv;
                    }
                }
                map[methodname] = views;
                methodname_method[methodname] = m;
            }
            var cmethod = controller_methods[methodname];
            if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
        }
    }
}

// Process view names collected from RequestMapping annotations
dlog("[ELDEBUG] Process view names collected from RequestMapping annotations");
var methods = nameTable.getMethodsByLabel("SpringMVCMapping", "java");
dlog("[ELDEBUG] SpringMVCMapping methods: " + methods);
if (methods !== null && methods !== undefined) {
    for each (var m in methods) {
        var viewname = extractLabelValues(m, "SpringMVCMapping::")[0];
        dlog("[ELDEBUG] SpringMVCMapping methods: " + m + " and mapping is " + viewname); 
        var controller_prefix = extractLabelValues(m, "SpringMVCControllerMapping::")[0];
        if (controller_prefix !== undefined && controller_prefix !== null && controller_prefix !== "") {
                viewname = controller_prefix + viewname;
        }
        if (viewname == undefined || viewname == null) {
            continue;
        }
        var pathindex = viewname.indexOf('{');
        if (pathindex > 0) {
            viewname = viewname.substr(0,pathindex-1);
        }
        dlog("[ELDEBUG] viewname is: " + viewname);
        if (!String(viewname).match(/\*|{.*}/)) {
            var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
            var views = map[methodname];
            if (views === null || views === undefined || views.length == 0) views = [];
            for each (var prefix in page_prefixes) {
                for each (var suffix in page_suffixes) {
                    vn = prefix + viewname + suffix;
                    vn = String(vn).replace(/\/\//g,'/');
                    vn = String(vn).replace(/\\\\/g,'\\');

                    dlog("[ELDEBUG] full view name (vn) is: " + viewname);

                    views[views.length] = vn;
                }
            }
            if (isApacheTiles) {
                for each(var atv in getTilesViews(viewname)) {
                    views[views.length] = atv;
                }
            }
            map[methodname] = views;
            methodname_method[methodname] = m;
        }
        var cmethod = controller_methods[methodname];
        if (cmethod === null || cmethod === undefined || cmethod.length == 0) controller_methods[methodname] = m;
    }
}

// Process @ModelAttribute annotated methods
// Last step after processing all other view collecting pieces
dlog("[ELDEBUG] Process @ModelAttribute annotated methods");
var ma_methods = nameTable.getMethodsByLabel("SpringModelAttributeMethod", "java");
if (ma_methods !== null && ma_methods !== undefined) {
    for each (var ma_method in ma_methods) {
        var enc_class = ma_method.getEnclosingClass();
        dlog("[ELDEBUG] looking at " + enc_class + "." + ma_method);
        var ma_methodname = String(enc_class.getPackageName() + "." + enc_class.getName() + "." + ma_method.getName());
        var views = map[ma_methodname];
        if (views === null || views === undefined || views.length == 0) views = [];
        map[ma_methodname] = views;
        methodname_method[ma_methodname] = ma_method;
        for each (var controller_method in enc_class.getMethods()) {
            dlog("[ELDEBUG] looking at sibling method " + enc_class + "." + controller_method);
            view_dispatch_method = false;
            for each (var l in controller_method.getLabels()) {
                if (String(l) == "SpringELVisible") {
                    view_dispatch_method = true;
                    break;
                }
            }
            if (view_dispatch_method) {
                var methodname = String(enc_class.getPackageName() + "." + enc_class.getName() + "." + controller_method.getName());
                var cviews = map[methodname];
                dlog("[ELDEBUG] cviews is " + cviews);
                if (cviews !== null && cviews !== undefined && cviews.length > 0)
                    map[ma_methodname] = map[ma_methodname].concatUnique(cviews)
                    dlog("[ELDEBUG] map[" + ma_methodname + "] is now: " + map[ma_methodname]);
            }
        }
    }
}


// Process collected views
dlog("[ELDEBUG] Process collected views");
// remove duplicated slashes and make sure the view file exists
// set SpringFunctionView:viewPath labels for backend usage
var validviewmap = {};
var allFiles = getAllProgramFileNames();
if (allFiles !== null && allFiles !== undefined) {
    for (var methodname in map) {
        //alert("Found " + String(map[methodname].length) + " possible views for method: " + methodname);
        var validviews = [];
        for each (var viewname in map[methodname]) {
            for each (f in allFiles) {
                if (f !== null && f.indexOf(viewname) > -1) {
                    var m = methodname_method[methodname];
                    m.setLabel("SpringFunctionView::" + f);
                    validviews[validviews.length] = f;
                    //alert("\t\tController method: " + "SpringFunctionView::" + f);
                }
            }
        }
        validviewmap[methodname] = validviews;
    }
}

// Caching unique page objects to inject
dlog("[ELDEBUG] Caching unique page objects to inject");
var field_map = {};
for each (var m in controller_methods) {
    if (m !== null) {
        var methodname = String(m.getEnclosingClass().getPackageName() + "." + m.getEnclosingClass().getName() + "." + m.getName());
        //alert("Controller method: " + methodname)
        for each (var label in m.getLabels()) {
            if (String(label).match(/SpringELVisible::([.a-zA-Z0-9]*)::([.a-zA-Z0-9]*)/)) {
                var fldname = extractAttributeName(label);
                var fldtype = extractAttributeType(label);
                if (fldname === "SpringConvention") fldname = generateFieldName(fldtype);
                //alert("       " + fldname + " ==== " + fldtype)
                if (fldname !== null) {
                    var cmethod = methodname;
                    var pages = uniq(validviewmap[cmethod]);
                    for each(var f in pages) {
                        var id = f + ":::" + fldname + ":::" + fldtype;
                        if (field_map[id] == undefined) {
                            field_map[id] = [{page: f, name: fldname, type: fldtype, controllermethod: cmethod}];
                        } else {
                            var items = field_map[id];
                            var additem = true;
                            for each (var item in items) {
                                if (item.page == f && item.name == fldname && item.type == fldtype && item.controllermethod == cmethod) {
                                    additem = false;
                                }
                            }
                            if (additem) items[items.length] = {page: f, name: fldname, type: fldtype, controllermethod: cmethod};
                            field_map[id] = items;
                        }
                    }
                }
            }
        }
    }
}
dlog("[ELDEBUG] Calling addFieldToFrameworkVisibilityTypeOfPage");
for each (var fieldlist in field_map) {
    for each (var field in fieldlist) {
        dlog("[+] Calling addFieldToFrameworkVisibilityTypeOfPage(\"" + field.page + "\", \"" + field.name + "\", \"" + field.type + "\", \"" + field.controllermethod + "\");");
        addFieldToFrameworkVisibilityTypeOfPage(field.page, field.name, field.type, field.controllermethod);
    }
}

// Find beans that are serialized with XStream
var xmlFiles = getXMLConfigFileNames();
var ns = new Namespace();
var springns = new Namespace("http://www.springframework.org/schema/beans");
var oxmns = new Namespace("http://www.springframework.org/schema/oxm");
for each (var filename in xmlFiles) {
    var contents = '';
    try {
        contents = readFile(filename);
    } catch (err) {
        log("Error reading file "+filename);
        continue;
    }
    try {
        if (contents.charAt(0) != '<') {
                contents = contents.substring(1);
        }
        var xml = new XML(contents);
        // XStream marshaller
        if (null !== xml && null !== xml.name() && null !== xml.name().localName && null !== xml.name().localName.match("beans")) {
            for each (var bean in xml..springns::bean) {
                if (String(bean["@class"]) == "org.springframework.oxm.xstream.XStreamMarshaller") {
                    for each (var prop in bean.springns::property) {
                        if (String(prop["@name"]) == "aliases") {
                            for each (var alias in prop..springns::prop) {
                                var xclass = nameTable.getClassByFullName(alias.text(), "java");
                                if (null !== xclass && xclass.getName() != "[UnknownType]") {
                                    xclass.setLabel("XStreamAlias");
                                    var superclasses = xclass.getSuperClasses();
                                    for each (var superclass in superclasses) {
                                        superclass.setLabel("XStreamAlias");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    } catch (err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
        // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
    }
}

//
// program.ADF_AMs maps amName to the object that holds info about this AM
//   amName         e.g. StoreServiceAMLocalWeb
//   appName        e.g. oracle.fodemo.storefront.store.service.StoreServiceAM
//   xmlfilename
//   fullclss
//   namespace
//   clss
//   VOs = new Array() of VO Objects (maps Name to VO)
//     Name         e.g. CustomerRegistration
//     ViewObjectName
//     xmlfilename
//     componentfullclss
//     componentnamespace
//     componentclss
//     rowfullclss      e.g oracle.fodemo.storefront.account.queries.CustomerRegistrationVORowImpl
//     rownamespace
//     rowclss
//     ViewAttributes = new Array() of Attribute Objects (maps Name to Attribute)
//       Name       e.g. PrincipalName
//       AliasName      e.g. PRINCIPALNAME
//       EntityUsage
//       EntityAttrName
//     EOs = new Array() of EO Objects (maps Name to EO)
//       Name       e.g. PersonEO
//       Entity
//       xmlfilename
//       rowfullclss    e.g. oracle.fodemo.storefront.entities.PersonEOImpl
//       rownamespace
//       rowclss
//       Attributes = new Array() of Attribute Objects (maps Name to Attribute)
//         Name     e.g. PrincipalName
//         ColumnName   e.g. PRINCIPALNAME
//
// program.ADF_Pages maps pagePath to the object that holds info about the page
//   pageId         e.g. account_basicInformationPageDef
//   pagePath       e.g. /account/basicInformation.jsff
//   fullPagePath           e.g. /home/user/public_html/account/basicInformation.jsff
//   pageDefPath        e.g. oracle.fodemo.storefront.pageDefs.account_basicInformationPageDef
//   Bindings = new Array() of Binding Objects (maps id to the object itself)
//     id           e.g. PrincipalName
//     iterator     e.g. CustomerRegistrationIterator
//     control      e.g. StoreServiceAMDataControl
//     binds        e.g. CustomerRegistration
// program.ADF_Controls maps the name of the AM (amName) to the Control object
//  ctlId           e.g. StoreServiceAMDataControl
//  amName          e.g. StoreServiceAMLocalWeb
//
program.ADF_AMs = new Array();
program.ADF_Pages = new Array();
program.ADF_Controls = new Array();

var adfappns = new Namespace("http://xmlns.oracle.com/adfm/application");
var adfdatans = new Namespace("http://xmlns.oracle.com/adfm/datacontrol");
for (var cfgfile in program.xml) {
  try {
    var cfg = new XML(program.xml[cfgfile]);
    if (null != cfg && null != cfg.name() && null != adfappns && cfg.name().uri == adfappns.uri && cfg.name().localName == "Application") {
      for each (var pageMap in cfg..adfappns::pageMap.adfappns::page) {
        var thisPage = new Object();
        thisPage.pageId = String(pageMap["@usageId"]);
        thisPage.pagePath = String(pageMap["@path"]);
        thisPage.pageDefPath = String(cfg..adfappns::pageDefinitionUsages.adfappns::page.(@id == thisPage.pageId)["@path"]);
        dbg("pageId: " + thisPage.pageId);
        dbg("pagePath: " + thisPage.pagePath);
        dbg("pageDefPath: " + thisPage.pageDefPath);
        getInfoAboutThisPage(thisPage);
      }
      for each (var ctl in cfg..adfappns::dataControlUsages.adfdatans::BC4JDataControl) {
        var thisControl = new Object();
        thisControl.ctlId = String(ctl["@id"]);
        thisControl.amName = String(ctl["@Configuration"]);
        dbg("ctlId: " + thisControl.ctlId);
        dbg("amName: " + thisControl.amName);
        program.ADF_Controls[thisControl.amName] = thisControl;
      }
    }
  } catch(err) {
    // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
  }
}

var bc4jconfns = new Namespace("http://xmlns.oracle.com/bc4j/configuration");
var bc4jns = new Namespace("http://xmlns.oracle.com/bc4j");
for (var cfgfile in program.xml) {
  for each (var cfg in program.xml[cfgfile]..bc4jconfns::AppModuleConfig) {
    var amName = String(cfg["@name"]);
    var appName = String(cfg["@ApplicationName"]);
    dbg("appName: " + appName);
    dbg("amName: " + amName);
    if (null != appName && 0 != appName.length && null != amName && 0 != amName.length) {
      for (var xmlAMFile in program.xml) {
        try {
          dbg("xmlAMFile: " + xmlAMFile);
          if (null != xmlAMFile.match(appName)) {
            dbg("MATCH@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@@");
            var AMXML = new XML(program.xml[xmlAMFile]);
            if (null != AMXML) {
              var thisAM = new Object();
              thisAM.amName = amName;
              thisAM.appName = appName;
              thisAM.xmlfilename = xmlAMFile;
              thisAM.fullclss = String(AMXML["@ComponentClass"]);

              // make sure we're dealing with valid Java class name
              if (false == JavaUtils.isValidPackageName(thisAM.fullclss)) {
                continue;
              }
              thisAM.namespace = thisAM.fullclss.substr(0, thisAM.fullclss.lastIndexOf("."));
              thisAM.clss = thisAM.fullclss.substr(thisAM.fullclss.lastIndexOf(".") + 1);
              dbg("thisAM.namespace: " + thisAM.namespace);
              dbg("thisAM.clss: " + thisAM.clss);
              thisAM.VOs = new Array();
              for each (var viewUsage in AMXML..bc4jns::ViewUsage) {
                var thisVO = new Object();
                thisVO.Name = String(viewUsage["@Name"]);
                dbg("thisVO.Name: " + thisVO.Name);
                thisVO.ViewObjectName = String(viewUsage["@ViewObjectName"]);
                dbg("thisVO.ViewObjectName: " + thisVO.ViewObjectName);
                for (var anotherXMLFile in program.xml) {
                  if (null != anotherXMLFile.match(thisVO.ViewObjectName)) {
                    dbg("another matched: " + anotherXMLFile);
                    //var VOXML = getXMLForFilename(anotherXMLFile);
                    var VOXML = new XML(program.xml[anotherXMLFile]);
                    if (null != VOXML) {
                      thisVO.xmlfilename = anotherXMLFile;
                      thisVO.componentfullclss = String(VOXML["@ComponentClass"]);
                      thisVO.componentnamespace = thisVO.componentfullclss.substr(0, thisVO.componentfullclss.lastIndexOf("."));
                      thisVO.componentclss = thisVO.componentfullclss.substr(thisVO.componentfullclss.lastIndexOf(".") + 1);
                      thisVO.rowfullclss = String(VOXML["@RowClass"]);
                      thisVO.rownamespace = thisVO.rowfullclss.substr(0, thisVO.rowfullclss.lastIndexOf("."));
                      thisVO.rowclss = thisVO.rowfullclss.substr(thisVO.rowfullclss.lastIndexOf(".") + 1);
                      dbg("thisVO.componentnamespace: " + thisVO.componentnamespace);
                      dbg("thisVO.componentclss: " + thisVO.componentclss);
                      dbg("thisVO.rownamespace: " + thisVO.rownamespace);
                      dbg("thisVO.rowclss: " + thisVO.rowclss);

                      // make sure we're dealing with valid Java package and class names
                      if (false == JavaUtils.isValidPackageName(thisVO.rownamespace) || false == JavaUtils.isValidIdentifier(thisVO.rowclss)) {
                        continue;
                      }

                      thisVO.EOs = new Array();
                      for each (var entityUsage in VOXML..bc4jns::EntityUsage) {
                        var thisEO = new Object();
                        thisEO.Name = String(entityUsage["@Name"]);
                        thisEO.Entity = String(entityUsage["@Entity"]);
                        dbg("thisEO.Name: " + thisEO.Name);
                        dbg("thisEO.Entity: " + thisEO.Entity);
                        for (var yetAnotherXMLFile in program.xml) {
                          if (null != yetAnotherXMLFile.match(thisEO.Entity)) {
                            dbg("yet another matched: " + yetAnotherXMLFile);
                            //var EOXML = getXMLForFilename(yetAnotherXMLFile);
                            var EOXML = new XML(program.xml[yetAnotherXMLFile]);
                            if (null != EOXML) {
                              thisEO.xmlfilename = yetAnotherXMLFile;
                              thisEO.rowfullclss = String(EOXML["@RowClass"]);
                              thisEO.rownamespace = thisEO.rowfullclss.substr(0, thisEO.rowfullclss.lastIndexOf("."));
                              thisEO.rowclss = thisEO.rowfullclss.substr(thisEO.rowfullclss.lastIndexOf(".") + 1);
                              dbg("thisEO.rownamespace: " + thisEO.rownamespace);
                              dbg("thisEO.rowclss: " + thisEO.rowclss);

                              // make sure we're dealing with valid Java package and class names
                              if (false == JavaUtils.isValidPackageName(thisEO.rownamespace) || false == JavaUtils.isValidIdentifier(thisEO.rowclss)) {
                                continue;
                              }

                              thisEO.Attributes = new Array();
                              for each (var attribute in EOXML..bc4jns::Attribute) {
                                var thisAttribute = new Object();
                                thisAttribute.Name = String(attribute["@Name"]);
                                thisAttribute.ColumnName = String(attribute["@ColumnName"]).replace(/_/g, "");
                                dbg("thisAttribute.Name: " + thisAttribute.Name);
                                dbg("thisAttribute.ColumnName: " + thisAttribute.ColumnName);

                                // make sure we're dealing with valid Java identifier
                                if (JavaUtils.isValidIdentifier(thisAttribute.ColumnName)) {
                                  thisEO.Attributes[thisAttribute.Name] = thisAttribute;
                                }
                              }
                            }
                          }
                        }
                        thisVO.EOs[thisEO.Name] = thisEO;
                      }

                      thisVO.ViewAttributes = new Array();
                      for each (var viewAttribute in VOXML..bc4jns::ViewAttribute) {
                        var thisAttribute = new Object();
                        thisAttribute.Name = String(viewAttribute["@Name"]);
                        thisAttribute.AliasName = String(viewAttribute["@AliasName"]).replace(/_/g, "");
                        thisAttribute.EntityUsage = String(viewAttribute["@EntityUsage"]);
                        thisAttribute.EntityAttrName = String(viewAttribute["@EntityAttrName"]);

                        // make sure we're dealing with valid Java identifier
                        if (JavaUtils.isValidIdentifier(thisAttribute.AliasName)) {
                          thisVO.ViewAttributes[thisAttribute.Name] = thisAttribute;
                        }
                        dbg("thisAttribute.Name: " + thisAttribute.Name);
                        dbg("thisAttribute.AliasName: " + thisAttribute.AliasName);
                        dbg("thisAttribute.EntityUsage: " + thisAttribute.EntityUsage);
                        dbg("thisAttribute.EntityAttrName: " + thisAttribute.EntityAttrName);
                      }
                    }
                  }
                }
                thisAM.VOs[thisVO.Name] = thisVO;
              }
              program.ADF_AMs[amName] = thisAM;
            }
          }
        } catch(err) {
          // Swallow XML Parsing errors
        }
      } 
    }
  }
}

openManagedBeanMap();
for each (var currentAM in program.ADF_AMs) {
  newManagedBeanSubmap();
  for each (var currentVO in currentAM.VOs) {
    var VOClassType = handleClassLabeling(currentVO.rownamespace, currentVO.rowclss);
    for each (var attribute in currentVO.ViewAttributes) {
      handleFieldLabeling(VOClassType, attribute.AliasName);
      var from = "";
      if (null != attribute.Name && 0 != attribute.Name.length) {
        from = "bindings." + attribute.Name + ".inputValue";
      }
      var to = "";
      if (0 != from.length && null != currentVO.rowfullclss && 0 != currentVO.rowfullclss.length) {
        to = "" + attribute.Name + ":" + currentVO.rowfullclss + "";
      }
      var currentEO = currentVO.EOs[attribute.EntityUsage];
      if (null != currentEO) {
        var EOClassType = handleClassLabeling(currentEO.rownamespace, currentEO.rowclss);
        if (null != currentEO.Attributes) {
          var entityAttribute = currentEO.Attributes[attribute.EntityAttrName];
          if (null != entityAttribute) {
            handleFieldLabeling(EOClassType, entityAttribute.ColumnName);
            var colon = "";
            if (0 != to.length) {
              colon = ":";
            }
            if (null != currentEO.rowfullclss && 0 != currentEO.rowfullclss.length && null != entityAttribute.Name && 0 != entityAttribute.Name.length) {
              to += "" + colon + entityAttribute.Name + ":" + currentEO.rowfullclss + "";
            }
            if (0 != from.length && 0 != to.length) {
              dbg("from: " + from);
              dbg("to: " + to);
              addManagedBeanSubmapPair(from, to);
            }
          }
        }
      }
    }
  }
  var listOfFullPaths = getFullPagePaths(currentAM.amName);
  for (var path in listOfFullPaths) {
    dbg("adding " + path + " to the managed bean file submap");
    addManagedBeanFile(path);
  }
}
closeManagedBeanMap();

function getInfoAboutThisPage(page) {
  var adfuins = new Namespace("http://xmlns.oracle.com/adfm/uimodel");
  for (var pageFile in program.xml) {
    if (null != pageFile.match(page.pageDefPath)) {
      try {
        var pageDef = new XML(program.xml[pageFile]);
        page.Bindings = new Array();
        for each (var binding in pageDef..adfuins::bindings.adfuins::attributeValues) {
          var thisBinding = new Object();
          thisBinding.id = String(binding["@id"]);
          thisBinding.iterator = String(binding["@IterBinding"]);
          thisBinding.control = String(pageDef..adfuins::executables.adfuins::iterator.(@id == thisBinding.iterator)["@DataControl"]);
          thisBinding.binds = String(pageDef..adfuins::executables.adfuins::iterator.(@id == thisBinding.iterator)["@Binds"]);
          dbg("thisBinding.id: " + thisBinding.id);
          dbg("thisBinding.iterator: " + thisBinding.iterator);
          dbg("thisBinding.control: " + thisBinding.control);
          dbg("thisBinding.binds: " + thisBinding.binds);
          page.Bindings[thisBinding.id] = thisBinding;
        }
      } catch(err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
      }
    }
  }
  for (var fullPagePath in program.cxml) {
    if (null != fullPagePath.match(page.pagePath)) {
      page.fullPagePath = fullPagePath;
      dbg("page.fullPagePath: " + page.fullPagePath);
    }
  }
  program.ADF_Pages[page.pagePath] = page;
}

function getFullPagePaths(am) {
  var listOfFullPaths = new Array();
  if (null != am && 0 != am.length) {
    dbg("getFullPagePaths:am: " + am);
    var control = program.ADF_Controls[am];
    if (null != control && null != control.ctlId) {
      for each (var page in program.ADF_Pages) {
        for each (var binding in page.Bindings) {
          if (binding.control == control.ctlId) {
            listOfFullPaths[page.fullPagePath] = true;
            dbg("getFullPagePaths:fullPagePath: " + page.fullPagePath);
          }
        }
      }
    }
  }
  return listOfFullPaths;
}

function handleClassLabeling(namespaceName, className) {
  if (null != namespaceName && null != className && 0 != className.length) {
    var classType = nameTable.getClassByName(namespaceName, className, "java");
    if (null != classType && '[UnknownType]' != classType.getName()) {
      dbg("put label on class: " + classType.getName());
      if (JavaUtils.isSafeForGlobal(classType)) classType.setLabel("ADFClass");
    }
    return classType;
  }
  return null;
}

function handleFieldLabeling(classType, fieldName) {
  if (null != classType && null != fieldName) {
    for each (var field in classType.getFields()) {
      if (fieldName == field.getName()) {
        dbg("put label on field: " + field.getName());
        field.setLabel("ADFField");
      }
    }
  }
}

var jsclasses = getClassesByLabel("AndroidJavascriptAccessible", Platform.ANDROID);
if (jsclasses !== null && jsclasses !== undefined) {
    for each (var jsclass in jsclasses) {
        if (jsclass !== null && jsclass !== undefined) {
            var before_Jelly_Bean = true;
            var version = getAndroidMinSdkVersion();
            if (!isNaN(version) && version > 16) before_Jelly_Bean = false;
            var methods = jsclass.getMethods();
            var annotatedMethods = [];
            var allMethods = [];
            if (methods !== null && methods !== undefined) {
                for each (var method in methods) {
                    allMethods[allMethods.length] = method;
                    var annotation = method.getAnnotation("android.webkit.JavascriptInterface");
                    if (annotation !== null && annotation !== undefined) {
                        // Commenting out since even if there are annotations, the app can run in insecure mode if
                        // minSdkVersion < 17 and app is installed in an Android device with version 4.1 or lower.
                        //before_Jelly_Bean = false;
                        annotatedMethods[annotatedMethods.length] = method;
                    }
                }
                if (before_Jelly_Bean) {
                    // All methods are entrypoints (the entrypoint rule will make sure they are public and not constructors)
                    for each (var m in allMethods) {
                        m.setLabel("AndroidJavascriptAccessibleMethod");
                    }
                    // JS exposed class is vulnerable to Mitm attacks leading to RCE
                    jsclass.setLabel("AndroidJavascriptVulnerable");
                } else {
                    // only annotated methods are entrypoints (the entrypoint rule will make sure they are public and not constructors)
                    for each (var m in annotatedMethods) {
                        m.setLabel("AndroidJavascriptAccessibleMethod");
                    }
                }
            }
        }
    }
}

// where all of the permission-protected methods will go
var results = new Array();

// checks whether the method is already in the list
function doResultsContain(name) {
  for each (var i in results) {
    if (i.key == name) {
      return true;
    }
  }
  return false;
}

function loadMap(android_map) {
    for (var key in android_map) {
      if (false == doResultsContain(key)) {
        var perms = android_map[key];
        if (null != perms) {
          var thisResult = new Object();
          var dotIndex = key.lastIndexOf(".");
          thisResult.key = key;
          thisResult.className = key.substring(0, dotIndex);
          thisResult.functionName = key.substr(dotIndex+1);
          dotIndex = thisResult.className.lastIndexOf(".");
      thisResult.namespaceName = thisResult.className.substring(0, dotIndex);
          thisResult.className = thisResult.className.substr(dotIndex+1);
      thisResult.permission = perms;
          if (false == doResultsContain(key)) {
            results[results.length] = thisResult;
          }
        }
      }
    }
}

function handleLabeling(namespaceName, className, functionName, label) {
  if (null != namespaceName && null != className && 0 != className.length) {
    var classType = getClassByName(namespaceName, className, Platform.ANDROID);
    if (null != classType && '[UnknownType]' != classType.getName()) {
      for each (var method in classType.getMethods()) {
        if (functionName == method.getName()) {
          //alert("put label '" + label + "' on method '" + method.getName() + "'");
          method.setLabel(label);
        }
      }
    }
  }
}

          // run the script only if it is an Android app
          if (JavaUtils.isAndroidApp()) {
loadMap(loadPersistedObject("program.android_map_apf"));
loadMap(loadPersistedObject("program.android_map_optional"));
loadMap(loadPersistedObject("program.android_map_or_over"));
loadMap(loadPersistedObject("program.android_map_or_simple"));

for each (var i in results) {
var permstring = "Requires permission(s): ";
    for (var j = 0; j < i.permission.length; j++) {
        var p = i.permission[j];
        var split = p.split(" or ");
        for (var k = 0; k < split.length; k++) {
            handleLabeling(i.namespaceName, i.className, i.functionName, split[k]);
        }
        if (j > 0) permstring = permstring + " and ";
        permstring = permstring + i.permission[j];
    }
    handleLabeling(i.namespaceName, i.className, i.functionName, permstring);
}
          }

/*
This script uses the output from capture rules:
    - 290B3FCF-D039-47D9-B427-4CFF458F1707
    - BFCCEBC5-9874-4731-920E-DD255E85ECFA
which capture the names of Apex controller classes and action methods associated with a Visualforce page elements, and adds labels to the NSTs corresponding to those captured method names.
Code examples:
```
<apex:page controller="MyController">
    <apex:form>
        <apex:inputText value="{!val}"/>
        <apex:commandButton action="{!onclick1}" value="submit"/>
    </apex:form>
</apex:page>
```
The above Visualforce page has a controller class named 'MyController', and its <apex:commandButton> element has an action handler 'MyController.onclick1()', which are defined in a separate Apex class file:
```
public class MyController {
    public PageReference onClick1() {
        ...
    }
}
```
*/

(function() {


    /* Parses the class and method names from the raw capture strings
        Example input: "mycontroller pagecontroller.onclick1()"
        Expected output: ["mycontroller", "onclick1"]
    */
    function parseMethodCapture(capture) {
        var cn_and_fn = capture.split(' ');
        var className = cn_and_fn[0];
        var methodName = cn_and_fn[1];
        if (className !== undefined && methodName !== undefined) {
            if (methodName.contains('.')) {
                methodName = methodName.substring(methodName.lastIndexOf('.')+1);
            }
            if (methodName.contains('(')) {
                methodName = methodName.substring(0, methodName.indexOf('('));
            }
            return [className, methodName];
        } else
            return [];
    }


    var actionMethodNames = nameTable.getGlobalCaptures('Visualforce_Action_Methods');
    // Add labels to Apex action methods. The code isn't efficient, but Apex test projects are generally small so we can improve it if there are actually performance problems.
    for (var i = 0; i < actionMethodNames.length; i++) {
        var signature = parseMethodCapture(actionMethodNames[i]);
        if (signature.length == 2) {
            var className = signature[0];
            var methodName = signature[1];

            var c = nameTable.getClassByFullName(className, 'apex');
            if (c !== null && c !== undefined) {
                var methods = c.getMethods();
                if (methods !== null && methods !== undefined) {
                    for (var j = 0; j < methods.length; j++) {
                        var method = methods[j];
                        if (method.getName() == methodName) {
                            method.setLabel('Visualforce_Action_Method')
                        }
                    }
                }
            }
        }
    }
})();

//
//  Returns true if indication is found that the application uses Apollo Server
//
function isApolloServerDetected() {
    // Return true if 'apollo-server.init' label is found. This label is used to 
    // detect if the ApolloServer() contructor is called within the application.
    var initMethods = getMethodsByLabel('apollo-server.init', ['javascript', 'typescript']);
    return (initMethods && initMethods.length > 0);
}

// 
// Adds 'apollo-server.entrypoint' label if Apollo usage is detected, enabling Apollo 
// entrypoint rules to match
//
function addAdditionalLabelsIfApolloDetected() {
    if (isApolloServerDetected()) {
        var entrypointMethods = getMethodsByLabel('apollo-server.entrypoint.candidate', ['javascript', 'typescript']);
        if (entrypointMethods && entrypointMethods.length > 0) {
            for each (var entrypointMethod in entrypointMethods) {
                dbg('Adding label apollo-server.entrypoint to ' + entrypointMethod.toString() + ' found at ' + 
                    entrypointMethod.getFileName() + ':' + entrypointMethod.getLineNumber());
                entrypointMethod.setLabel('apollo-server.entrypoint');
            }
        }
    }
}

