var MASS_ASSIGNMENT_REGEXP = /manager|admin|role|access|price|cost|secret|priv/i;

function processField(field, visited) {
    // Loop through nested fields in the given class if they are not primitive or System classes
    // If field name matches Mass Assignment regular expression, label it with exposedCommandField
    // alert("processing field " + field.getName());
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedCommandField");
    }
    if (!type.isPrimitive() && !key.match(/^(System|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    processField(new_field, visited);
                }
            }
        }
    }
}

// Collect all command classes
var cmclasses = nameTable.getClassesByLabel("insecureBinding", "dotnet");
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null && cmclass != '[UnknownType]') {
            var visited = {};
            visited[cmclass.getPackageName() + "." + cmclass.getName()] = true;
            var fields = cmclass.getFields();
            var methods = cmclass.getMethods();

            // Loop through the command class fields and look for other non primitive nor system classes nested in the object
            for each (var field in fields) {
                // Ignore read only fields
                var roattr = field.getAnnotation("System.ComponentModel.ReadOnlyAttribute");
                if (roattr !== undefined && roattr != null) continue;
                // Check if field has setter otherwise is read only
                var field_name = field.getName();
                var setter_found = false;
                for each (var method in methods) {
                    if (method.getName() == "set_" + field_name) {
                        setter_found = true;
                        break;
                    }
                }
                if (!setter_found) continue;

                processField(field, visited);
            }
        }
    }
}

var MASS_ASSIGNMENT_REGEXP = /manager|admin|role|access|price|cost|secret|priv/i;

function processField(field, visited) {
    // Loop through nested fields in the given class if they are not primitive or System classes
    // If field name matches Mass Assignment regular expression, label it with exposedCommandField
    // alert("processing field " + field.getName());
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedCommandField");
    }
    if (!type.isPrimitive() && !key.match(/^(System|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    processField(new_field, visited);
                }
            }
        }
    }
}

// Collect all command classes
var cmclasses = nameTable.getClassesByLabel("insecureBinding", "dotnet");
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null && cmclass != '[UnknownType]') {
            var visited = {};
            visited[cmclass.getPackageName() + "." + cmclass.getName()] = true;
            var fields = cmclass.getFields();
            var methods = cmclass.getMethods();

            // Loop through the command class fields and look for other non primitive nor system classes nested in the object
            for each (var field in fields) {
                // Ignore read only fields
                var roattr = field.getAnnotation("System.ComponentModel.ReadOnlyAttribute");
                if (roattr !== undefined && roattr != null) continue;
                // Check if field has setter otherwise is read only
                var field_name = field.getName().substring(1).replace("_k__BackingField","");
                var setter_found = false;
                for each (var method in methods) {
                    if (method.getName() == "set_" + field_name) {
                        setter_found = true;
                        break;
                    }
                }
                if (!setter_found) continue;
                // SCA translate properties as _<name>_k__BackingField. In order to match only field access to class properties (since Fields cannot be matched) we have to check that field name ends with "_BackingField"
                if (field.getName().indexOf("_k__BackingField") === -1) continue;

                processField(field, visited);
            }
        }
    }
}

// Helper Functions
function extractFirstValue(str) {
    var first_delimiter = str.indexOf("::");
    var last_delimiter = str.lastIndexOf("::");
    if (first_delimiter > 0 && last_delimiter > 0 && last_delimiter !== first_delimiter) {
        return String(str.substring(first_delimiter + 2, last_delimiter));
    }
    return null;
}

function extractSecondValue(str) {
    var first_delimiter = str.indexOf("::");
    var last_delimiter = str.lastIndexOf("::");
    if (first_delimiter > 0 && last_delimiter > 0 && last_delimiter !== first_delimiter) {
        return String(str.substring(last_delimiter + 2));
    }
    return null;
}

