        }
    }
}

(function(debug) {
    function log(msg) {
        if (debug) {
            alert('dotnet.aws.handlers alert: ' + msg)
        }
    }

    /**
     * 
     * @param {String} capture in the form of either 'ASSEMBLY::NAMESPACE.CLASSNAME::FUNCTIONNAME'
     * or it may also contain appended '//EVENT_SOURCE' 
     */
    function labelHandlerAndEvents(capture) {
        var FQCN_DELIMITER = '::'
        var  EVENT_DELIMITER = '//'

        var fqcnAndEvent = capture.split(EVENT_DELIMITER)
        var fqcnWithAssembly = fqcnAndEvent[0].split(FQCN_DELIMITER)
        if (fqcnWithAssembly.length != 3){
            log('Unknown assembly string: ' + fqcnWithAssembly)
            return {} // unknown 
        }
        var fqcn = fqcnWithAssembly[1]
        var functionName = fqcnWithAssembly[2]
        var event = null;
        if (fqcnAndEvent.length == 1){
            event = ''
        }else{
            event = fqcnAndEvent[1]
        }

        var methods = findMethod(fqcn, functionName);
        if (methods.length > 0){
            log('found method: ' + fqcn + '.' + functionName);
            labelHandler(methods);
            labelEvent(methods, event)
        }

    }

    /**
     * 
     * @param {String} className fully qualified function name 
     * @param {String} functionName
     * @return {Array<jsMethod>} the method(s) from the nametable
     */
    function findMethod(className, functionName) {
        var fqfn = className + '.' + functionName
        if (methodCache[fqfn] !== undefined){
            return methodCache[fqfn]
        }
        var c = nameTable.getClassByFullName(className, 'dotnet')
        if (c === null || c === undefined){
            log(className + ' not found');
            return new Array();
        }
        log('found ' + className)
        var methods = c.getMethods()
        if (methods === null || methods === undefined){
            log('no methods found on ' + className)
            return new Array();
        }
        var methodsArr = new Array()
        for (var i = 0; i < methods.length; i++){
            var method = methods[i];
            if (method.name == functionName) {
                log('found ' + functionName)
                methodsArr.push(method)
            }
        }
        methodCache[fqfn] = methodsArr
        return methodsArr
    }
    // cache the method so that we don't accidentally look it up from the nametable a bunch of times
    var methodCache = {}

    /**
     * Takes a list of methods and labels them to signify they are an AWS lambda
     * @param {Array<jsMethod>} methods the AWS handler methods to label
     */
    function labelHandler(methods){
        for (var i = 0; i < methods.length; i++){
            var method = methods[i]
            log('setting lambda label on ' + method.name)
            method.setLabel('AWS_Lambda_Handler')
        }
    }

    /**
     * Sets labels on the methods for associated AWS event sources
     * @param {Array<jsMethod>} methods the methods to label for the event
     * @param {String} event the name of the event
     */
    function labelEvent(methods, event){
        if (event == '' || event === null || event === undefined){
            return;
        }
        for (var i = 0; i < methods.length; i++){
            var method = methods[i]
            if (event.indexOf('Api') > -1){
                log('setting ApiGateway label on ' + method.name)
                method.setLabel('AWS_Lambda_ApiGateway')
            }
            if (event.indexOf('S3') > -1){
                log('setting S3 label on ' + method.name)
                method.setLabel('AWS_Lambda_S3')
            }
        }
    }

    var captures = nameTable.getGlobalCaptures('dotnet.aws.handler');
    for (var i = 0; i < captures.length; i++ ) {
        labelHandlerAndEvents(captures[i])
    }


})(false)

