// Check if the current JSON file is an Azure Resource Manager configuration
function isArmJsonFile(jsonString) {
    var lines = jsonString.split('\n');

    for each (var line in lines) {
        if (line.match("\"\\$schema\"") && line.match("http://schema\.management\.azure\.com/schemas/.*/deploymentTemplate\.json")) {
            return true;
        }
    }

    return false;
}

var allFiles = getAllProgramFileNames();

for each (var fName in allFiles) {
    if (fName.match(/.*\.json$/i)){
        //alert("Found json file: " + fName);
        var jsonFileContents = '';
        try {
            jsonFileContents = readFile(fName);
        } catch (err) {
            log("Error reading file "+fName);
            continue;
        }
        if (isArmJsonFile(jsonFileContents)) {
            var lines = jsonFileContents.split('\n');

            for (var i = 0; i < lines.length; i++){
                var lineNum = i + 1;

                // If supportsHttpsTrafficOnly is set to false report issue
                if (lines[i].match("\"supportsHttpsTrafficOnly\"[ \t]*:[ \t]*(\")?false(\")?")) {
                    dbg("matched supportsHttpsTrafficOnly");
                    createScriptedIssue("HttpsTrafficOnly", "2F0920C5-009E-412F-BEA8-CC18EA3682B3", lineNum, lineNum, fName)
                }

                // If allowBlobPublicAccess is set to true report issue
                if (lines[i].match("\"allowBlobPublicAccess\"[ \t]*:[ \t]*(\")?true(\")?")) {
                    dbg("matched supportsHttpsTrafficOnly");
                    createScriptedIssue("allowBlobPublicAccess", "40824D4F-E087-4721-995A-C162D8C57622", lineNum, lineNum, fName)
                }
            }
        }
    }
}

function log(msg) {
