 }
    /**
    *
    * label Google cloud functions based on trigger type 
    * @param method {object} the method object
    * @param trigger_type {string} Function trigger type 
    */
    function labelGCPEntry(method, http_trigger) {
        if (method == '' || method === null || method === undefined){
        return;
        }
        // if the trigger type is http trigger
        if (http_trigger == "--trigger-http") {
            method.setLabel("GCP_Func_http_trigger");
            //log('Set label: GCP_Func_http_trigger');
        } else { 
            method.setLabel("GCP_Func_ICC_CLOUD"); 
            //log('Set label: GCP_Func_ICC_CLOUD');
        }
    }

    /**
     * Check lambda entry point for the corresponding trigger type
     * check if the entry point exists in the config file, so we can override the capture lambda name
     * as it takes precedence over the default function name 
     */
    function chkEntrypoint(fnName,captureName){
        // this is the default case when the config file doesn't have "--entry-point"  or 
        // if "--entry-point" equals to lambda name in the config file
        var FLambda = fnName;
        var captured = nameTable.getGlobalCaptures(captureName);

        for (var i = 0; i < captured.length; i++) {
            var item = captured[i];
            var retrieve = item.split('//');
            // The default function name 
            var lambda = retrieve[0].trim();
            // Other entries in the config file
            var config = retrieve[1].trim();

            if (lambda == fnName){
                //log('Found lambda: ' + fnName);
                if (config.includes("--entry-point")) {
                    var retValue = config.split('=');
                    var entry_point = retValue[1].trim();
                    //log('test for entrypoint and lambda: ' + entry_point + ', fn: ' + lambda );
                    if (entry_point != lambda){
                        FLambda = entry_point;
                        //log('Found different entrypoint: ' + entry_point + ', fn: ' + lambda );
                    }    
                }    
            }
        }     
        return FLambda
    }   
    /**
    *  This method retrieves captured values in yaml or json build config files, matching function names and sets the right label based on the trigger type
    * @param captureName {string} the capture rule label name
    * @param lang {string} the function language: mainly dynamic language such as python and JS/TS
    */
    function LabelGCP_FnName(captureName, lang){
        try{ 
            var captured = nameTable.getGlobalCaptures(captureName);
            // check captured properties and get the lambda function name and the trigger type
            for (var i = 0; i < captured.length; i++) {
                var item = captured[i];
                //log(item);
                var retrieve = item.split('//');
                // The default function name 
                var lambda = retrieve[0].trim();
                // Other entries in the config file
                var config = retrieve[1].trim();
                // to store the trigger type
                var triggerType = "";

                //check if the --trigger-event (1st gen) --trigger-bucket, --trigger-topic or --trigger-event-filters (2nd gen)  exists in the config file.
                // This won't, specifically, check "--gen 2” as we are interested to verify if "http trigger" exists or not and label/taint accordingly 
                if (config.includes("--trigger-event") || config.includes("--trigger-topic") || config.includes("--trigger-bucket") ||  config.includes("--trigger-event-filters")) {
                    triggerType = "non-http-trigger";
                    //check if the entry point is different from default lambda name
                    lambda = chkEntrypoint(lambda,captureName);
                } 
                //check if --trigger-http exists in the config file 
                else if (config == "--trigger-http"){
                    triggerType = config;
                     //check if the entry point is different from default lambda name
                    lambda = chkEntrypoint(lambda,captureName);
                }  
                // it's important to check the triggertype if empty to avoid FPs (may cause double labelling)   
                if (lambda !== "" && triggerType !== ""){
                    var global_functions = nameTable.getGlobalFunctions(lang)
                    //log('IN: ' + lambda);
                    if (global_functions !== null){ 
                        for each (var gf in global_functions) {
                            //get the global function name
                            var gf_sig = gf.getName();
                            //check if the lambda function matches and its trigger type
                            if (lambda == gf_sig) {    
                            //   log('Method match, set the labels ' + lambda + ':' + http_trigger)
                                gf.setLabel("GCP_Func_Entry_Point");
                                labelGCPEntry(gf,triggerType)
                            }
                        } 
                    }
                }    
            }    
        } catch (err) {
            //   
            log("Exception thrown was: " + err + ". Please review for any syntax errors.");
        } 
    } 

    /**
     * check com.fortify.sca.rules.GCPHttpTrigger property
     */
    function getGCPHttpTriggerProp(){
        var httptriggerType = getProperty("com.fortify.sca.rules.GCPHttpTrigger");
        if (httptriggerType !== "" &&  httptriggerType !== null ) {
            httptriggerType = httptriggerType.trim();
        }    
        return httptriggerType;
    }
    /**
    *  This method checks if sca properties for GCP function are existed; 
    *  if not it checks for the existing yaml or json config files, then set the right label.
    *  Two sca.rule properties: "com.fortify.sca.rules.GCPFunctionName" for the function name and "com.fortify.sca.rules.GCPHttpTrigger"
    *  to check for http-trigger type
    */    
    function GCPConfigPropertySca() {
        try{
            var lambda = getProperty("com.fortify.sca.rules.GCPFunctionName"); 
            var httptriggerType  = getGCPHttpTriggerProp() == "true"; 

            if (lambda !== "" &&  lambda !== null ) {
                //log('testing properties');
                var global_functions = nameTable.getGlobalFunctions("python");
                lambda = lambda.trim();
                if (global_functions !== null){ 
                    for each (var gf in global_functions) {
                        //get the global function name
                        var gf_sig = gf.getName();
                        //check if the lambda function matches and its trigger type
                        if (lambda == gf_sig) {    
                            gf.setLabel("GCP_Func_Entry_Point");
                            if (httptriggerType){
                                gf.setLabel("GCP_Func_http_trigger");
                            }   
                            else {
                                gf.setLabel("GCP_Func_ICC_CLOUD");
                            }   
                        }
                    } 
                }    
            }
            else {
                LabelGCP_FnName("gcf.lambda_yaml_options","python");
                LabelGCP_FnName("gcf.lambda_json_options","python");
            }
        } catch (err) {
            //   
            log("Exception thrown was: " + err + ". Please review for any syntax errors.");
        }   
    }    

    GCPConfigPropertySca();

(function () {
    function processType(type, visited) {
        // Loop through nested fields in the given class if they are not primitive of java JDK classes
        if (type === null
            || type === undefined
            || type.getName() == "[UnknownType]"
            || type.isPrimitive()
            || type.getPackageName() === null
            || type.getPackageName().match(/^java/)
            || type.getPackageName().match(/^org\.springframework/)) {
                return;
        }
        var key = String(type.getPackageName() + "." + type.getName());
        //alert("CommandClass: " + key)
        if (visited[key] !== true) {
            visited[key] = true;
            var fields = type.getFields();
            if (fields !== null && fields !== undefined) {
                // Loop through the command class fields and look for other non primitive
                // and non-JDK classes nested in the object
                for each (var new_field in fields) {
                    processField(new_field, visited);
                }
            }
        }
    }

    function processField(field, visited) {
        if (field === null || field === undefined) {
            return;
        }
        field.setLabel("commandField");
        //alert("\tCommandField: " + field.getName())
        processType(field.getType(), visited);
    }

    // Collect all Spring command classes
    var visited = {};
    var sp2cc = nameTable.getClassesByLabel("spring2CommandObject", "java");
    var sp3cc = nameTable.getClassesByLabel("spring3CommandObject", "java");
    var cmclasses = null;
    if (sp2cc === null && sp3cc !== null) cmclasses = sp3cc;
    if (sp2cc !== null && sp3cc === null) cmclasses = sp2cc;
    if (sp2cc !== null && sp3cc !== null) cmclasses = sp2cc.concat(sp3cc);
    if (cmclasses != null) {
        for each (var cmclass in cmclasses) {
            processType(cmclass, visited);
        }
    }
})();

// Collect all dotnet property fields
var dotnetproperty = nameTable.getFieldsByLabel("dotnetProperty", "dotnet");
if (dotnetproperty != null && dotnetproperty !== undefined) {
    for each (var prop in dotnetproperty) {
        if (prop != null && prop !== undefined) {

            var enclosingclass = prop.getEnclosingClass();

            if (enclosingclass !== null && enclosingclass !== undefined && enclosingclass != '[UnknownType]') {

                var methods = enclosingclass.getMethods();
                var field_name = prop.getName();

                for each (var method in methods) {
                    if (method.getName() == "set_" + field_name || method.getName() == "get_" + field_name) {
                        method.setLabel("propertyMethod");
                    }
                }
            }
        }
    }
}

                        //
                        // Set up data structures for managed beans.  This handles both JSF and
                        // Spring managed bean configuration files.
                        //
                        function setUpManagedBeans() {
                          var jsfns1 = new Namespace("");                                              // handle JSF < 1.2
                          var jsfns2 = new Namespace("http://java.sun.com/xml/ns/javaee");             // handle JSF >= 1.2
                          var jsfns3 = new Namespace("http://java.sun.com/xml/JSF/Configuration");     // handle another JSF faces namespace
                          var jsfns4 = new Namespace("http://xmlns.jcp.org/xml/ns/javaee");     // handle JSF 2.2 faces namespace
                          var springns = new Namespace("http://www.springframework.org/schema/beans"); // handle spring beans that work with JSF
                          var adfns = new Namespace("http://xmlns.oracle.com/adf/controller");         // handle Oracle ADF
                          var dir_group = new Object(), groups = new Array;
                          var group;
                          var sep = null;
                          var found;

                          // (local function)
                          function processAnnotations(annotation, clss, beanNameFn, beanClassNameFn) {
                            var beans = new Array();
                            var beanName = String(beanNameFn(annotation));
                            var beanClassName = String(beanClassNameFn(clss));
                            if (beanName == "" || beanClassName == "") {
                                dbg("Invalid managed-bean element: Empty bean name or class");
                                return;
                            }
                            if (JavaUtils.isValidPackageName(beanClassName)) {
                                var bean = new Object();
                                bean.beanName = beanName;
                                bean.beanClassName = beanClassName;
                                beans[beans.length] = bean;
                                var beanClass = nameTable.getClassByName("", beanClassName, "java");
                                if (JavaUtils.isSafeForGlobal(beanClass) && beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                  dbg("Labeling class " + beanClass.getPackageName() + '.' + beanClass.getName());
                                  beanClass.setLabel("ManagedBeanClass");
                                }
                            }
                            // We dont have config files to group beans together. All the beans resolution
                            // coming from annotated manged bean classes are grouped under dir "/"
                            var dir = "/";
                            if (dir_group[dir] == null) {
                                group = new Object();
                                group.dir = dir;
                                group.files = new Array();
                                group.beans = beans;
                                dir_group[dir] = group;
                                groups[groups.length] = group;
                            } else {
                                dir_group[dir].beans = dir_group[dir].beans.concat(beans);
                            }
                          }

                          // (local function)
                          function processDecls(cfgfile, decls, beanNameFn, beanClassNameFn) {
                                var beans = new Array();
                                var pos, pos1, dir;

                                for each (var decl in decls) {
                                  var beanName = String(beanNameFn(decl));
                                  var beanClassName = String(beanClassNameFn(decl));
dbg("Found " + beanName + " -> " + beanClassName);
                                  if (beanName == "" || beanClassName == "") {
                                        dbg("Invalid managed-bean element: Empty bean name or class in " + decl);
                                        continue;
                                  }
                                  if (JavaUtils.isValidPackageName(beanClassName)) {
                                        var bean = new Object();
                                        bean.beanName = beanName;
                                        bean.beanClassName = beanClassName;
                                        beans[beans.length] = bean;
                                        var beanClass = nameTable.getClassByName("", beanClassName, "java");
                                        if (beanClass != null && '[UnknownType]' != beanClass.getName()) {
                                          beanClass.setLabel("ManagedBeanClass");
                                        }
                                  }
                                }
                                // The applicable containing directory is (we hope) the one containing
                                // the WEB-INF directory.
                                pos = cfgfile.lastIndexOf(sep);
                                do {
                                  pos1 = pos;
                                  pos = cfgfile.lastIndexOf(sep, pos - 1);
                                } while (pos > 0 && cfgfile.substring(pos + 1, pos1) != "WEB-INF");
                                if (pos <= 0) {
                                  //log("\"WEB-INF\" not found in \"" + cfgfile + "\"");
                                } else {
                                  dir = cfgfile.substring(0, pos);
dbg("Dir: " + dir);
                                  if (dir_group[dir] == null) {
                                        group = new Object();
                                        group.dir = dir;
                                        group.files = new Array();
                                        group.beans = beans;
                                        dir_group[dir] = group;
                                        groups[groups.length] = group;
                                  } else {
                                        dir_group[dir].beans = dir_group[dir].beans.concat(beans);
                                  }
                                }
                          }

                          var springJSFIntegration = false;
                          // First, collect the bean declarations from the config files, organizing
                          // them by the directory containing the config file.
                          for (var cfgfile in program.xml) {
                                var cfg = program.xml[cfgfile];
                                if (sep == null) {
                                  if (cfgfile[1] == ":" && cfgfile[2] == "\\") sep = "\\";
                                  else sep = "/";
                                }
                                if (cfg.name() == null ||
                                        // Ignore files that arent under a WEB-INF directory
                                        cfgfile.indexOf(sep + "WEB-INF" + sep) < 0) {
                                  continue;
                                }
                                dbg("Looking at " + cfgfile);
                                dbg("NS " + cfg.name().uri);
                                dbg("LN " + cfg.name().localName);
                                if (cfg.name().uri == jsfns1.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns1::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns1::["managed-bean"],
                                                           function (decl) { return decl..jsfns1::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns1::["managed-bean-class"]; });
                                } else if (cfg.name().uri == jsfns2.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns2::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns2::["managed-bean"],
                                                           function (decl) { return decl..jsfns2::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns2::["managed-bean-class"]; });
                                } else if (cfg.name().uri == jsfns3.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns3::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns3::["managed-bean"],
                                                           function (decl) { return decl..jsfns3::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns3::["managed-bean-class"]; });
                                } else if (cfg.name().uri == jsfns4.uri && cfg.name().localName == "faces-config") {
                                    for each(var elresolver in cfg..jsfns4::["el-resolver"]) {
                                        if (elresolver !== null && elresolver !== undefined) {
                                            if (elresolver.text() == "org.springframework.web.jsf.el.SpringBeanFacesELResolver") {
                                                springJSFIntegration = true;
                                                break;
                                            }
                                        }
                                    }
                                    processDecls(cfgfile, cfg..jsfns4::["managed-bean"],
                                                           function (decl) { return decl..jsfns4::["managed-bean-name"]; },
                                                           function (decl) { return decl..jsfns4::["managed-bean-class"]; });
                                }
                                if (cfg.name().uri == adfns.uri && cfg.name().localName == "adfc-config") {
                                    processDecls(cfgfile, cfg..adfns::["managed-bean"],
                                                           function (decl) { return decl..adfns::["managed-bean-name"]; },
                                                           function (decl) { return decl..adfns::["managed-bean-class"]; });
                                }
                                if (springJSFIntegration && cfg.name().uri == springns.uri && cfg.name().localName == "beans") {
                                    processDecls(cfgfile, cfg..springns::["bean"],
                                                           function (decl) {
                                                        var id = decl.attribute("id");
                                                        if (String(id) == "") id = decl.attribute("name");
                                                        return id;
                                                       },
                                                       function (decl) { return decl.attribute("class"); });
                                  // Local function to handle nested imports.  Since we don't bother to figure
                                  // out which is the root config file, we can wind up processing leaf files
                                  // more than once, but no harm is done thereby.
                                  function processImports(cfgroot) {
                                        for each (var importelt in cfgroot..springns::["import"]) {
                                          var dir = cfgfile;
                                          var importfile = String(importelt.attribute("resource"));
                                          // strip basename, leaving directory
                                          dir = dir.substring(0, dir.lastIndexOf(sep));
                                          if (importfile.indexOf("file:") == 0) {
                                                importfile = importfile.substring(5);
                                          } else if (importfile.indexOf("classpath:") == 0) {
                                                //log("Can't resolve classpath import resource: " + importfile);
                                                continue;
                                          } else {
                                                // Leading slash is ignored (per Spring docs)
                                                if (importfile.charAt(0) == "/") {
                                                  importfile = importfile.substring(1);
                                                }
                                                // It's common for these paths to start with one or more ".." elements
                                                while (importfile.indexOf("../") == 0) {
                                                  importfile = importfile.substring(3);
                                                  dir = dir.substring(0, dir.lastIndexOf(sep));
                                                }
                                                if (sep == "\\") {
                                                  importfile = importfile.replace(/\//g, "\\");
                                                }
                                                importfile = dir + sep + importfile;
                                          }
dbg("Import: " + importfile);
                                          var imported = program.xml[importfile];
                                          if (imported == null) {
                                                setUpCaseInsensitiveXmlFileMap();
                                                imported = program.xml_ci[importfile.toLowerCase()];
                                          }
                                          if (imported == null) {
                                                //log("Can't find Spring bean import file [" + importfile + "]");
                                          } else {
                                                processDecls(cfgfile, imported..springns::["bean"],
                                                                         function (decl) { return decl.attribute("id"); },
                                                                         function (decl) { return decl.attribute("class"); });
                                                processImports(imported);
                                          }
                                        }
                                  }

                                  processImports(cfg);
                                }
                          }

                          // and collect the bean declarations from the annotated managed bean classes files
                          var allClasses = nameTable.getAllClasses("java");
                          var ann;
                          for each (var clss in allClasses) {
                              if (clss != null) {

                                  // Helper functions
                                  var beanNameFnName = function (annotation) {
                                              var nameProp = annotation.get("name");
                                              if (nameProp == null) {
                                                  // Bean name is set by the framework as the class name with the first letter lowercase
                                                  beanName = clss.getName().substr(0,1).toLowerCase() + clss.getName().substr(1);
                                              } else {
                                                  // Bean name is set by the developer through the annotation
                                                  beanName = nameProp.getStrValue();
                                              }
                                              return beanName;
                                          };
                                  var beanNameFnValue = function (annotation) {
                                              var nameProp = annotation.get("value");
                                              if (nameProp == null) {
                                                  // Bean name is set by the framework as the class name with the first letter lowercase
                                                  beanName = clss.getName().substr(0,1).toLowerCase() + clss.getName().substr(1);
                                              } else {
                                                  // Bean name is set by the developer through the annotation
                                                  beanName = nameProp.getStrValue();
                                              }
                                              return beanName;
                                          };
                                  var beanClassFn = function (clss) { return clss.getPackageName() + "." +  clss.getName();};
                                  // JSF2 @ManagedBean annotated beans
                                  ann = clss.getAnnotation("javax.faces.bean.ManagedBean");
                                  if (ann != null) {
                                      processAnnotations(ann, clss, beanNameFnName, beanClassFn);
                                  }
                                  // JSR330 @Named annotated beans
                                  ann = clss.getAnnotation("javax.inject.Named");
                                  if (ann != null) {
                                      processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                  }
                                  // JSR @javax.annotation.ManagedBean annotated beans
                                  ann = clss.getAnnotation("javax.annotation.ManagedBean");
                                  if (ann != null) {
                                      processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                  }
                                  // Spring beans in case JSF/Spring integration is enabled
                                  if (springJSFIntegration) {
                                    // Spring @Component annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Component");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @Repository annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Repository");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @Service annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Service");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @Controller annotated beans
                                    ann = clss.getAnnotation("org.springframework.stereotype.Controller");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                    // Spring @RestController annotated beans
                                    ann = clss.getAnnotation("org.springframework.web.bind.annotation.RestController");
                                    if (ann != null) {
                                        processAnnotations(ann, clss, beanNameFnValue, beanClassFn);
                                    }
                                  }
                              }
                          }


                          // Second, sort the groups into decreasing order by directory (decreasing so
                          // that in case any of them are nested (which they really shouldn't be anyway)
                          // we try the deeper ones first).
                          groups.sort(function (g1, g2) {
                                                        if (g2.dir < g1.dir) return -1;
                                                        else if (g2.dir > g1.dir) return 1;
                                                        else return 0;
                                                  });
                          // Third, collect the JSP/JSPX/XHTML files in each group.
                          for each (var file in getJSPFileNames()) {
                                for each (var g in groups) {
                                  found = false;
                                  if (file.indexOf(g.dir) == 0) {
                                        g.files[g.files.length] = file;
                                        found = true;
                                        // let the groups share the same files
                                        // break;
                                  }
                                  //if (!found) log("Can't find config file for [" + file + "]");
                                }
                          }
                          // Finally, pass the data back to the analyzer.  Alas, we have to do it
                          // this way -- we can't just pass the whole data structure.
                          openManagedBeanMap();
                          for (var i = 0; i < groups.length; ++i) {
                                group = groups[i];
                                newManagedBeanSubmap();
                                for (var j = 0; j < group.beans.length; ++j) {
                                  addManagedBeanSubmapPair(group.beans[j].beanName, group.beans[j].beanClassName);
                                }
                                for (var j = 0; j < group.files.length; ++j) {
                                  addManagedBeanFile(group.files[j]);
                                }
                          }
                          closeManagedBeanMap();
                        }

                        function setUpCaseInsensitiveXmlFileMap() {
                          if (program.xml_ci == null) {
                                program.xml_ci = new Object();
                                for (var fn in program.xml) {
                                  program.xml_ci[fn.toLowerCase()] = program.xml[fn];
                                }
                          }
                        }

                        if (!program.managed_beans_set_up) {
                          setUpManagedBeans();
                          program.managed_beans_set_up = true;
                        }

function checkSpringBootConfiguration(name, value) {
    // Actuator Endpoint configuration 
    if (name == "management.security.enabled" && value == "false") {
        endpoints_15_exposed = true;
    }
    else if (name.match(/endpoints.*\.sensitive/) && value == "false") {
        endpoints_15_exposed = true;
    }
    else if (name == "endpoints.sensitive" && value == "false") {
        endpoints_sensitive = true;
    }
    else if (name == "management.endpoints.web.exposure.include" && value == "*") {
        endpoints_20_exposed = true;
    }
    // JMX configuration
    else if (name == "management.endpoints.jmx.exposure.exclude" && value == "*") {
        jmx_enabled = false;
    }
    else if (name == "spring.jmx.enabled" && value == "true") {
        jmx_enabled = true;
    }
}

var checks = {
    // Password Management: Password in Configuration File
    "1253DB08-DB3F-4F26-B94E-9D5DEB3F9632": [ 
        function(name, value) { return name.match(".*pass(wd|word|phrase).*") && value.indexOf("${") !== 0 && value !== "" && value !== "~" && value !== "null"},
    ],
    // Password Management: Empty Password in Configuration File
    "E4D2C5FF-456F-43B2-B279-01E8D6AD5630": [ 
        function(name, value) { return name.match(".*pass(wd|word|phrase).*") && (value === "" || value === "~" || value === "null") },
    ],
    // Admin MBean Enabled
    "35555AF0-088D-4573-A18A-2F14DC4760B0": [ 
        function(name, value) { return name == "spring.application.admin.enabled" && value == "true" },
    ],
    // Insecure Transport
    "219715CE-739B-4A21-BE7D-D1A42CC432FF": [ 
        function(name, value) { return name == "server.ssl.enabled" && value == "false" },
        function(name, value) { return name == "spring.couchbase.env.ssl.enabled" && value == "false" },
        function(name, value) { return name == "management.server.ssl.enabled" && value == "false" },
    ],
    // Server Identity Verification Disabled
    "7E1B5AD8-01A5-4C4A-8CA7-8D00E7EFDD0D": [ 
        function(name, value) { return name == "spring.rabbitmq.ssl.verify-hostname" && value == "false" },
        function(name, value) { return name == "spring.rabbitmq.ssl.validate-server-certificate" && value == "false" },
        function(name, value) { return name == "management.cloudfoundry.skip-ssl-validation" && value == "true" },
    ],
    // System Information Leak: External
    "C5C9C0FE-00E2-40A1-AF6F-2F4077C24D1F": [ 
        function(name, value) { return name == "server.error.include-stacktrace" && value.match("always|on-trace-param") },
        function(name, value) { return name == "management.endpoint.configprops.keys-to-sanitize" && value == "" },
        function(name, value) { return name == "management.endpoint.env.keys-to-sanitize" && value == "" },
    ],
    // Actuator Endpoint Security Disabled
    "8E025144-B98C-45A6-89F9-FA57943F60E8": [ 
        function(name, value) { return name == "management.security.enabled" && value == "false" },
        function(name, value) { return name.match(/endpoints.*\.sensitive/) && value == "false" },
    ],
    // Shutdown Actuator Endpoint Enabled
    "253B7D80-2FE6-4ABC-AB37-8C7C6EFB082A": [ 
        function(name, value) { return name == "endpoints.shutdown.enabled" && value == "true" },
    ],
    // Overly Permissive CORS Policy
    "C04203BD-4F34-46C3-9697-948F0C62AB22": [ 
        function(name, value) { return name == "endpoints.cors.allowed-origins" && value == "*" },
    ],
    // Session Cookie not Sent Over SSL
    "A8F7B91B-A77E-44E2-BCED-D148BC119210": [ 
        function(name, value) { return name == "server.servlet.session.cookie.secure" && value == "false" },
    ],
    // HTTPOnly not Set on Session Cookie
    "04825001-46B5-4241-B1BC-C6FBDDD46813": [ 
        function(name, value) { return name == "server.servlet.session.cookie.http-only" && value == "false" },
    ],
    // Persistent Session Cookie
    "4E971761-D1B1-4F0E-A5A9-B5EBBDC4C5F1": [ 
        function(name, value) { return name == "server.servlet.session.cookie.persistent" && value == "true" },
    ],
    // Overly Broad Session Cookie Domain
    "5F39B0C2-6AAF-4FD7-9A88-29C9BD061126": [ 
        function(name, value) { return name == "server.servlet.session.cookie.domain" && (value.match("^(\.)?[a-z0-9\-]+\.[a-z0-9\-]+$") || value.match("^(\.)?[a-z0-9\-]+\.[a-z]{1,3}\.[a-z]{1,3}$")) },
    ],
    // Overly Broad Session Cookie Path 
    "8624CC84-BAA0-4172-9AB9-2BA8915FD75F": [ 
        function(name, value) { return name == "server.servlet.session.cookie.path" && value.match("^/$") },
    ]
}

// Inspect application.yaml files
var allFiles = getAllProgramFileNames();
for each (var file in allFiles) {
    if (file.match(/application.*\.y(a)?ml$/i)) {
        try {
            var props = yamlToPropertyMap(file);
            for each (var p in props) {
                var line = p.substr(0, p.indexOf("::"));
                var prop = p.substr(p.indexOf("::") + 2);
                var propName = prop.substr(0, prop.indexOf("="));
                var propValue = prop.substr(prop.indexOf("=") + 1);

                // Check configuration
                checkSpringBootConfiguration(propName, propValue);

                // Report issues
                for (var ruleId in checks) {
                    for (var check in checks[ruleId]) {
                        if (checks[ruleId][check](propName, propValue.toLowerCase())) {
                            createScriptedIssue(propName, ruleId, line, line, file); 
                        }
                    }
                }

            }
        } catch (err) {
            warn_internal("Error parsing build scripts: " + err);
        }
    }
}

// Inspect project dependencies
var dependencies = [];
if (hasPersistedObject("program.dependencies")) {
    dependencies = loadPersistedObject("program.dependencies");
}

for (var dep in dependencies) {
    var pathInfo = dependencies[dep];
    var file = pathInfo.split(":")[0];
    var line = pathInfo.split(":")[1];

    // Only create issue for gradle since it should be reported in maven by config rule
    if (file.indexOf("build.gradle") > -1) {

        if (dep.indexOf("org.springframework.boot:spring-boot-starter-actuator:") === 0) {
            // Dynamic Code Evaluation: Unsafe Deserialization 
            if (jmx_enabled) {
                createScriptedIssue(dep, "7DE83F69-C426-4436-A9E2-187EE2AD8A78", line, line, file); 
            }

            // System Information Leak: Spring Boot Actuators Enabled (1.0-1.4)
            if (hasDependency("org.springframework.boot", "", "1.") &&
                !hasDependency("org.springframework.boot", "", "1.5") &&
                endpoints_14_exposed) {
                createScriptedIssue(dep, "7A266996-0386-4872-A43E-E1D132B7ABCD", line, line, file); 
            }
            // System Information Leak: Spring Boot Actuators Enabled (1.5.x)
            else if (hasDependency("org.springframework.boot", "", "1.5") &&
                endpoints_15_exposed) {
                createScriptedIssue(dep, "7A266996-0386-4872-A43E-E1D132B7ABCD", line, line, file); 
            }
            // System Information Leak: Spring Boot Actuators Enabled (2.x)
            else if (hasDependency("org.springframework.boot", "", "2.") && 
                endpoints_20_exposed &&
                !hasDependency("org.springframework.boot", "spring-boot-starter-security")) {
                createScriptedIssue(dep, "7A266996-0386-4872-A43E-E1D132B7ABCD", line, line, file); 
            }
        }
        else if (dep.indexOf("org.springframework.boot:spring-boot-devtools:") === 0) {
            // Spring Boot Misconfiguration: DevTools Enabled
            createScriptedIssue(dep, "88EAC0BC-B9E8-4105-9E84-D2940EF0A61D", line, line, file); 
        }
    }
}

/**
1. Determine if mapper XML file
2. Determine aliases
3. Retrieve namespace/class name
4. retrieve functions by "id"
5. label functions for relevant sinks/sources
*/

function init_mybatis(){
    /**
    Unfortunately mybatis mapper files don't have a specific namespace, just use DOCTYPE, which is apparently thrown away with E4X.
    Will just assume all XML files with element like:
    <mapper namespace="org.some.company"> is for a MyBatis project.
    Only other alternative would be to go through lots of configuration files trying to determine values. This is impossible in some cases such as hardcoded full paths, which we'd need to guess.
    Also other things like MyBatis-Spring plugin can recursively go through namespaces, specifying everything as mapper files under that. Would be difficult and unreliable from via rulescripting.
    If later gain ability to check DOCTYPE somehow, this could be checked in the mapper file I think.
     */
     var ns = new Namespace("");
     var mapper_func_arr = new Array();
     mybatis_query_types = ["select", "insert", "update", "delete"]; //different XML elements. Only source on select
     for each (var mapper in program.xml){
        dbg("iterating over program.xml");
        if (null != mapper.name() && null != mapper.name().localName.match("mapper") && null != mapper["@namespace"]){ //any mapper element with existing namespace attribute
            dbg("Found a MyBatis mapper file");
            var mybatis_mapper_namespace =  mapper["@namespace"];

            for each (var query_type in mybatis_query_types){

                for each (var query in mapper..ns::[query_type]){
                    //get id attribute, which is really the method name in the Java class
                    if (null != query.name() && null != query.name().localName.match(query_type) && null != query["@id"]){
                        var mapper_func = String(query["@id"]);
                        /**
                            Planned to put the methods into an array and then go through this,
                            but couldn't figure out a way to do the logic properly for methods that may be in super classes.
                            May be possible with labels/gotos but it was starting to get ugly and unnecessarily complicated.
                            Leaving as a single method and class name means that the additional function will be called more,
                            but I don't think there should be a substantial performance hit rather than repeatedly looping building/destroying and looping arrays.
                        */
                        funcFinder(mybatis_mapper_namespace, mapper_func, query_type);
                    }
                }
            }
        }
     }
}

function funcFinder(class_name, func_name, query_type){
    var found = false;
    /*
    'found' var is used for determing if need to look through super class(es) for mapper methods.
    Couldn't get this logic to work nicely for arrays. Put back to this function receiving single function name.
    Obviously leads to this function being called more, but I don't think it should have any performance impact
    */
    mapper_class = nameTable.getClassByFullName(class_name, "java");
    if (null != mapper_class && "[UnknownType]" != mapper_class.getName()){
        mapper_methods = mapper_class.getMethods(); //instead of calling getMethods() within a loop to generate the same array multiple times, will do just once per class and pass to labelMapper
        found = labelMapper(mapper_class, func_name, mapper_methods, query_type);
        if (!found){
            //if method not found, could be in super class
            dbg("No relevant MyBatis Mapper methods found in " + mapper_class.getName() + " for Mapper ID: " + func_name + ". Will continue search within super classes.");
            for each (var super_class in mapper_class.getSuperClasses()){
                found = labelMapper(super_class, func_name, super_class.getMethods(), query_type);
                if (found){
                    break; //no need to loop through the rest of the super classes once found
                }
            }
        }
    }
}

function labelMapper(klass, func_name, klass_methods, query_type){
    var found = false;
    for each (var method in klass_methods){
        if (String(method.getName()) == func_name){
            dbg("Found a matching MyBatis mapper method.");
            method.setLabel("MyBatisQueryFunc");
            //if select query, also want this to be a source
            dbg("query_type is: " + query_type);
            if (query_type == "select"){
                method.setLabel("MyBatisSelectQuery")
            }
            dbg("MyBatis label added to MyBatis function: " + klass.getName() + "." + method.getName());
            found = true; //just using a variable for clarity
            return found; //if func_name already identified and labelled, no need to loop through other methods.
        }
    }
    return found;
}

function init_mybatis_annotations(){
    var allClasses = nameTable.getAllClasses("java");
    var myBatisAnnotations = ["org.apache.ibatis.annotations.Select", "org.apache.ibatis.annotations.Update", "org.apache.ibatis.annotations.Insert", "org.apache.ibatis.annotations.Delete", "org.apache.ibatis.annotations.SelectProvider", "org.apache.ibatis.annotations.UpdateProvider", "org.apache.ibatis.annotations.InsertProvider", "org.apache.ibatis.annotations.DeleteProvider"];
    var found = false;
    /**
        For the sake of performance, will check if the program being scanned contains any MyBatis annotations. If it does, then we have to go through every method in order to find these and label the method appropriately.
        Preferably we'd use a characterization rule to label the mapper methods within the interface, however this currently cannot be done due to SCA bug 43470. The associated SSR bug to fix this by including a characterization rule is bug 43467, blocked by the SCA bug. The rulescript has additional performance impacts since it will have to loop through every Java method in order to identify the annotations.
    */
    for each (var annotationMethod in myBatisAnnotations){
        var klass = nameTable.getClassByFullName(annotationMethod, "java");
        if (klass != null && klass.getName() != '[UnknownType]'){

            found = true;
            break;
        }
    }
    //if no MyBatis annotations found, don't bother looping through every method.
    if (!found){
        //dbg("MyBatis annotations not found. Won't loop through methods");
        return;
    }

    for each (var klass in allClasses){
        for each (var method in klass.getMethods()){
            for each (var annotationName in myBatisAnnotations){
                queryAnnotation = method.getAnnotation(annotationName);
                if (null != queryAnnotation){
                    method.setLabel("MyBatisQueryFunc"); //definitely Access Control: Database sink. If method doesn't take any arguments, it won't hurt having the label.
                    //now check if also a sink for SQL Injection)
                    annotationConst = queryAnnotation.get("value");
                    if (annotationConst && sqlInjectionPossible(annotationConst)){ //checks if constant, then if so run the function against the annotation
                        method.setLabel("MyBatisQueryFuncWithSQLi");
                        dbg("setting SQL Injection label for: " + method.getName());
                    }
                    //if a select query, also need a source.
                    if (annotationName == "org.apache.ibatis.annotations.Select" || annotationName == "org.apache.ibatis.annotations.SelectProvider"){
                        method.setLabel("MyBatisSelectQuery");
                    }
                    //label SelectProvider methods.
                    if (annotationName == "org.apache.ibatis.annotations.SelectProvider") {
                        var annotType = queryAnnotation.get("type");
                        var annotMethod = queryAnnotation.get("method");
                        if (annotType != null && annotType != undefined && annotType.isClassLiteral() && annotMethod != null && annotMethod != undefined) {
                            var classLiteralValue = annotType.getClassLiteralValue();
                            if(classLiteralValue != null && classLiteralValue != undefined) {
                                var classPlusMethod = classLiteralValue + "." + annotMethod.getStrValue(); 
                                if(!selectProviderMethods.includes(classPlusMethod)) {
                                    var classLiteralValueClass = nameTable.getClassByFullName(classLiteralValue, "java");
                                    if(classLiteralValueClass != null && classLiteralValueClass != undefined) {
                                        for each (var classLiteralValueClassMethod in classLiteralValueClass.getMethods()) {
                                            if(classLiteralValueClassMethod.getName() == annotMethod.getStrValue()) {
                                                if(classLiteralValueClassMethod.getArgumentTypes() != null && classLiteralValueClassMethod.getArgumentTypes() != undefined
                                                   && method.getArgumentTypes() != null && method.getArgumentTypes() != undefined
                                                   && classLiteralValueClassMethod.getArgumentTypes().length == method.getArgumentTypes().length) {
                                                    classLiteralValueClassMethod.setLabel("MyBatisSelectProviderMethod");
                                                    selectProviderMethods.push(classPlusMethod);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

function sqlInjectionPossible(annotationConstant){
    if (annotationConstant.isArray()){
        //dbg("we have an array");
        for (var i = 0; ; i++){
        //for each (var elem in annotationConstant){
            var elem = annotationConstant.element(i);
            if (null == elem){
                //dbg("reached end of array");
                break;
            }
            //recursively go through array
            if (sqlInjectionPossible(elem)){
                //found a match, otherwise want to continue searching through elements
                return true;
            }
        }
    }
    else if (annotationConstant.isString()){
        var annotationVal = annotationConstant.getStrValue();
        /*
            originally checked for '${', but mozilla bug with checking for '{', so changing to just '$'. I can't think of instances where this wouldn't be sufficient.
            If there are problems, we'll have to bump the formatversion up to 3.18, since it looks like we probably upgraded the mozilla library used in SCA.
        */
        if (annotationVal.search("\\$(?![\\.A-z])") != -1){ //regex search for '$' and not '$.'. Bit ugly, but hey-ho
            dbg("we found the SQLi string in \"" + annotationVal + "\"");
            return true;
        }
    }
    return false;
}

init_mybatis();
var selectProviderMethods = new Array();
init_mybatis_annotations();


function debugMsg(msg) {
    //alert(msg);
}

function processHandler(handler, events) {
    var method = "handleRequest";
    if (handler.indexOf("::") > 0) {
        method = handler.split("::")[1];
        handler = handler.split("::")[0];
    }
    var dotIndex = handler.lastIndexOf(".");
    var packageName = handler.substr(0,dotIndex);
    handler = handler.substring(dotIndex + 1);
    var handlerClass = nameTable.getClassByName(packageName, handler, "java");
    if (handlerClass != "[UnknownType]" && handlerClass != undefined  && handlerClass != null) {
        debugMsg("Found handler: " + handlerClass.getPackageName() + "." + handlerClass.getName());
        debugMsg("Searching method: " + method);
        for each (var m in handlerClass.getMethods()) {
            if (method == m.getName()) {
                debugMsg("Labeling: " + m.getEnclosingClass().getName() + "." + m.getName() + " as AWS_Lambda_Handler");
                m.setLabel("AWS_Lambda_Handler") 
                setTypeLabels(m, events);
            }
        }
    } else {
        var global_functions = nameTable.getGlobalFunctions("python");
        if (global_functions !== undefined && global_functions !== null && global_functions.length > 0) {
            for each (var func in global_functions) {
                if (packageName == func.getNameSpace() && handler == func.getName()) {
                    debugMsg("Found handler: " + func.getNameSpace() + "." + func.getName());
                    debugMsg("Searching method: " + func);
                    debugMsg("Labeling: " + func.getNameSpace() + "." + func.getName() + " as AWS_Lambda_Handler");    
                    func.setLabel("AWS_Lambda_Handler") 
                    setTypeLabels(func, events);
                }
            }
        }
    }
}

function setTypeLabels(handler, events) {
    if (events !== undefined && events !== null) {
        if (events.indexOf('S3') > -1) {
            handler.setLabel("AWS_Lambda_S3") 
        }
        if (events.indexOf('Api') > -1) {
            handler.setLabel("AWS_Lambda_ApiGateway") 
        }
    }
}

var lambdaRe = /Type:['"\s]*AWS::Serverless::Function["'\s]*/g;
var handlerRe = /(\s+)Handler:\s*(.*)/g;
var eventTypeRe = /(\s+)Type:\s*(.*)/g;

var allFiles = getAllProgramFileNames();

for each (var f in allFiles) {
    if (f.match(/.*\.(yml|yaml)$/i)) {
        var fileContent = '';
        try {
            fileContent = readFile(f);
        } catch (err) {
            log("Error reading file "+f);
            continue;
        }
        try {
            debugMsg("Processing: " + f)
            if (fileContent.match(lambdaRe)) {
                var lines = fileContent.split("\n");
                var currentHandlerStr = "";
                var currentEventTypes = [];
                for each (var line in lines) {
                    if (line.match(lambdaRe)) {
                        // New Lambda function, process previous one if exists and reset handler structures
                        if (currentHandlerStr != "") 
                            processHandler(currentHandlerStr, currentEventTypes);
                        currentHandlerStr = "";
                        currentEventTypes = [];
                    } else if (line.match(handlerRe)) {
                        // Process Handler declarations
                        currentHandlerStr = handlerRe.exec(line)[2].replace(/'/g, "").replace(/"/g, "");
                    } else if (line.match(eventTypeRe)) {
                        // Process Event type
                        currentEventTypes.push(eventTypeRe.exec(line)[2]);
                    }
                }
                if (currentHandlerStr != "") 
                    processHandler(currentHandlerStr, currentEventTypes);
            }
        } catch (err) {
            debugMsg("Error parsing AWS files");
            debugMsg(err)
        }
    }
}

function debugMsg(msg) {
    //alert(msg);
}

function processHandler(handler, events) {
    var method = "handleRequest";
    if (handler.indexOf("::") > 0) {
        method = handler.split("::")[1];
        handler = handler.split("::")[0];
    }
    var dotIndex = handler.lastIndexOf(".");
    var packageName = handler.substr(0,dotIndex);
    handler = handler.substring(dotIndex + 1);
    var handlerClass = nameTable.getClassByName(packageName, handler, "java");
    if (handlerClass != "[UnknownType]" && handlerClass != undefined  && handlerClass != null) {
        debugMsg("Found handler: " + handlerClass.getPackageName() + "." + handlerClass.getName());
        debugMsg("Searching method: " + method);
        for each (var m in handlerClass.getMethods()) {
            if (method == m.getName()) {
                debugMsg("Labeling: " + m.getEnclosingClass().getName() + "." + m.getName() + " as AWS_Lambda_Handler");
                m.setLabel("AWS_Lambda_Handler") 
                setTypeLabels(m, events);
            }
        }
    } else {
        var global_functions = nameTable.getGlobalFunctions("python");
        if (global_functions !== undefined && global_functions !== null && global_functions.length > 0) {
            for each (var func in global_functions) {
                if (packageName == func.getNameSpace() && handler == func.getName()) {
                    debugMsg("Found handler: " + func.getNameSpace() + "." + func.getName());
                    debugMsg("Searching method: " + func);
                    debugMsg("Labeling: " + func.getNameSpace() + "." + func.getName() + " as AWS_Lambda_Handler");    
                    func.setLabel("AWS_Lambda_Handler") 
                    setTypeLabels(func, events);
                }
            }
        }
    }
}

function setTypeLabels(handler, events) {
    if (events !== undefined && events !== null) {
