var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;

function processField(field, visited) {
    // Loop through nested fields in the given class if they are not primitive or System classes
    // If field name matches Mass Assignment regular expression, label it with exposedRESTField
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedRESTField");
    }
    if (!type.isPrimitive() && !key.match(/^(java|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    processField(new_field, visited);
                }
            }
        }
    }
}
// Collect all command classes
var cmclasses = nameTable.getClassesByLabel("RESTInsecureBinding", "java");
if (cmclasses !== null) {
    for each (var cmclass in cmclasses) {
        if (cmclass !== null && cmclass != "[UnknownType]") {
            var visited = {};
            visited[cmclass.getPackageName() + "." + cmclass.getName()] = true;
            /*
                If JAXB binds a class to XML, then, by default, all public members will be bound, i.e., public getter and setter pairs, or public fields. Any protected, package-visible or private member is bound if it is annotated with a suitable annotation such as XmlElement or XmlAttribute. You have several possibilities to influence this default behaviour.

                You can annotate a package or a top level class with XmlAccessorType, setting its value element to one of the enum constants FIELD, PROPERTY, PUBLIC_MEMBER or NONE. If FIELD is set every non static, non transient field will be automatically bound. PROPERTY instructs JAXB to do this for getter and setter pairs. NONE suppresses bind except for explicitly annotated fields or properties. A class without this annotation inherits the XmlAccessorType setting either from its superclass or from the package setting.

                The other annotation to be mentioned in this context is XmlTransient. It suppresses binding for its target which can be an entire class or a field or a method. This is also useful if you have a name clash resulting from a public field, say foo, and methods getFoo and setFoo.
            */
            var jaxbann = cmclass.getAnnotation("javax.xml.bind.annotation.XmlRootElement");
            var fields = cmclass.getFields();
            var methods = cmclass.getMethods();
            if (jaxbann !== undefined && jaxbann !== null) {
                var acctype = cmclass.getAnnotation("javax.xml.bind.annotation.XmlAccessorType");
                if (acctype !== undefined && acctype !== null) {
                    if (acctype.get("value").getEnumValue() == "NONE") {
                        // NONE accessor type: only XmlElement or XmlAttribute annotated fields
                        for each (var field in fields) {
                            var XmlElement = field.getAnnotation("javax.xml.bind.annotation.XmlElement");
                            var XmlAttribute = field.getAnnotation("javax.xml.bind.annotation.XmlAttribute");
                            var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                            if (((XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)) {
                                processField(field, visited);
                            }
                        }
                    } else if (acctype.get("value").getEnumValue() == "PROPERTY") {
                        // PROPERTY accessor type: only fields with public getters, and setters
                        for each (var field in fields) {
                            var getter = "get" + field.getName().toLowerCase();
                            var setter = "set" + field.getName().toLowerCase();
                            has_setter = has_getter = false;
                            for each (var method in methods) {
                                if (getter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                                    var XmlTransient = method.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                    if (XmlTransient === null || XmlTransient === undefined) has_getter = true;
                                }
                                if (setter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                                    var XmlTransient = method.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                    if (XmlTransient === null || XmlTransient === undefined) has_setter = true;
                                }
                            }
                            if (has_setter && has_getter) {
                                var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                if (XmlTransient === null || XmlTransient === undefined) {
                                    processField(field, visited);
                                }
                            }
                        }
                    } else if (acctype.get("value").getEnumValue() == "FIELD")  {
                        // FIELD accessor type: non static, non transient fields
                        for each (var field in fields) {
                            var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                            // Bug 43992: FieldMeta does not has any isTransient method :(
                            // Bug 43991 jsField.getSymbol is protected (it is public in jsMethod) So we cannot check if field is static
                            // if (!field.getSymbol().iStatic() && (XmlTransient === null || XmlTransient === undefined)) {
                            if (XmlTransient === null || XmlTransient === undefined) {
                                processField(field, visited);
                            }
                        }
                    }
                } else {
                    // No Accessor type so: only public fields or private/protected ones with XmlTransient, XmlElement or XmlAttribute
                    for each (var field in fields) {
                        var XmlElement = field.getAnnotation("javax.xml.bind.annotation.XmlElement");
                        var XmlAttribute = field.getAnnotation("javax.xml.bind.annotation.XmlAttribute");
                        var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                        // Bug 43991 jsField.getSymbol is protected (it is public in jsMethod) So we cannot check if field is static
                        // if ((field.getSymbol().isPublic() || (XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)){
                        if (((XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)){
                            processField(field, visited);
                        }
                    }
                }
            }
        }
    }
}

