                    if (acctype.get("value").getEnumValue() == "NONE") {
                        // NONE accessor type: only XmlElement or XmlAttribute annotated fields
                        for each (var field in fields) {
                            var XmlElement = field.getAnnotation("javax.xml.bind.annotation.XmlElement");
                            var XmlAttribute = field.getAnnotation("javax.xml.bind.annotation.XmlAttribute");
                            var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                            if (((XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)) {
                                processField(field, visited);
                            }
                        }
                    } else if (acctype.get("value").getEnumValue() == "PROPERTY") {
                        // PROPERTY accessor type: only fields with public getters, and setters
                        for each (var field in fields) {
                            var getter = "get" + field.getName().toLowerCase();
                            var setter = "set" + field.getName().toLowerCase();
                            has_setter = has_getter = false;
                            for each (var method in methods) {
                                if (getter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                                    var XmlTransient = method.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                    if (XmlTransient === null || XmlTransient === undefined) has_getter = true;
                                }
                                if (setter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                                    var XmlTransient = method.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                    if (XmlTransient === null || XmlTransient === undefined) has_setter = true;
                                }
                            }
                            if (has_setter && has_getter) {
                                var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                                if (XmlTransient === null || XmlTransient === undefined) {
                                    processField(field, visited);
                                }
                            }
                        }
                    } else if (acctype.get("value").getEnumValue() == "FIELD")  {
                        // FIELD accessor type: non static, non transient fields
                        for each (var field in fields) {
                            var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                            // Bug 43992: FieldMeta does not has any isTransient method :(
                            // Bug 43991 jsField.getSymbol is protected (it is public in jsMethod) So we cannot check if field is static
                            // if (!field.getSymbol().iStatic() && (XmlTransient === null || XmlTransient === undefined)) {
                            if (XmlTransient === null || XmlTransient === undefined) {
                                processField(field, visited);
                            }
                        }
                    }
                } else {
                    // No Accessor type so: only public fields or private/protected ones with XmlTransient, XmlElement or XmlAttribute
                    for each (var field in fields) {
                        var XmlElement = field.getAnnotation("javax.xml.bind.annotation.XmlElement");
                        var XmlAttribute = field.getAnnotation("javax.xml.bind.annotation.XmlAttribute");
                        var XmlTransient = field.getAnnotation("javax.xml.bind.annotation.XmlTransient");
                        // Bug 43991 jsField.getSymbol is protected (it is public in jsMethod) So we cannot check if field is static
                        // if ((field.getSymbol().isPublic() || (XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)){
                        if (((XmlElement !== null && XmlElement !== undefined) || (XmlAttribute !== null && XmlAttribute !== undefined)) && (XmlTransient === null || XmlTransient === undefined)){
                            processField(field, visited);
                        }
                    }
                }
            }
        }
    }
}

/*
This script uses the output from capture rules:
    - F6EFA44C-D8DC-434F-A965-3ECA9951099E
    - D0A25DF6-1802-4BB1-A783-6C1EEF3BDF05
    - 1FC6467C-94D5-4D4E-9EEF-B4F93307FF1B
    - 3A3B82A4-04D7-4261-B4CA-6ED1409AABD1
which capture the names of classes and methods associated with the shortcode handler, and adds labels to the NSTs corresponding to those captured method names.
Code examples:
```
add_shortcode( 'podlove-subscribe-button', array( 'PodloveSubscribeButton', 'shortcode' ) );
add_shortcode( 'caption', 'img_caption_shortcode' );
```
The above 2 add_shortcode() calls set the shortcode handlers 'PodloveSubscribeButton.shortcode()' and img_caption_shortcode().
```
*/

(function() {


    /* Parses the class name and source location of that class and then finds the method name 
	    belonging to this class with the same source location.
		These labels are captured using captures "ShortCode_MethodName_sourcelocation"
		and "ShortCode_ClassName_sourcelocation". Corresponding rules are 
		D0A25DF6-1802-4BB1-A783-6C1EEF3BDF05 and 1FC6467C-94D5-4D4E-9EEF-B4F93307FF1B.

    */
    function parseClassMethodCapture(classNameSourceLocationCapture) {
        var cn_and_sl = classNameSourceLocationCapture.split(' ');
        var className = cn_and_sl[0];
        var classSourceLocation = cn_and_sl[1];
        var methodNameSourceLocations = nameTable.getGlobalCaptures('ShortCode_MethodName_sourcelocation');
        for (var i = 0; i < methodNameSourceLocations.length; i++) {
            var mn_and_sl = methodNameSourceLocations[i].split(' ');
            var methodName = mn_and_sl[0];
            var methodSourceLocation = mn_and_sl[1];
            if (className !== undefined && methodName !== undefined
                && classSourceLocation !== undefined && methodSourceLocation !== undefined
                && classSourceLocation == methodSourceLocation) {
                return [className, methodName];
            }
        }
        return []
    }

    var addshortcodeWordPressMethod = nameTable.getGlobalCaptures('ShortCode_WordPress_Method');
    if (addshortcodeWordPressMethod !== null && addshortcodeWordPressMethod !== undefined && addshortcodeWordPressMethod.length > 0) {
        var classNameSourceLocations = nameTable.getGlobalCaptures('ShortCode_ClassName_sourcelocation');
        // Add labels to add_shortcode functions.
		// e.g. labels method 'shortcode' in code such as: 
		//    add_shortcode( 'podlove-subscribe-button', array( 'PodloveSubscribeButton', 'shortcode' ) );
        for (var i = 0; i < classNameSourceLocations.length; i++) {
            var signature = parseClassMethodCapture(classNameSourceLocations[i]);
            if (signature.length == 2) {
                var className = signature[0];
                var methodName = signature[1];

                var c = nameTable.getClassByFullName(className.toLowerCase(), 'php');
                if (c !== null && c !== undefined) {
                    var methods = c.getMethods();
                    if (methods !== null && methods !== undefined) {
                        for (var j = 0; j < methods.length; j++) {
                            var method = methods[j];
                            if (method.getName() == methodName) {
                                method.setLabel('ShortCode_Add_Method')
                            }
                        }
                    }
                }
            }
        }

        var callbackNames = nameTable.getGlobalCaptures('ShortCode_Add_Methods');
        // Add labels to add_shortcode functions when Class is not present.
		// e.g. labels method 'img_caption_shortcode' in code such as: 
		//    add_shortcode( 'caption', 'img_caption_shortcode' );
        for (var i = 0; i < callbackNames.length; i++) {
            var methodName = callbackNames[i];
            var methods = nameTable.getGlobalFunctions('php');
            if (methods !== null && methods !== undefined) {
                for (var j = 0; j < methods.length; j++) {
                    var method = methods[j];
                    if (method.getName() == methodName) {
                        method.setLabel('ShortCode_Add_Method')
                    }
                }
            }
        }
    }
})();

// Spring 4.2.0 defaults as per http://docs.spring.io/spring/docs/current/javadoc-api/org/springframework/web/accept/ContentNegotiationManagerFactoryBean.html
var useJAF = true;
var favorPathExtension = true;
var ignoreAcceptHeader = false;

var ns = new Namespace("http://www.springframework.org/schema/beans");
for each (var cfg in program.xml) {
    if (null == cfg.name() || null == cfg.name().localName.match("beans")) {
        continue;
    }
    for each(var j in cfg..ns::bean) {
        if (String(j['@class']) == "org.springframework.web.accept.ContentNegotiationManagerFactoryBean"){
            for each(var k in j..ns::property) {
                if (String(k['@name']).toLowerCase() == "usejaf" && String(k['@value']).toLowerCase() == "false") useJAF = false;
                if (String(k['@name']).toLowerCase() == "favorpathextension" && String(k['@value']).toLowerCase() == "false") favorPathExtension = false;
                if (String(k['@name']).toLowerCase() == "ignoreacceptheader" && String(k['@value']).toLowerCase() == "true") ignoreAcceptHeader = true;
            }
        }
    }
}
if (!ignoreAcceptHeader || (useJAF && favorPathExtension)) persistObject("program.spring_rfd_config_protection", "false");
else persistObject("program.spring_rfd_config_protection", "true");

var allClasses = nameTable.getAllClasses("java");
var springDataWebSupportEnabled = false;
var controllers = [];
for each (var clss in allClasses) {
    if (clss != null) {
        var springDataWebSupportApplication = clss.getAnnotation("org.springframework.data.web.config.EnableSpringDataWebSupport");
        var controller = clss.getAnnotation("org.springframework.stereotype.Controller");
        var restController = clss.getAnnotation("org.springframework.web.bind.annotation.RestController");
        if (controller !== null || restController !== null) controllers.push(clss);
        if (springDataWebSupportApplication !== null) var springDataWebSupportEnabled = true;
    }
}
if (springDataWebSupportEnabled) {
    for each (var c in controllers) {
        c.setLabel("SpringDataWebSupportEnabled");
    }
}

var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;

// Function to extrac a list of values (sufices) from labels given a prefix
function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj != null && prefix != null && prefix != "") {
        var labels = obj.getLabels();
        if (labels != null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                    var value = String(l.substring(prefix.length));
                    if (value != null && value.length > 0) {
                        values[values.length++] = value;
                    }

                }
            }
        }
    }
    return values;
}

function registerController(controller2commandclass, controllerClass, commandClass) {
    // Checks if command class is already present in the map, if so, it adds the controller class to the list for that command class
    if (controllerClass !== null && controllerClass.getName() != "[UnknownType]") {
        var ccname = commandClass.getPackageName() + "." + commandClass.getName();
        var controllerName = controllerClass.getPackageName() + "." + controllerClass.getName();
        var controller = {};
        controller.filename = "";
        try {
            controller.filename = String(controllerClass.getFileName());
        } catch (err) {
            var fields = controllerClass.getFields();
            if (fields !== null && fields !== undefined) {
                if (fields.length > 0 && fields[0] !== null && fields[0] !== undefined) controller.filename = String(fields[0].getFileName());
            }
        }
        if (controller.filename === undefined || controller.filename === null) controller.filename = "";
        controller.linenumber = 1;
        controller.name = String(controllerName);
        var controller_list = controller2commandclass[ccname];
        if (controller_list === null || controller_list === undefined) {
            controller2commandclass[ccname] = [controller];
        } else {
            controller_list[controller_list.length++] = controller;
            controller2commandclass[ccname] = controller_list;
        }
    }
}

function processField(field, visited, controllerClass) {
    // Loop through nested fields in the given class if they are not primitive of java JSD classes
    // If field name matches Mass Assignment regular expression, label it with exposedCommandField
    //Username, password, logged_in_status,
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedCommandField");
    }
    if (!type.isPrimitive() && !key.match(/^(java|null).*/) && visited[key] != true) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            registerController(controller2commandclass, controllerClass, type);
            for each (var new_field in fields) {
                var new_key = new_field.getType().getPackageName() + "." + new_field.getType().getName();
                if (visited[new_key] != true) {
                    processField(new_field, visited, controllerClass);
                }
            }
        }
    }
}

// Collect all Spring command classes
var sp2cc = nameTable.getClassesByLabel("spring2CommandObject", "java");
var sp3cc = nameTable.getClassesByLabel("spring3CommandObject", "java");
// This map will contain a list of command class and for each one a list of controllers that bind the command class without special configuration
var controller2commandclass = {};
var cmclasses = [];
if (sp2cc != null && sp2cc != undefined) for each (var c in sp2cc) cmclasses.push(c);
if (sp3cc != null && sp3cc != undefined) for each (var c in sp3cc) cmclasses.push(c);
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null) {
            var labels = cmclass.getLabels();
            if (labels != null) {
                var insecureBinding = false;
                // Loop through command class labels and set insecureBinding to true if any label starts with that prefix
                for each (var label in labels) {
                    if (label.indexOf("insecureBinding") == 0) {
                        insecureBinding = true;
                        break;
                    }
                }
                if (insecureBinding) {
                    // If command class is bound insecurely, extract the controllers that fail to bind it securely from the labels
                    var controllerNames = extractLabelValues(cmclass, "insecureBinding~");
                    for each (var controllerName in controllerNames) {
                        var controllerClass = nameTable.getClassByFullName(controllerName, "java");
                        // Add the controller to the command class list in the controller2commandclass map
                        registerController(controller2commandclass, controllerClass, cmclass);
                        var visited = {};
                        visited[cmclass.getPackageName() + "." + cmclass.getName()] = true;
                        var fields = cmclass.getFields();
                        if (fields !== null && fields !== undefined) {
                            // Loop through the command class fields and look for other non primitive nor java classes nested in the object
                            for each (var field in fields) {
                                processField(field, visited, controllerClass);
                            }
                        }
                    }
                }
            }
        }
    }
}
if (null != controller2commandclass) {
    // Persist map fopr later usage
    persistObject("program.spring_controller2commandclass_map", controller2commandclass);
}

var spring_beans = loadPersistedObject("program.spring_beans");
var spring2_validated_fields = new Array();
var spring3_validated_command_classes = new Array();
var spring2_command_class_Map = {};

// Fill Spring 2 CommandClass to callback map
var callbacks = nameTable.getMethodsByLabel("commandClass", "java");
if (callbacks != null) {
    for each (var cb in callbacks) {
        var element = new Object();
        element.callback = cb.getName();
        element.fileName = cb.getFileName();
        element.lineNumber = cb.getLineNumber();
        controllerClass = cb.getEnclosingClass().getPackageName() + "." + cb.getEnclosingClass().getName();
        element.commandClass = nameTable.getLabelValue("commandClass", cb);
        spring2_command_class_Map[controllerClass] = element;
        // alert("Controller " + controllerClass);
        // alert("CommandClass " + element.commandClass);
    }
}

// 1.1 Process Spring Command Classes annotated with JSR 303 validation annotations
var cmclasses = nameTable.getClassesByLabel("JSR303Validated", "java");
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null) {
            var labels = cmclass.getLabels();
            if (labels != null) {
                for each (var label in labels) {
                    if (label == "spring3CommandObject") {
                        var cclassName = cmclass.getPackageName() + "." + cmclass.getName();
                        try {
                            //alert("Adding class " + cclassName + " as validated class in " + cmclass.getFileName());
                            addValidatedCommandClass(spring3_validated_command_classes, cclassName, cmclass.getFileName(), cmclass.getLineNumber());
                        } catch (err) {
                            //log("Error getting filename and linenumber from class, maybe class is not user defined");
                        }
                    }
                }
            }
        }
    }
}

// 1.2, 1.3, 1.4 SpringValidatorFramework (SVF) set in the initBinder and run automatically with @Valid or run with validate
var cmclasses = nameTable.getClassesByLabel("spring3CommandObject", "java");
if (cmclasses != null) {
    for each (var cmclass in cmclasses) {
        if (cmclass != null) {
            var commandClass = cmclass.getPackageName() + "." + cmclass.getName();
            var labels = cmclass.getLabels();
            if (labels != null) {
                for each (var label in labels) {
                    if (label == "validatorClass") {
                        var validatorClass = nameTable.getLabelValue("validatorClass", cmclass);
                        if (validatorClass != null && validatorClass != "" && validatorClass != "undefined") {
                            if (validatorClass != "org.springframework.validation.Validator" && validatorClass != "org.springmodules.validation.bean.BeanValidator") {
                                var vclass = nameTable.getClassByFullName(validatorClass, "java");
                                if (vclass != null && vclass.getName() != "[UnknownType]") {
                                    // alert("We have a valid validator class: " + validatorClass);
                                    try {
                                        addValidatedCommandClass(spring3_validated_command_classes, commandClass, vclass.getFileName(), vclass.getLineNumber());
                                    } catch (err) {
                                        //log("Error getting filename and linenumber from class, maybe class is not user defined");
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

// 1.5 Spring 3 Global validators
var xmlFiles = getXMLConfigFileNames();
var visited = {};
var ns = new Namespace();
var springns = new Namespace("http://www.springframework.org/schema/beans");
var mvcns = new Namespace("http://www.springframework.org/schema/mvc");
for each (var filename in xmlFiles) {
    var contents = '';
    try {
        contents = readFile(filename);
    } catch (err) {
        log("Error reading file "+filename);
        continue;
    }
    try {
        if (contents.charAt(0) != '<') {
                contents = contents.substring(1);
        }
        var xml = new XML(contents);
        if (null != xml && null != xml.name() && null != xml.name().localName && null != xml.name().localName.match("beans")) {
            for each (var j in xml.children()) {
                if (null != j.name() && null != j.name().localName.match("annotation-driven")) {
                    if (String(j["@validator"]) != "") {
                        if (spring_beans != null) {
                            for each (var bean in spring_beans) {
                                if (bean.name == String(j["@validator"])) {
                                    className = bean.namespaceName + "." + bean.className;
                                    if (className != "org.springframework.validation.beanvalidation.LocalValidatorFactoryBean") {
                                        // Excluding LocalValidatorFactoryBean since they will be caught by the JSR303 labeling rules
                                        var vclass = nameTable.getClassByFullName(className, "java");
                                        if (vclass != null && vclass.getName() != "[UnknownType]") {
                                            var cmclasses = nameTable.getClassesByLabel("spring3CommandObject", "java");
                                            for each (var cmclass in cmclasses) {
                                                if (cmclass != null) {
                                                    var commandclass = cmclass.getPackageName() + "." + cmclass.getName();
                                                    if (!(commandclass in visited)) {
                                                        try {
                                                            addValidatedCommandClass(spring3_validated_command_classes, commandclass, vclass.getFileName(), vclass.getLineNumber());
                                                            visited[commandclass] = true;
                                                        } catch (err) {
                                                            //log("Error getting filename and linenumber from class, maybe class is not user defined");
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    } catch (err) {
        // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
        // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
    }
}

if (spring_beans != null) {

    // 2.1. Find Command classes bound with controllers and validators in the Spring config file
    for each (var bean in spring_beans) {
        if (bean.isCommandClass) {
                var commandClass = "";
                var validatorClass = "";
                for each (var prop in bean.propertyElements) {
                    if (prop.name == "validator-ref" || prop.name == "validator") {
                        if (prop.ref != null && prop.ref != "") {
                            // alert("  Looking for ref: " + prop.ref);
                            for each (var bean2 in spring_beans) {
                                if (bean2.name == prop.ref) {
                                    // alert("  Validator class " + bean2.namespaceName + "." + bean2.className);
                                    validatorClass = bean2.namespaceName + "." + bean2.className;
                                }
                            }
                        } else if (prop.value != null && prop.value != "") {
                            // alert("  Validator class " + prop.value);
                            validatorClass = prop.value;
                        }
                    }
                    if (prop.name == "commandClass") {
                        // alert("  CommandClass " + prop.value)
                        commandClass = prop.value;
                    }

            }
                var vclass = nameTable.getClassByFullName(validatorClass, "java");
                var cmclass = nameTable.getClassByFullName(commandClass, "java");
                if (vclass != null && vclass.getName() != "[UnknownType]" && cmclass != null && cmclass.getName() != "[UnknownType]") {
                    var fields = cmclass.getFields();
                    if (fields != null) {
                        for each (var field in fields) {
                        // alert("  Adding " + commandClass + " field " + field.getName() + " to validated fields");
                        try {
                            addValidatedField(spring2_validated_fields, commandClass, field.getName(), vclass.getFileName(), vclass.getLineNumber());
                        } catch (err) {
                            //log("Error getting filename and linenumber from class, maybe class is not user defined");
                        }
                        }
                    }
                }
                else if (vclass != null && vclass.getName() != "[UnknownType]" ) {
                    // 2.2 Where Command classes are not bound to the controoler in the XML file, get controller
                    controllerClass = bean.namespaceName + "." + bean.className;
                    // alert("We have a validator with no command class for cotroller "+ controllerClass);
                    var cclass = nameTable.getClassByFullName(controllerClass, "java");
                    if (cclass != null && cclass.getName() != "[UnknownType]") {
                    // alert("valid class");
                        var labels = cclass.getLabels();
                        if (labels != null) {
                        for each (var label in labels) {
                            // alert("label " + label);
                            if (label == "commandClass") {
                                // alert("controller is labeled with command class");
                                var commandClass = nameTable.getLabelValue("commandClass", cclass);
                                // alert("Find class " + commandClass);
                                commandClass = commandClass.substr(0,commandClass.indexOf("."));
                                // alert("Find class " + commandClass);
                                var allclasses = nameTable.getAllClasses("java");
                                var models = new Array();
                                for each (var clss in allclasses) {
                                    if (clss.getName() == commandClass) {
                                        models[models.length] = clss;
                                    }
                                }
                                if (models.length == 1) {
                                    cmclass = models[0];
                                    commandClass = cmclass.getPackageName() + "." + cmclass.getName();
                                    if (cmclass != null && cmclass.getName() != "[UnknownType]") {
                                        // alert("We have a valid command class: " + commandClass);
                                        var cmfields = cmclass.getFields();
                                        for each (var cmfield in cmfields) {
                                            // alert("  Adding " + commandClass + " field " + cmfield.getName() + " to validated fields");
                                            try {
                                                addValidatedField(spring2_validated_fields, commandClass, cmfield.getName(), vclass.getFileName(), vclass.getLineNumber());
                                            } catch (err) {
                                                //log("Error getting filename and linenumber from class, maybe class is not user defined");
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    }
            }
        }
    }

    if (null != spring2_validated_fields) {
        persistObject("program.spring2_validated_fields", spring2_validated_fields);
    }
    if (null != spring3_validated_command_classes) {
        persistObject("program.spring3_validated_command_classes", spring3_validated_command_classes);
    }
    if (null != spring2_command_class_Map) {
        persistObject("program.spring2_command_class_Map", spring2_command_class_Map);
    }

}

function addValidatedField(array, className, fieldName, fileName, lineNumber) {
        var thisResult = null;
        var resultArrayElement = new Object();
        resultArrayElement.fileNames = new Array();
        resultArrayElement.fileNames[0] = fileName;
        resultArrayElement.lineNumbers = new Array();
        resultArrayElement.lineNumbers[0] = lineNumber;
        resultArrayElement.source = "set" + fieldName.substr(0, 1).toUpperCase() + fieldName.substr(1);
        // alert("Adding setter " + resultArrayElement.source + " for index '" + className + "' with validator " + fileName + ":" + lineNumber );

        if (null == array[className]) {
            thisResult = new Array();
        } else {
            thisResult = array[className];
        }
        thisResult[thisResult.length] = resultArrayElement;
        array[className] = thisResult;
}

function addValidatedCommandClass(array, className, fileName, lineNumber) {
        var thisResult = null;
        var element = new Object();
        element.fileNames = new Array();
        element.fileNames[0] = fileName;
        element.lineNumbers = new Array();
        element.lineNumbers[0] = lineNumber;
        // alert("Adding command class " + className + " with validator " + fileName + ":" + lineNumber );

    if (array != null) {
        array[className] = element;
    }
}

var strutsActions = loadPersistedObject("program.struts_actions2");
if (strutsActions !== null) {
    for each (var action in strutsActions) {
        if (action !== null && action !== undefined && action.clss !== null && action.clss !== undefined && action.clss == "org.apache.struts2.s1.Struts1Action") {
            //alert("Struts1 Plugin action detected");
            var cn = action.params['className'];
            if (cn !== "null" && cn !== null && cn !== undefined) {
                var actionClass = nameTable.getClassByFullName(cn, "java");
                //alert(actionClass.getName());
                if (actionClass != null && actionClass != undefined && '[UnknownType]' != actionClass.getName()) {
