var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;

function processField(field, visited) {
    // Loop through nested fields in the given class if they are not primitive of java JDK classes
    // If field name matches Mass Assignment regular expression, label it with exposedActionFormField
    //Username, password, logged_in_status,
    var name = String(field.getName());
    var type = field.getType();
    var key = String(type.getPackageName() + "." + type.getName());
    if (name.match(MASS_ASSIGNMENT_REGEXP)) {
        field.setLabel("exposedActionFormField");
    }
    if (!type.isPrimitive() && !key.match(/^(java|null).*/) && !visited[key]) {
        visited[key] = true;
        var fields = type.getFields();
        if (fields != null) {
            for each (var nested_field in fields) {
                var new_key = nested_field.getType().getPackageName() + "." + nested_field.getType().getName();
                if (visited[new_key] != true) {
                    processField(nested_field, visited);
                }
            }
        }
    }
}
// Struts 1
var visited = {};
var action_forms  = nameTable.getClassesByLabel("Struts1ActionForm", "java");
if (null != action_forms) {
    for each (var action_form in action_forms) {
        var fields = action_form.getFields();
        var methods = action_form.getMethods();
        for each (var field in fields) {
            var getter = "get" + field.getName().toLowerCase();
            var setter = "set" + field.getName().toLowerCase();
            has_setter = has_getter = false;
            for each (var method in methods) {
                if (getter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_getter = true;
                }
                if (setter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_setter = true;
                }
            }
            if (has_setter && has_getter) {
                processField(field, visited);
            }
        }
    }
}
// ActionForms defined as DynaActionForms
for each (var form_bean in form_beans) {
    // Grab form_bean properties without triggering the null dereference exception
    var clss, property_details;
    for (var key in form_bean) {
        if (key == "clss") {
            clss = form_bean[key];
        }
        if (key == "property_details") {
            property_details = form_bean[key];
        }
    }
    if (clss == "org.apache.struts.action.DynaActionForm"
        || "org.apache.struts.validator.DynaValidatorActionForm"
        || "org.apache.struts.validator.DynaValidatorForm") {
        for each (var prop in property_details) {
            if (!prop['type'].match(/^(java|null).*/) && !visited[prop['type']]) {
                var clss = nameTable.getClassByFullName(prop['type'],"java");
                if (null != clss && clss.getName() != "[UnknownType]" && !clss.isPrimitive()) {
                    var fields = clss.getFields();
                    if (fields !== null && fields !== undefined) {
                        for each (var field in fields) {
                            processField(field, visited);
                        }
                    }
                }
            }
        }
    }
    // if (form_bean.clss == "org.apache.struts.action.DynaActionForm") {
    //     for each (var prop in form_bean.property_details) {
    //         if (!prop['type'].match(/^(java|null).*/) && !visited[prop['type']]) {
    //             var clss = nameTable.getClassByFullName(prop['type'],"java");
    //             if (null!= clss && clss.getName() != "[UnknownType]" && !clss.isPrimitive()) {
    //                 var fields = clss.getFields();
    //                 for each (var field in fields) {
    //                     processField(field, visited);
    //                 }
    //             }
    //         }
    //     }
    // }
}
// if (null != program.form_beans) {
