// Struts 2
function processAction(action, visited) {
    if (action !== null && action !== undefined && action != "[UnknownType]") {
        var fields = action.getFields();
        var methods = action.getMethods();
        for each (var field in fields) {
            var getter = "get" + field.getName().toLowerCase();
            var setter = "set" + field.getName().toLowerCase();
            has_setter = has_getter = false;
            for each (var method in methods) {
                if (getter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_getter = true;
                }
                if (setter == method.getName().toLowerCase() && method.getSymbol().isPublic()) {
                    has_setter = true;
                }
            }
            if (has_setter && has_getter) {
                processField(field, visited);
            }
        }
    }
}

var visited = {};
if (null != program.struts_actions) {
    // Actions defined in configuration files
    for each (var action_obj in program.struts_actions) {
        var action = nameTable.getClassByName(action_obj.namespaceName, action_obj.className, "java");
        processAction(action, visited);
    }
}
var actions = nameTable.getClassesByLabel("Struts2Action", "java");
if (null != actions) {
    // Actions defined via annotations and classes that extends ActionSupport
    for each (var action in actions) {
        processAction(action, visited);
    }
}
var models = nameTable.getClassesByLabel("Struts2ActionModel", "java");
if (null != models) {
    // Actions using ModelDriven
    for each (var model in models) {
        processAction(model, visited);
    }
}

/*
This script uses the output from capture rule:
    - CE141634-C670-4313-A40F-4FAF9F5862AC
which capture the names of classes and methods associated with the callback method names within 'register_routes' method of wp_rest_controller class in WordPress Core. 
It adds labels to the NSTs corresponding to those captured class/method names.
Code examples:
```
class RSVPMaker_Listing_Controller extends WP_REST_Controller {

	public function register_routes() {

		$namespace = 'rsvpmaker/v1';

		$path = 'future';

		register_rest_route(
			$namespace,
			'/' . $path,
			array(

				array(

					'methods'             => 'GET',

					'callback'            => array( $this, 'get_items' ),

					'permission_callback' => array( $this, 'get_items_permissions_check' ),

				),

			)
		);

	}
```
The above will capture methods 'get_items' and 'get_items_permissions_check' in class 'RSVPMaker_Listing_Controller'.
```
*/

(function() {


    var callbackClassMethodNames = nameTable.getGlobalCaptures('WP_rest_controller_route_callback');
    // Add labels to callbacks in register_routes methods of wp_rest_controller
    for (var i = 0; i < callbackClassMethodNames.length; i++) {
        var signature = callbackClassMethodNames[i].split(':');
        if (signature.length == 2) {
            var className = signature[0];
            var methodName = signature[1];
            var c = nameTable.getClassByFullName(className.toLowerCase(), 'php');
            if (c !== null && c !== undefined) {
                var methods = c.getMethods();
                if (methods !== null && methods !== undefined) {
                    for (var j = 0; j < methods.length; j++) {
                        var method = methods[j];
                        if (method.getName() == methodName) {
                            method.setLabel('rest_route_callback_function')
                        }
                    }
                }
            }
        }
    }

})();

function tensorflow_unsafe_deserialization_checks(){
    /**
     * This script is to check whether unsafe deserialization is established globally. For example using tf.keras.config.enable_unsafe_deserialization(). If unsafe deserialization is globally set, issues associated with it will be reported.
     */

    _areTensorflowUnsafeDeserializationEnabledGlobally = false //defaults to false
    _loadModel = new Array(); //these will be reported if unsafe deserialization is established globally

    _pushToLoadModelCalls = function(sink){
        _loadModel[_loadModel.length] = sink;
    }

    _unsafeDeserializationEnabledGlobally = function() {
        _areTensorflowUnsafeDeserializationEnabledGlobally = true;
    }

    this.loopFuncs = {
        "63280010-A926-470B-B1EA-3797AD73E77E": _pushToLoadModelCalls,
        "5F5EEC40-22F0-4362-89AD-44F659CB8BCB": _unsafeDeserializationEnabledGlobally

    }

    this.postFuncs = new Array();
    this.postFuncs.push(function(){
        if (!_areTensorflowUnsafeDeserializationEnabledGlobally){
            //log("unsafe deserialization is not enabled, removing issue");
            //if TensorFlow unsafe deserialization is not set globally, we need to remove the issues as they are false positives.
            for each (var vuln in _loadModel){
                // warn("Removing vulnerability: " + vuln)
                vuln.remove();
            }
        }
    });
}

//Certain python methods will resolve as coming from generic types requiring matching rules 
//to be too broad. Filter rule results that used the AWS_SAGEMAKER_XTHRU taint but did not have a AWS_SAGEMAKER_SOURCE source rule
//Additionally filter rules that have a sink with AWS_SAGEMAKER_SOURCE taint as it is an FP for not being removed per the required dataflow involving passthrough 6B93D53E
function AWS_SageMaker_Python_Passthrough_Cleanup(){
    var vulns = getVulnerabilities();

    //Cycle through vulnerabilities found and look at their taint paths, serching for AWS_SAGEMAKER_XTHRU and AWS_SAGEMAKER_SOURCE neutral taint
    for each (var vuln in vulns){

        if (vuln === null || vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null) continue;

        var sourceid = String(vuln.getSourceRule().getIdentifier());
        var aws_sagemaker_source = false;
        // 0 postpended on ID for characterization rule
        if(sourceid.equals("8F9C5C27-74CA-4F45-8A47-3DBB85A287D30")){
            aws_sagemaker_source = true;
        }

        var taintPaths = vuln.getTaintPaths();  

        if (taintPaths !== null && taintPaths !== undefined) {

            for (var i = 0; i < taintPaths.length; i++) {

                var theseTaintFlags = taintPaths[i].getTaintFlags();

                for (var j = 0; j < theseTaintFlags.length; j++) {


                    // If vuln taint flags includes AWS_SAGEMAKER_SOURCE it hasn't passed through the correct passthrough that removes AWS_SAGEMAKER_SOURCE (6B93D53E) and is an FP
                    if (theseTaintFlags[j].equals("AWS_SAGEMAKER_SOURCE")){
                        //alert(sourceid);
                        //alert(theseTaintFlags[j]);
                        //alert(vuln.getPrimaryLine());
                        taintPaths[i].removePath();

                    // If AWS_SAGEMAKER_XTHRU was used and the source was not a AWS_SAGEMAKER_SOURCE source function, filter out the vuln as it's likely FP
                    }else if(theseTaintFlags[j].equals("AWS_SAGEMAKER_XTHRU") && !aws_sagemaker_source){
                        //alert(sourceid);
                        taintPaths[i].removePath();
                    }
                }
            }
        }              
    }
}

AWS_SageMaker_Python_Passthrough_Cleanup();

var vulns = getVulnerabilities();
if (JavaUtils.isAndroidApp()) {
    var defaultFactoryRule = "58FB5A42-BA7F-460C-A60B-FF67B8CA0607";
    var removeCertPinningIssues = false;
    for each (var vuln in vulns) {
        var ruleID = String(vuln.getRule().getIdentifier());
        if (ruleID == defaultFactoryRule) {
            removeCertPinningIssues = true;
            vuln.remove();
        }
    }
    if (removeCertPinningIssues) {
        for each (var vuln in vulns) {
            var ruleID = String(vuln.getRule().getIdentifier());
            if (["DA6F3C64-0A25-40E5-AD59-85968AEC9EF0", // Java.Net DF 1
                    "B1F5D0B0-DE56-42DE-ACD2-B79107F3324D", // Java.Net DF 2
                    "09D93C59-75F1-448C-8B37-10D545E435E2", // Java.Net Semantic
                    "6F32FF87-B31E-4BC1-9CF1-8FB42AEA70B8", // Java.Net Semantic
                    "A7B775B3-B4D9-4827-A592-3067AA9D3BE5"  // Sink Source rule for SSL_URL
                ].indexOf(ruleID) > -1) {
                vuln.remove();
            }
        }
    }
} else {
    // Remove Java Certificate pinning issues from non-Android applications
    for each (var vuln in vulns) {
        var ruleID = String(vuln.getRule().getIdentifier());
        if (["DA6F3C64-0A25-40E5-AD59-85968AEC9EF0", // Java.Net DF 1
                "B1F5D0B0-DE56-42DE-ACD2-B79107F3324D", // Java.Net DF 2
                "09D93C59-75F1-448C-8B37-10D545E435E2", // Java.Net Semantic
                "6F32FF87-B31E-4BC1-9CF1-8FB42AEA70B8", // Java.Net Semantic
                "A7B775B3-B4D9-4827-A592-3067AA9D3BE5",  // Sink Source rule for SSL_URL
                "43B34F1C-DBE0-4B58-A5C7-96C91F69B26D0", // Apache HttpComponents DF 1 ('0' added due to characterization)
                "67F5CED0-A51C-42D7-A789-FFF952F58C49", // Apache HttpComponents DF 2
                "C1626FA5-5FBE-450E-9E65-BCF3B135F68D", // Inadequate Certificate Verification Semantic 1
                "3FF883E4-282F-4457-9D71-2B9D3B7E93C5", // Inadequate Certificate Verification Semantic 2
                "2D79EF35-2EBB-4733-90AA-283D4A140CB3"// Inadequate Certificate Verification Semantic 3
            ].indexOf(ruleID) > -1) {
            vuln.remove();
        }
    }
}

