// Fill an array with all the webview.loads where JS is enabled
var vulns=getVulnerabilities();
var jsenabledloads = new Array();
var universal_access_enabled_loads = new Array();
for each (var vuln in vulns) {
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    if (vuln !== null) {
        var id = vuln.getRule().getIdentifier();
        if (String(id) == "7EB9AAC7-0A03-4A18-B938-4C918875B168") {
            var load = new Object();
            load.primaryCall = vuln.getPrimaryCall();
            load.primaryLine = vuln.getPrimaryLine();
            load.primaryFile = vuln.getPrimaryFile();
            jsenabledloads[jsenabledloads.length] = load;
            // Remove these issues since they are used to gather information to decide how are we going to treat Resource Injection issues
            vuln.remove();
        }
        else if (String(id) == "A6D8D0AC-6DCF-4404-8C33-D896B46C933C") {
            var load = new Object();
            load.primaryCall = vuln.getPrimaryCall();
            load.primaryLine = vuln.getPrimaryLine();
            load.primaryFile = vuln.getPrimaryFile();
            universal_access_enabled_loads[universal_access_enabled_loads.length] = load;
            // Remove these issues since they are used to gather information to decide how are we going to treat File Based Cross-zone Scripting
            vuln.remove();
        }
        // Remove Non final public static fields from r.java file
        // Fixes bug 40189
        else if (String(id) == "3F30430E-C978-475D-97A0-37D917C45791") {
            if (vuln.getPrimaryFile().search(/^.*[\/|\\]r\.java$/i) > -1) {
                vuln.remove();
            }
        }
    }
}
// If there is at least one insecure load, process XSS and Resource injection sinks
if (jsenabledloads.length > 0) {
    for each (var vuln in vulns) {
        if (vuln != null) {
            var id = vuln.getRule().getIdentifier();
            // Resource Injection
            if (String(id) == "2A465657-F205-48FA-97B5-AD0919BC389A") {
                if (isJSEnabled(vuln, jsenabledloads)) {
                    // alert("Removing Resource Injection issue because JS is enabled, but now, you should get a XSS");
                    vuln.remove();
                } else {
                    // alert("Find and remove XSS issue since JS is disabled");
                    for each (var vuln2 in vulns) {
                        if (vuln2 !== null && (vuln2.getPrimaryFile() === null || vuln2.getPrimaryLine() === null)) continue;
                        if (vuln2 !== null) {
                            var id = vuln2.getRule().getIdentifier();
                            var xsssinks = ["BAAC4B08-D189-4C7F-B8F7-EDC9E8672FAD", "5E920A04-FBCA-4DD9-8ED5-5F059DA2C41C", "FFA3596B-3B35-4338-A7C2-1D78E2E7F000", "8ED6028B-1CF1-4BBC-9788-3E1ED5890050", "857470D1-E209-4FCA-B27E-80E44A394A7D"];
                            if (contains(xsssinks, String(id))) {
                                if ( String(vuln.getPrimaryCall()) == String(vuln2.getPrimaryCall()) && String(vuln.getPrimaryLine()) == String(vuln2.getPrimaryLine()) && String(vuln.getPrimaryFile()) == String(vuln2.getPrimaryFile())) {
                                    // alert("Removing XSS issue since we dont know if JS is enabled for sure ");
                                    vuln2.remove();
                                    break;
                                }
                            }
                        }
                    }
                }
            }
            // File Based Cross-Zone Scripting 1
            else if (String(id) == "23B7335E-9205-4F71-9436-EA7A98C133BB") {
                if (!isJSEnabled(vuln, jsenabledloads)) {
                    //alert("Removing File Based Cross-Zone Scripting issue because JS is not enabled 1");
                    vuln.remove();
                }
            }
            // File Based Cross-Zone Scripting 2
            else if (String(id) == "F50A060D-28AB-4E9A-89EB-79E44E416055") {
                if (!isJSEnabled(vuln, universal_access_enabled_loads)) {
                    //alert("Removing File Based Cross-Zone Scripting issue because JS is not enabled 2");
                    vuln.remove();
                }

            }
        }
    }
} else {
    // There are no webview loads with JS enabled
    for each (var vuln in vulns) {
        if (vuln != null) {
            var id = vuln.getRule().getIdentifier();
            var xsssinks = ["BAAC4B08-D189-4C7F-B8F7-EDC9E8672FAD", "5E920A04-FBCA-4DD9-8ED5-5F059DA2C41C", "FFA3596B-3B35-4338-A7C2-1D78E2E7F000", "857470D1-E209-4FCA-B27E-80E44A394A7D"];
            // File Based Cross-Zone Scripting
            if (String(id) == "23B7335E-9205-4F71-9436-EA7A98C133BB") {
                // alert("Removing File Based Cross-Zone Scripting issue because JS is not enabled 2");
                vuln.remove();
                continue;
            }
            else if (contains(xsssinks, String(id))) {
                // alert("Removing XSS issue since JS is disabled");
                vuln.remove();
                continue;
            }
        }
    }
}

function isJSEnabled (vuln, jsenabledloads) {
    result = false;
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) return false;
    for each (var load in jsenabledloads) {
        if ( String(load.primaryCall) == String(vuln.getPrimaryCall()) && String(load.primaryLine) == String(vuln.getPrimaryLine()) && String(load.primaryFile) == String(vuln.getPrimaryFile())) {
            result = true;
        }
    }
    return result;
}

