                if (!isJSEnabled(vuln, jsenabledloads)) {
                    //alert("Removing File Based Cross-Zone Scripting issue because JS is not enabled 1");
                    vuln.remove();
                }
            }
            // File Based Cross-Zone Scripting 2
            else if (String(id) == "F50A060D-28AB-4E9A-89EB-79E44E416055") {
                if (!isJSEnabled(vuln, universal_access_enabled_loads)) {
                    //alert("Removing File Based Cross-Zone Scripting issue because JS is not enabled 2");
                    vuln.remove();
                }

            }
        }
    }
} else {
    // There are no webview loads with JS enabled
    for each (var vuln in vulns) {
        if (vuln != null) {
            var id = vuln.getRule().getIdentifier();
            var xsssinks = ["BAAC4B08-D189-4C7F-B8F7-EDC9E8672FAD", "5E920A04-FBCA-4DD9-8ED5-5F059DA2C41C", "FFA3596B-3B35-4338-A7C2-1D78E2E7F000", "857470D1-E209-4FCA-B27E-80E44A394A7D"];
            // File Based Cross-Zone Scripting
            if (String(id) == "23B7335E-9205-4F71-9436-EA7A98C133BB") {
                // alert("Removing File Based Cross-Zone Scripting issue because JS is not enabled 2");
                vuln.remove();
                continue;
            }
            else if (contains(xsssinks, String(id))) {
                // alert("Removing XSS issue since JS is disabled");
                vuln.remove();
                continue;
            }
        }
    }
}

function isJSEnabled (vuln, jsenabledloads) {
    result = false;
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) return false;
    for each (var load in jsenabledloads) {
        if ( String(load.primaryCall) == String(vuln.getPrimaryCall()) && String(load.primaryLine) == String(vuln.getPrimaryLine()) && String(load.primaryFile) == String(vuln.getPrimaryFile())) {
            result = true;
        }
    }
    return result;
}

