        var contents = '';
        try {
            contents = readFile(filename);
        } catch (err) {
            log("Error reading file "+filename);
            continue;
        }
        try {
            if (contents.charAt(0) != '<') {
                  contents = contents.substring(1);
            }
            var xml = new XML(contents);
            // Castor Marshaller
            if (null != xml && null != xml.name() && null != xml.name().localName && null != xml.name().localName.match("beans")) {
                for each (var bean in xml..springns::bean) {
                    if (String(bean["@class"]) == "org.springframework.oxm.castor.CastorMarshaller") {
                        for each (var prop in bean.springns::property) {
                            if (String(prop["@name"]) == "entityResolver") {
                                return true;
                            }
                        }
                    }
                }
            }
        } catch (err) {
          // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
          // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
          return false;
        }
    }
    return false;
}

function isSecureJAXRS () {
    var xmlFiles = getXMLConfigFileNames();
    var ns = new Namespace("http://java.sun.com/xml/ns/j2ee");
    for each (var filename in xmlFiles) {
        var contents = '';
        try {
            contents = readFile(filename);
        } catch (err) {
            log("Error reading file "+filename);
            continue;
        }
        try {
            if (contents.charAt(0) != '<') {
                  // Running into problems with xml files that begin with the character FEFF
                  // Apparently this is a standard way to say that the file is unicode, but
                  // it causes the Rhino XML parser to go nuts.  I'm going to zap the
                  // charater, and no doubt pay the price when some file that actually uses
                  // some fancy characters comes along. bvc
                  contents = contents.substring(1);
            }
            var xml = new XML(contents);
            if (null != xml && null != xml.name() && null != xml.name().localName && null != xml.name().localName.match("web-app")) {
                var path = filename.replace("\\", "/").split("/");
                if (path[path.length-2] != "WEB-INF") {
                    dbg(path[path.length-2]);
                    break;
                }
                for each (var j in xml.children()) {
                    // Jersey, CXF, Restlet Secure by default in their latest versions
                    var secure = true;
                    if (null != j.name() && null != j.name().localName.match("context-param")) {
                        for each (var k in j.children()) {
                             // RestEasy. Secure configuration. Jersey Secure configuration
                            if (String(k.name().localName) == "param-name" && (String(k.text()) ==  "resteasy.document.expand.entity.references" || String(k.text()) ==  "com.sun.jersey.config.feature.DisableXmlSecurity")) {
                                for each (var k in j.children()) {
                                    if (String(k.name().localName) == "param-value" && String(k.text()).toLowerCase() ==  "true") {
                                        return false;
                                    } else if (String(k.name().localName) == "param-value" && String(k.text()).toLowerCase() ==  "false") {
                                        return true;
                                    }
                                }
                            }
                        }
                    } else if (null != j.name() && null != j.name().localName.match("servlet")) {
                        for each (var h in j.children()) {
                            if (null != h.name() && null != h.name().localName.match("init-param")) {
                                for each (var k in h.children()) {
                                    // RestEasy. Secure configuration. Jersey Secure configuration
                                    if (String(k.name().localName) == "param-name" && (String(k.text()) ==  "resteasy.document.expand.entity.references" || String(k.text()) ==  "com.sun.jersey.config.feature.DisableXmlSecurity")) {
                                        for each (var k in h.children()) {
                                            if (String(k.name().localName) == "param-value" && String(k.text()).toLowerCase() ==  "true") {
                                                return false;
                                            } else if (String(k.name().localName) == "param-value" && String(k.text()).toLowerCase() ==  "false") {
                                                return true;
                                            }
                                        }
                                    }
                                }
                            // RestEasy. Insecure by default
                            } else if (String(h.name().localName) == "servlet-class" && (String(h.text()) ==  "org.jboss.resteasy.plugins.server.servlet.HttpServletDispatcher")) {
                                return false;
                            }
                        }
                    }
                }
            }
        } catch (err) {
            // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
            // log("Error processing file: " + filename + " as an XML file. Exception thrown was: " + err + ". Please review the file for any syntax errors.");
        }
    }
    return secure;
}

function correlatesWith(ruleId ,line, file) {
    var vulns = getVulnerabilities();
    for each (var v in vulns) {
        if (v !== null && (v.getPrimaryFile() === null || v.getPrimaryLine() === null)) continue;
        if (String(v.getRule().getIdentifier()) == ruleId && v.getPrimaryLine() == line && v.getPrimaryFile() == file) {
            return true;
        }
    }
    return false;
}
var vulns = getVulnerabilities();
for each (var vuln in vulns) {
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    var ruleId = String(vuln.getRule().getIdentifier());
    if (ruleId == "B35860D9-B131-4D09-92D5-E7C786D3C708") {
        if (correlatesWith("93A88C53-D00C-4A86-9747-D9A0B3176085", vuln.getPrimaryLine(), vuln.getPrimaryFile())) {
            vuln.remove();
            continue;
        }
    } else if (ruleId == "9B4C8277-C168-4C18-BF8D-FACF1D026042") {
        if (correlatesWith("A5AD7144-4DEF-4D04-AF49-E6D7DD86176F", vuln.getPrimaryLine(), vuln.getPrimaryFile())) {
            vuln.remove();
            continue;
        }
    }
}

