/*
 * Returns true if vuln is an 'Access Control: Database' dataflow issue
 */
function isDataflowACDBIssue(vuln) {
    if (vuln === null ||
        vuln.getPrimaryFile() === null ||
        vuln.getPrimaryLine() === null)
        return false;

    var rule = vuln.getRule();
    return rule.getCategory() == 'Access Control' && rule.getSubcategory() == 'Database' && vuln.getAnalyzerName() == 'dataflow';
}
/*
 * Removes 'Access Control: Database' dataflow issues when the source is from the database
 */
function removeACDBIssuesWithDatabaseTaintSource() {
    var vulns = getVulnerabilities() || [];
    for (var i = 0; i < vulns.length; i++) {
        var vuln = vulns[i];
        if (isDataflowACDBIssue(vuln)) {
            var taintPaths = vuln.getTaintPaths() || [];
            for (var j = 0; j < taintPaths.length; j++) {
                var taintPath = taintPaths[j];
                var taintFlags = taintPath.getTaintFlags();
                for (var k = 0; k < taintFlags.length; k++) {
                    if (taintFlags[k] == 'DATABASE') {
                        dbg('Removing "DATABASE" taint path from Access Control: Database vulnerability. File: ' +
                            vuln.getPrimaryFile() + ', Line: ' + vuln.getPrimaryLine());
                        taintPath.removePath();
                        break;
                    }
                }
            }
        }
    }
}
removeACDBIssuesWithDatabaseTaintSource();

//look through captures of implicit intents and their usage to determine whether an internal intent has been used.
//if an internal intent has been used, keep the found vuln, otherwise, remove it as it's a FP
function android_iii_filter(){

    var intimpintent_caps = nameTable.getGlobalCaptures('android.implicitIntent.actionID');
    var intentuse_caps = nameTable.getGlobalCaptures('android.intent.consumes');

    var vulns = getVulnerabilities();

    //Cycle through vulnerabilities found and look at their result locations to compare to intent use captures
    for each (var vuln in vulns){

        var rule = vuln.getRule();

        if (rule.getCategory() == 'Intent Manipulation' && rule.getSubcategory() == 'Implicit Internal Intent' && vuln.getAnalyzerName() == 'controlflow' && rule.getIdentifier() == 'F1766E86-CDF5-4E98-89CD-95633154A4B6'){

            var vloc = vuln.getPrimaryLine();
            var vfile = vuln.getPrimaryFile();
            //use forward slash for comparison
            vfile = vfile.replace("\\", "/");

            //check each intent-use for a match to the vuln line and filepath (there will be a single match)
            //we use the intent-use to map Action-Name specification captures by filepath, variable name, declaration location
            for(var j = 0; j < intentuse_caps.length; j++){

                var intentuse_cap = intentuse_caps[j];
                var iu_cap_sp = intentuse_cap.split('//');

                var iu_varname = iu_cap_sp[0];
                var iu_line = iu_cap_sp[1];
                var iu_fp = iu_cap_sp[2];
                iu_fp = iu_fp.replace("\\", "/");

                //matching vuln location and intent-use capture location
                if(vloc == iu_line && vfile == iu_fp){

                    //want to report vuln and continue (not remove) as soon as we find a non-system action (issysact == false)
                    var issysact = true;

                    // Look through captured implicit intent action name values (specifically find ones with matching variables)
                    for (var i = 0; i < intimpintent_caps.length; i++) {

                        var intimpintent_cap = intimpintent_caps[i];
                        var iii_sp = intimpintent_cap.split('//');
                        var  iii_varname = "";
                        var  iii_line = "";
                        var  iii_fp = "";
                        var  iii_actval = "";

                        if(iii_sp[0]){
                            iii_varname = iii_sp[0].trim();
                        }else{
                            iii_varname = "";
                        }

                        if(iii_sp[1]){
                            iii_line = iii_sp[1].trim();
                        }else{
                            iii_line = "";
                        }

                        if(iii_sp[2]){
                            iii_fp = iii_sp[2].trim();
                            //use forward slash for comparison
                            iii_fp = iii_fp.replace("\\", "/");
                        }else{
                            iii_fp = "";
                        }

                        if(iii_sp[3]){
                            iii_actval = iii_sp[3].trim();
                        }else{
                            iii_actval = "";
                        }                        

                        //if variable names match, filepath matches, line number is sooner (we reasonably know it was set before use, not 100% certainty, but reasonably covering an atypical use case of not setting value via constructor [a warning in the ide]), see if the action is implicit
                        if(iu_varname == iii_varname && iii_fp == iu_fp && iii_line < iu_line){

                            issysact = isSystemAction(iii_actval);

                            //when we find an internal (non-system) action, we want to keep the vuln and thus 
                            //can move on to check the next vuln.
                            if(issysact == false){
                                break;
                            }

                        }

                    }         

                    //we want to remove vulns that are actions that aren't internal (System actions are OK, no vuln)
                    //
                    //presence of a nonsystem action is enough to flag, worst case don't want to have one 
                    //specified incase of accidental misuse, continue to next vuln
                    if(issysact){
                        vuln.remove();
                        break;
                    }else{
                        break; 
                    }

                }

            }

        }
    }

}

//analyze a action name to see if it's a system action, otherwise likely an internal one
//may need to use an exhaustive list comparison in the future if there are a ton of FN's due to people using the 
//official SDK prefix for their internal actions. Seperated out function for making that potential fix easy if needed (hopefully not)
function isSystemAction(action_name){

    var isa = true;

    var systemActionPrefix = "android.intent.action.";

    if(action_name.length() > 22){
        if(action_name.substring(0,22) == systemActionPrefix){
            isa = true;
        }else{
            isa = false;
        }      
    }
    else{
        isa = false;
    }

    return isa;

}

android_iii_filter();

//look through captures of pending intent flag values and label pending intent send methods when the flag value is not set to FLAG_IMMUTABLE
function android_pi_filter(){

    var piflag_caps = nameTable.getGlobalCaptures('android.pendingIntent.flag');

    var vulns = getVulnerabilities();

    //Cycle through vulnerabilities found and look at their result locations, see if it is a good flag value and filter out the finding if so
    for each (var vuln in vulns){

        var rule = vuln.getRule();
        if (rule.getCategory() == 'Intent Manipulation' && rule.getSubcategory() == 'Mutable Pending Intent' && vuln.getAnalyzerName() == 'semantic' && rule.getIdentifier() == '8BC0DDDA-99D2-4C66-A6C5-7105D1C55F18'){

            var vloc = vuln.getPrimaryLine();
            var vfile = vuln.getPrimaryFile();
            //use forward slash for comparison
            vfile = vfile.replace("\\", "/");

            // Look through captured pending intent flag values remove corresponding findings for values that are OK
            for (var i = 0; i < piflag_caps.length; i++) {

                var piflag_cap = piflag_caps[i];
                var piflag_cap_sp = piflag_cap.split('//');

                //the integer value of the pending intent flag
                var piflag = piflag_cap_sp[0].trim();
                //the location in code of the pending intent send method
                var pilocation = piflag_cap_sp[1].trim();
                //the associated filepath name
                var pifp = piflag_cap_sp[2].trim();
                //use forward slash for comparison
                pifp = pifp.replace("\\", "/");

                //compare vuln to capture to see if they're the same snip of code
                if(pilocation == vloc && pifp == vfile){

                    var labelbool = flagOK(piflag);

                    //if FLAG_IMMUTABLE is set, it's okay and the vuln should be removed
                    if (labelbool == true){
                        //remove result, FP            
                        vuln.remove();
                        break;
                    }
                }
            }
        }
    }

}

//analyze a flag value to see if it specifies FLAG_IMMUTABLE value
function flagOK(flagval){

    //Bitwise AND, if specified value is true, resulting value will be equal to flag value
    var result = true;
    //67108864 is FLAG_IMMUTABLE
    var test = flagval & 67108864;

    if (test == 67108864){
        result = true;
    }
    else{
        result = false;
    }    

    return result;
}

android_pi_filter();

            // run this script only if it is an Android application
            if (JavaUtils.isAndroidApp()) {
    var vulns = sca.getVulnerabilities();

    // Get the permissions used for Intents and Content Providers, since these don't show up as labels on methods.
    // We need this to determine overprivilege.
    var intentperms = new Object();
    for (var i = 0; i < vulns.length; i++) {
        var sourcerule = vulns[i].getSourceRule();
        var id = sourcerule.getIdentifier();
        // Is this an Intent source?
        var matchIntents = /41da4a4c-033b-4a47-9237-202533b3b7(\d+)/.exec(id);
        var matchProviders = /8ec972fe-97f2-4b9e-b97d-6914b705d(\d+)/.exec(id);
        if (matchIntents != null) {
            // Get the permission and mark it as used
            var perm = sourcerule.getMetaInfo().get("permissions")[0];
            var split = perm.split(" and ");
            for (var j = 0; j < split.length; j++) {
                intentperms[split[j]] = true;
                //alert("Intent permission: " + split[j]);
            }
        } else if (matchProviders != null) {
            // Get the permission and mark it as used
            var perm = sourcerule.getMetaInfo().get("permissions")[0];
            var split = perm.split(" and ");
            for (var j = 0; j < split.length; j++) {
                intentperms[split[j]] = true;
                //alert("Intent permission: " + split[j]);
            }
        }
        // Handles the WebView corner case
        // Currently does not work for Katrina, so commented out
        //if (sourcerule.getIdentifier() == "CF88CB32-D8F5-4216-B024-F2C537CE2DEC") {
            //intentperms["android.permission.INTERNET"] = true;
        //}
    }

    // In an earlier phase, we created a warning for each permission that's used.
    // Now, check whether the permissions really were used.  If so, remove the warnings.
    // Currently, we also remove permissions associated with Content Providers.
    var remove = new Array();
    var requestedperms = new Object();
    for (var i = 0; i < vulns.length; i++) {
        if (vulns[i] !== null && (vulns[i].getPrimaryFile() === null || vulns[i].getPrimaryLine() === null)) continue;
        var rule = vulns[i].getRule();
        // Is this an overprivilege warning?
        if (rule.getIdentifier() == "DA628366-FBE1-4D37-879F-7B8F53FF24C1") {
            // Read in the manifest
            var manifestfile = vulns[i].getPrimaryFile();
            var filecontents = '';
            try {
                filecontents = readFile(manifestfile);
            } catch (err) {
                log("Error reading file "+manifestfile);
                continue;
            }
            if (filecontents.charAt(0) != '<') {
                filecontents = filecontents.substring(1);
            }
            var lines = filecontents.split("\n");
            var line = lines[vulns[i].getPrimaryLine()-1];

            // Grab the permission from the line
            var pattern = /android:name(?:\s*)=(?:\s*)"([\w\.]+)"/;
            var match = pattern.exec(line);
            var stop = 1;
            while ((match == null || match.length <= 1) && stop < 11 && lines.length > vulns[i].getPrimaryLine()-stop) {
                line = lines[vulns[i].getPrimaryLine()-1-stop];
                match = pattern.exec(line);
                stop++;
            }
            if (match != null && match.length > 1) {
                var perm = match[1]; // The permission
                requestedperms[perm] = true;
                //alert("Permission request: " + perm);
                // Is it used by function calls or Intents?
                var uses = getMethodsByLabel(perm, Platform.ANDROID);
                if ((uses != null && uses.length > 0) || intentperms[perm]) {
                    remove.push(i);
                    //alert("Use found for: " + perm);
                } else {
                    //alert("No use found for: " + perm);
                    //if (blacklist[perm]) {
                        //remove.push(i);
                        //alert("Blacklisted: " + perm);
                    //}

                }
            }

        }
    }

    // In an earlier phase, we created a warning for every Intent, Provider, and WebView that's used.
    // Now, check whether we can remove those underprivilege warnings.
    for (var i = 0; i < vulns.length; i++) {
        var sourcerule = vulns[i].getSourceRule();
        var id = sourcerule.getIdentifier();
        // Is this an Intent source?
        var matchIntents = /41da4a4c-033b-4a47-9237-202533b3b7(\d+)/.exec(id);
        var matchProviders = /8ec972fe-97f2-4b9e-b97d-6914b705d(\d+)/.exec(id);
        if ((matchIntents != null) || (matchProviders != null)) {
            // Mark this as a spurious underprivilege warning
            var perm = sourcerule.getMetaInfo().get("permissions")[0];
            var split = perm.split(" and ");
            var satisfied = false;
            for (var j = 0; j < split.length; j++) {
                if (requestedperms[split[j]]) {
                    satisfied = true;
                } 
            }
            if (split.length > 1 && satisfied) {
                remove.push(i);
            }
            if (split.length == 1 && satisfied) {
                remove.push(i);
            }
        } //else if (id == "CF88CB32-D8F5-4216-B024-F2C537CE2DEC") {
                // EDIT FOR WEBVIEW BUG: currently does not work for Katrina, so comment out
            //if (requestedperms["android.permission.INTERNET"]) {
                //remove.push(i);
            //}
        //}
    }

    // We remove overprivilege warnings for permissions that actually were used,
    // and underprivilege warnings for Intents that actually have permissions.
    for (var i = 0; i < remove.length; i++) {
        vulns[remove[i]].remove();
    }

    // Sometimes there will be two sink warnings for the same line of code.
    // Here, we consolidate them.
    var seen = new Object();
    var newvulns = sca.getVulnerabilities();
    for (var i = 0; i < newvulns.length; i++) {
        if (newvulns[i] !== null && (newvulns[i].getPrimaryFile() === null || newvulns[i].getPrimaryLine() === null)) continue;
        var ruleid = newvulns[i].getRule().getIdentifier();
        var matchIntentSink = /E6C26AE5-D230-4F53-9280-61892BBABAF[123]/.exec(ruleid);
        var matchProviderSink = /8ec972fe-97f2-4b9e-b97d-6914b705d00[12345]/.exec(ruleid);
        if (matchIntentSink != null) {
            var file = newvulns[i].getPrimaryFile().replace("/","").replace(".","");
            var loc = newvulns[i].getPrimaryLine();

            var sourcerule = newvulns[i].getSourceRule();
            var sourceid = sourcerule.getIdentifier();
            var sourcematch = /41da4a4c-033b-4a47-9237-202533b3b7(\d+)/.exec(sourceid);
            if (sourcematch != null) {
                var perm = sourcerule.getMetaInfo().get("permissions")[0];
                var fileloc = file+loc+perm;
                if (seen[fileloc]) {
                    if (seen[fileloc] == ruleid) {
                        //alert("Removing rule ID " + ruleid + " as a duplicate.");
                        newvulns[i].remove();
                    }
                } else {
                    seen[fileloc] = ruleid;
                }
            }
        } else if (matchProviderSink != null) {
            var file = newvulns[i].getPrimaryFile().replace("/","").replace(".","");
            var loc = newvulns[i].getPrimaryLine();

            var sourcerule = newvulns[i].getSourceRule();
            var sourceid = sourcerule.getIdentifier();
            var sourcematch = /8ec972fe-97f2-4b9e-b97d-6914b705d(\d+)/.exec(sourceid);
            if (sourcematch != null) {
                var perm = sourcerule.getMetaInfo().get("permissions")[0];
                var fileloc = file+loc+perm;
                if (seen[fileloc]) {
                    if (seen[fileloc] == ruleid) {
                        //alert("Removing rule ID " + ruleid + " as a duplicate.");
                        newvulns[i].remove();
                    }
                } else {
                    seen[fileloc] = ruleid;
                }
            }
        }
    }
}

