/**
    angular2+ works differently than AngularJS (1.x)

    it does allow the developer access to window, and so it's possible to have a regular XSS vulnerability inside a
    typescript component. However, inside a template file (associated with a component), <script> tags are not allowed,
    and the only way to have an XSS is by having the value go through one of the @angular/platform-browser DomSanitizer
    validation functions. There are basically just ways of Angular saying that the developer has identified them as
    safe and so it shouldn't bother protecting against them in that particular use case.

    From a translation perspective, an XSS in the template such as:

    <p [innerHtml]="untrustedValue">foo</p>

    is extracted out to something like:

    var temp = new HtmlParagraphElement();
    temp.innerHtml = untrustedValue;

    This is good because all of our previous sinks work, but is bad because this is not vulnerable unless it has
    previously gone through DomSanitizer.bypassSecurityTrustHtml().
    The workaround for this is that we add a specific taint with these passthroughs, then we identify angular templates
    via a label, and remove all XSS issues except those containing one of the specific angular taints that show the
    protection has been bypassed.

*/

/**
*  A function to remove an issue if it doesn't contain one of a select array of taints
*  @Param vuln: jsVulnerability: the vulnerability to inspect
*  @Param taintFlagsToPreserve: Array<string>: the list of taintflags that should prevent the issue being removed
*
*/
function removeWhenNotContainingTaint(vuln, taintFlagsToPreserve){
    var taintPaths = vuln.getTaintPaths();
    if (taintPaths === null || taintPaths === undefined){
        //log("Attempted to get taint paths from non-dataflow issue");
        return;
    }
    for each (var taintPath in taintPaths){
        var taintFlags = taintPath.getTaintFlags();
        var trusted = false;
        // loop through the taintflags on the current path to see if any of the taintflags in "taintFlagsToPreserve" is set
        for each (var taintFlag in taintFlags){
            for each (var taintFlagToPreserve in taintFlagsToPreserve) {
                if (taintFlag == taintFlagToPreserve){
                    trusted = true;
                    break;
                }
            }
            if (trusted)
                break;
        }
        if (!trusted){
            // alert("Removing taint path to sink, as path not trusted");
            // alert('Removing vuln in: ' + vuln.getPrimaryFile() + ':' + vuln.getPrimaryLine());
            taintPath.removePath();
        }
    }
}

/**
*  A function to extract the appended part of a dynamically created label. Basically strips off the prefix.
*  @Param obj: any: the object you are trying to get labels from
*  @Param prefix: the prefix that you want to strip off
*  @return: a list of dynamic added values
*
*/
function extractLabelValues(obj, prefix) {
    var values = [];
    if (obj !== null && prefix !== null && prefix !== "") {
        var labels = obj.getLabels();
        if (labels !== null) {
            for each (var l in labels) {
                if (l.indexOf(prefix) == 0) {
                    var value = String(l.substring(prefix.length));
                    if (value != null && value.length > 0) {
                        values[values.length++] = value;
                    }
                }
            }
        }
    }
    return values;
}

/**
*  Gets the final filename off of a full or relative path
*  If the path is already just a file, this is returned.
*  @Param path: string: the path you are trying to retrieve the filename
*  @return: the filename with a path stripped off
*/
function getFilename(path) {
    if (path === null || path === undefined) {
        // alert('path is undefined');
        return '';
    }
    var lastSlashIndex = path.lastIndexOf("/");
    if (lastSlashIndex > 0){
        return String(path.substring(lastSlashIndex + 1));
    } else {
        // is of the form 'foo.html' instead of './foo.html' that is standard
        return String(templateUrl);
    }
}

var ANGULAR_TEMPLATE_CONST = "AngularTemplate";
var fields = nameTable.getFieldsByLabel(ANGULAR_TEMPLATE_CONST, "typescript");
var templateFiles = [];

for each (var field in fields) {
    var templateUrls = extractLabelValues(field, ANGULAR_TEMPLATE_CONST + "::");
    for each (var templateUrl in templateUrls) {
        templateFiles[templateFiles.length] = getFilename(templateUrl);
    }
}

// don't bother going further if no templates found. Probably not an angular 2+ application
if (templateFiles.length > 0) {
    var vulns = getVulnerabilities();
    for each (var vuln in vulns) {
        var category = vuln.getRule().getCategory();
        // in this case we only care about XSS false positives. I don't particularly care which subcategory is flagging
        if (category != "Cross-Site Scripting"){
            continue;
        }
        var filename = getFilename(vuln.getPrimaryFile());
        for each (var templateFile in templateFiles) {
            if (filename == templateFile) {
                // remove the issue if it doesn't contain one of the ANGULAR_BYPASS_ taintflags
                removeWhenNotContainingTaint(vuln,
                    ['ANGULAR_BYPASS_RESOURCE_URL',
                    'ANGULAR_BYPASS_URL',
                    'ANGULAR_BYPASS_HTML',
                    'ANGULAR_BYPASS_STYLE',
                    'ANGULAR_BYPASS_SCRIPT']);
            }
        }
    }
}

dbg("in aspdotnet_csr");
var visited = {};
var vulns = getVulnerabilities();
var disabledGlobally = getVulns(vulns, "F6DC4809-5095-4D99-ACB5-98ECCD213985");
var disabledLocally = getVulns(vulns, "392FFDDB-4EA8-48D7-8064-98804851BD8C");
var aspDotNetApp = loadPersistedObject("aspDotNetApp");
var webconfig = loadPersistedObject("program.webconfig");
var title = "ASP.NET Validation";

// if no Request Validation Disabled vulnerabilities are reported
if ((null == disabledGlobally && null == disabledLocally) || (0 == disabledGlobally.length && 0 == disabledLocally.length)) {
  if(true == aspDotNetApp) {
    handleValidation(vulns, webconfig, visited, title);
  }
}

// if Request Validation Disabled is only reported via an internal rule
if ((null == disabledGlobally || 0 == disabledGlobally.length) && null != disabledLocally && 0 != disabledLocally.length) {
  handleLocallyDisabledValidation(vulns, disabledLocally, webconfig, visited, title);
}

// if Request Validation Disabled is reported via configuration rules
if (null != disabledGlobally && 0 != disabledGlobally.length) {
  handleGloballyDisabledValidation(vulns, disabledGlobally, visited, title);
}

function handleValidation(vulns, webconfig, visited, title) {
  dbg("in handleValidation");
  if (null != vulns) {
    dbg("null != vulns");
    for each (v in vulns) {
      dbg("iterating over vulns");
      // we only wanna do ASP.NET CSR for XSS and Header Manipulation
      if (false == isRelevantForRequestValidation(v)) {
        continue;
      }
      if (true == isWeb(v)) {
        if (!(v in visited)) {
          dbg("! v in visited");
          var sinkRule = v.getRule();
          if (null != sinkRule) {
            dbg("sinkRule != null");
            var metaInfoMap = sinkRule.getMetaInfo();
            lowerProbabilityForCSR(v, metaInfoMap, visited);
            var nodes = new Array();
            if (null != webconfig) {
              dbg("null != webcnfig");
              var node = new Object();
              node.text = "Default Validation Enabled for Application";
              node.fileName = webconfig;
              node.lineNumber = 1;
              nodes[0] = node;
            }
            var taintSource = v.getTaintSource();
            if (null != taintSource) {
              dbg("null != taintSource");
              var fileName = taintSource.getFile();
              if (null != fileName && null != fileName.match(/.*\.aspx\.cs$/)) {
                dbg("fileName matches .aspx.cs: " + fileName);
                fileName = fileName.substring(0, fileName.lastIndexOf(".cs"));
                dbg("modified fileName: " + fileName);
                var node = new Object();
                node.text = "Default Validation Enabled on Page";
                node.fileName = fileName;
                node.lineNumber = 1;
                nodes[1] = node;
              }
            }
            addEvidenceForCSR(v, title, nodes);
          }
        }
      }
    }
  }
}

function handleLocallyDisabledValidation(vulns, disabledLocally, webconfig, visited, title) {
  dbg("in handleLocallyDisabledValidation");
  if (null != vulns) {
    dbg("null != vulns");
    for each (v in vulns) {
      dbg("itertaing over vulns");
      // we only wanna do ASP.NET CSR for XSS and Header Manipulation
      if (false == isRelevantForRequestValidation(v)) {
        continue;
      }
      if (true == isWeb(v)) {
        if (!(v in visited)) {
          dbg("! v in visited");
          var dv = getValidationDisabledVuln(v, disabledLocally);
          if (dv !== null && dv.getPrimaryFile() !== null && dv.getPrimaryLine() !== null) {
            dbg("null != dv");
            var nodes = new Array();
            var node = new Object();
            node.text = "Validation Disabled on Page";
            node.fileName = dv.getPrimaryFile();
            node.lineNumber = dv.getPrimaryLine() - 0;
            nodes[0] = node;
            addEvidenceForCSR(v, title, nodes);
            visited[v] = true;
          }
          else {
            dbg("null == dv");
            var sinkRule = v.getRule();
            if (null != sinkRule) {
              dbg("null != sinkRule");
              var metaInfoMap = sinkRule.getMetaInfo();
              lowerProbabilityForCSR(v, metaInfoMap, visited);
              var nodes = new Array();
              if (null != webconfig) {
                dbg("null != webconfig");
                var node = new Object();
                node.text = "Default Validation Enabled for Application";
                node.fileName = webconfig;
                node.lineNumber = 1;
                nodes[0] = node;
              }
              var taintSource = v.getTaintSource();
              if (null != taintSource) {
                dbg("null != taintSource");
                var fileName = taintSource.getFile();
                if (null != fileName && null != fileName.match(/.*\.aspx\.cs$/)) {
                  dbg("fileName matches .aspx.cs: " + fileName);
                  fileName = fileName.substring(0, fileName.lastIndexOf(".cs"));
                  dbg("modified fileName: " + fileName);
                  var node = new Object();
                  node.text = "Default Validation Enabled on Page";
                  node.fileName = fileName;
                  node.lineNumber = 1;
                  nodes[1] = node;
                }
              }
              addEvidenceForCSR(v, title, nodes);
            }
          }
        }
      }
    }
  }
}

function handleGloballyDisabledValidation(vulns, disabledGlobally, visited, title) {
  dbg("in handleGloballyDisabledValidation");
  if (null != vulns) {
    dbg("null != vulns");
    for each (v in vulns) {
      dbg("iterating over vulns");
      if (v !== null && (v.getPrimaryFile() === null || v.getPrimaryLine() === null)) continue;
      // we only wanna do ASP.NET CSR for XSS and Header Manipulation
      if (false == isRelevantForRequestValidation(v)) {
        continue;
      }
      if (true == isWeb(v)) {
        if (!(v in visited)) {
          dbg("! v in visited");
          var nodes = new Array();
          var index = 0;
          for (index = 0; index < disabledGlobally.length; index++) {
            dbg("iterating over disabledGlobally: " + index);
            var node = new Object();
            node.text = "Validation Disabled for Application";
            if (null != disabledGlobally[index]) {
              dbg("null != disabledGlobally[index]");
              node.fileName = disabledGlobally[index].getPrimaryFile();
              node.lineNumber = disabledGlobally[index].getPrimaryLine() - 0;
            }
            nodes[index] = node;
          }
          addEvidenceForCSR(v, title, nodes);
          visited[v] = true;
        }
      }
    }
  }
}

function getValidationDisabledVuln(v, disabledLocally) {
  dbg("in getValidationDisabledVuln");
  if (v != null && disabledLocally != null) {
    dbg("not null");
    var taintSource = v.getTaintSource();
    if (null != taintSource) {
      dbg("null != taintSource");
      var fileName = taintSource.getFile();
      if (null != fileName) {
        dbg("fileName is not null: " + fileName);
        if (-1 != fileName.lastIndexOf(".cs")) {
          fileName = fileName.substring(0, fileName.lastIndexOf(".cs"));
          dbg("modified fileName: " + fileName);
        }
        for each (dv in disabledLocally) {
          dbg("iterating over disabledLocally");
          var primaryFile = dv.getPrimaryFile();
          dbg("primaryFile: " + primaryFile);
          if (null != primaryFile && primaryFile.toLowerCase() == fileName.toLowerCase()) {
            dbg("found matching vulnerability");
            return dv;
          }
        }
      }
    }
  }
  return null;
}

function isRelevantForRequestValidation(v) {
  dbg("in isRelevantForRequestValidation");
  if (null != v) {
    dbg("v != null");
    var rule = v.getRule();
    if (null != rule) {
      dbg("null != rule");
      var category = rule.getCategory();
      if (null != category && (category == "Cross-Site Scripting" || category == "Header Manipulation")) {
        dbg("relevant for Request Validation");
        return true;
      }
    }
  }
  return false;
}

var xss_ct_sinks = [];
var xss_issues = [];
var xsscs_issues = [];
var vulns = getVulnerabilities();

for each (var vuln in vulns) {
    if (vuln === null || vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null) continue;

    var ruleId = String(vuln.getRule().getIdentifier());

    // Process XSS-enabling content-type sink 
    if (
    // java sinks
    ruleId == "FDCFBA5C-0950-46DB-9EE4-D1B38C520A280" 
     || ruleId == "608E6289-F91C-4613-96C1-5CD9CD2E1D640"
     // python sinks
     || ruleId == "24F7FE27-05CE-4CAB-A55A-6308BBB879FA0"
    ) {
        var xss_ct_sink = new Object();
        xss_ct_sink.primaryLine = vuln.getPrimaryLine();
        xss_ct_sink.primaryFile = vuln.getPrimaryFile();
        xss_ct_sinks.push(xss_ct_sink);
        vuln.remove();
    // Process XSS issues
    } else if (
            // java sinks
            ruleId == "63C7A9AF-5B44-4A46-8C21-E3C2639EF9700" // RequestHandler return statement 
            || ruleId == "3C19233C-2670-47FA-B8E7-0F0F293B6C97" // RequestHandler return statement
            || ruleId == "6E1F953A-5636-47C5-9388-137B0D55E94C"  // XSS:PV sink for write(Object)
            || ruleId == "76F7C5DF-850D-4AC8-A3FE-8AE7AABFB50E"  // XSS:PV sink for write(byte[],,)
            || ruleId == "D2CCABEC-2B85-4098-9DC4-ED47CA91D3AD"  // XSS:PV sink for write(char[],,)
            || ruleId == "13F1572D-8D31-468B-B578-D51F88401C0D"  // XSS:PV sink for write(char)
            || ruleId == "0E836836-C5D0-4977-9EC1-0CE2AFF9F083"  // XSS:PV sink for write(String,,)
            || ruleId == "60A5F5D9-5446-4DB0-B247-954D3F8C201F"  // XSS:PV sink for printf|format(String)
            || ruleId == "33A421F1-EE1A-467F-BE4A-EBFE352EE1D2"  // XSS:PV sink for printf|format(Locale,String)
            || ruleId == "F84BAB3E-8F3F-485D-91D3-6223E0832DBA"  // XSS:R sink for write(object)
            || ruleId == "FD4D94D1-4971-4A61-B0F9-852C15F36089"  // XSS:AI sink for write(object)
            || ruleId == "F200F116-96DA-4F5B-A9AA-74EDBD984E84"  // XSS:R sink for write(byte[],,)
            || ruleId == "DF56EC82-B9E3-4AB1-AC1D-07DFC2DA9AC6"  // XSS:AI sink for write(byte[],,)
            || ruleId == "6EA1768A-744C-4638-8894-C6A1E07DAB14"  // XSS:R sink for write(char[],,)
            || ruleId == "A8043DA3-CB6C-4C16-890C-C77F260EF4CE"  // XSS:AI sink for write(char[],,)
            || ruleId == "B4E14469-A03F-49BA-B6C3-1907946C7E26"  // XSS:R sink for write(char)
            || ruleId == "AF464E66-2748-4305-B053-DA795B0267FC"  // XSS:AI sink for write(char)
            || ruleId == "798E4513-03B3-4252-A644-FBA596AEFB2B"  // XSS:R sink for write(String,,)
