  var missingCompRules = [
    "83F6E487-70ED-4935-8B68-9E2ED3583F42", // replacing 7E507116-859D-4DA7-B643-29029A0C9C27
    "D534F2AC-B993-479E-9032-DFEA8CBCFDF2", // 24F89137-6D72-4A5B-8AA5-EFDED0C0AAF6
    "F11B4967-48B2-49B2-9B91-C6431E4E4B1B", // 64E163CB-B7E4-4721-808A-419DBEA9E668
    "3EAAAB32-EFC6-4C63-A75D-F13CA3553296", // C3A1B9E8-F113-40A7-92D6-C8F65D943D65
    "792FB2AF-3CF8-492B-AEBC-9C0ADDFD6E6C", // D8569903-2332-405B-A712-0F48274A6D32
    // "APF-MISSING-COMPONENT-RULE-6",  no such rule provided to replace 23D3C30C-8249-45BD-BA2F-992A3757BC21
    "436A9149-5962-494C-BF87-0EA6143E3BAE",
  ];
  var remove = new Array();
  vulns = sca.getVulnerabilities();
  for (var i = 0; i < vulns.length; i++) {
    var rule = vulns[i].getSourceRule().getIdentifier();
    for (var j = 0; j < missingCompRules.length; j++) {
      if (rule == missingCompRules[j]) {
        vulns[i].remove();
      }
    }
  }
}


/**
 *
 * This script to check if [Required] attribute in asp.net forced to behave like [BindRequired] and suppress the relavnt rule.
 */

function cleanup() {

  var vulns = getVulnerabilities();

  // condition to supress the issue  
  var removeIssue = false;

  //main Rule to check if there is code to override Required attribute
  var rule_sup = "CBE20468-17E7-4895-9A9E-1793DB6BC935";

  //Vulnerabilities to be removed
  var rulez1 = "C0F7D70E-BB3E-4144-8ED2-6D0524B792FC";

  for each (var vuln in vulns) {
  var ruleid = vuln.getRule().getIdentifier();
    if (ruleid !== undefined && ruleid !== null) {
      if (ruleid == rule_sup) {
        removeIssue = true;
          vuln.remove();
       }
    }   
  }   
  if (removeIssue == true) {
      for each (var vuln in vulns) {
      var ruleid = vuln.getRule().getIdentifier(); 
      if (ruleid !== undefined && ruleid !== null) { 
        if (ruleid == rulez1 ) {
            vuln.remove();
        }
      }   
    }
  } 
}       
