var vulns = getVulnerabilities();
var contentVulnLocations = {};
var dataflowVulns = [];

// ContentRule issues are helper issues and should always be removed by this script.
// We will be reporting an issue if there is both a dataflow and a content issues reported on the same line.
for each (var vuln in vulns) {
    if (vuln === null || vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null) continue; 
    var ruleID = String(vuln.getRule().getIdentifier());
    var lineNumber = vuln.getPrimaryLine();
    var fileName = vuln.getPrimaryFile();
    if (ruleID.equals("5EC21588-8698-4B90-9689-7E323A8CCD04") ||
        ruleID.equals("A959D907-51DD-459A-A97E-663A71F7230F") ||
        ruleID.equals("A55BE18E-6AC6-4A99-A777-D3757574F4AE")) {
            contentVulnLocations[fileName+lineNumber] = true;
            vuln.remove();
    } else if (ruleID.equals("7B643269-E04F-4404-9F84-D613C85630420") ||
               ruleID.equals("BB577448-55DF-4B81-BFD2-42CF7AB23D140") ||
               ruleID.equals("666A888F-9793-4968-B89E-1126603BE9CC0")) {
            dataflowVulns.push(vuln);
    }
}
for each (var vuln in dataflowVulns) {
    var lineNumber = vuln.getPrimaryLine();
    var fileName = vuln.getPrimaryFile();
    // remove the dataflow issue if it's not reported by the content rules
    if (!contentVulnLocations[fileName+lineNumber]) {
        vuln.remove();
    }
}

var form_beans = loadPersistedObject("program.form_beans");
var MASS_ASSIGNMENT_REGEXP = /admin|role|access|price|cost|secret|priv/i;
var issues2remove = [];
if (form_beans != null) {
    // Grab form_bean properties without triggering the null dereference exception
    for each (var form_bean in form_beans) {
        var clss, property_details;
        for (var key in form_bean) {
            if (key == "clss") {
                clss = form_bean[key];
            }
            if (key == "property_details") {
                property_details = form_bean[key];
            }
        }
        if (clss == "org.apache.struts.action.DynaActionForm"
            || "org.apache.struts.validator.DynaValidatorActionForm"
            || "org.apache.struts.validator.DynaValidatorForm") {
            for each (var prop in property_details) {
                if (!prop['name'].match(MASS_ASSIGNMENT_REGEXP)) {
                    issues2remove[issues2remove.length] = prop;
                }
            }
        }
        // if (form_bean.clss == "org.apache.struts.action.DynaActionForm") {
        //     for each (var prop in form_bean.property_details) {
        //         if (!prop['name'].match(MASS_ASSIGNMENT_REGEXP)) {
        //             issues2remove[issues2remove.length] = prop;
        //         }
        //     }
        // }
    }
}
if (issues2remove.length > 0) {
    var vulns = getVulnerabilities();
    for each (var vuln in vulns) {
        if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
        var ruleID = String(vuln.getRule().getIdentifier());
        if (ruleID.equals("8C44759E-8F16-494B-AC39-46D57E9F9863")) {
            var lineNumber = vuln.getPrimaryLine();
            var fileName = vuln.getPrimaryFile();
            for each (var p in issues2remove) {
                if (lineNumber == p['lineNumber'] && fileName == p['fileName']) {
                    vuln.remove();
                }
            }
        }
    }
}

