        var id = vuln.getRule().getIdentifier();
        if (String(id) == "506C9A74-D6B3-4D59-BE85-83647C42784E0" || String(id) == "2F434B61-CB69-4447-9F92-4794D19912810" || String(id) == "FB964D4F-43A8-4803-8F48-FD8E5A3466630") {
            xss_file = String(vuln.getPrimaryFile());
            remove = true;
            for each (var cgi_file in cgi_files) {
                if (cgi_file == xss_file) {
                    remove = false;
                    break;
                }
            }
            if (remove) vuln.remove();
        }
        if (String(id) == "FDEED79B-78B1-4F15-BF53-C4AF7FA586680") {
            if (!memcached) vuln.remove();
        }
    }
}

//String Termination Error findings should not occur for 'primitive' types
function cpp_nullterm_filter(){

    var vulns = getVulnerabilities();

    //Cycle through vulnerabilities found and look for string term vulns
    for each (var vuln in vulns){

        var rule = vuln.getRule();

        if (rule.getCategory() == 'String Termination Error'){        

            var type;

            try{
                type = vuln.getThisType();
            } catch(err) {
                // Swallow potential npe from non-dataflow
            }

            //make sure not null before further access
            if(type){
                //if it's a primitive and not a pointer or an array, remove
                if(type.isPrimitive() && !type.isPointer() && !type.isArray){

                    //string termination errors cannot be found in primitive (can't be a string) variables 
                    vuln.remove();

                }                    
            }


        }
    }
}

cpp_nullterm_filter();

