(function () {
    function extractLabelValues(obj, prefix) {
        var values = [];
        if (obj !== null && prefix !== null && prefix !== "") {
            var labels = obj.getLabels();
            if (labels !== null) {
                for each (var l in labels) {
                    if (l.indexOf(prefix) == 0) {
                        var value = String(l.substring(prefix.length));
                        if (value !== null && value.length > 0) {
                            values[values.length++] = value;
                        }
                    }
                }
            }
        }
        return values;
    }

    function lowerProbabilityForCSR(v, metaInfoMap) {
        if (null !== metaInfoMap) {
            var probability = metaInfoMap.get("Probability");
            // alert(probability);
            // alert(metaInfoMap.get("package")[0]);
            if (null != probability) {
                if (1 == probability.length) {
                    var oldProb = 0;
                    // if the probability was already modified by means other than CSR, use the probability from the vulnerability, otherwise -- from the rule
                    if (null !== v.getMetaInfo("Probability")) {
                        oldProb = parseFloat(v.getMetaInfo("Probability"));
                        // alert("taking probability from the vulnerability");
                    }
                    else {
                        oldProb = parseFloat(probability[0]);
                        // alert("taking probability from the rule ");
                    }
                    var newProb = oldProb-3;
                    // if the new probability is below 1, re-set it to 1
                    if (newProb < 1) newProb = 1;
                    // alert("old probability: '" + oldProb + "'");
                    // alert("new probability: '" + newProb + "'");
                    // alert("changing probability for vulnerability: " + v.getInstanceIdentifier() + " from " + oldProb + " to " + newProb);
                    v.addMetaInfo("Probability", newProb);
                }
            }
        }
    }

    method_url_map = {};
    urlPattern_sourceInfo_map = {};
    var view_methods = nameTable.getMethodsByLabel("DJANGO_URLCONF", "python");
    if (view_methods !== null) {
        for each (var vmethod in view_methods) {
            // alert ("vmethod name " + vmethod.name);
            var values = extractLabelValues(vmethod, "DJANGO_URLCONF::");
            for each (var value in values) {
                // alert("value : " + value);
                var quad = value.split("::"); // pattern, method name, line number, file name
                var method = {};
                if (quad[0].indexOf("r'") === 0) method.regexp = quad[0].substring(2,quad[0].length-1);
                else method.regexp = quad[0];
                if (method.regexp.indexOf("^") === 0) method.regexp = method.regexp.substring(1);
                if (method.regexp.indexOf("$") === method.regexp.length-1) method.regexp = method.regexp.substring(0, method.regexp.length-1);

                var dotidx = quad[1].lastIndexOf(".");
                if (dotidx > -1) method.name = quad[1].substring(dotidx+1);
                else method.name = quad[1];
                method_url_map[method.name] = method;

                // Additional information for analysis evidence : file name and line number.
                var sourceInfo = {}
                sourceInfo.filename = quad[2];
                sourceInfo.linenumber = quad[3];
                urlPattern_sourceInfo_map[method.regexp] = sourceInfo

                // alert("URL regexp: " + method.regexp + " Function: " + method.name + " fileName: " + sourceInfo.filename + " line number: " + sourceInfo.linenumber);
            }
        }
    }

    // loop all vulnerabilities originated in Django sources/entrypoints
    var vulns = getVulnerabilities();
    for each (var vuln in vulns) {
        if (vuln !== null) {
            var id = String(vuln.getSourceRule().getIdentifier());
            if (
                id == "1D691675-91F1-468D-88C1-231EEDDD794D0" ||
                id == "369AC0CA-A19B-48FC-B3B9-03C9BCA7EA930" ||
                id == "899AC510-B44B-4971-BFA3-799C03EFC1410" ||
                id == "087EDA03-D3BC-4012-9251-7D6F5B9882550" ||
                id == "EA44F549-FE6D-4BE7-9E6B-448038B62C1D0") {
                // for each issue, get enclosing function, check it has DJANGO_VIEW_METHOD
                var sourceEnclosingMethod = vuln.getSourceEnclosingFunction();
                var labels = sourceEnclosingMethod.getLabels();
                if (labels !== null) {
                    for each (var l in labels) {
                        try {
                            if (l == "DJANGO_VIEW_METHOD") {
                                // look for view method name in map, get rexexp, add evidence trace
                                var o = method_url_map[sourceEnclosingMethod.name];
                                if (o !== undefined && o !== null) {
                                    var taintSource = vuln.getTaintSource();
                                    if (null !== taintSource) {
                                        var sourceInfo = urlPattern_sourceInfo_map[o.regexp];
                                        var filename = sourceInfo.filename;
                                        var linenumber = sourceInfo.linenumber;
                                        var urlDescriptionTag = "Django Method Mapping";
                                        // TODO: when using include() we are missing the parent path
                                        var externalEntry = o.regexp;
                                        vuln.addExternalEntry(urlDescriptionTag, externalEntry, filename, linenumber);
                                        if (id == "1D691675-91F1-468D-88C1-231EEDDD794D0") {
                                            var metaInfoMap = vuln.getRule().getMetaInfo();
                                            lowerProbabilityForCSR(vuln, metaInfoMap);
                                        }
                                    }
                                }
                                break;
                            }
                        } catch (err) {}
                    }
                }
            }
        }
    }
})();

