(function () {
    function checkAndRemove(vuln) {
        var csrfRuleId = "78E0700E-56FE-45A2-A11B-6A560F730576";
        var vulns = getVulnerabilities() || [];

        for (var i = 0; i < vulns.length; i++) {
            var vulnToRemove = vulns[i];
            //Remove if we find a Vulnerability in the same file as the defaultRule, however, we cannot check for line number
            //since they do not match. So, this will effectively remove all 78E0700E findings in the same file, but note that 
            //it is also not common to have multiple forms in the same page where one has CSRF protection and the others do't.
            if (String(vulnToRemove.getRule().getIdentifier()) == csrfRuleId && vuln.getPrimaryFile() == vulnToRemove.getPrimaryFile())
                vulnToRemove.remove();
        }
    }

	var defaultRule = "D9075869-6900-4E64-BDEA-9346ABD3488F";
	var vulns = getVulnerabilities() || [];

    //We look for the defaultRule first in order to remove all the CSRF-related findings
	for (var i = 0; i < vulns.length; i++) {
		var vuln = vulns[i];
		if (String(vuln.getRule().getIdentifier()) == defaultRule)
            checkAndRemove(vuln);
	}
})();

