      var line = String(vuln.getPrimaryLine());

      if (ruleid == "E8885AA6-C967-490A-B4DF-5F4692EF6BF5") {
        for each (var f in allFiles) {
          if (f == file) {
            try {
              var jspfile = new XML(getXMLForContentFile(f));
              if (null != jspfile) {
                // handle <script/>
                for each (var scripttag in jspfile..script) {
                  var scriptline = String(scripttag["@__FFY__LOC"]);
                  var colonIndex = scriptline.lastIndexOf(":");
                  scriptline = scriptline.substring(0, colonIndex);
                  var tagtext = String(scripttag.text());
                  if (tagtext != null && tagtext != "") {
                      if (line == Number(scriptline) + 1 && -1 != tagtext.search("<!--") && -1 != tagtext.search("-->")) {
                        vuln.remove();
                      }
                  }
                }

                // handle <style/>
                for each (var styletag in jspfile..style) {
                  var styleline = String(styletag["@__FFY__LOC"]);
                  var colonIndex = styleline.lastIndexOf(":");
                  styleline = styleline.substring(0, colonIndex);
                  //if (line == Number(styleline) + 1 && -1 != styletag.text().search("<!--") && -1 != styletag.text().search("-->"))
                  if (line == Number(styleline) + 1) {
                    vuln.remove();
                  }
                }
              }
            }
            catch (err) {
               // actively ignoring XML parsing errors. Not much help to customers. See bug 31939 for more details.  
               // warn_internal("Error processing " + f + " as an XML file: " + err);
            }
          }
        }
      }
    }
  }
}
catch (err) {
  warn_internal("Error filtering HTML comment results " + err);
}

// figures out whether this is an Objective-C application
function isObjectiveCApp() {
    for each (var filename in getAllProgramFileNames()) {
        if (null != filename) {
            var shortName = String(filename).replace(/\\/g, "/");
            shortName = shortName.substring(shortName.lastIndexOf("/")+1);
            var extension = shortName.substring(shortName.lastIndexOf(".")+1);
            if (extension != null && ("m" == extension.toLowerCase() || "mm"  == extension.toLowerCase() )) {
                return true;
            }
        }
    }
    return false;
}

// The remove function. Remove all the results for the specified Category and SubCategories
function remove_rules(probCat) {
    var vulns=getVulnerabilities();
    toNextVuln:
    for each (var vuln in vulns) {
        var ruleRR=vuln.getRule();
        var ruleID=String(ruleRR.getIdentifier());
        var cat = String (ruleRR.getCategory());

        // subcat is "null" when there is NO subcategory is associated with a Vulnerability
        var subcat = String(ruleRR.getSubcategory());

        var psclist = probCat[cat];

        if (psclist != null) {
            for (var psc in psclist) {
                if (psclist[psc].equals(subcat)) {
                    vuln.remove();
                    continue toNextVuln;
                }
            }
        }
    }
}

