(function () {
  var vulns = getVulnerabilities();

  acdb_issues = [];
  sqli_structural_issues = [];
  sqli_dataflow_issues = [];

  for (let i = 0; i < vulns.length; i++) {
    let vuln = vulns[i];
    var category = String(vuln.getRule().getCategory());
    var subcategory = String(vuln.getRule().getSubcategory());
    var analyzer = String(vuln.getAnalyzerName());

    var fileName = vuln.getPrimaryFile().toLowerCase();

    if (
      fileName.endsWith(".sql") ||
      fileName.endsWith(".pks") ||
      fileName.endsWith(".pkh") ||
      fileName.endsWith(".pkb")
    ) {
      if (category == "SQL Injection") {
        if (analyzer == "dataflow") {
          sqli_dataflow_issues[sqli_dataflow_issues.length] = vuln;
        } else if (analyzer == "structural") {
          sqli_structural_issues[sqli_structural_issues.length] = vuln;
        }
      } else if (category == "Access Control" && subcategory == "Database") {
        acdb_issues[acdb_issues.length] = vuln;
      }
    }
  }

  if (sqli_dataflow_issues.length > 0 && sqli_structural_issues.length > 0) {
    for (let i = 0; i < sqli_dataflow_issues.length; i++) {
      let dataflow_vuln = sqli_dataflow_issues[i];

      for (let j = 0; j < sqli_structural_issues.length; j++) {
        let structural_vuln = sqli_structural_issues[j];

        if (
          dataflow_vuln.getPrimaryLine() == structural_vuln.getPrimaryLine() &&
          dataflow_vuln.getPrimaryFile() == structural_vuln.getPrimaryFile()
        ) {
          // Remove structural issue from results
          structural_vuln.remove();
        }
      }
    }
  }

  if (sqli_dataflow_issues.length > 0 && acdb_issues.length > 0) {
    for (let i = 0; i < sqli_dataflow_issues.length; i++) {
      let sql_vuln = sqli_dataflow_issues[i];
      for (let j = 0; j < acdb_issues.length; j++) {
        let acdb_vuln = acdb_issues[j];

        // SQLI (Dataflow) > ACDB
        if (
          sql_vuln.getAnalyzerName() == "dataflow" &&
          sql_vuln.getPrimaryLine() == acdb_vuln.getPrimaryLine() &&
          sql_vuln.getPrimaryFile() == acdb_vuln.getPrimaryFile()
        ) {
          // Remove ACDB issue from results
          acdb_vuln.remove();
        }
        // SQLI (Structural) > ACDB (!Dataflow)
        else if (
          sql_vuln.getAnalyzerName() == "structural" &&
          acdb_vuln.getAnalyzerName() != "dataflow" &&
          sql_vuln.getPrimaryLine() == acdb_vuln.getPrimaryLine() &&
          sql_vuln.getPrimaryFile() == acdb_vuln.getPrimaryFile()
        ) {
          // Remove ACDB issue from results
          acdb_vuln.remove();
        }
        // ACDB (Dataflow) > SQLI (Structural)
        else if (
          sql_vuln.getAnalyzerName() == "structural" &&
          acdb_vuln.getAnalyzerName() == "dataflow" &&
          sql_vuln.getPrimaryLine() == acdb_vuln.getPrimaryLine() &&
          sql_vuln.getPrimaryFile() == acdb_vuln.getPrimaryFile()
        ) {
          // Remove SQLI issue from results
          sql_vuln.remove();
        }
      }
    }
  }
})();

//Certain python methods will resolve as coming from generic types requiring matching rules 
//to be too broad. Filter rule results that used the gRPC rules but did not have a gRPC source
function gRPC_Python_Passthrough_Cleanup(){
    var vulns = getVulnerabilities();

    //Cycle through vulnerabilities found and look at their taint paths, serching for gRPC Specific taint
    for each (var vuln in vulns){

        if (vuln === null || vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null) continue;

        var sourceid = String(vuln.getSourceRule().getIdentifier());

        //if the source is gRPC source, any potential gRPC passthrough is fine, don't need to check
        if(!sourceid.equals("F829A426-BF37-4D40-A36F-7902DDC395B50")){

            var taintPaths = vuln.getTaintPaths();  

            if (taintPaths !== null && taintPaths !== undefined) {

                for (var i = 0; i < taintPaths.length; i++) {

                    var theseTaintFlags = taintPaths[i].getTaintFlags();

                    for (var j = 0; j < theseTaintFlags.length; j++) {

                        // If gRPC_Read_Xthru was used and the source was not a gRPC source function, filter out the vuln
                        // 0 postpended on ID for characterization rule
                        if (theseTaintFlags[j].equals("GRPC_READ_XTHRU")){
                            //alert(sourceid);
                            taintPaths[i].removePath();
                        }
                    }
                }
            }
        }
    }
}

gRPC_Python_Passthrough_Cleanup();

var lowerFriorityFlags = [
    "ARGS",
    "CACHE",
    "CHANNEL",
    "CONSOLE",
    "ENVIRONMENT",
    "FILE_SYSTEM",
    "JSON",
    "LDAP",
    "NAMING",
    "PROPERTY",
    "REGISTRY",
    "SERIALIZED",
    "STDIN",
    "STREAM",
    "XML"
];
function applyCSR(taintPaths) {
    for each (tp in taintPaths) {
        for each (tf in tp.getTaintFlags()) {
            if (lowerFriorityFlags.indexOf(String(tf)) > -1) return true;
        }
    }
    return false;
}
function doTaintFlagBasedInputCSR(vuln) {
    if (vuln === null && vuln === undefined) return;
    var visited = {}; // Not needed but used by the lowerProbabilityForCSR function
    var doCSR = applyCSR(vuln.getTaintPaths());
    if (doCSR) {
        var sinkMetaInfo = vuln.getRule().getMetaInfo();
        if (null != sinkMetaInfo) {
            lowerProbabilityForCSR(vuln, sinkMetaInfo, visited);
        }
    }
}
function init() {
    var vulns=getVulnerabilities();
    for each (vuln in vulns){
        if (vuln.getAnalyzerName() == "dataflow") doTaintFlagBasedInputCSR(vuln);
    }
}
