/*
Remove all Insecure IPC: URL Scheme Hijacking issues if no custom URL schemes
are defined in the info.plist files. Additionally, if we do need to report the 
vulnerability, issues from rule EA34FEA8 (SwiftUI) need to be trimmed down to 
only one issue remaining. This has to be done in a post script due to SwiftUI's 
implementation of handling custom URLs involve lots of lambdas.
*/

var vulns = getVulnerabilities();
var uikit_vulns = new Array();
var swiftui_vulns = new Array();
var swiftui_entry_point_file = "";
var custom_url_scheme_enabled = false;

for each (var vuln in vulns) {
    var id = String(vuln.getRule().getIdentifier());

    /* Check if custom URL schemes are defined by internal rule BDB575BA */
    if (id == "BDB575BA-3615-440B-8A89-FFED24891715") {
        custom_url_scheme_enabled = true;
    }
    /* Catch URL scheme hijacking issues for the UIKit framework */
    else if (id == "AD45BCB7-B679-41A3-B859-DE518FDC934F" ||
                id == "9FDD725A-91E6-4E21-88EB-2073FA5DB7B2") {
        uikit_vulns.push(vuln);
    }
    /* Catch URL scheme hijacking issues for the SwiftUI framework */
    else if (id == "EA34FEA8-16C7-4089-982E-9DD5A4F58BF2") {
            swiftui_vulns.push(vuln);
    }
    /* Find the entry point class location of a SwiftUI app */
    else if (id == "F288A980-45F8-4A90-9C33-F54AE8711B63") {
        swiftui_entry_point_file = vuln.getPrimaryFile();
    }
}

/* Remove all URL scheme hijacking issues if no custom URL is defined */
if (!custom_url_scheme_enabled) {
    for each (var vuln in uikit_vulns)
        vuln.remove();
    for each (var vuln in swiftui_vulns)
        vuln.remove();
}
/* 
    If do need to report, only keep one of the SwiftUI issues. The one to keep
    is the first issue in the entry point SwiftUI.App class
*/
else if (swiftui_entry_point_file != "" && swiftui_vulns.length > 1) {
    var vuln_to_keep = null;
    var vuln_line_to_keep = Number.MAX_SAFE_INTEGER;
    for each (var vuln in swiftui_vulns) {
        var vuln_file = vuln.getPrimaryFile();
        var vuln_line = parseInt(vuln.getPrimaryLine());
        /*
        Consider keeping the issue if it's in the same file as the main entry point class. Keep the one
        with the lowest line number.
        */
        if (vuln_file == swiftui_entry_point_file) {
            if (vuln_to_keep == null || vuln_line < vuln_line_to_keep) {
                vuln_to_keep = vuln;
                vuln_line_to_keep = vuln_line;
            }
        }
    }

    /* remove all SwiftUI issues except the one in the main entry point class */
    var iid_to_keep = "N/A";
    if (vuln_to_keep != null)
        iid_to_keep = vuln_to_keep.getInstanceIdentifier();
    for each (var vuln in swiftui_vulns) {
        if (vuln.getInstanceIdentifier() != iid_to_keep) {
            vuln.remove();
        }
    }
}

/*
 * Returns true if vuln matches the ruleId
 */
function isMatch(vuln, ruleId) {
    if (vuln === null ||
        vuln.getPrimaryFile() === null ||
        vuln.getPrimaryLine() === null)
        return false;

    return vuln.getRule().getIdentifier() == ruleId;
}
/*
 * Removes 'Insecure Storage: Universal Pasteboard' dataflow issues when the localOnly option has been set to true/YES
 */
function cleanUniversalPasteboardIssues(internalRuleId, universalPasteboardRuleId) {
    var vulns = getVulnerabilities() || [];

    // Look for internal rule detections of localOnly = true/YES
    var localOnlyOptionDetections = []
    for (var i = 0; i < vulns.length; i++) {
        var vuln = vulns[i];
        if (isMatch(vuln, internalRuleId)) {
            var location = vuln.getPrimaryFile() + ':' + vuln.getPrimaryLine();
            localOnlyOptionDetections[localOnlyOptionDetections.length] = location;
            dbg('Local pasteboard configuration detected at ' + location);
            vuln.remove();
        }
    }

    // Remove 'Insecure Storage: Universal Pasteboard' issues where localOnly configuration is OK
    for (var i = 0; i < vulns.length; i++) {
        var vuln = vulns[i];
        if (isMatch(vuln, universalPasteboardRuleId)) {
            var location = vuln.getPrimaryFile() + ':' + vuln.getPrimaryLine();
            if (localOnlyOptionDetections.includes(location)) {
                dbg('Removing \'Insecure Storage: Universal Pasteboard\' issue from ' + location);
                vuln.remove();
            }
        }
    }
}
function cleanUniversalPasteboardIssuesForSwift() {
    cleanUniversalPasteboardIssues('A4446CBC-38EC-485D-8FE6-9B8F0D04D525', 'FA21F1DD-A1D9-47F9-BB8B-F9D7C330DE2E');
}
