              }   // end of for each(v)
            }
        // end of if null != jsfInputs

        /**
         * check to see if a file contains a valid extension or not such that it could be mapped to a URL. Has to be some type of HTML-like file in order to be a view that could be mapped.
         */
        function isUrlMappable(filename){
            var validExtensions = ['html', '.jsp', '.tag', '.tagx', '.jspx', '.jsff', '.faces', '.ctp', '.htm', '.cfml', '.cfc', '.asp', '.vbscript', '.as', '.mxml', '.erb'];
            for (var extension in validExtensions){
                if (filename.toLowerCase().endsWith(extension)){
                    return true;
                }
            }
            return false;
        }

var vulns = getVulnerabilities();
var visited = {};
// recover controller 2 command class map
var controller2commandclass = loadPersistedObject("program.spring_controller2commandclass_map");

if (controller2commandclass !== null && controller2commandclass !== undefined) {
    for each (v in vulns) {
        if (null != v) {
            // For each exposed field, add trace nodes pointing to the the controller that fail to securely bind the command class that contain the field
            if (v.getRule().getIdentifier() == "BEB2A290-95C9-4646-A2D5-6D3B75C3679A0") {
                var commandClass = v.getEnclosingFunction().getEnclosingClass();
                var ccname = commandClass.getPackageName() + "." + commandClass.getName();
                var controllers = controller2commandclass[ccname];
                var nodes = [];
                for each (var c in controllers) {
                    var node = {};
                    node.text = "Controller";
                    node.fileName = c.filename;
                    node.lineNumber = c.linenumber;
                    nodes[nodes.length++] = node;
                }
                addEvidence(v, "Binding Controllers", nodes);
            }
        }
    }
}

function addEvidence(v, title, nodes) {
  if (null != v && null != title && null != nodes && 0 != nodes.length) {
    var src = v.getTaintSource();
    if (null != src) {
      var trace = src.createTrace(title);
      if (null != trace) {
        for (var i in nodes) {
          if (null != nodes[i] && null != nodes[i].text && null != nodes[i].fileName && 0 != nodes[i].fileName.length) {
            trace.addNode(nodes[i].fileName, nodes[i].lineNumber, nodes[i].text);
          }
        }
      }
    }
  }
}

/* master javascript post script that loops over the vulns once, performing all the checks, then runs logic once this has finished */


/*
* create a check object that contains instance variables, with any functions.
* 2 special objects:
* loopFuncs is an object where the keys/fields are rule IDs to match, and the values are callbacks to run when the rule ID matches. Can also specify an object against "categories" which specifies category name: callback key/value pairs.
* postFuncs is an array of functions to be called in order after the loop over all vulns has occurred
*
* I've done them within in separate lib scripts to make them easier to read. If this causes problems, we could either
* put them in this one script, or persist them from a mid script. That may be the better option if we eventally have some fingerprinting capabilities
*/

//Example:
/*
function test_check(){
    _myField = 'foo';
    _myArray = new Array();
    this.loopFuncs = {
        'ruleId' : function(){
            alert(_myField);
        },
        'otherRuleId': function(vuln){ //the vuln matching 'otherRuleId' will automatically be passed to the callback
            _myArray.push(vuln);
        },
        //or for categories, specify a "categories" field that points to an array of objects where the category is the key, and callback the value. Whole Category: Subcategory needs to be specified where there is a subcategory
        categories: [{"Category Name: Subcategory Name": callback}]
    };
    this.postFunc = new Array();
    postFunc.push(function(){
        for each (var vuln in _myArray){
            vuln.remove();
        }
    });
}

Then this just needs to be created and added to the list of checks below
*/

var checks = new Array();

/* add each check instance to the array */
/* Note: if the formatVersion of the script that contains the function is higher than the version of this script, it will be undefined!
Best to check prior to adding to the array */
//either declare the variable as something or check this way to prevent a reference error
if (typeof expressjs_mime_sniffing_check !== "undefined"){
    checks.push(new expressjs_mime_sniffing_check());
}
if (typeof angular_sce_checks !== "undefined"){
    checks.push(new angular_sce_checks());
}
if (typeof angular_xsrf_checks !== "undefined"){
    checks.push(new angular_xsrf_checks());
}
if (typeof angular_ngCookie_checks !== "undefined"){
    checks.push(new angular_ngCookie_checks());
}
if (typeof expressjs_csrf_checks !== "undefined"){
    checks.push(new expressjs_csrf_checks());
}

if (typeof tensorflow_unsafe_deserialization_checks !== "undefined"){
    checks.push(new tensorflow_unsafe_deserialization_checks());
}

/* go through all checks and add the loop funcs to a global list to run in a single loop over all issues found */
for each (var check in checks){
    var funcs = check.loopFuncs;
    for (var id in funcs){
        if (funcs.hasOwnProperty(id)){
            if (id === 'categories'){
                //categories: [{"Cross-Site Request Forgery": _addToIssues}]
                for each (var callback_by_category in funcs[id]){
                    //Should be an object category_name: callback
                    for (var category_name in callback_by_category){
                        if (callback_by_category.hasOwnProperty(category_name)){
                            addCategoryCheck(category_name, callback_by_category[category_name]);
                        }
                    }
                }
            }else{
                addRuleCheck(id, funcs[id]);
            }
        }
    }
}

var vulns = getVulnerabilities();
for each (var vuln in vulns){
    checkRule(vuln);
}

/* loop through all post functions across all checks */
for each (var check in checks){
    for each (func in check.postFuncs){
        if (typeof func !== 'function'){
            //log('function: ' + func + ' is not a function');
        }else{
            func();
        }
    }
}

var vulns = getVulnerabilities();
var candidates = new Array();
var evidences = new Array();
var externally_available_issues = new Array();
var passcode_not_required_issues = new Array();
var default_access_level = new Array();
for each (var vuln in vulns) {
    var id = String(vuln.getRule().getIdentifier());
    /*
        Identify all SecItemAdd calls
    */
    if (id == "2E05E889-BD16-463E-BDD8-506CECBB3480") {
        var candidate = new Object();
        candidate.ruleid = id;
        candidate.primaryCall = vuln.getPrimaryCall();
        candidate.primaryLine = vuln.getPrimaryLine();
        candidate.primaryFile = vuln.getPrimaryFile();
        candidate.vulnerability = vuln;
        candidates[candidates.length] = candidate;
    }
    else if (id == "30C74967-984B-4FCF-AC6E-3D121811A240") {
        // collect "Externally Available Keychain" issues to filter them out once we know which ones take the default access level
        var issue = new Object();
        issue.primaryCall = vuln.getPrimaryCall();
        issue.primaryLine = vuln.getPrimaryLine();
        issue.primaryFile = vuln.getPrimaryFile();
        issue.vulnerability = vuln;
        externally_available_issues[externally_available_issues.length] = issue;
    }
    else if (id == "1D601BB3-365D-4884-82EA-0F9F74F89C4D") {
        // collect "Passcode Policy Unenforced" issues to filter them out once we know which ones take the default access level
        var issue = new Object();
        issue.primaryCall = vuln.getPrimaryCall();
        issue.primaryLine = vuln.getPrimaryLine();
        issue.primaryFile = vuln.getPrimaryFile();
        issue.vulnerability = vuln;
        passcode_not_required_issues[passcode_not_required_issues.length] = issue;
    }
    /* 
       Get all evidences that there is a Keychain access level explicitly set 
    */
    else if (id == "B13C1261-0DF2-4F02-9C67-86F2055270450" // Externally Available
          || id == "483152F7-0833-4305-8238-E947BB30E8B80" // Lacking
          || id == "C36DCE9D-290D-4307-B08C-3C57FB7459790" // Insufficient
          || id == "9686A819-8379-4CA6-B4BB-D6B3B26887D10" // Passcode Policy Unenforced
          || id == "C00F1BD5-5752-4E01-ACF5-83A8C314233C0") // Passcode Policy Enforced
        {
        var evidence = new Object();
        evidence.primaryCall = vuln.getPrimaryCall();
        evidence.primaryLine = vuln.getPrimaryLine();
        evidence.primaryFile = vuln.getPrimaryFile();

        if (id == "C00F1BD5-5752-4E01-ACF5-83A8C314233C0") {
            vuln.remove();
            evidence.type = "Passcode Policy Enforced";
        }
        evidences[evidences.length] = evidence;
   }
}
if (candidates.length > 0) {
    // Remove all "Unspecified Keychain Access Policy" issues if there is at least an evidence of a explicitly set access level 
    for each (var candidate in candidates) {
        var uses_default_level = true;
        for each (var evidence in evidences) {
            if (String(evidence.primaryCall) === String(candidate.primaryCall)
                && String(evidence.primaryLine) == String(candidate.primaryLine)
                && String(evidence.primaryFile) == String(candidate.primaryFile)) {
                candidate.vulnerability.remove();
                uses_default_level = false;
                break;
            }
        }
        if (uses_default_level) {
            default_access_level[default_access_level.length] = candidate;
        }
    }
}
// Once we know which calls to SecItemAdd calls take the default configuration, we can filter the rest of issues
// 1) Externally Available Keychain
for each (var issue in externally_available_issues) {
    var remove_issue = true;
    if (default_access_level.length > 0) {
        for each (var default_access_issue in default_access_level) {
            if (String(default_access_issue.primaryCall) === String(issue.primaryCall)
                && String(default_access_issue.primaryLine) == String(issue.primaryLine)
                && String(default_access_issue.primaryFile) == String(issue.primaryFile)) {
                remove_issue = false;
                break;
            }
        }
    }
    for each (var evidence in evidences) {
        if (String(evidence.primaryCall) === String(issue.primaryCall)
            && String(evidence.primaryLine) == String(issue.primaryLine)
            && String(evidence.primaryFile) == String(issue.primaryFile)) {
            if (evidence.type == "Passcode Policy Enforced") {
                remove_issue = true;
            }
            break;
        }
    }
    if (remove_issue) issue.vulnerability.remove();
}
// 2) Passcode Policy Unenforced
for each (var issue in passcode_not_required_issues) {
    var remove_issue = true;
    if (default_access_level.length > 0) {
        for each (var default_access_issue in default_access_level) {
            if (String(default_access_issue.primaryCall) === String(issue.primaryCall)
                && String(default_access_issue.primaryLine) == String(issue.primaryLine)
                && String(default_access_issue.primaryFile) == String(issue.primaryFile)) {
                remove_issue = false;
                break;
            }
        }
    }
    for each (var evidence in evidences) {
        if (String(evidence.primaryCall) === String(issue.primaryCall)
            && String(evidence.primaryLine) == String(issue.primaryLine)
            && String(evidence.primaryFile) == String(issue.primaryFile)) {
            if (evidence.type == "Passcode Policy Enforced") {
                remove_issue = true;
            }
            break;
        }
    }
    if (remove_issue) issue.vulnerability.remove();
}

