// don't both running if no NPM dependencies were found
if (foundDeps.length > 0) {
    deleteIfRequiredVersionFound(requirements)
}

function deleteIfRequiredVersionFound(reqs) {

    var mapOfStoredIssues = {}

    var vulns = getVulnerabilities() || []

    // store the issues that may need to be deleted
    for (var i = 0; i < vulns.length; i++) {
        var vuln = vulns[i];

        for (var j = 0; j < reqs.length; j++) {
            var req = reqs[j]
            var ruleID = req.ruleID
            var actualRuleID = ruleID + '0'
            if (String(vuln.getRule().getIdentifier()) == actualRuleID) {
                if (mapOfStoredIssues.hasOwnProperty(ruleID)) {
                    mapOfStoredIssues[ruleID].push(vuln)
                } else {
                    var vulnList = []
                    vulnList.push(vuln)
                    mapOfStoredIssues[ruleID] = vulnList
                }

            }
        }
    }

    // delete issues based on dep requirements

    var comparator = new JSDependencyComparator(jsDeps)
    for (var i = 0; i < reqs.length; i++) {
        var req = reqs[i]
        if (comparator.depHasRequiredVersion(req.depName, req.requiredVersion)) {
            var storedIssues = mapOfStoredIssues[req.ruleID] || []
            for (var j = 0; j < storedIssues.length; j++) {
                var vuln = storedIssues[j]
                vuln.remove()
            }
        }
    }

}

(function() {

    var kotlinFPs = function(){
        _myArray = new Array();
        addIfKotlin = function(vuln) {
            var f = vuln.getPrimaryFile()
            if (f.match(/.*\.(kt|kts)$/i)){
                dbg('found a matching vuln in a kotlin file. Removing...')
                _myArray.push(vuln)
            }
        }
        this.loopFuncs = {
            categories: [
                { "Code Correctness: null Argument To Equivalence Method": addIfKotlin }, // FPs in 20.1.2. Mostly due to unsupported function refs being 'null'
                { "Null Dereference": addIfKotlin },                            // doesn't make sense to flag. Kotlin compiler does really good job of null checks, and we should only flag if we do a better job.
                { "Redundant Null Check": addIfKotlin },                        // doesn't make sense to flag. Kotlin compiler does really good job of null checks, and we should only flag if we do a better job.
                { "Poor Error Handling: Overly Broad Catch": addIfKotlin },     // discussed internally, and much more common in kotlin, due to unchecked exceptions.
                { "Poor Style: Value Never Read": addIfKotlin },                // FPs in 20.1.2
            ]
        };
        this.postFuncs = [(function(){
            for each (var vuln in _myArray){
                vuln.remove();
            }
        })];
    }

    kotlin.checks.add(kotlinFPs)

}())

