//If web.config is configured to use SSL then we should not be reporting this issue.

var vulns = getVulnerabilities();
var codeVulns = new Array();
var sslDisabled = false;

for each (var vuln in vulns)
{
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    var rule = vuln.getRule();
    if (rule.getIdentifier() == "3ED6A9E3-4EBD-4DA3-B723-D81D3FF528DF" || rule.getIdentifier() == "C8579F66-FBBD-49CE-9F34-728730313238")
    {
        dbg("we found the issue in code file");
        codeVulns[codeVulns.length] = vuln;
    }
    else if (rule.getIdentifier() == "4D329B36-258E-4B24-B1B3-A35F42BCB858")
    {
        dbg("we found the issue in config");
        sslDisabled = true;
    }
}
dbg("if the SSL is configured then we need to remove issue reported by rule 3ED6A9E3");
if (!sslDisabled)
{
    for each (var vuln in codeVulns)
    {
        vuln.remove();
    }
}

