var restrictEnabled = false;

for each (var vuln in vulns)
{
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    var rule = vuln.getRule();
    if (rule.getIdentifier() == "8D4CCBE6-1370-4120-802C-AC6FB80960EB" || rule.getIdentifier() == "D742990A-F999-4A19-BAA9-1C722D8CEF55" || rule.getIdentifier() == "9FD5798F-D726-4864-A157-8F8560470CF5"
         || rule.getIdentifier() == "7A2571C1-9B36-4C80-9DEB-4CF78E339C55")
    {
        dbg("we found the issue in code file");
        codeVulns[codeVulns.length] = vuln;
    }
    else if (rule.getIdentifier() == "3BA45F5F-45DA-4FB1-B333-B218D4CB0CD4")
    {
        dbg("we found that developer has enabled the restrictxmlcontrols settings in config");
