var ignore_words = ["i18n", "ApplicationResources", "resource", "label", "lang", "package.json", "package-lock.json", "package.lock.json", "bower.json"];

for (var i = 0; i < vulns.length; i++) {
    var vuln = vulns[i]
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    var id = String(vuln.getRule().getIdentifier());

    // Weak Cryptographic Signature: Psychic Signature
    if (id === "C7C29130-F13D-4203-8476-149DB9C0A4B2") {
        var jdkVersion = getJDKVersion();
        var jdk_num = jdkVersion ? parseInt(jdkVersion) : 0;

        if (jdk_num < 15 || jdk_num > 18) {
            vuln.remove();
        }

        continue;
    }

    // Global Servlet Error Page
    if (id === "98735695-DE35-4379-8C42-EA724B958B8A") {
        vuln.remove();
        global_error_page = true;
        continue;
    }
    if (id === "7369617C-E2D6-461C-BEE4-66A4A139BDA7" || id === "5B884F37-E83D-4541-9DF4-E4C973452D1A" || id === "63D409CD-BFA3-40A1-AAA7-9B400C96DD3A") {
        global_error_page_remove_candidates[global_error_page_remove_candidates.length++] = vuln;
        continue;
    }

    // Castor XXE filtering
    if (id === "E1E7810B-E8B3-4269-A4D8-C4C6E70CEE53" || id === "F11D85B7-9B39-46EB-980F-F3928D59DCB1") {
        vuln.remove();
        secure_castor_xxe = true;
        continue;
    }

    // Filter out "(Empty)? Password in Configuration file" and "Encoding Confusion" issues if file path includes known locale codes
    var breakout = false;
    if (id === "C09B4A17-F100-44a0-B315-6C7A39F01DA1"
        || id === "76DA878E-6459-4eb5-BDCF-208E0CF79AA4"
        || id === "CBB19E7F-DD2F-4BE2-8186-E00D0BFA09F6"
        || id === "29C589A2-3796-4486-A12D-BCE05ADFFE11"
        // or Password Management rules for JSON/YAML
        || id == "70E3DB4A-01C9-4D1B-BB12-719E70F331DD"
        || id == "E84C1430-630A-4F78-A4E9-4ED95CA516E8"
        || id == "DB650454-AD1A-4B75-A1BA-1DDEA4F8EF00"
        || id == "B6761AF6-AA29-47D2-A090-0086975E71BD"
        // Password Management: Password in Comment
        || id == "4732083C-74C8-4B62-B089-451F2B55A9F9"
        // or BiDi Control Characters
        || id == "28AC7755-F497-4170-A394-8404B81A92A9") {
        // replace all underscores with hyphens, and unify file separators to forward slashes for easier regex matching
        var DIR_SEPARATOR = '/';
        var path = vuln.getPrimaryFile().replace('_', '-').replace('\\', DIR_SEPARATOR); // canonicalize all underscores to "-" for matching locale
        var optional_country_code = "(-[a-z]{2,3})?" // country/region code for locale. Uses "-" due to replacement above
        for (var j = 0;  j < locales.length; j++){
            var locale = locales[j]
            locale = locale + optional_country_code
            var locale_before_extension = new RegExp("[\-\./]" + locale + "\\.", "gi"); // Eg data.es.properties, data_es.properties or data/es.properties
            var locale_in_directory = new RegExp(DIR_SEPARATOR + locale + DIR_SEPARATOR, "gi");           // Eg ../en_us/data.properties
            if (path.match(locale_before_extension) || path.match(locale_in_directory)) {
                vuln.remove();
                breakout = true;
                break;
            }
        }
        if (breakout) continue; // if vuln removed, no need to check ignore_words
        var filename = path.substr(path.lastIndexOf("/"));
        for (var j = 0;  j < ignore_words.length; j++){
            var word = ignore_words[j]
            if (filename.indexOf(word) > -1) {
                vuln.remove();
                breakout = true;
                break;
            }
        }
    }
    if (breakout) continue;
    // Password in Configuration File filtering
    if (id === "26FA1D1C-C9AE-4D45-9D0D-2972534ECDCE" || id === "13BCF957-DEF6-4FF2-A001-E9D9436EB608" || id === "E037B3EC-AA11-487A-A98E-8313717BB0DB" || id === "8D71F4F2-A263-4C74-BEBD-73239D634378") {
        var key = String(vuln.getPrimaryFile()) + ":" + String(vuln.getPrimaryLine());
        passwordMgmt_dominants[key] = vuln.getInstanceIdentifier();
    }
    // Empty Password in Configuration File filtering
    if (id === "3DA75F8A-A534-44DD-AC0D-3E9DE9582284" || id === "3B5F85EE-E394-4AC9-B742-F71F4E7820D8" || id === "9476CFC7-3247-4E0B-BEA3-2ED8901C2478" || id === "B425596C-8BFC-4237-8AE3-6295F4739AE4") {
        var key = String(vuln.getPrimaryFile()) + ":" + String(vuln.getPrimaryLine());
        emptyPasswordMgmt_dominants[key] = vuln.getInstanceIdentifier();
    }

}

if (global_error_page) {
    for (var i = 0;  i < global_error_page_remove_candidates.length; i++){
        var vuln = global_error_page_remove_candidates[i]
        vuln.remove();
    }
}

var passwordMgmt_dominants_keys = [];
for (var k in passwordMgmt_dominants) passwordMgmt_dominants_keys[passwordMgmt_dominants_keys.length++] = k;

var emptyPasswordMgmt_dominants_keys = [];
for (var k in emptyPasswordMgmt_dominants) emptyPasswordMgmt_dominants_keys[emptyPasswordMgmt_dominants_keys.length++] = k;

var passwordMgmt = passwordMgmt_dominants_keys.length > 0 ? true : false;
var emptyPasswordMgmt = emptyPasswordMgmt_dominants_keys.length > 0 ? true : false;
if (secure_castor_xxe || emptyPasswordMgmt || passwordMgmt) {
    for (var i = 0;  i < vulns.length; i++){
        var vuln = vulns[i]
        if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
        var id = String(vuln.getRule().getIdentifier());
        var category = String(vuln.getRule().getCategory()) + ":" + String(vuln.getRule().getSubcategory());
        var key = String(vuln.getPrimaryFile()) + ":" + String(vuln.getPrimaryLine());
        var iid = vuln.getInstanceIdentifier();

        // Castor XXE filtering
        if (secure_castor_xxe && (id === "126939A4-862C-4C0E-8EB0-AB6DA46D9E07" || id === "2E460778-528B-4FBB-BE2D-BABB942C1C72")) {
            vuln.remove();
        }
        // Password in Configuration File filtering
        if (category === "Password Management:Password in Configuration File" && passwordMgmt_dominants[key] !== undefined && iid !== passwordMgmt_dominants[key]) {
            vuln.remove();
        }
        // Empty Password in Configuration File filtering
        if (category === "Password Management:Empty Password in Configuration File" && emptyPasswordMgmt_dominants[key] !== undefined && iid !== emptyPasswordMgmt_dominants[key]) {
            vuln.remove();
        }
    }
}

