var vulns = getVulnerabilities();
var privacy_violation_issues = []
var privacy_violation_itunes_issues = [] 
for each (var vuln in vulns) {
    var cat = String(vuln.getRule().getCategory());
    var subcat = String(vuln.getRule().getSubcategory());
    if (cat === "Privacy Violation" && subcat === "Sensitive Data Accessible From iTunes") {
        privacy_violation_itunes_issues[privacy_violation_itunes_issues.length] = vuln;
    } else if (cat === "Privacy Violation" && subcat === "null") {
        privacy_violation_issues[privacy_violation_issues.length] = vuln;
    } else if (cat === "Privacy Violation" && subcat === "Health Information") {
        privacy_violation_issues[privacy_violation_issues.length] = vuln;
    }
}
if (privacy_violation_issues.length > 0 && privacy_violation_itunes_issues.length > 0) {
    for each (var candidate in privacy_violation_issues) {
        for each (var issue in privacy_violation_itunes_issues) {
            if (candidate.getPrimaryLine() == issue.getPrimaryLine() 
                && candidate.getPrimaryFile() == issue.getPrimaryFile()) {
                candidate.remove();
            } 
        }
    }
}

// Script to emulate a ResultFilterRule which are not working on Swift nor Objective-C
var vulns = getVulnerabilities();

// "Privacy Violation: Sensitive Data Accessible From iTunes" is dominant over "Privacy Violation" issues
var privacy_violation_issues = []
var privacy_violation_itunes_issues = [] 
var privacy_violation_shoulder_surfing_issues = []

// "NoSQL Injection: Realm" is dominant over "Access Control: Database" issues
access_control_database_issues = []
nosql_injection_realm_issues = []

// Only necessary in Swift3
// Lackind and Insufficient data protection issues reported with 232254B2-E8F1-4C7F-B0C4-745E22D2BC10 and 4661E5D9-CF4F-461E-8EBD-F9AA7C958AA7 are dominant over the ones
// reported with 96B2DE9B-262D-46A0-A096-5D9D76785200 and 2A46A486-2F84-4A58-BE31-E72BF940E755
var data_protection_dominants = []
var data_protection_subordinates = []
var always_remove = []

// Collect relevant vulns
for each (var vuln in vulns) {
    var id = String(vuln.getRule().getIdentifier());
    var cat = String(vuln.getRule().getCategory());
    var subcat = String(vuln.getRule().getSubcategory());

    if (cat === "Privacy Violation" && subcat === "Sensitive Data Accessible From iTunes") {
        privacy_violation_itunes_issues[privacy_violation_itunes_issues.length] = vuln;
    } else if (cat === "Privacy Violation" && subcat === "null") {
        privacy_violation_issues[privacy_violation_issues.length] = vuln;
    } else if (cat === "Privacy Violation" && subcat === "Health Information") {
        privacy_violation_issues[privacy_violation_issues.length] = vuln;
    } else if (cat === "Privacy Violation" && subcat === "Shoulder Surfing") {
        privacy_violation_shoulder_surfing_issues[privacy_violation_shoulder_surfing_issues.length] = vuln;
    } else if (cat === "NoSQL Injection" && subcat === "Realm") {
        nosql_injection_realm_issues[nosql_injection_realm_issues.length] = vuln;
    } else if (cat === "Access Control" && subcat === "Database") {
        access_control_database_issues[access_control_database_issues.length] = vuln;
    }

    // Only necessary in Swift3
    // Lacking and Insufficient data protection issues reported with 232254B2-E8F1-4C7F-B0C4-745E22D2BC10 and 4661E5D9-CF4F-461E-8EBD-F9AA7C958AA7 are dominant over the ones
    // reported with 96B2DE9B-262D-46A0-A096-5D9D76785200 and 2A46A486-2F84-4A58-BE31-E72BF940E755
    if (id == "232254B2-E8F1-4C7F-B0C4-745E22D2BC10" || 
        id == "4661E5D9-CF4F-461E-8EBD-F9AA7C958AA7" || 
        id == "F7CC8460-FFB0-4536-9350-67AE0D32216F" ) {
        data_protection_dominants[data_protection_dominants.length] = vuln;
        if (id == "F7CC8460-FFB0-4536-9350-67AE0D32216F") {
            always_remove[always_remove.length] = vuln;
        }
    } else if (id == "96B2DE9B-262D-46A0-A096-5D9D76785200" || id == "2A46A486-2F84-4A58-BE31-E72BF940E755") {
        data_protection_subordinates[data_protection_subordinates.length] = vuln;
    }
}

// "Privacy Violation: Sensitive Data Accessible From iTunes" is dominant over "Privacy Violation" issues
if (privacy_violation_issues.length > 0 && privacy_violation_itunes_issues.length > 0) {
    for each (var candidate in privacy_violation_issues) {
        for each (var issue in privacy_violation_itunes_issues) {
            if (candidate.getPrimaryLine() == issue.getPrimaryLine() 
                && candidate.getPrimaryFile() == issue.getPrimaryFile()) {
                candidate.remove();
            } 
        }
    }
}

// "Privacy Violation: Shoulder Surfing" is dominant over "Privacy Violation" issues
if (privacy_violation_issues.length > 0 && privacy_violation_shoulder_surfing_issues.length > 0) {
    for each (var candidate in privacy_violation_issues) {
        for each (var issue in privacy_violation_shoulder_surfing_issues) {
            if (candidate.getPrimaryLine() == issue.getPrimaryLine() 
                && candidate.getPrimaryFile() == issue.getPrimaryFile()) {
                candidate.remove();
            } 
        }
    }
}

// "NoSQL Injection: Realm" is dominant over "Access Control: Database" issues
if (access_control_database_issues.length > 0 && nosql_injection_realm_issues.length > 0) {
    for each (var candidate in access_control_database_issues) {
        for each (var issue in nosql_injection_realm_issues) {
            if (candidate.getPrimaryLine() == issue.getPrimaryLine() 
                && candidate.getPrimaryFile() == issue.getPrimaryFile()) {
                candidate.remove();
            } 
        }
    }
}

// Only necessary in Swift3
// Lackind and Insufficient data protection issues reported with 232254B2-E8F1-4C7F-B0C4-745E22D2BC10 and 4661E5D9-CF4F-461E-8EBD-F9AA7C958AA7 are dominant over the ones
// reported with 96B2DE9B-262D-46A0-A096-5D9D76785200 and 2A46A486-2F84-4A58-BE31-E72BF940E755
if (data_protection_dominants.length > 0 && data_protection_subordinates.length > 0) {
    for each (var candidate in data_protection_subordinates) {
        for each (var issue in data_protection_dominants) {
            if (candidate.getPrimaryLine() == issue.getPrimaryLine() 
                && candidate.getPrimaryFile() == issue.getPrimaryFile()) {
                candidate.remove();
            } 
        }
    }
}
if (always_remove.length > 0) {
    for each(var deleteme in always_remove) {
        deleteme.remove();
    }
}


/**
* Due to problems with SCA finding issues in stub libraries, I've decided to strip these out with a post script. This can be disabled once bugs 45120 and 45184 have been fixed
*/
function cleanup(){
    dbg("Getting vulns");
    var vulns = getVulnerabilities();
    var internal_lib_path = "/Core/ruby/libs/"; /* I'm not particularly happy with this. If this turns out to delete real issues, we'll have to think of something else */
    var internal_ruby_path = "/Core/ruby/1.9/";
    var scaInstallDir = getSCAInstall();
    if (scaInstallDir !== null){
        /* prepend to lib paths. If not found, will just default to hardcoded values above */
        internal_lib_path = scaInstallDir.concat(internal_lib_path);
        dbg("internal_lib_path: " + internal_lib_path);
        internal_ruby_path = scaInstallDir.concat(internal_ruby_path);
        dbg("internal_ruby_path: " + internal_ruby_path);
    }
    var ruby_extensions = new Array(".rb"); /* just in case others need to be added subsequently */
    for each (var vuln in vulns) {
        if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
        var path = vuln.getPrimaryFile();
        if (path !== null && path !== undefined && (path.indexOf(internal_lib_path) !== -1 || path.indexOf(internal_ruby_path) !== -1)) {
            /* scripts run across all rulepacks. I only want this to apply to ruby projects, so will check file extensions */
            path = unixPath(path);
            for each (var extension in ruby_extensions){
                if (path.toLowerCase().endsWith(extension)){
                    vuln.remove();
                    dbg("removed issues in file: " + path);
                    break; //no need to check the others if already removed
                }
            }
        }else{
            dbg(path + " didn't match either of the internal paths");
        }
    }
}

cleanup();

// Bug 65821
// entrypoint 48A2E618-B2D3-44CF-A57D-C3E5D16D302B should only apply to Scala Play projects
// usually noise in other projects
(function (debug) {

    function log(msg){
        if (debug){
            alert(msg);
        }
    }

    if (!isPlayProject()) {
        removeNoisyAkkaEntrypoints();
    }

    /**
     * Returns true if identified as a Scala Play project by a placeholder
     * @private
     * @returns {boolean}
     */
    function isPlayProject() {
        var vulns = getVulnerabilities();
        var found = false;
        for (var i = 0; i < vulns.length; i++) {
            var issue = vulns[i];
            if (isPlayPlaceholder(issue)) {
                log('placeholder found');
                found = true;
                issue.remove();
                // intentionally no break so that all placeholder issues removed. Otherwise functionally the same.
            }
        }
        return found;
    }

    /**
     * Removes noisy entry points from Akka that should only apply to Scala Play projects
     * @returns {void}
     */
    function removeNoisyAkkaEntrypoints() {
        var vulns = getVulnerabilities();
        for (var i = 0; i < vulns.length; i++) {
            var issue = vulns[i];
            var sourceRule = issue.sourceRule.identifier;
            if (sourceRule.startsWith('48A2E618-B2D3-44CF-A57D-C3E5D16D302B')) {
                log('found issue to remove at ' + issue.primaryFile + ':' + issue.primaryLine);
                issue.remove();
            }
        }
    }

    /**
     * Returns true if the jsVuln is an identifier rule for Scala Play projects
     * @private
     * @param issue - the jsVuln object
     * @returns {boolean}
     */
    function isPlayPlaceholder(issue) {
        if (issue == null || issue == undefined) {
            return false;
        }
        var placeholder = '670D4D7F-9CC7-42E0-B3CA-0291C4215DAB';
        if (issue.getRule().getIdentifier() == placeholder) {
            return true;
        }
        return false;
    }

})(false)

var vulns=getVulnerabilities();
var xmlloads = new Array();
var xxeissues = new Array();

for each (var vuln in vulns) {
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    if (vuln !== null) {
        var id = vuln.getRule().getIdentifier();
        if (String(id) == "4CE841FA-960B-4FFD-A51F-B670B1E842CA") {
            var load = new Object();
            load.primaryCall = vuln.getPrimaryCall();
            load.primaryLine = vuln.getPrimaryLine();
            load.primaryFile = vuln.getPrimaryFile();
            xmlloads[xmlloads.length] = load;
            // Remove these issues since they are used to gather information to decide how are we going to treat XXE issues 
            vuln.remove();
        }
        if (String(id) == "6F64A0AB-A977-4C9A-9FFF-B6FC0C503444") {
            var issue = new Object();
            issue.primaryCall = vuln.getPrimaryCall();
            issue.primaryLine = vuln.getPrimaryLine();
            issue.primaryFile = vuln.getPrimaryFile();
            issue.vuln= vuln;
            xxeissues[xxeissues.length] = issue;
        }
    }
}

if (xxeissues.length > 0 && xmlloads.length > 0) {
    for each (var issue in xxeissues) {
        end:
        for each (var load in xmlloads) {
            if ( String(issue.primaryCall) == String(load.primaryCall) 
                && String(issue.primaryLine) == String(load.primaryLine)
                && String(issue.primaryFile) == String(load.primaryFile)) {
                issue.vuln.remove();
                continue end;
            }
        }
    }
}

