    if (ruleID.equals("C299361B-1527-4671-BE97-9BD565C7BACC")) {
        mainIssues[mainIssues.length] = vuln;
    }
    // Main Issues (configuration)
    else if (ruleID.equals("78824315-2286-4004-BD33-C460AE4A0A53")) {
        if (isProtectedInConfig) vuln.remove();
        else mainIssues[mainIssues.length] = vuln;
