// Global vars
var endpoints_sensitive = false;
var endpoints_14_exposed = true;
var endpoints_15_exposed = false;
var endpoints_20_exposed = false;

if (hasDependency("org.springframework.boot", "", "1.") || 
    hasDependency("org.springframework.boot", "", "2.0") ||
    hasDependency("org.springframework.boot", "", "2.1")) {
    var jmx_enabled = true;
} else {
    var jmx_enabled = false;

}

function checkSpringBootMisconfigurations(name, value) {
    // Actuator Endpoint configuration 
    if (name == "management.security.enabled" && value.toLowerCase() == "false") {
        endpoints_15_exposed = true;
    }
    else if (name.match(/endpoints.*\.sensitive/) && value.toLowerCase() == "false") {
        endpoints_15_exposed = true;
    }
    else if (name == "endpoints.sensitive" && value.toLowerCase() == "false") {
        endpoints_sensitive = true;
    }
    else if (name == "management.endpoints.web.exposure.include" && value == "*") {
        endpoints_20_exposed = true;
    }
    // JMX configuration
    else if (name == "management.endpoints.jmx.exposure.exclude" && value == "*") {
        jmx_enabled = false;
    }
    else if (name == "spring.jmx.enabled" && value.toLowerCase() == "true") {
        jmx_enabled = true;
    }
}

// Inspect application.yaml files
var allFiles = getAllProgramFileNames();
for each (var f in allFiles) {
    if (f.match(/application.*\.y(a)?ml$/i)) {
        try {
            var props = yamlToPropertyMap(f);
            for each (var p in props) {
                var line = p.substr(0, p.indexOf("::"));
                var prop = p.substr(p.indexOf("::") + 2);
                var propName = prop.substr(0, prop.indexOf("="));
                var propValue = prop.substr(prop.indexOf("=") + 1);
                checkSpringBootMisconfigurations(propName, propValue);
            }
        } catch (err) {
            warn_internal("Error parsing build scripts: " + err);
        }
    }
}

