var redirect_directives = new Array();
var open_redirects_issues = new Array();
var xss_issues = new Array();

var vulns = getVulnerabilities();
for (var i = 0; i < vulns.length; i++) {
    var vuln = vulns[i];
    if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;
    var id = vuln.getRule().getIdentifier();
    if (String(id) == "210D0BA7-6898-474C-911F-FC3322B3B5DE0") {
        var redirect_directive = new Object();
        redirect_directive.primaryLine = vuln.getPrimaryLine();
        redirect_directive.primaryFile = vuln.getPrimaryFile();
        redirect_directives.push(redirect_directive);
        vuln.remove();
    }
    else if (String(id) == "44F68395-73CB-4912-942C-98DC34FA90D80" || String(id) == "9CB67BC5-9AE9-4240-9126-A105051B1A72") {
        xss_issues.push(i);
    }
    else if (String(id) == "3FEEB585-7B7D-4805-8D7B-084C8B999B0E0") {
        open_redirects_issues.push(i);
    }
}

// Remove Open Redirect issues if there are no evidences that "redirect:" directive is used
if (open_redirects_issues.length > 0) {
    if (redirect_directives.length == 0) {
        for each (var issue_idx in open_redirects_issues) {
            var issue = vulns[issue_idx];
            issue.remove();
        }
    } else {
        for each (var issue_idx in open_redirects_issues) {
            var issue = vulns[issue_idx];
            var remove_issue = true;
            for each (var directive in redirect_directives) {
                if (
                    issue.getPrimaryLine() == directive.primaryLine &&
                    issue.getPrimaryFile() == directive.primaryFile
                    ) {
                    remove_issue = false;
                }
            }
            if (remove_issue) issue.remove();
        }
    }
}
// Remove XSS issues if there are evidences that "redirect:" directives are used
if (xss_issues.length > 0 && redirect_directives.length > 0) {
    for each (var issue_idx in xss_issues) {
        var issue = vulns[issue_idx];
        var remove_issue = false;
        for each (var directive in redirect_directives) {
            if (
                issue.getPrimaryLine() == directive.primaryLine &&
                issue.getPrimaryFile() == directive.primaryFile
                ) {
                remove_issue = true;
            }
        }
        if (remove_issue) issue.remove();
    }
}

