var vulns = getVulnerabilities();
var candidates = new Array();
var evidences = new Array();
var externally_available_issues = new Array();
var passcode_not_required_issues = new Array();
var default_access_level = new Array();
for each (var vuln in vulns) {
    var id = String(vuln.getRule().getIdentifier());
    /*
        Identify all SecItemAdd calls
    */
    if (id == "6D88DF40-EC37-43BD-B212-DDD60E2E09A8") {
        var candidate = new Object();
        candidate.ruleid = id;
        candidate.primaryCall = vuln.getPrimaryCall();
        candidate.primaryLine = vuln.getPrimaryLine();
        candidate.primaryFile = vuln.getPrimaryFile();
        candidate.vulnerability = vuln;
        candidates[candidates.length] = candidate;
    }
    else if (id == "9FA8C120-B3E3-43EC-B48A-F6D6A335FD0B") {
        // collect "Externally Available Keychain" issues to filter them out once we know which ones take the default access level
        var issue = new Object();
        issue.primaryCall = vuln.getPrimaryCall();
        issue.primaryLine = vuln.getPrimaryLine();
        issue.primaryFile = vuln.getPrimaryFile();
        issue.vulnerability = vuln;
        externally_available_issues[externally_available_issues.length] = issue;
    }
    else if (id == "71DBEB46-6857-4DF6-92A2-1D7E63FB7E0A") {
        // collect "Passcode Not required" issues to filter them out once we know which ones take the default access level
        var issue = new Object();
        issue.primaryCall = vuln.getPrimaryCall();
        issue.primaryLine = vuln.getPrimaryLine();
        issue.primaryFile = vuln.getPrimaryFile();
        issue.vulnerability = vuln;
        passcode_not_required_issues[passcode_not_required_issues.length] = issue;
    }
    /* 
       Get all evidences that there is a Keychain access level explicitly set 
    */
    else if (id == "BC789645-54BA-4A37-826E-A85104F603DD0" // Externally Available
          || id == "AC1B37E3-30B7-4C27-8DA9-6FEEFB75C7A40" // Lacking
          || id == "7B32E20D-E446-47D8-8C72-82DA67DC306F0" // Insufficient
          || id == "50D44D45-8211-49A5-BE51-F4DA44352B8A0" // Passcode Policy Unenforced
          || id == "0973274C-22A2-483D-8004-E0D0CAF57A4B0") // Passcode Required
        {
        var evidence = new Object();
        evidence.primaryCall = vuln.getPrimaryCall();
        evidence.primaryLine = vuln.getPrimaryLine();
        evidence.primaryFile = vuln.getPrimaryFile();

        if (id == "0973274C-22A2-483D-8004-E0D0CAF57A4B0") {
            vuln.remove();
            evidence.type = "Passcode Policy Enforced";
        }
        evidences[evidences.length] = evidence;
   }
}
if (candidates.length > 0) {
    // Remove all "Unspecified Keychain Access Policy" issues if there is at least an evidence of a explicitly set access level 
    for each (var candidate in candidates) {
        var uses_default_level = true;
        for each (var evidence in evidences) {
            if (String(evidence.primaryCall) === String(candidate.primaryCall)
                && String(evidence.primaryLine) == String(candidate.primaryLine)
                && String(evidence.primaryFile) == String(candidate.primaryFile)) {
                candidate.vulnerability.remove();
                uses_default_level = false;
                break;
            }
        }
        if (uses_default_level) {
            default_access_level[default_access_level.length] = candidate;
        }
    }
}
// Once we know which calls to SecItemAdd calls take the default configuration, we can filter the rest of issues
// 1) Externally Available Keychain
for each (var issue in externally_available_issues) {
    var remove_issue = true;
    if (default_access_level.length > 0) {
        for each (var default_access_issue in default_access_level) {
            if (String(default_access_issue.primaryCall) === String(issue.primaryCall)
                && String(default_access_issue.primaryLine) == String(issue.primaryLine)
                && String(default_access_issue.primaryFile) == String(issue.primaryFile)) {
                remove_issue = false;
                break;
            }
        }
    }
    for each (var evidence in evidences) {
        if (String(evidence.primaryCall) === String(issue.primaryCall)
            && String(evidence.primaryLine) == String(issue.primaryLine)
            && String(evidence.primaryFile) == String(issue.primaryFile)) {
            if (evidence.type == "Passcode Policy Enforced") {
                remove_issue = true;
            }
            break;
        }
    }
    if (remove_issue) issue.vulnerability.remove();
}
// 2) Passcode Policy Unenforced
for each (var issue in passcode_not_required_issues) {
    var remove_issue = true;
    if (default_access_level.length > 0) {
        for each (var default_access_issue in default_access_level) {
            if (String(default_access_issue.primaryCall) === String(issue.primaryCall)
                && String(default_access_issue.primaryLine) == String(issue.primaryLine)
                && String(default_access_issue.primaryFile) == String(issue.primaryFile)) {
                remove_issue = false;
                break;
            }
        }
    }
    for each (var evidence in evidences) {
        if (String(evidence.primaryCall) === String(issue.primaryCall)
            && String(evidence.primaryLine) == String(issue.primaryLine)
            && String(evidence.primaryFile) == String(issue.primaryFile)) {
            if (evidence.type == "Passcode Policy Enforced") {
                remove_issue = true;
            }
            break;
        }
    }
    if (remove_issue) issue.vulnerability.remove();
}

