(function (debug) {
    function log(msg){
        if (debug){
            alert(msg);
        }
    }
  // Check if user has passed the command line flag "com.fortify.sca.rules.enable_wi_correlation"
  if (getProperty("com.fortify.sca.rules.enable_wi_correlation") == null) {
    log("WebInspect Correlation not enabled.");
    return;
    // Check if application has spring jars included in the project
  } else if (!isSpringApp()) {
    log(
      "Not a Spring App. Cross platform scanning was enabled and used to scan a non-spring application"
    );
    return;
  } else {
    var results = new Array();

    var today = new Date();
    var date =
      today.getFullYear() +
      "-" +
      (today.getMonth() + 1) +
      "-" +
      today.getDate();
    var time =
      today.getHours() + ":" + today.getMinutes() + ":" + today.getSeconds();
    var dateTime = String(date + " " + time);

    var buildID = getProperty("com.fortify.sca.BuildID");
    if (buildID === null || buildID === undefined) {
      buildID = "Null";
    }

    var output = {
      Version: "1.0.6",
      OriginVersion: getVersion(),
      Origin: "SCA",
      OriginID: buildID,
      OriginDateTime: dateTime,
      Description: "",
      Frameworks: new Array("spring"),
      Rules: results,
    };

    var vulns = getVulnerabilities();
    var counter = 1;

    var hardCodedAnnoList = [
      ["org.springframework.web.bind.annotation.GetMapping", "GET"],
      ["org.springframework.web.bind.annotation.PostMapping", "POST"],
      ["org.springframework.web.bind.annotation.PutMapping", "PUT"],
      ["org.springframework.web.bind.annotation.DeleteMapping", "DELETE"],
      ["org.springframework.web.bind.annotation.PatchMapping", "PATCH"],
      ["org.springframework.web.bind.annotation.RequestMapping", "GET"],
      ["org.springframework.web.bind.annotation.RequestMapping", "POST"],
      ["org.springframework.web.bind.annotation.RequestMapping", "PUT"],
      ["org.springframework.web.bind.annotation.RequestMapping", "DELETE"],
      ["org.springframework.web.bind.annotation.RequestMapping", "PATCH"],
      ["org.springframework.web.bind.annotation.RequestMapping", "OPTIONS"],
      ["org.springframework.web.bind.annotation.RequestMapping", "HEAD"],
      ["org.springframework.web.bind.annotation.RequestMapping", "TRACE"],
    ];

    for (var vulnIndex = 0; vulnIndex < vulns.length; vulnIndex++) {
      var vuln = vulns[vulnIndex];
      if (vuln == null || vuln == undefined) continue;

      if (vuln.getRule() === null) continue;

      var thisResultCata = vuln.getRule().getCategory();
      var thisResultSubCata = vuln.getRule().getSubcategory();

      if (
        thisResultCata == "Cross-Site Scripting" ||
        thisResultCata == "SQL Injection"
      ) {
        if (vuln.getTaintSource() === null) continue;
        var entryPosition = vuln.getTaintSource().getEntryPointArgument();
        if (entryPosition == null || entryPosition == "this") {
          continue;
        }

        if (thisResultSubCata !== null && thisResultSubCata !== "") {
          thisResultCata = thisResultCata + ": " + thisResultSubCata;
        }

        var thisResult = {
          ID: "",
          Validation: false,
          PathMatches: [],
          Parameters: [],
          HttpMethodMatches: [],
        };

        thisResult.ID = vuln.getInstanceIdentifier();

        // Gather unique taint flags from issue and add to result
        var issueTaintFlags = [];
        var issueValidationTaintFlags = [];
        var taintPaths = vuln.getTaintPaths();
        if (taintPaths !== null && taintPaths !== undefined) {
          for (var i = 0; i < taintPaths.length; i++) {
            var theseTaintFlags = taintPaths[i].getTaintFlags();
            for (var j = 0; j < theseTaintFlags.length; j++) {
              // If validation taint flag present, store it
              if (theseTaintFlags[j].includes("VALIDATED"))
                issueValidationTaintFlags.push(theseTaintFlags[j]);
              // if not a validation taint flag add it to taintflags
              else issueTaintFlags.push(theseTaintFlags[j]);
            }
          }
        }

        thisResult.Validation = issueValidationTaintFlags.filter(function (
          item,
          index
        ) {
          return issueValidationTaintFlags.indexOf(item) === index;
        });

        // thisResult.taintflags = issueTaintFlags.filter(function (item, index) {
        // return issueTaintFlags.indexOf(item) === index;
        // });

        entryPosition = entryPosition.intValue();

        var sourceFunction = vuln.getSourceEnclosingFunction();

        if (sourceFunction !== null) {
          var controller = sourceFunction.getEnclosingClass();
        }

        dbg(
          "setting thisResult.URL.sourceLocation to " +
            sourceFunction.getFileName() +
            ":" +
            sourceFunction.getLineNumber()
        );
        //thisResult.PathMatches = sourceFunction.getFileName() + ":" + sourceFunction.getLineNumber();
        if (controller !== null && controller !== undefined)
          var controllerRequestMapping = controller.getAnnotation(
            "org.springframework.web.bind.annotation.RequestMapping"
          );

        var functionMapping = getFunctionMapping(
          hardCodedAnnoList,
          sourceFunction
        );

        // Check for the request type
        httpMethodMatches = new Array();
        var url = "";
        var isTemplated = false;

        if (functionMapping !== null) {
          // If there is both a function and class Mapping
          if (controllerRequestMapping !== null) {
            url = getAnnotationValue(controllerRequestMapping);
          }
          url += getAnnotationValue(functionMapping);

          if (url !== null) {
            thisResult.PathMatches.push(url);
            if (url.includes("{")) {
              dbg("setting thisResult.URL.isTemplated = true");
              isTemplated = true;
            }

            var argTypes = sourceFunction.getArgumentTypes();
            var entryType = argTypes[entryPosition + 1]; // again +1. I think it's including 'this' in the arguments. Needs to be in parenthesis to prevent breaking JS!
            var entryNames = sourceFunction.getArgumentNames();
            var entryName = "";

            if (entryNames !== null && entryNames.length >= entryPosition + 1) {
              entryName = entryNames[entryPosition + 1];
            }

            var typeFields = GetFieldsOfTypeAndSupers(entryType);

            thisResult.Parameters[0] = {};
            thisResult.Parameters[0].DataType = canonicalizeType(
              entryType,
              "JAVA"
            );

            // thisResult.Parameters[0].DataType = String(entryType);
            thisResult.Parameters[0].fields =
              convertTypeArrayToStringArray(typeFields);
            var paramAnnotation = getParamAnnotation(
              hardCodedAnnoList,
              entryPosition + 1,
              sourceFunction
            );
            //sourceFunction.getParameterAnnotation(entryPosition + 1, "org.springframework.web.bind.annotation.RequestParam");

            thisResult.Parameters[0].parameterID =
              getAnnotationValue(paramAnnotation);

            // If the Param does not have an annotation try and get the param name
            if (thisResult.Parameters[0].parameterID == null) {
              if (entryName != null) {
                thisResult.Parameters[0].parameterID = entryName;
              } else {
                // If there is no annotation and the param name is null skip because we won't be able to correlate
                continue;
              }
            }

            var theseFindings = new Array();
            theseFindings.push({
              Category: thisResultCata,
              FindingType: normalizeCategory(thisResultCata),
              Origin: "SCA",
              OriginFindingID: vuln.getInstanceIdentifier(),
            });

            thisResult.Parameters =
              /*thisResult.Parameters[0];*/
              flattenParameters(thisResult.Parameters[0], theseFindings);
          }

          httpMethodMatches = getHttpMethods(
            functionMapping,
            sourceFunction,
            hardCodedAnnoList
          );
        }

        thisResult.HttpMethodMatches = httpMethodMatches;

        log(
          "found a " +
            getCategory(vuln.getRule()) +
            " issue using an entrypoint: " +
            controller +
            "." +
            sourceFunction.getName() +
            "(" +
            entryPosition +
            ")"
        );

        // TODO: get from method
        // TODO: find types of templated URLs, e.g. /{petId}/. What types if petId? Can be retrieved elsewhere.
        if (controllerRequestMapping != null && functionMapping == null) {
          dbg("found a request mapping in " + controller);
          // var mapping = controllerRequestMapping.get("value");
          var url = getAnnotationValue(controllerRequestMapping);

          log("source leading to XSS at: " + url);
          dbg("setting thisResult.PathMatches =  " + url);
          thisResult.PathMatches = new Array();
          thisResult.PathMatches.push(url);

          if (url.includes("{")) {
            dbg("setting thisResult.URL.isTemplated = true");
            isTemplated = true;
          }

          var modelAttributeAnnotation = sourceFunction.getParameterAnnotation(
            entryPosition + 1 /* parameter seems to be off ???? */,
            "org.springframework.web.bind.annotation.ModelAttribute"
          );

          if (modelAttributeAnnotation != null) {
            dbg(
              "found a @ModelAttribute annotation on " +
                sourceFunction.getName()
            );
            var modelAttribute = modelAttributeAnnotation.get("value");

            log(
              "Found an XSS at " +
                vuln.getPrimaryFile() +
                ":" +
                vuln.getPrimaryLine()
            );
            dbg(
              "source leading to XSS at: " +
                url +
                " using modelAttribute: " +
                modelAttribute.getStrValue()
            );

            var argTypes = sourceFunction.getArgumentTypes();
            var entryType = argTypes[entryPosition + 1]; // again +1. I think it's including 'this' in the arguments. Needs to be in parenthesis to prevent breaking JS!

            var typeFields = GetFieldsOfTypeAndSupers(entryType);

            dbg("creating thisResult.Parameters");
            thisResult.Parameters = new Array();
            thisResult.Parameters[0] = {};

            log(
              "the entry of type " +
                entryType.getName() +
                " has " +
                typeFields.length +
                " fields:"
            );

            thisResult.Parameters[0].DataType = canonicalizeType(
              entryType,
              "JAVA"
            );
            // thisResult.Parameters[0].DataType = String(entryType);
            thisResult.Parameters[0].fields =
              convertTypeArrayToStringArray(typeFields);

            thisResult.Parameters[0].parameterID = getOrAddParameterID(
              thisResult.Parameters[0]
            );

            var theseFindings = new Array();
            theseFindings.push({
              Category: thisResultCata,
              FindingType: normalizeCategory(thisResultCata),
              Origin: "SCA",
              OriginFindingID: vuln.getInstanceIdentifier(),
            });

            thisResult.Parameters =
              /*thisResult.Parameters[0];*/
              flattenParameters(thisResult.Parameters[0], theseFindings);

            dbg("source rule: " + vuln.getSourceRule().getIdentifier());
            dbg("sink rule: " + vuln.getRule().getIdentifier());
          }
        }
        // TODO: Check Params for RequestParam Annotations
        if (
          thisResult !== null &&
          thisResult !== undefined &&
          thisResult.Parameters !== null &&
          thisResult.Parameters !== undefined &&
          thisResult.Parameters.length > 0
        ) {
          dbg("pushing result " + counter);
          counter = counter + 1;
          results.push(thisResult);
        }
      }
    }

    // alert(JsonStringify(output));
    createPrivateResultFile(output, "dast/sast.json");
  }
})(false);

var filter_categories = [
  "Dead Code",
  "Poor Style",
  "Poor Error Handling",
  "Password Management: Password in Comment",
  "Code Correctness: Class Does Not Implement Equivalence Method",
  "Code Correctness: Class Does Not Implement Cloneable",
  "Code Correctness: clone() Invokes Overridable Function",
  "Code Correctness: Constructor Invokes Overridable Function",
  "Code Correctness: readObject() Invokes Overridable Function",
  "Code Correctness: Erroneous finalize() Method",
  "Code Correctness: Hidden Method",
  "Code Correctness: Misleading Method Signature",
];

var filter_ruleIDs = [
  // Java Null Password rules not specific to Java/Android API
  // overlap with .Net Null Password rules
  "0309AEFE-C671-4990-9FA9-F42D8592FE7D",
  "7F93FCBC-9AD1-4CBE-88EF-AE4A0CC9736F",
  "9E12D121-F22A-404D-AD37-62DD19A5550A",
  "5F0F53B6-1538-47EE-A74F-675016928C09",
  // Java Empty Password rules not specific to Java/Android API
  // overlap with .Net Empty Password rules
  "A3A363FE-737E-47BF-857A-11B825B220FC",
  "25064B56-002D-41A3-A8F9-1F55786774AC",
  "E860A083-1FBD-4A75-AC3C-22FD10E9998E",
  "75B898D4-0898-4B9C-85AC-822332541BD9",
  // Java Hardcoded Password rules not specific to Java/Android API
  // overlap with .Net Hardcoded Password rules
  "FA11564C-5B12-4D93-9AA3-B4CCA86BD8D9",
  "442F9B03-D1A8-47FF-851E-FDB6B743FDE9",
  "AAEA8939-9574-4B84-89E4-975D2648AA41",
  "9675E054-A1D0-41E6-BE69-AAEB58DB972B",
  // Empty/Hardcoded/Null Encryption Key rules from JSP rulepack
  // overlap with corresponding rules from Java rulepack
  "D34F43A1-5D35-4C77-BDC0-C7561A0C88BF",
  "B4459D3C-04B8-4566-AE24-4F03B1255180",
  "C0D136C9-5F9E-4F50-984A-DBC791AC2170",
  "F36EB589-F648-4A34-9476-A094316FF0EB",
  "6B659F0E-FF88-45AF-9ABC-2DAC0B030EA2",
  "91558F44-1CA9-4860-AF89-E7A6D388DAA9",
  "D643A371-A426-49B3-BF7C-08BB27BA9A8D",
  "D918D2E7-4780-4D87-AA5F-F7943BF7D91D",
  "1F28DC6C-C9F2-4CF7-97CF-81869BBA1D6B",
  "3CFCB607-7521-48EA-952D-B36C7C4B6DBC",
  "41FC5763-D986-4586-BF50-6197E65DAED1",
  "767D35F0-D11A-4E43-9140-CB73C3A4BB11",
];

var source_ruleIDs = ["91106795-F643-4B94-A2BA-68CB374EB31B"];

var vulns = getVulnerabilities();
for (var i in vulns) {
  var vuln = vulns[i];
  if (vuln.getPrimaryFile() === null || vuln.getPrimaryFile() === undefined)
    continue;
  var filename = vuln.getPrimaryFile().toLowerCase();
  if (filename.endsWith(".cs")) {
    var filtered = false;

    var ruleLang = String(vuln.getRule().getLanguage()).toLowerCase();
    if (ruleLang === "java" || ruleLang === "jsp") {
      var category = String(vuln.getRule().getCategory());

      for (var j in filter_categories) {
        var cat = filter_categories[j];
        if (cat === category) {
          vuln.remove();
          filtered = true;
          break;
        }
      }
    }

    if (!filtered) {
      var ruleId = String(vuln.getRule().getIdentifier().toUpperCase());
      for (var j in filter_ruleIDs) {
        var id = filter_ruleIDs[j];
        if (ruleId === id) {
          vuln.remove();
          break;
        }
      }
      var sourceRuleId = String(
        vuln.getSourceRule().getIdentifier().toUpperCase()
      );
      for (var j in source_ruleIDs) {
        var id = source_ruleIDs[j];
        if (sourceRuleId.startsWith(id)) {
          vuln.remove();
          break;
        }
      }
    }
  }
}

(function(){
    var vulns = getVulnerabilities();
    var lines = new Array();

    //
    // Problem: Multiple weak cipher suites will report many issues on the same line
    //
    // Remove duplicates of Insecure Transport: Weak SSL Cipher when:
    // 1. Issue exist on same file
    // 2. Issue exist on the same line
    //
    for each (var vuln in vulns){
        if (vuln !== null && (vuln.getPrimaryFile() === null || vuln.getPrimaryLine() === null)) continue;

        var rule = vuln.getRule();
        if (rule.getIdentifier() == "6B06C72B-55FB-4DED-8D70-33EEF2007EA20"){
            var loc = "".concat(vuln.getPrimaryFile(), ":", vuln.getPrimaryLine());

            // If vuln is already exists at this location, remove
            if (lines.includes(loc)){
                vuln.remove();
                continue;
            }

            lines.push(loc);
        }
    }
})();

/*

**************** IMPORTANT ****************
ADVISED TO ASSIGN GROUP 5 IN PROPERTIES
*******************************************
Any post-scripts relying upon this functionality needs to be declared before this script runs,
so assigning a group value 5 will always ensure that this script executes at the very last.

*/

(function() {
    /* master  post script that loops over the vulns once, performing all the checks, then runs logic once this has finished */
    /* adapted from master_js_post_checks, but this relies on java_scripting_library for separating out where checks are stored */


    /*
    * create a check object that contains instance variables, with any functions.
    * 2 special objects:
    * loopFuncs is an object where the keys/fields are rule IDs to match, and the values are callbacks to run when the rule ID matches. Can also specify an object against "categories" which specifies category name: callback key/value pairs.
    * postFuncs is an array of functions to be called in order after the loop over all vulns has occurred
    *
    * I've done them within in separate lib scripts to make them easier to read. If this causes problems, we could either
    * put them in this one script, or persist them from a mid script. That may be the better option if we eventally have some fingerprinting capabilities
    */

    //Example:
    /*
    function test_check(){
        _myField = 'foo';
        _myArray = new Array();
        this.loopFuncs = {
            'ruleId' : function(){
                alert(_myField);
            },
            'otherRuleId': function(vuln){ //the vuln matching 'otherRuleId' will automatically be passed to the callback
                _myArray.push(vuln);
            },
            //or for categories, specify a "categories" field that points to an array of objects where the category is the key, and callback the value. Whole Category: Subcategory needs to be specified where there is a subcategory
            categories: [{"Category Name: Subcategory Name": callback}]
        };
        this.postFuncs = new Array();
        this.postFuncs.push(function(){
            for each (var vuln in _myArray){
                vuln.remove();
            }
        });
    }

    Then this just needs to be created and added to the list of checks below
    */

    function dbg_vuln(msg, vuln) {
        function show(msg) {
            if (getProperty('com.fortify.sca.rules.DebugScripts') == 'true'){
                alert(msg)
            }
        }

        // takes separator and then varargs for things to join
        function joinBySeparator(separator) {
            var args = new Array()
            for (var i = 1; i < arguments.length; i++) { // get everything from arguments exception separator
                args.push(arguments[i]) // arguments is not an actual array, so can't use shift().
            }
            return args.join(separator)
        }

        if (vuln === undefined){
            show(msg)
        }else{
            var r = vuln.getRule()
            var cat = _vulnCategoryNormalizer(r.getCategory(), r.getSubcategory())
            show(joinBySeparator(': ', cat, vuln.getPrimaryFile(), vuln.getPrimaryLine(), msg))
        }
    }

    /* a list of rule IDs with associated callbacks. May optionally take an array of callbacks */
    var _ruleid_checks = {};
    var _category_checks = {};

    /* the callback is called */
    function _addRuleCheck(ruleID, callback){
        dbg_vuln('adding callback for rule ID: ' + ruleID)
        _addCheck(ruleID, callback, _ruleid_checks);
    }
    /* will add callbacks to a global object such that when something is compared to the category, the callback is called */
    function _addCategoryCheck(category, callback){
        //adding category check
        dbg_vuln('adding callback for category: "' + category + '"')
        _addCheck(category, callback, _category_checks);
    }

    /* generic function for adding a callback to an object */
    function _addCheck(condition, callback, obj){
        var callbacks = obj[condition];
        var callbacksArray = null;
        if (callbacks === null || callbacks === undefined){
            callbacksArray = new Array();
        }else{
            callbacksArray = callbacks;
        }
        /* don't bother checking if the conditional func, already set. May want to change in the future */
        callbacksArray.push(callback);
        obj[condition] = callbacksArray;
    }

    /* takes a vuln and runs it against the relevant callbacks */
    function _checkRule(vuln){
        category = String(vuln.getRule().getCategory());
        subcategory = String(vuln.getRule().getSubcategory());
        //normalize category name
        issue_category = _vulnCategoryNormalizer(category,subcategory);
        dbg_vuln('Category: ' + issue_category)
        issue_rule_id = String(vuln.getRule().getIdentifier());
        dbg_vuln('Rule ID: ' + issue_rule_id)

        //get Rule ID checks
        rule_id_callbacks = _ruleid_checks[issue_rule_id];
        //check category. If this wants to be changed to remove all subcategories under a category, this would need to be looped
        category_callbacks = _category_checks[issue_category];

        var callbacks = new Array();
        if (rule_id_callbacks !== null && rule_id_callbacks !== undefined && category_callbacks !== null && category_callbacks !== undefined){
            dbg_vuln('matching rule ID and category check', vuln)
            callbacks = rule_id_callbacks.concat(category_callbacks);
        }else if (rule_id_callbacks !== null && rule_id_callbacks !== undefined){
            //if so category_callbacks is undefined/null
            dbg_vuln('matching rule ID check', vuln)
            callbacks = rule_id_callbacks;
        }else if (category_callbacks !== null && category_callbacks !== undefined){
            //if so rule_id_callbacks is undefined/null
            dbg_vuln('matching category check', vuln)
            callbacks = category_callbacks;
        }


        for (var i = callbacks.length-1; i>=0; i--){
            var callback = callbacks[i]
            if (typeof callback !== 'function'){
                //log('the callback: ' + callback + ' is not a function!');
            }else{
                callback(vuln);
            }
        }
    }

    /* returns the category with optional subcategory, delimited by a colon */
    function _vulnCategoryNormalizer(category, subcategory){
        return (subcategory != "null" && subcategory !== undefined) ? String(category + ": " + subcategory) : String(category);
    }

    // the main function of this script. Automatically runs.
    (function main(){

        var checks = java.checks.retrieve()
        dbg_vuln('Java has ' + checks.length + ' checks')

        /* go through all checks and add the loop funcs to a global list to run in a single loop over all issues found */
        for (var i = checks.length-1; i >= 0; i--){
            var funcs = checks[i].loopFuncs;
            for (var id in funcs){
                if (funcs.hasOwnProperty(id)){
                    if (id === 'categories'){
                        dbg_vuln('Found categories to check: ' + funcs[id].length)
                        //categories: [{"Cross-Site Request Forgery": _addToIssues}]
                        // should be an array we need to loop over
                        for (var j = 0; j < funcs[id].length; j++){
                            var callback_by_category = funcs[id][j]
                            //Should be an object category_name: callback
                            for (var category_name in callback_by_category){
                                if (callback_by_category.hasOwnProperty(category_name)){
                                    _addCategoryCheck(category_name, callback_by_category[category_name]);
                                }
                            }
                        }
                    }else{
                        // otherwise it's a rule ID
                        _addRuleCheck(id, funcs[id]);
                    }
                }
            }
        }

        var vulns = getVulnerabilities();
        dbg_vuln('found ' + vulns.length + ' vulns')
        for (var i = vulns.length - 1; i >= 0; i--){
            _checkRule(vulns[i]);
        }

        /* loop through all post functions across all checks */
        for each (var check in checks) {
            for each (func in check.postFuncs){
                if (typeof func !== 'function'){
                    dbg('function: ' + func + ' is not a function. Re-check postFuncs is an array of functions');
                    dbg_vuln('function: ' + func + ' is not a function. Re-check postFuncs is an array of functions');
                }else{
                    dbg_vuln('calling ' + func)
                    func();
                }
            }
        }
    })()

})()

