        }else{
            var r = vuln.getRule()
            var cat = _vulnCategoryNormalizer(r.getCategory(), r.getSubcategory())
            show(joinBySeparator(': ', cat, vuln.getPrimaryFile(), vuln.getPrimaryLine(), msg))
        }
    }

    /* a list of rule IDs with associated callbacks. May optionally take an array of callbacks */
    var _ruleid_checks = {};
    var _category_checks = {};

    /* the callback is called */
    function _addRuleCheck(ruleID, callback){
        _addCheck(ruleID, callback, _ruleid_checks);
    }
    /* will add callbacks to a global object such that when something is compared to the category, the callback is called */
    function _addCategoryCheck(category, callback){
