        }
        /* don't bother checking if the conditional func, already set. May want to change in the future */
        callbacksArray.push(callback);
        obj[condition] = callbacksArray;
    }

    /* takes a vuln and runs it against the relevant callbacks */
    function _checkRule(vuln){
        category = String(vuln.getRule().getCategory());
        subcategory = String(vuln.getRule().getSubcategory());
        //normalize category name
        issue_category = _vulnCategoryNormalizer(category,subcategory);
        issue_rule_id = String(vuln.getRule().getIdentifier());

        //get Rule ID checks
        rule_id_callbacks = _ruleid_checks[issue_rule_id];
        //check category. If this wants to be changed to remove all subcategories under a category, this would need to be looped
        category_callbacks = _category_checks[issue_category];

        var callbacks = new Array();
        if (rule_id_callbacks !== null && rule_id_callbacks !== undefined && category_callbacks !== null && category_callbacks !== undefined){
            dbg_vuln('matching rule ID and category check', vuln)
            callbacks = rule_id_callbacks.concat(category_callbacks);
        }else if (rule_id_callbacks !== null && rule_id_callbacks !== undefined){
            //if so category_callbacks is undefined/null
            dbg_vuln('matching rule ID check', vuln)
            callbacks = rule_id_callbacks;
        }else if (category_callbacks !== null && category_callbacks !== undefined){
            //if so rule_id_callbacks is undefined/null
            dbg_vuln('matching category check', vuln)
            callbacks = category_callbacks;
        }


        for each (var callback in callbacks){
            if (typeof callback !== 'function'){
                //log('the callback: ' + callback + ' is not a function!');
            }else{
                callback(vuln);
            }
        }
    }

    /* returns the category with optional subcategory, delimited by a colon */
    function _vulnCategoryNormalizer(category, subcategory){
        return (subcategory != "null" && subcategory !== undefined) ? String(category + ": " + subcategory) : String(category);
    }

    // the main function of this script. Automatically runs.
    (function main(){

        var checks = kotlin.checks.retrieve()

        /* go through all checks and add the loop funcs to a global list to run in a single loop over all issues found */
        for each (var check in checks){
            var funcs = check.loopFuncs;
            for (var id in funcs){
                if (funcs.hasOwnProperty(id)){
                    if (id === 'categories'){
                        //categories: [{"Cross-Site Request Forgery": _addToIssues}]
                        // should be an array we need to loop over
                        for each (var callback_by_category in funcs[id]){
                            //Should be an object category_name: callback
                            for (var category_name in callback_by_category){
                                if (callback_by_category.hasOwnProperty(category_name)){
