        &lt;items&gt;UsernameToken&lt;/items&gt;
        &lt;user&gt;bob&lt;/user&gt;
        &lt;passwordCallbackClass&gt;org.apache.rampart.samples.PWCBHandler&lt;/passwordCallbackClass&gt;
